/* ═══════════════════════════════════════════════════════════════════════════
   3. SECURITY & FORMATTING HELPERS
   ═══════════════════════════════════════════════════════════════════════════ */
function padZ(n) { return String(n).padStart(2, '0'); }
function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function fmtUsd(n) {
  if (n === null || n === undefined || !Number.isFinite(Number(n))) {
    return 'Hesaplanamadı';
  }
  const val = Math.round(Number(n));
  const sign = val < 0 ? '-' : '';
  return sign + '$' + Math.abs(val).toLocaleString('en-US');
}

function safeLabel(value, maxLen = 72) {
  if (value === null || value === undefined) return '';
  return String(value).replace(/\s+/g, ' ').trim().slice(0, maxLen);
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function fixedPointBigInt(value) {
  const text = String(value ?? '').trim();
  if (!/^-?\d{1,20}$/.test(text)) return null;
  try { return BigInt(text); } catch (_) { return null; }
}

function formatFixedPoint(value, digits = 3) {
  const parsed = fixedPointBigInt(value);
  if (parsed === null) return '—';
  const scale = 1000000n;
  const negative = parsed < 0n;
  const absolute = negative ? -parsed : parsed;
  const whole = absolute / scale;
  const fraction = String(absolute % scale).padStart(6, '0').slice(0, digits);
  return `${negative ? '-' : ''}${whole}${digits ? '.' + fraction : ''}`;
}

function formatFixedPercent(value) {
  const parsed = fixedPointBigInt(value);
  if (parsed === null) return '—';
  const tenths = (parsed * 1000n) / 1000000n;
  const negative = tenths < 0n;
  const absolute = negative ? -tenths : tenths;
  return `${negative ? '-' : ''}${absolute / 10n}.${absolute % 10n}%`;
}

function fixedPointDifferenceAtLeast(left, right, threshold = 50000n) {
  const leftValue = fixedPointBigInt(left);
  const rightValue = fixedPointBigInt(right);
  if (leftValue === null || rightValue === null) return false;
  const difference = leftValue >= rightValue
    ? leftValue - rightValue
    : rightValue - leftValue;
  return difference >= threshold;
}

function appendNeuralValue(container, label, value, className = '') {
  const entry = document.createElement('span');
  if (className) entry.className = className;
  const labelNode = document.createTextNode(`${label}: `);
  const valueNode = document.createElement('b');
  valueNode.textContent = value;
  entry.append(labelNode, valueNode);
  container.appendChild(entry);
}

function applyNeuralObservation(data) {
  if (!isRecord(data) || data.schema_ver !== 1 || !el.neuralCard) return;
  state.neuralObservation = data;

  const gateDecision = safeLabel(data.gate_decision || 'UNKNOWN', 48);
  const mode = safeLabel(data.mode || 'SYMBOLIC_ONLY', 24);
  const runtimeStatus = safeLabel(data.runtime_status || 'UNKNOWN', 32);
  const gateAccepted = data.gate_accepted === true;
  const modelTrusted = data.model_trusted === true;
  const authorityExpected = data.authority_expected === true;
  const authorityCommitted = data.authority_committed === true;
  const rollbackApplied = data.rollback_applied === true;
  const rollbackFailed = data.rollback_failed === true;
  const booleanFieldsValid = [
    'gate_accepted',
    'fallback',
    'model_trusted',
    'authority_expected',
    'authority_committed',
    'rollback_applied',
    'rollback_failed',
  ].every(field => typeof data[field] === 'boolean');
  const acceptedBounded =
    gateDecision === 'ACCEPTED_BOUNDED' &&
    mode === 'ASSURANCE' &&
    authorityExpected &&
    authorityCommitted;
  const acceptedAdvisory =
    gateDecision === 'ACCEPTED_ADVISORY' &&
    mode === 'ADVISORY' &&
    !authorityExpected &&
    !authorityCommitted;
  const accepted =
    booleanFieldsValid &&
    gateAccepted &&
    modelTrusted &&
    runtimeStatus === 'OK' &&
    data.fallback === false &&
    !rollbackApplied &&
    !rollbackFailed &&
    (acceptedBounded || acceptedAdvisory);
  const unsafe =
    rollbackFailed ||
    (!accepted && (
      gateAccepted ||
      data.fallback === false ||
      authorityCommitted ||
      rollbackApplied
    ));
  const fallback = !accepted;

  el.neuralCard.classList.remove(
    'neural--accepted', 'neural--rejected', 'neural--unsafe'
  );
  el.neuralCard.classList.add(
    unsafe ? 'neural--unsafe' : (accepted ? 'neural--accepted' : 'neural--rejected')
  );
  if (el.neuralGate) el.neuralGate.textContent = gateDecision || 'UNKNOWN';
  if (el.neuralMode) el.neuralMode.textContent = mode;

  const modelId = safeLabel(data.model_id || 'not loaded', 48);
  const modelVersion = safeLabel(data.model_version || '', 24);
  const trustLabel = modelTrusted ? 'trusted' : 'untrusted';
  if (el.neuralModel) {
    el.neuralModel.textContent =
      `${modelId}${modelVersion ? '@' + modelVersion : ''} · ${trustLabel}`;
    el.neuralModel.title =
      `load=${safeLabel(data.model_load_status || 'UNKNOWN', 32)} · ` +
      `runtime=${runtimeStatus} · schema=${safeLabel(data.feature_schema_version, 8)}`;
  }
  if (el.neuralTick) {
    el.neuralTick.textContent =
      `${safeLabel(data.tick, 24) || '—'} / ${safeLabel(data.observed_history_ticks, 8) || '0'} of 8`;
  }
  if (el.neuralFallback) {
    el.neuralFallback.textContent =
      unsafe ? 'UNSAFE CLAIM · IGNORED' : (fallback ? 'ACTIVE · SYMBOLIC' : 'NO');
  }
  if (el.neuralReason) {
    const authority = acceptedBounded && accepted
      ? 'Bounded proposal committed by symbolic authority.'
      : 'No neural mutation committed; symbolic state remains authoritative.';
    const safety = unsafe
      ? ' Inconsistent telemetry claims were ignored.'
      : '';
    el.neuralReason.textContent =
      `${safeLabel(data.gate_reason || 'No gate reason supplied.', 180)} ${authority}${safety}`;
  }

  if (el.neuralNodeList) {
    el.neuralNodeList.replaceChildren();
    const nodes = Array.isArray(data.nodes) ? data.nodes.slice(0, 64) : [];
    nodes.forEach(rawNode => {
      if (!isRecord(rawNode)) return;
      const node = document.createElement('div');
      node.className = 'neural-node';
      const divergent = fixedPointDifferenceAtLeast(
        rawNode.reported_state_fp, rawNode.authoritative_state_fp
      );
      if (divergent) node.classList.add('neural-node--divergent');

      const heading = document.createElement('div');
      heading.className = 'neural-node-name';
      const name = document.createElement('span');
      name.textContent = safeLabel(rawNode.node_id || 'UNKNOWN_NODE', 40);
      const flag = document.createElement('span');
      flag.className = 'neural-node-flag';
      flag.textContent = divergent ? 'TELEMETRY DIVERGENCE' : 'CONSISTENT';
      heading.append(name, flag);
      node.appendChild(heading);

      const values = document.createElement('div');
      values.className = 'neural-values';
      appendNeuralValue(values, 'Reported', formatFixedPoint(rawNode.reported_state_fp));
      appendNeuralValue(
        values,
        accepted ? 'Neural estimate' : 'Neural estimate (rejected)',
        rawNode.neural_output_available === true
          ? formatFixedPoint(rawNode.estimated_true_state_fp)
          : 'unavailable',
        'neural-estimate'
      );
      appendNeuralValue(
        values, 'Authoritative symbolic', formatFixedPoint(rawNode.authoritative_state_fp)
      );
      appendNeuralValue(values, 'Trust', formatFixedPercent(rawNode.trust_fp));
      node.appendChild(values);

      if (rawNode.neural_output_available === true) {
        const risks = document.createElement('div');
        risks.className = 'neural-risks';
        risks.textContent =
          `Anomaly ${formatFixedPercent(rawNode.anomaly_score_fp)} · ` +
          `Confidence ${formatFixedPercent(rawNode.confidence_fp)} · ` +
          `OOD ${formatFixedPercent(rawNode.ood_score_fp)} · ` +
          `Outage S/M/L ${formatFixedPercent(rawNode.outage_short_fp)} / ` +
          `${formatFixedPercent(rawNode.outage_medium_fp)} / ` +
          `${formatFixedPercent(rawNode.outage_long_fp)}`;
        node.appendChild(risks);
      }
      el.neuralNodeList.appendChild(node);
    });
  }

  if (el.neuralLevers) {
    el.neuralLevers.replaceChildren();
    const title = document.createElement('strong');
    title.textContent = 'Symbolically evaluated lever candidates: ';
    el.neuralLevers.appendChild(title);
    const levers = Array.isArray(data.lever_candidates)
      ? data.lever_candidates.filter(isRecord).slice(0, 3)
      : [];
    if (!levers.length) {
      el.neuralLevers.appendChild(document.createTextNode('none'));
    } else {
      const summary = levers.map(lever => {
        const marker = lever.selected === true ? 'SELECTED ' : '';
        return `${marker}${safeLabel(lever.lever_id || 'unknown', 40)} ` +
          `(neural ${formatFixedPercent(lever.neural_score_fp)}, ` +
          `symbolic ${formatFixedPercent(lever.symbolic_score_fp)})`;
      }).join(' · ');
      el.neuralLevers.appendChild(document.createTextNode(summary));
    }
  }

  const disposition = unsafe
    ? 'UNSAFE PAYLOAD IGNORED'
    : (accepted ? (acceptedBounded ? 'BOUNDED ACCEPT' : 'ADVISORY ACCEPT') : 'SYMBOLIC FALLBACK');
  const decisionKey = `${gateDecision}:${disposition}`;
  if (state.lastNeuralDecision !== decisionKey) {
    addAuditLog(
      unsafe ? 'err' : (accepted ? 'ok' : 'warn'),
      `NEURAL GATE: ${gateDecision} · ${disposition}`
    );
    state.lastNeuralDecision = decisionKey;
  }
  if (unsafe) SFX.alarm();
}

/* ═══════════════════════════════════════════════════════════════
   LEFT TAB SWITCHER
   ═══════════════════════════════════════════════════════════════ */
function addAuditLog(level, msg) {
  if (!el.cryptoLog) return;
  const now = new Date();
  const ts = `${padZ(now.getHours())}:${padZ(now.getMinutes())}:${padZ(now.getSeconds())}`;

  const row = document.createElement('div');
  row.className = 'audit-entry';

  const tsEl = document.createElement('span');
  tsEl.className = 'audit-ts';
  tsEl.textContent = ts;

  const tagEl = document.createElement('span');
  tagEl.className = 'audit-tag ' + (level || 'info');
  tagEl.textContent = level === 'ok' ? '[ONAY]' : level === 'warn' ? '[UYARI]' : level === 'err' ? '[KRİTİK]' : '[KAYIT]';

  const msgEl = document.createElement('span');
  msgEl.className = 'audit-msg';
  msgEl.textContent = msg;

  row.appendChild(tsEl);
  row.appendChild(tagEl);
  row.appendChild(msgEl);

  el.cryptoLog.insertBefore(row, el.cryptoLog.firstChild);
  while (el.cryptoLog.children.length > CFG.LOG_MAX_ENTRIES) {
    el.cryptoLog.removeChild(el.cryptoLog.lastChild);
  }
}

function addReplLine(text, tone = 'info') {
  if (!el.lcOutput) return;
  const div = document.createElement('div');
  div.style.padding = '1px 0';
  if (tone === 'err') div.style.color = 'var(--crit)';
  else if (tone === 'ok') div.style.color = 'var(--ok)';
  else if (tone === 'cmd') div.style.color = 'var(--accent)';
  div.textContent = text;
  el.lcOutput.appendChild(div);
  el.lcOutput.scrollTop = el.lcOutput.scrollHeight;
  while (el.lcOutput.children.length > 150) {
    el.lcOutput.removeChild(el.lcOutput.firstChild);
  }
}

function setStudioFeedback(msg, colorVar) {
  if (!el.feedbackBar) return;
  el.feedbackBar.textContent = msg;
  el.feedbackBar.style.color = colorVar || 'var(--text-3)';
}

/* ═══════════════════════════════════════════════════════════════════════════
   4. STATIC DRAFT TOPOLOGY PREVIEW (NO FAKE TICK SIMULATION)
   Used ONLY when the user compiles a natural-language or JSON draft in
   Scenario Studio while offline, to inspect node/edge/lever structure at t=0.
   ═══════════════════════════════════════════════════════════════════════════ */
function extractScenarioModelFromPack(pack, sigScheme = 'UNSIGNED') {
  const m = (pack && pack.extended_causal_model) || {};
  const meta = (pack && pack.meta) || {};
  const fin = meta.financials || {};
  const nodes = Array.isArray(m.nodes) ? m.nodes : [];
  const initial_nodes = nodes.map(n => ({
    id: String(n.id || ''),
    label: String(n.label || n.id || ''),
    category: String(n.category || n.kind || 'Service'),
    unit: String(n.unit || '%'),
    data_source: String(n.data_source || meta.data_provenance || 'USER_INPUT'),
    timestamp: String(n.timestamp || meta.last_import_timestamp || ''),
    initial_state: Number(n.state_fp !== undefined ? (n.state_fp > 2 ? n.state_fp / 1000000 : n.state_fp) : (n.state ?? 0.5)),
    initial_reported: Number(n.reported_state_fp !== undefined ? (n.reported_state_fp > 2 ? n.reported_state_fp / 1000000 : n.reported_state_fp) : (n.state_fp !== undefined ? (n.state_fp > 2 ? n.state_fp / 1000000 : n.state_fp) : 0.5)),
    initial_trust: Number(n.trust_fp !== undefined ? (n.trust_fp > 2 ? n.trust_fp / 1000000 : n.trust_fp) : (n.trust ?? 1.0)),
    weight: Number(n.weight_fp !== undefined ? (n.weight_fp > 2 ? n.weight_fp / 1000000 : n.weight_fp) : (n.weight ?? 0.2)),
    decay: Number(n.decay_fp !== undefined ? (n.decay_fp > 2 ? n.decay_fp / 1000000 : n.decay_fp) : (n.decay ?? 0.03)),
    floor: Number(n.floor_fp !== undefined ? (n.floor_fp > 2 ? n.floor_fp / 1000000 : n.floor_fp) : (n.floor ?? 0.1))
  }));
  const edges = (Array.isArray(m.edges) ? m.edges : []).filter(e => e && e.to).map(e => ({
    from: String(e.from || ''),
    to: String(e.to || ''),
    multiplier: Number(e.multiplier_fp !== undefined ? (e.multiplier_fp > 10 ? e.multiplier_fp / 1000000 : e.multiplier_fp) : (e.weight ?? 0.5)),
    lag_ticks: Number(e.lag_ticks ?? 0)
  }));
  const feedback_loops = (Array.isArray(m.feedback_loops) ? m.feedback_loops : []).map(fl => ({
    id: String(fl.id || ''),
    from: String(fl.from || ''),
    to: String(fl.to || ''),
    gain: Number(fl.gain_fp !== undefined ? (fl.gain_fp > 10 ? fl.gain_fp / 1000000 : fl.gain_fp) : (fl.gain ?? 0.1)),
    trigger_threshold: Number(fl.trigger_threshold_fp !== undefined ? (fl.trigger_threshold_fp > 10 ? fl.trigger_threshold_fp / 1000000 : fl.trigger_threshold_fp) : (fl.trigger_threshold ?? 0.5))
  }));
  const deadlines = Array.isArray(m.hard_deadlines) && m.hard_deadlines.length > 0
    ? m.hard_deadlines.map(d => ({
      node_id: String(d.node_id || ''),
      at_tick: Number(d.at_tick ?? -1),
      latches_outage: true,
      condition: String(d.condition || 'UNCONDITIONAL'),
      threshold: Number(d.threshold_fp !== undefined ? (d.threshold_fp > 10 ? d.threshold_fp / 1000000 : d.threshold_fp) : (d.threshold ?? 0))
    }))
    : nodes.filter(n => Number(n.deadline_tick ?? -1) >= 0).map(n => ({
      node_id: String(n.id),
      at_tick: Number(n.deadline_tick),
      latches_outage: String(n.kind || '').toLowerCase() === 'perishable',
      condition: 'UNCONDITIONAL',
      threshold: 0
    }));
  const hysteresis = (Array.isArray(m.hysteresis) ? m.hysteresis : []).map(h => ({
    id: String(h.id || ''),
    threshold_tick: Number(h.threshold_tick ?? 0),
    reversible: Boolean(h.reversible),
    permanent_loss: Number(h.permanent_loss_fp !== undefined ? h.permanent_loss_fp / 1000000 : (h.permanent_loss ?? 0)),
    condition: String(h.condition || 'UNCONDITIONAL'),
    trigger_threshold: Number(h.trigger_threshold_fp !== undefined ? (h.trigger_threshold_fp > 10 ? h.trigger_threshold_fp / 1000000 : h.trigger_threshold_fp) : (h.trigger_threshold ?? 0))
  }));
  const levers = (Array.isArray(m.levers) ? m.levers : []).map(lv => {
    const onSuc = lv.on_success || {};
    return {
      id: String(lv.id || ''),
      code: String(lv.code || lv.id || ''),
      label: String(lv.label || lv.id || ''),
      notes: String(lv.notes || ''),
      cost_usd: Number(lv.cost_usd ?? -1),
      data_source: String(lv.data_source || meta.data_provenance || 'USER_INPUT'),
      target: String(lv.target || onSuc.target_node_id || ''),
      success_p: Number(lv.success_p !== undefined ? lv.success_p : ((lv.success_p_fp ?? 700000) / 1000000)),
      cost_ticks: Number(lv.cost_ticks ?? 8),
      lockout_ticks: Number(lv.lockout_ticks ?? 0),
      available: true,
      remaining_lockout: 0,
      on_success: {
        target_node_id: String(onSuc.target_node_id || lv.target || ''),
        state_delta: Number(onSuc.state_delta !== undefined ? onSuc.state_delta : ((onSuc.state_delta_fp ?? 0) / 1000000)),
        trust_delta: Number(onSuc.trust_delta !== undefined ? onSuc.trust_delta : ((onSuc.trust_delta_fp ?? 0) / 1000000)),
        friction_delta: Number(onSuc.friction_delta !== undefined ? onSuc.friction_delta : ((onSuc.friction_delta_fp ?? 0) / 1000000)),
        clear_irrecoverable: Boolean(onSuc.clear_irrecoverable)
      }
    };
  });
  return {
    type: 'scenario_model',
    scenario_id: String(pack.id || 'USER-SCENARIO'),
    pack_loaded: true,
    sector: String(pack.sector || 'UNIVERSAL'),
    region: String(pack.region || 'GLOBAL'),
    title: String(meta.title || pack.id || 'Taslak Model'),
    enterprise_code: String(meta.enterprise_code || pack.id || 'USER-SCENARIO'),
    sector_label: String(meta.sector_label || pack.sector || 'Evrensel Süreç Modeli'),
    synopsis: String(meta.synopsis || ''),
    compliance: String(meta.compliance || 'ISO 22301 / ISO 31000'),
    data_provenance: String(meta.data_provenance || 'USER_INPUT'),
    data_source_note: String(meta.data_source_note || ''),
    assumptions: Array.isArray(meta.assumptions) ? meta.assumptions : [],
    data_gaps: Array.isArray(meta.data_gaps) ? meta.data_gaps : [],
    financials: {
      available: Boolean(fin.available),
      currency: String(fin.currency || 'USD'),
      unit_name: String(fin.unit_name || 'Birim/Saat'),
      baseline_units_per_hour: Number(fin.baseline_units_per_hour ?? 100),
      hourly_downtime_cost_usd: Number(fin.hourly_downtime_cost_usd ?? 0),
      sla_breach_penalty_usd: Number(fin.sla_breach_penalty_usd ?? 0),
      source_note: String(fin.source_note || '')
    },
    signature_scheme: sigScheme,
    meta_signed: false,
    tick_minutes: Number(meta.tick_minutes ?? 15),
    horizon_hours: Number(meta.horizon_hours ?? 96),
    initial_nodes,
    edges,
    feedback_loops,
    intel_bindings_list: Array.isArray(pack.intel_bindings) ? pack.intel_bindings : [],
    intel_sequence_list: Array.isArray(pack.intel_sequence) ? pack.intel_sequence : [],
    deadlines,
    hysteresis,
    levers
  };
}

function loadStaticDraftPreview(pack, analysis) {
  const m = pack.extended_causal_model;
  const meta = pack.meta || {};
  state.generatedScenario = analysis || null;
  state.currentTick = 0;
  state.throughputRatio = 1.0;
  state.frictionMu = 1.0;
  state.outageActive = false;
  state.tickHistory = [];
  state.scenarioMeta.scenarioId = String(pack.id || 'USER-SCENARIO');
  state.scenarioMeta.sector = String(pack.sector || 'UNIVERSAL');
  state.scenarioMeta.sigStatus = 'UNSIGNED_LOCAL_DRAFT';
  state.scenarioMeta.signatureScheme = 'UNSIGNED';
  state.scenarioMeta.metaSigned = false;
  state.scenarioMeta.tickMinutes = Number(meta.tick_minutes || 15);
  state.scenarioMeta.horizonHours = Number(meta.horizon_hours || 96);

  state.scenarioModel = extractScenarioModelFromPack(pack, 'UNSIGNED');
  state.engineLevers = state.scenarioModel.levers;
  state.causalNodes = (m.nodes || []).map(n => ({
    id: safeLabel(n.id || '?', 40),
    type: safeLabel(n.kind || n.type || 'Service', 24),
    state_fp: Number(n.state_fp !== undefined ? (n.state_fp > 2 ? n.state_fp / 1000000 : n.state_fp) : (n.state ?? 0.5)),
    reported_fp: Number(n.reported_state_fp !== undefined ? (n.reported_state_fp > 2 ? n.reported_state_fp / 1000000 : n.reported_state_fp) : (n.state_fp !== undefined ? (n.state_fp > 2 ? n.state_fp / 1000000 : n.state_fp) : 0.5)),
    trust_fp: Number(n.trust_fp !== undefined ? (n.trust_fp > 2 ? n.trust_fp / 1000000 : n.trust_fp) : (n.trust ?? 1.0)),
    friction_fp: Number(n.weight_fp !== undefined ? (n.weight_fp > 2 ? n.weight_fp / 1000000 : n.weight_fp) : 0.2),
    capacity_scale: 1.0,
    irrecoverable: false,
    outage_active: false
  }));
  state.causalEdges = (m.edges || []).filter(e => e.to).map(e => ({
    from: safeLabel(e.from || '', 40),
    to: safeLabel(e.to || '', 40),
    weight_fp: Number(e.multiplier_fp !== undefined ? (e.multiplier_fp > 10 ? e.multiplier_fp / 1000000 : e.multiplier_fp) : (e.weight ?? 0.5)),
    lag_ticks: Number(e.lag_ticks ?? 0)
  }));

  updateConnectionStatusPill('draft_preview');
  layoutCausalGraph();
  drawCausalGraph();
  drawCrisisTimeline();
  refreshEnterpriseWorkbench();
}

/* ═══════════════════════════════════════════════════════════════════════════
   5. IN-BROWSER WASM ENGINE BRIDGE (Optional Standalone Bundle Support)
   Uses real compiled Rust caelus_core via WebAssembly when window.CAELUS_WASM_B64
   is present (generated by tools/build_standalone.py).
   ═══════════════════════════════════════════════════════════════════════════ */
const WasmEngine = (function () {
  let ex = null;
  let activePack = null;
  let scenarioId = 'BS-01_SAHTE_UFUK';

  function u8() { return new Uint8Array(ex.memory.buffer); }
  function writeBuf(str) {
    const b = new TextEncoder().encode(str);
    const n = Math.min(b.length, ex.cae_buf_cap());
    u8().set(b.subarray(0, n), ex.cae_buf());
    return n;
  }
  function readBuf(len) {
    const p = ex.cae_buf();
    return new TextDecoder().decode(u8().slice(p, p + len));
  }
  function snapshot() { return JSON.parse(readBuf(ex.cae_snapshot())); }

  function resolveEmbeddedScenarioPack(id) {
    const map = window.CAELUS_SCENARIOS;
    if (!map || !map[id]) return null;
    try {
      return typeof map[id] === 'string' ? JSON.parse(map[id]) : map[id];
    } catch (_) {
      return null;
    }
  }

  function pushAll(quiet = false) {
    const snap = snapshot();
    handleEngineEvent({
      data: JSON.stringify({
        type: 'engine_state',
        state: scenarioId,
        scenario_id: scenarioId,
        tick: snap.tick,
        friction_mult: snap.clamped_friction,
        throughput_ratio: snap.throughput_ratio,
        outage_active: snap.outage_active,
        any_hysteresis_flip: snap.any_hysteresis_flip,
        any_deadline_missed: snap.any_deadline_missed,
        _quiet: quiet
      })
    });
    handleEngineEvent({ data: JSON.stringify({ ...snap, type: 'snapshot', _quiet: quiet }) });
    handleEngineEvent({ data: readBuf(ex.cae_levers()) });
    return snap;
  }

  return {
    get ready() { return !!ex; },
    async init() {
      if (ex) return true;
      if (!window.CAELUS_WASM_B64) return false;
      try {
        const bin = Uint8Array.from(atob(window.CAELUS_WASM_B64), c => c.charCodeAt(0));
        const { instance } = await WebAssembly.instantiate(bin, {});
        ex = instance.exports;
        return true;
      } catch (_) {
        return false;
      }
    },
    hasScenario(id) {
      return Boolean(resolveEmbeddedScenarioPack(id));
    },
    loadScenarioId(id) {
      const pack = resolveEmbeddedScenarioPack(id);
      if (!pack) return false;
      return this.loadPack(pack, { sigStatus: 'WASM_BUNDLE_UNVERIFIED_AT_RUNTIME' });
    },
    loadPack(pack, options = {}) {
      if (!ex || !pack) return false;
      const json = JSON.stringify(pack);
      if (ex.cae_load(writeBuf(json)) !== 0) return false;
      activePack = JSON.parse(json);
      scenarioId = String(pack.id || 'USER-SCENARIO');
      state.generatedScenario = options.analysis || null;
      state.tickHistory = [];
      const sigStatus = options.sigStatus || 'WASM_BUNDLE_UNVERIFIED_AT_RUNTIME';
      const meta = pack.meta || {};
      handleEngineEvent({
        data: JSON.stringify({
          type: 'scenario_loaded',
          id: scenarioId,
          scenario_id: scenarioId,
          sector: String(pack.sector || 'UNIVERSAL'),
          sig_status: sigStatus,
          signature_scheme: sigStatus === 'UNSIGNED_LOCAL_DRAFT' ? 'UNSIGNED' : 'WASM_BUNDLE',
          meta_signed: false,
          tick_minutes: Number(meta.tick_minutes ?? 15),
          horizon_hours: Number(meta.horizon_hours ?? 96)
        })
      });
      handleEngineEvent({
        data: JSON.stringify(extractScenarioModelFromPack(pack, sigStatus === 'UNSIGNED_LOCAL_DRAFT' ? 'UNSIGNED' : 'WASM_BUNDLE'))
      });
      pushAll(false);
      return true;
    },
    command(cmdLine) {
      if (!ex) return false;
      const parts = String(cmdLine || '').trim().split(/\s+/);
      const c = (parts[0] || '').toLowerCase();
      if (c === 'tick') {
        const n = Math.max(1, Math.min(10000, parseInt(parts[1] || '1', 10) || 1));
        ex.cae_tick(n);
        pushAll(false);
      } else if (c === 'lever') {
        ex.cae_lever(writeBuf(parts[1] || ''));
        pushAll(false);
      } else if (c === 'scenario' || c === 'load') {
        const targetId = parts.slice(1).join(' ');
        this.loadScenarioId(targetId);
      } else if (c === 'reset' && activePack) {
        this.loadPack(activePack, { analysis: state.generatedScenario, sigStatus: state.scenarioMeta.sigStatus });
      } else {
        pushAll(false);
      }
      return true;
    }
  };
})();

/* ═══════════════════════════════════════════════════════════════════════════
   6. LIVE C++ WEBSOCKET BRIDGE (ws://127.0.0.1:47809)
   ═══════════════════════════════════════════════════════════════════════════ */
function resolveWsUrl() {
  const params = new URLSearchParams(window.location.search || '');
  const rawPort = params.get('ws_port') || params.get('wsPort') || window.CAELUS_WS_PORT || window.location.port || '47809';
  const port = String(rawPort).match(/^\d{1,5}$/) ? clamp(Number(rawPort), 1, 65535) : 47809;
  const servedOverHttp = window.location.protocol === 'http:' || window.location.protocol === 'https:';
  const host = servedOverHttp && window.location.hostname ? window.location.hostname : '127.0.0.1';
  const token = params.get('token');
  const query = token ? ('/?token=' + encodeURIComponent(token)) : '';
  return `ws://${host}:${port}${query}`;
}

const WS_URL = resolveWsUrl();
let liveWs = null;

function updateSimulationButtonsState() {
  const canSimulate = state.engineMode === 'ws' || state.engineMode === 'wasm';
  [el.btnStep1, el.btnStep4, el.btnStep24, el.btnAutoSim, el.btnSimReset, el.btnAutoSolve, el.btnClearOutage].forEach(btn => {
    if (btn) btn.disabled = !canSimulate;
  });
  if (el.btnRunCompareLever) {
    el.btnRunCompareLever.disabled = state.engineMode !== 'ws';
  }
}

function formatHumanDateTime(isoOrText, localeCode) {
  const raw = String(isoOrText || '').trim();
  if (!raw || raw === '—' || raw === 'null') return 'Belirtilmedi';
  // Extract ISO-8601 prefix if embedded in text
  const isoMatch = raw.match(/^(\d{4}-\d{2}-\d{2})[T\s](\d{2}:\d{2})(?::(\d{2}))?(?:\.\d+)?Z?/);
  if (!isoMatch) return raw;
  const [, datePart, hmPart] = isoMatch;
  const [y, m, d] = datePart.split('-').map(Number);
  const loc = String(localeCode || (state && state.activeLocaleCode) || 'tr-TR').toLowerCase();
  const monthsTr = ['Oca', 'Şub', 'Mar', 'Nis', 'May', 'Haz', 'Tem', 'Ağu', 'Eyl', 'Eki', 'Kas', 'Ara'];
  const monthsEn = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const mIdx = Math.max(0, Math.min(11, (m || 1) - 1));
  const mName = loc.startsWith('en') ? monthsEn[mIdx] : monthsTr[mIdx];
  return `${d} ${mName} ${y} ${hmPart} UTC`;
}

function updateConnectionStatusPill(mode) {
  state.engineMode = mode;
  updateSimulationButtonsState();
  if (!el.livePill || !el.liveWatermark) return;

  if (mode === 'ws') {
    el.livePill.className = 'engine-pill live';
    el.livePill.textContent = '● Canlı Hesaplama';
    el.liveWatermark.textContent = 'Hesaplama Motoru: Bağlı ve Hazır';
    if (el.engineOfflineBanner) el.engineOfflineBanner.classList.add('hidden');
  } else if (mode === 'wasm') {
    el.livePill.className = 'engine-pill wasm';
    el.livePill.textContent = '● Yerel Hesaplama';
    el.liveWatermark.textContent = 'Hesaplama Motoru: Tarayıcı İçi Yerel Çekirdek';
    if (el.engineOfflineBanner) el.engineOfflineBanner.classList.add('hidden');
  } else if (mode === 'draft_preview') {
    el.livePill.className = 'engine-pill';
    el.livePill.textContent = '● Başlangıç Görünümü';
    el.liveWatermark.textContent = 'Görünüm Modu: Yerel Taslak Önizlemesi';
    if (el.engineOfflineBanner) {
      el.engineOfflineBanner.classList.remove('hidden');
      if (el.engineOfflineDetail) {
        el.engineOfflineDetail.textContent = 'Derlenen/yüklenen taslak modelin başlangıç topolojisi (Adım 0) görüntüleniyor. Canlı C++/Rust veya WASM motoru bağlı olmadığı için adım ilerletme (tick) çalıştırılmaz; kapasite/sürtünme simülasyon sonucu değildir.';
      }
    }
  } else if (mode === 'disconnected_stale') {
    el.livePill.className = 'engine-pill';
    el.livePill.textContent = '● Son Bilinen Durum';
    el.liveWatermark.textContent = `Uyarı: Motor Bağlantısı Kesildi · Son Bilinen Veri (Adım ${state.currentTick})`;
    if (el.engineOfflineBanner) {
      el.engineOfflineBanner.classList.remove('hidden');
      if (el.engineOfflineDetail) {
        el.engineOfflineDetail.textContent = `Canlı C++/Rust motor bağlantısı kesildi. Ekrandaki düğüm ve kapasite değerleri Adım ${state.currentTick} anındaki son bilinen TARİHSEL VERİDİR; canlı simülasyon akışı durmuştur.`;
      }
    }
  } else {
    el.livePill.className = 'engine-pill';
    el.livePill.textContent = '● Çevrimdışı Görünüm';
    el.liveWatermark.textContent = 'Hesaplama Motoru: Çevrimdışı Görünüm';
    if (el.engineOfflineBanner) {
      el.engineOfflineBanner.classList.remove('hidden');
      if (el.engineOfflineDetail) {
        el.engineOfflineDetail.textContent = 'Canlı C++/Rust motoru (ws://127.0.0.1:47809) veya gömülü WASM çekirdeği bağlı değil. Yanıltıcı sonuç üretmemek adına yerel JS taklit modeli çalıştırılmaz. Motoru başlatmak için: dist\\caelus_os.exe --scenario BS-01_SAHTE_UFUK --repl';
      }
    }
  }
  updateGuidedNextStepBanner(state.lastEvaluation);
}

function connectLiveBridge() {
  if (liveWs && liveWs.readyState <= WebSocket.OPEN) return;
  try {
    liveWs = new WebSocket(WS_URL);
  } catch (_) {
    setTimeout(connectLiveBridge, CFG.WS_RECONNECT_MS);
    return;
  }

  liveWs.onopen = () => {
    state.staleDisconnected = false;
    updateConnectionStatusPill('ws');
    liveWs.send('load_world');
    if (state.digitalWorldStore && state.digitalWorldStore.userActivatedWorld && typeof restoreActiveDigitalWorldToEngine === 'function') {
      restoreActiveDigitalWorldToEngine(false);
    } else {
      liveWs.send('status');
      liveWs.send('list levers');
    }
    addAuditLog('ok', `C++/Rust nedensel motor köprüsü bağlandı (${WS_URL}).`);
  };

  liveWs.onmessage = handleEngineEvent;

  liveWs.onclose = () => {
    const wasConnected = state.engineMode === 'ws';
    liveWs = null;
    if (WasmEngine.ready) {
      state.staleDisconnected = false;
      updateConnectionStatusPill('wasm');
    } else if (state.engineMode === 'draft_preview' || state.generatedScenario) {
      state.staleDisconnected = false;
      updateConnectionStatusPill('draft_preview');
    } else if (wasConnected && state.causalNodes.length > 0) {
      state.staleDisconnected = true;
      updateConnectionStatusPill('disconnected_stale');
      addAuditLog('warn', `Canlı C++/Rust motor bağlantısı kesildi; Adım ${state.currentTick} verileri TARİHSEL VERİ olarak işaretlendi.`);
      refreshEnterpriseWorkbench();
    } else {
      state.staleDisconnected = false;
      state.causalNodes = [];
      state.causalEdges = [];
      state.engineLevers = [];
      state.scenarioModel = null;
      state.scenarioMeta.sigStatus = 'UNVERIFIED_OFFLINE';
      updateConnectionStatusPill('offline');
      if (wasConnected) {
        addAuditLog('warn', 'Canlı C++/Rust motor bağlantısı kesildi; çevrimdışı bekleme moduna geçildi.');
      }
      refreshEnterpriseWorkbench();
    }
    setTimeout(connectLiveBridge, CFG.WS_RECONNECT_MS);
  };

  liveWs.onerror = () => { };
}

function sendEngineCommand(cmd) {
  const clean = String(cmd || '').trim();
  if (!clean) return;
  addReplLine(`> ${clean}`, 'cmd');

  if (liveWs && liveWs.readyState === WebSocket.OPEN) {
    if (state.engineMode === 'draft_preview') {
      state.generatedScenario = null;
      updateConnectionStatusPill('ws');
    }
    liveWs.send(clean);
    return;
  }
  if (WasmEngine.ready) {
    WasmEngine.command(clean);
    return;
  }
  addReplLine('[HATA] Gerçek C++/Rust motoru (ws://127.0.0.1:47809) veya WASM çekirdeği bağlı değil. Farklı bir yerel JS modeli gerçek motor gibi çalıştırılmaz.', 'err');
  addAuditLog('err', `KOMUT REDDEDİLDİ (${clean}): Gerçek motor bağlantısı yok.`);
}

function loadScenarioById(scenarioId) {
  if (!KNOWN_SIGNED_SCENARIO_IDS.has(scenarioId) && typeof openSavedTwinModelById === 'function') {
    const savedLib = typeof loadSavedModelsLibrary === 'function' ? loadSavedModelsLibrary() : {};
    if (savedLib && savedLib[scenarioId]) {
      openSavedTwinModelById(scenarioId);
      return;
    }
  }

  state.generatedScenario = null;
  state.lastEngineCounterfactual = null;
  state.derivedFromSignedScenario = null;
  state.pendingHistoricalRun = null;
  state.lastHistoricalComparison = null;
  state.staleDisconnected = false;
  state.scenarioMeta.scenarioId = scenarioId;
  state.tickHistory = [];
  state.preserveDiffOnNextLoad = false;
  state.lastDiffReport = null;
  state.lastDiffByNodeId = {};
  if (el.dtDiffBanner) el.dtDiffBanner.classList.add('hidden');
  if (el.dtPreviewBox) el.dtPreviewBox.classList.add('hidden');
  if (el.signedModifiedBanner) el.signedModifiedBanner.classList.add('hidden');
  if (el.histResultsBox) el.histResultsBox.classList.add('hidden');

  if (el.scenarioSelect && el.scenarioSelect.value !== scenarioId) {
    const exists = Array.from(el.scenarioSelect.options).some(o => o.value === scenarioId);
    if (exists) el.scenarioSelect.value = scenarioId;
  }

  if (liveWs && liveWs.readyState === WebSocket.OPEN) {
    updateConnectionStatusPill('ws');
    liveWs.send(`scenario ${scenarioId}`);
    liveWs.send('status');
    liveWs.send('list levers');
    addAuditLog('info', `Canlı motordan senaryo talep edildi: ${scenarioId}`);
  } else if (WasmEngine.ready && WasmEngine.hasScenario(scenarioId)) {
    updateConnectionStatusPill('wasm');
    WasmEngine.loadScenarioId(scenarioId);
    addAuditLog('info', `WASM çekirdeğinde senaryo yüklendi: ${scenarioId}`);
  } else {
    state.causalNodes = [];
    state.causalEdges = [];
    state.engineLevers = [];
    state.scenarioModel = null;
    state.scenarioMeta.sigStatus = 'UNVERIFIED_OFFLINE';
    updateConnectionStatusPill('offline');
    refreshEnterpriseWorkbench();
    addAuditLog('warn', `Senaryo seçildi (${scenarioId}) ancak gerçek motor bağlı değil; bağlantı bekleniyor.`);
  }
}

/* ═══════════════════════════════════════════════════════════════════════════
   7. ENGINE EVENT ROUTER & ENTERPRISE WORKBENCH RENDERER
   ═══════════════════════════════════════════════════════════════════════════ */
function handleEngineEvent(ev) {
  let data;
  try {
    const raw = String(ev.data || '').trim();
    const clean = raw.startsWith('[REPL_JSON]') ? raw.slice(11).trim() : raw;
    data = JSON.parse(clean);
  } catch (_) {
    return;
  }
  if (!data || typeof data !== 'object') return;

  // Prevent background WS telemetry from overwriting an active Studio Draft Preview
  if (state.engineMode === 'draft_preview' && !WasmEngine.ready) {
    return;
  }
  if (state.staleDisconnected && liveWs && liveWs.readyState === WebSocket.OPEN) {
    state.staleDisconnected = false;
    updateConnectionStatusPill('ws');
  }

  const evType = String(data.type || data.event || '').toLowerCase();

  if (evType === 'neural_observation') {
    applyNeuralObservation(data);
    return;
  }

  if (evType === 'world_store_loaded') {
    if (typeof handleRemoteWorldStoreLoaded === 'function') {
      handleRemoteWorldStoreLoaded(data);
    }
    return;
  }

  if (evType === 'world_store_saved') {
    if (el.dwPersistenceBadge) {
      el.dwPersistenceBadge.textContent = `💾 DEPO: YEREL DİSK (${data.file || 'caelus_world_store.json'}) + TARAYICI SENKRON`;
      el.dwPersistenceBadge.className = 'kpi-badge ok';
    }
    return;
  }

  if (evType === 'scenario_loaded' || data.scenario_pack) {
    if (state.pendingHistoricalRun || state.pendingWorldBranchRun) return;
    const scId = data.id || data.scenario_id;
    if (scId && scId !== state.scenarioMeta.scenarioId) {
      state.lastEngineCounterfactual = null;
    }
    if (scId) state.scenarioMeta.scenarioId = String(scId);
    if (data.sector || data.region) state.scenarioMeta.sector = String(data.sector || data.region);
    if (data.sig_status) {
      state.scenarioMeta.sigStatus = String(data.sig_status);
    } else if (state.engineMode === 'ws' && KNOWN_SIGNED_SCENARIO_IDS.has(state.scenarioMeta.scenarioId)) {
      state.scenarioMeta.sigStatus = 'VERIFIED_V1_META_UNSIGNED';
    }
    if (data.signature_scheme) state.scenarioMeta.signatureScheme = String(data.signature_scheme);
    if (data.meta_signed !== undefined) state.scenarioMeta.metaSigned = Boolean(data.meta_signed);
    if (data.pubkey_trusted !== undefined) state.scenarioMeta.pubkeyTrusted = Boolean(data.pubkey_trusted);
    if (data.audit_active !== undefined) state.scenarioMeta.auditActive = Boolean(data.audit_active);
    if (data.audit_entries !== undefined) state.scenarioMeta.auditEntries = Number(data.audit_entries);
    if (data.audit_chain_head !== undefined) state.scenarioMeta.auditChainHead = String(data.audit_chain_head);
    if (data.tick_minutes !== undefined) state.scenarioMeta.tickMinutes = Number(data.tick_minutes);
    if (data.horizon_hours !== undefined) state.scenarioMeta.horizonHours = Number(data.horizon_hours);
    refreshEnterpriseWorkbench();
    return;
  }

  if (evType === 'scenario_model') {
    if (state.pendingHistoricalRun || state.pendingWorldBranchRun || state.pendingIncidentEngineRun) return;
    const isSameTwin = Boolean(state.twinState && state.twinState.scenarioId === data.scenario_id);
    // Preserve rich user twinState metadata (units, timestamps, assumptions, importHistory) when active model matches
    if (isSameTwin) {
      const ts = state.twinState;
      data.title = data.title || ts.title;
      data.sector_label = data.sector_label || ts.sectorLabel;
      data.synopsis = data.synopsis || ts.synopsis;
      data.data_provenance = ts.dataProvenance || data.data_provenance;
      data.assumptions = Array.isArray(ts.assumptions) && ts.assumptions.length > 0 ? ts.assumptions : data.assumptions;
      data.data_gaps = Array.isArray(ts.dataGaps) && ts.dataGaps.length > 0 ? ts.dataGaps : data.data_gaps;
      data.import_history = Array.isArray(ts.importHistory) ? ts.importHistory : [];
      if (ts.financials) {
        data.financials = {
          available: Boolean(ts.financials.available),
          currency: 'USD',
          unit_label: ts.financials.unitName || 'Birim/Saat',
          unit_name: ts.financials.unitName || 'Birim/Saat',
          baseline_units: Number(ts.financials.baselineUnitsPerHour || 100),
          baseline_units_per_hour: Number(ts.financials.baselineUnitsPerHour || 100),
          downtime_cost_per_hour_usd: Number(ts.financials.hourlyDowntimeCostUsd || 0),
          hourly_downtime_cost_usd: Number(ts.financials.hourlyDowntimeCostUsd || 0),
          sla_breach_penalty_usd: Number(ts.financials.slaBreachPenaltyUsd || 0),
          source_note: ts.financials.sourceNote || ''
        };
      }
      if (Array.isArray(data.initial_nodes) && Array.isArray(ts.nodes)) {
        data.initial_nodes.forEach(n => {
          const tn = ts.nodes.find(x => x.id === n.id);
          if (tn) {
            n.label = tn.label || n.label;
            n.category = tn.category || n.category;
            n.unit = tn.unit || n.unit;
            n.data_source = tn.dataSource || n.data_source;
            n.timestamp = tn.timestamp || n.timestamp;
            n.deadline_min_state = (Number(tn.deadlineMinStatePct ?? 65) / 100);
          }
        });
      }
      if (Array.isArray(data.levers) && Array.isArray(ts.levers)) {
        data.levers.forEach(lv => {
          const tl = ts.levers.find(x => x.id === lv.id);
          if (tl) {
            lv.label = tl.label || lv.label;
            lv.cost_usd = tl.costUsd ?? lv.cost_usd;
            lv.data_source = tl.dataSource || lv.data_source;
            lv.notes = tl.notes || lv.notes;
          }
        });
      }
    }
    state.scenarioModel = data;
    if (data.scenario_id) state.scenarioMeta.scenarioId = String(data.scenario_id);
    if (data.sector) state.scenarioMeta.sector = String(data.sector);
    if (data.pubkey_trusted !== undefined) state.scenarioMeta.pubkeyTrusted = Boolean(data.pubkey_trusted);
    if (data.audit_active !== undefined) state.scenarioMeta.auditActive = Boolean(data.audit_active);
    if (data.audit_entries !== undefined) state.scenarioMeta.auditEntries = Number(data.audit_entries);
    if (data.audit_chain_head !== undefined) state.scenarioMeta.auditChainHead = String(data.audit_chain_head);
    if (data.signature_scheme) {
      state.scenarioMeta.signatureScheme = String(data.signature_scheme);
      const pinned = state.scenarioMeta.pubkeyTrusted;
      if (data.signature_scheme === 'V3') state.scenarioMeta.sigStatus = pinned ? 'VERIFIED_V3' : 'VERIFIED_V3_UNPINNED_KEY';
      else if (data.signature_scheme === 'V2') state.scenarioMeta.sigStatus = pinned ? 'VERIFIED_V2' : 'VERIFIED_V2_UNPINNED_KEY';
      else if (data.signature_scheme === 'V1') state.scenarioMeta.sigStatus = pinned ? 'VERIFIED_V1_META_UNSIGNED' : 'VERIFIED_V1_UNPINNED_KEY';
      else if (data.signature_scheme === 'DEV_UNSIGNED') state.scenarioMeta.sigStatus = 'DEV_UNSIGNED';
    }
    if (data.meta_signed !== undefined) state.scenarioMeta.metaSigned = Boolean(data.meta_signed);
    if (data.tick_minutes !== undefined) state.scenarioMeta.tickMinutes = Number(data.tick_minutes);
    if (data.horizon_hours !== undefined) state.scenarioMeta.horizonHours = Number(data.horizon_hours);
    if (Array.isArray(data.levers) && data.levers.length > 0) {
      state.engineLevers = data.levers;
    }
    if (!isSameTwin) {
      syncTwinEditorFromCurrentModel(true);
    } else {
      renderTwinEditorForms();
    }
    if (typeof ensureDigitalWorldForCurrentModel === 'function') {
      ensureDigitalWorldForCurrentModel();
    }
    state.preserveDiffOnNextLoad = false;
    refreshEnterpriseWorkbench();
    return;
  }

  if (evType === 'counterfactual_result') {
    state.lastEngineCounterfactual = data;
    const ba = data.branch_a || {};
    const bb = data.branch_b || {};
    const tpA = Math.round(Number(ba.throughput_ratio ?? 0) * 100);
    const tpB = Math.round(Number(bb.throughput_ratio ?? 0) * 100);
    addAuditLog(
      'ok',
      `SENARYO MOTOR KOŞUMU (${data.lever_id} · +${data.horizon_ticks}t · Tohum:${data.seed}): Değişiklik yapılmazsa %${tpA} vs Değişiklik yapılırsa %${tpB}`
    );
    addReplLine(
      `[İKİ DURUM KARŞILAŞTIRMASI] Seçenek=${data.lever_id} Ufuk=+${data.horizon_ticks}t Tohum=${data.seed} | Değişiklik yapılmazsa: %${tpA} (Kesinti:${ba.outage_active}) | Değişiklik yapılırsa: %${tpB} (Kesinti:${bb.outage_active})`,
      'ok'
    );

    const compiler = window.CaelusScenarioCompiler;
    if (state.pendingIncidentEngineRun && typeof completePendingIncidentEngineRun === 'function') {
      completePendingIncidentEngineRun(data);
      return;
    }

    if (state.pendingRealDataSnapshotRun && typeof completePendingRealDataSnapshotRun === 'function') {
      completePendingRealDataSnapshotRun(data);
      return;
    }

    if (state.pendingWorldBranchRun && typeof completePendingWorldBranchRun === 'function') {
      completePendingWorldBranchRun(data);
      return;
    }

    if (state.pendingHistoricalRun && compiler && typeof compiler.evaluateHistoricalComparison === 'function') {
      const pendingPrep = state.pendingHistoricalRun;
      state.pendingHistoricalRun = null;
      const histReport = compiler.evaluateHistoricalComparison(pendingPrep, data, state.twinState);
      state.lastHistoricalComparison = histReport;
      renderHistoricalComparisonResults(histReport);
      addAuditLog(
        'ok',
        `GEÇMİŞ OLAY KARŞILAŞTIRMASI (${histReport.incidentId}): ${histReport.comparableNodeCount}/${histReport.totalModelNodes} varlık karşılaştırıldı, ${histReport.uncomparableCount} karşılaştırılamayan alan raporlandı.`
      );
      if (liveWs && liveWs.readyState === WebSocket.OPEN && state.twinState) {
        const restorePack = compiler.buildScenarioPackFromTwin(state.twinState);
        state.preserveDiffOnNextLoad = true;
        liveWs.send(`load_json ${JSON.stringify(restorePack)}`);
        setTimeout(() => {
          if (liveWs && liveWs.readyState === WebSocket.OPEN) {
            liveWs.send('status');
          }
        }, 60);
      }
      refreshEnterpriseWorkbench();
      return;
    }

    refreshEnterpriseWorkbench();
    if (typeof window.focusCaelusScenarioStep === 'function') {
      window.focusCaelusScenarioStep('3', { skipScroll: true });
    }
    if (state.activeQuietView === 'senaryolar') {
      window.scrollTo({ top: 0, behavior: 'instant' });
    }
    return;
  }

  if (evType === 'lever_result') {
    const ok = Boolean(data.success);
    const fb = Number(data.friction_before ?? state.frictionMu).toFixed(3);
    const fa = Number(data.friction_after ?? state.frictionMu).toFixed(3);
    const tb = Math.round(Number(data.throughput_before ?? state.throughputRatio) * 100);
    const ta = Math.round(Number(data.throughput_after ?? state.throughputRatio) * 100);
    addAuditLog(
      ok ? 'ok' : 'warn',
      `KALDIRAÇ SONUCU (${data.lever_id}): ${ok ? 'BAŞARILI' : 'BAŞARISIZ/KİLİTLİ'} · Sürtünme ${fb}x → ${fa}x · Kapasite %${tb} → %${ta}`
    );
    addReplLine(
      `[MOTOR] Kaldıraç ${data.lever_id}: ${ok ? 'BAŞARILI' : 'BAŞARISIZ/KİLİTLİ'} (Sürtünme ${fb}x -> ${fa}x, Kapasite %${tb} -> ${ta}%)`,
      ok ? 'ok' : 'err'
    );
    return;
  }

  if (evType === 'engine_state' || data.state) {
    if (data.scenario_id && data.scenario_id !== 'LIVE') {
      state.scenarioMeta.scenarioId = String(data.scenario_id);
    }
    if (data.tick !== undefined) state.currentTick = Number(data.tick);
    if (data.friction_mult !== undefined) state.frictionMu = clamp(Number(data.friction_mult), 1, 3);
    if (data.throughput_ratio !== undefined) state.throughputRatio = clamp(Number(data.throughput_ratio), 0, 1);
    if (data.outage_active !== undefined) state.outageActive = Boolean(data.outage_active);
    state.delayHours = Math.max(0, (state.frictionMu - 1) * 7.5);

    pushTickHistory(
      state.currentTick,
      state.throughputRatio,
      state.frictionMu,
      state.outageActive,
      Boolean(data.any_hysteresis_flip),
      Boolean(data.any_deadline_missed)
    );
    refreshEnterpriseWorkbench();
    return;
  }

  if (evType === 'snapshot' || Array.isArray(data.nodes)) {
    if (data.scenario_id) state.scenarioMeta.scenarioId = String(data.scenario_id);
    if (data.tick !== undefined) state.currentTick = Number(data.tick);
    if (data.clamped_friction !== undefined) state.frictionMu = clamp(Number(data.clamped_friction), 1, 3);
    if (data.throughput_ratio !== undefined) state.throughputRatio = clamp(Number(data.throughput_ratio), 0, 1);
    if (data.outage_active !== undefined) state.outageActive = Boolean(data.outage_active);
    if (data.intel_events_total !== undefined) state.intelEventsTotal = Number(data.intel_events_total);
    if (data.intel_events_unbound !== undefined) state.intelEventsUnbound = Number(data.intel_events_unbound);

    if (Array.isArray(data.nodes)) {
      state.causalNodes = data.nodes.map(n => ({
        id: safeLabel(n.id || n.node_id || '?', 40),
        type: safeLabel(n.type || n.kind || 'Service', 24),
        state_fp: Number(n.state_fp ?? n.state ?? 0),
        reported_fp: Number(n.reported_fp ?? n.reported ?? n.state_fp ?? n.state ?? 0),
        trust_fp: Number(n.trust_fp ?? n.trust ?? 1),
        friction_fp: Number(n.friction_fp ?? n.friction ?? 0.2),
        capacity_scale: clamp(Number(n.capacity_fp ?? n.capacity ?? 1), 0.5, 2.0),
        irrecoverable: Boolean(n.irrecoverable),
        outage_active: Boolean(n.outage_active)
      }));
    }
    if (Array.isArray(data.edges)) {
      state.causalEdges = data.edges.map(e => ({
        from: safeLabel(e.from || e.source || '', 40),
        to: safeLabel(e.to || e.target || '', 40),
        weight_fp: Number(e.weight_fp ?? e.weight ?? 0.5),
        lag_ticks: Number(e.lag_ticks ?? 0)
      }));
    }

    pushTickHistory(
      state.currentTick,
      state.throughputRatio,
      state.frictionMu,
      state.outageActive,
      Boolean(data.any_hysteresis_flip),
      Boolean(data.deadline_missed)
    );
    layoutCausalGraph();
    drawCausalGraph();
    refreshEnterpriseWorkbench();
    return;
  }

  if (evType === 'levers' || Array.isArray(data.levers)) {
    state.engineLevers = Array.isArray(data.levers) ? data.levers : [];
    refreshEnterpriseWorkbench();
    return;
  }

  if (evType === 'friction') {
    if (data.value !== undefined) state.frictionMu = clamp(Number(data.value), 1, 3);
    if (data.tick !== undefined) state.currentTick = Number(data.tick);
    pushTickHistory(state.currentTick, state.throughputRatio, state.frictionMu, state.outageActive, false, false);
    refreshEnterpriseWorkbench();
    return;
  }

  if (evType === 'optimization') {
    const onTime = Boolean(data.on_time);
    addAuditLog(onTime ? 'ok' : 'warn', `ÇÖZÜCÜ RAPORU: SLA Durumu=${onTime ? 'ZAMANINDA' : 'GECİKME RİSKİ'} · Çarpan=${Number(data.friction_mult || state.frictionMu).toFixed(2)}x`);
    return;
  }

  if (evType === 'regime_exceeded') {
    addAuditLog('err', `MODEL REJİM UYARISI: Ham sürtünme talebi (${Number(data.raw_multiplier || 3).toFixed(2)}x) 3.0x model tavanını aştı.`);
  }
}

function pushTickHistory(tick, ratio, friction, outage, hysFlip, deadlineMiss) {
  const last = state.tickHistory[state.tickHistory.length - 1];
  if (last && last.tick === tick) {
    last.ratio = ratio;
    last.friction = friction;
    last.outage = outage;
    last.hysFlip = last.hysFlip || hysFlip;
    last.deadlineMiss = last.deadlineMiss || deadlineMiss;
  } else {
    state.tickHistory.push({ tick, ratio, friction, outage, hysFlip, deadlineMiss });
    if (state.tickHistory.length > CFG.TICK_HISTORY_MAX) state.tickHistory.shift();
  }
  if (el.ctTickBadge) {
    el.ctTickBadge.textContent = `ADIM: ${tick} · ${state.tickHistory.length} kayıt`;
  }
  drawCrisisTimeline();
}

/* ═══════════════════════════════════════════════════════════════════════════
   8. MASTER WORKBENCH UI RENDERING (KPIs, Tables, Horizons, ROI, Policies)
   ═══════════════════════════════════════════════════════════════════════════ */
function updateTrustStateMatrixUI(activeStateKey, pillLabel, pillTone) {
  if (el.dtActiveTrustPill) {
    el.dtActiveTrustPill.textContent = `AKTİF SINIF: ${pillLabel}`;
    el.dtActiveTrustPill.className = `kpi-badge ${pillTone || 'warn'}`;
  }
  const cardMap = {
    draft: el.trustCardDraft,
    unsigned: el.trustCardUnsigned,
    testkey: el.trustCardTestkey,
    trusted: el.trustCardTrusted
  };
  Object.entries(cardMap).forEach(([key, cardEl]) => {
    if (!cardEl) return;
    const isActive = key === activeStateKey;
    cardEl.style.borderWidth = isActive ? '2px' : '1px';
    cardEl.style.borderColor = isActive
      ? (key === 'trusted' ? 'var(--ok)' : 'var(--accent)')
      : 'var(--border)';
    cardEl.style.background = isActive
      ? 'rgba(0, 212, 255, 0.11)'
      : 'var(--bg-0)';
    cardEl.style.boxShadow = isActive
      ? '0 0 14px rgba(0, 212, 255, 0.18)'
      : 'none';
  });
}

function renderSignatureAndGovernanceBadges(profile, compiler) {
  const sig = state.scenarioMeta.sigStatus || 'UNVERIFIED_OFFLINE';
  const keyTrusted = Boolean(state.scenarioMeta.pubkeyTrusted);
  const auditActive = Boolean(state.scenarioMeta.auditActive);
  const auditEntries = Number(state.scenarioMeta.auditEntries || 0);
  const auditHead = String(state.scenarioMeta.auditChainHead || '');

  if (state.engineMode === 'offline') {
    if (el.scSigBadge) {
      el.scSigBadge.textContent = 'DOĞRULANMADI (MOTOR YOK)';
      el.scSigBadge.className = 'kpi-badge warn';
    }
    if (el.govIntegrityBadge) {
      el.govIntegrityBadge.textContent = 'MOTOR BAĞLI DEĞİL';
      el.govIntegrityBadge.className = 'kpi-badge warn';
    }
    if (el.govSigStatus) el.govSigStatus.textContent = 'Motor Bağlantısı Yok';
    if (el.govKeyTrust) el.govKeyTrust.textContent = 'Doğrulanmadı (Çevrimdışı)';
    if (el.govAuditStatus) el.govAuditStatus.textContent = 'Doğrulanmadı (Çevrimdışı)';
    if (el.govStateHash) el.govStateHash.textContent = 'int64 × 10⁶ · Veri Yok';
    updateTrustStateMatrixUI('draft', '1. TASLAK (MOTOR BAĞLI DEĞİL)', 'warn');
    return;
  }

  // 1. Senaryo İmza Durumu (V3 / V2 / V1 / WASM / Draft)
  const isV3 = sig === 'VERIFIED_V3' || sig === 'VERIFIED_V3_UNPINNED_KEY';
  const isV2 = sig === 'VERIFIED_V2' || sig === 'VERIFIED_V2_UNPINNED_KEY';
  const isV1 = sig === 'VERIFIED_V1_META_UNSIGNED' || sig === 'VERIFIED_V1_UNPINNED_KEY' || sig === 'VERIFIED (Ed25519)';
  const isSigned = isV3 || isV2 || isV1;

  if (state.engineMode === 'draft_preview' || state.engineMode === 'disconnected_stale' || state.staleDisconnected) {
    updateTrustStateMatrixUI('draft', '1. TASLAK (SİMÜLASYON YOK / BAĞLANTI KESİK)', 'warn');
  } else if (isSigned && keyTrusted) {
    updateTrustStateMatrixUI('trusted', `4. GÜVENİLEN İMZALI (Pinli ${isV3 ? 'V3' : isV2 ? 'V2' : 'V1'})`, 'ok');
  } else if (isSigned && !keyTrusted) {
    updateTrustStateMatrixUI('testkey', `3. TEST ANAHTARLI (Pinli Değil · ${isV3 ? 'V3' : isV2 ? 'V2' : 'V1'})`, 'warn');
  } else {
    updateTrustStateMatrixUI('unsigned', '2. İMZASIZ (DEV_UNSIGNED — Etkileşimli Mod)', 'warn');
  }

  if (isV3) {
    if (el.scSigBadge) {
      el.scSigBadge.textContent = keyTrusted ? '✓ ED25519 V3 (TAM KAPSAM)' : '⚠ ED25519 V3 (TEST ANAHTARI)';
      el.scSigBadge.className = 'kpi-badge ' + (keyTrusted ? 'ok' : 'warn');
    }
    if (el.govSigStatus) {
      el.govSigStatus.textContent = 'Ed25519 V3 Doğrulandı (Graf + meta + üstveri imzalı)';
    }
  } else if (isV2) {
    if (el.scSigBadge) {
      el.scSigBadge.textContent = keyTrusted ? '✓ ED25519 V2 (TAM)' : '⚠ ED25519 V2 (TEST ANAHTARI)';
      el.scSigBadge.className = 'kpi-badge ' + (keyTrusted ? 'ok' : 'warn');
    }
    if (el.govSigStatus) {
      el.govSigStatus.textContent = 'Ed25519 V2 Doğrulandı (Graf + meta imzalı)';
    }
  } else if (isV1) {
    if (el.scSigBadge) {
      el.scSigBadge.textContent = '⚠ ED25519 (V1 · meta İMZASIZ)';
      el.scSigBadge.className = 'kpi-badge warn';
    }
    if (el.govSigStatus) {
      el.govSigStatus.textContent = 'Ed25519 V1 (Graf imzalı; meta/tick_minutes imzasız)';
    }
  } else if (sig === 'WASM_BUNDLE_UNVERIFIED_AT_RUNTIME') {
    if (el.scSigBadge) {
      el.scSigBadge.textContent = '⚠ WASM PAKETİ (DERLEME PINLİ)';
      el.scSigBadge.className = 'kpi-badge warn';
    }
    if (el.govSigStatus) {
      el.govSigStatus.textContent = 'WASM Gömülü Paket (Çalışma zamanı Ed25519 doğrulaması yok)';
    }
  } else if (state.derivedFromSignedScenario) {
    if (el.scSigBadge) {
      el.scSigBadge.textContent = `⚠ İMZASI DÜŞÜRÜLDÜ (${state.derivedFromSignedScenario} → TASLAK YENİ SÜRÜM · DEV_UNSIGNED)`;
      el.scSigBadge.className = 'kpi-badge warn';
    }
    if (el.govSigStatus) {
      el.govSigStatus.textContent = `İmzalı Senaryodan (${state.derivedFromSignedScenario}) Türetilen İmzasız Yerel Taslak / Yeni Sürüm (DEV_UNSIGNED)`;
    }
    if (el.signedModifiedBanner) {
      el.signedModifiedBanner.classList.remove('hidden');
      if (el.signedModifiedTitle) {
        el.signedModifiedTitle.textContent = `⚠️ İmzalı Senaryo (${state.derivedFromSignedScenario}) Değiştirildi — Mevcut Kriptografik İmza Artık Geçerli Gösterilmez`;
      }
      if (el.signedModifiedDetail) {
        el.signedModifiedDetail.textContent =
          `Orijinal imzalı senaryo (${state.derivedFromSignedScenario}) üzerinde veri aktarımı veya model düzenlemesi yapıldığı için önceki Ed25519 imzası geçersiz kılınmış ve model yeni taslak sürüme (${state.scenarioMeta.scenarioId || state.derivedFromSignedScenario + '_TASLAK_V2'} · DEV_UNSIGNED) geçirilmiştir.`;
      }
      if (el.signedModifiedPill) {
        el.signedModifiedPill.textContent = `${state.scenarioMeta.scenarioId || 'TASLAK_V2'} · DEV_UNSIGNED`;
      }
    }
  } else {
    if (el.scSigBadge) {
      el.scSigBadge.textContent = '⚠ İMZASIZ YEREL TASLAK';
      el.scSigBadge.className = 'kpi-badge warn';
    }
    if (el.govSigStatus) {
      el.govSigStatus.textContent = 'İmzasız (Yerel Derleyici / JSON Taslağı / Dev Modu)';
    }
    if (el.signedModifiedBanner) {
      el.signedModifiedBanner.classList.add('hidden');
    }
  }
  if (isSigned && el.signedModifiedBanner) {
    el.signedModifiedBanner.classList.add('hidden');
  }

  // 2. Anahtar Güven Çapası (Pinned Trust Anchor vs Unpinned Dev/Test Key)
  if (el.govKeyTrust) {
    if (isSigned && keyTrusted) {
      el.govKeyTrust.textContent = '✓ Pinli Güven Çapası (CAELUS_TRUSTED_PUBKEY)';
    } else if (isSigned && !keyTrusted) {
      el.govKeyTrust.textContent = '⚠ Pinli Değil (Test / Geliştirme Anahtarı)';
    } else {
      el.govKeyTrust.textContent = 'Doğrulanmadı (İmzasız / Anahtar Yok)';
    }
  }

  // 3. Adli Denetim Zinciri (Forensic Audit Trail)
  if (el.govAuditStatus) {
    if (auditActive) {
      const shortHead = auditHead ? ` · Baş: ${auditHead.slice(0, 10)}…` : '';
      el.govAuditStatus.textContent = `✓ Aktif (Blake3 + Ed25519 · ${auditEntries} kayıt${shortHead})`;
    } else if (state.engineMode === 'ws' || state.engineMode === 'disconnected_stale') {
      el.govAuditStatus.textContent = 'Devre Dışı (--audit-log etkinleştirilmedi)';
    } else {
      el.govAuditStatus.textContent = 'Doğrulanmadı (Yerel Taslak / WASM)';
    }
  }

  // Overall Governance Header Badge (never claims full verification unless all 3 hold)
  if (el.govIntegrityBadge) {
    if (state.engineMode === 'disconnected_stale' || state.staleDisconnected) {
      el.govIntegrityBadge.textContent = 'TARİHSEL VERİ (BAĞLANTI KESİLDİ)';
      el.govIntegrityBadge.className = 'kpi-badge warn';
    } else if (state.engineMode === 'draft_preview') {
      el.govIntegrityBadge.textContent = 'TASLAK ÖNİZLEME (MOTOR YOK)';
      el.govIntegrityBadge.className = 'kpi-badge warn';
    } else if ((isV3 || isV2) && keyTrusted && auditActive) {
      el.govIntegrityBadge.textContent = `✓ TAM BÜTÜNLÜK (${isV3 ? 'V3' : 'V2'} + PINLİ ANAHTAR + DENETİM)`;
      el.govIntegrityBadge.className = 'kpi-badge ok';
    } else if ((isV3 || isV2) && keyTrusted && !auditActive) {
      el.govIntegrityBadge.textContent = `ED25519 ${isV3 ? 'V3' : 'V2'} (DENETİM ZİNCİRİ KAPALI)`;
      el.govIntegrityBadge.className = 'kpi-badge warn';
    } else if ((isV3 || isV2) && !keyTrusted) {
      el.govIntegrityBadge.textContent = `ED25519 ${isV3 ? 'V3' : 'V2'} (TEST ANAHTARI — PINLİ DEĞİL)`;
      el.govIntegrityBadge.className = 'kpi-badge warn';
    } else if (isV1) {
      el.govIntegrityBadge.textContent = keyTrusted
        ? 'ED25519 V1 (KISMİ KAPSAM: meta İMZASIZ)'
        : 'ED25519 V1 (TEST ANAHTARI + meta İMZASIZ)';
      el.govIntegrityBadge.className = 'kpi-badge warn';
    } else if (sig === 'WASM_BUNDLE_UNVERIFIED_AT_RUNTIME') {
      el.govIntegrityBadge.textContent = 'WASM SABİT-NOKTA (int64 × 10⁶)';
      el.govIntegrityBadge.className = 'kpi-badge warn';
    } else {
      el.govIntegrityBadge.textContent = 'İMZASIZ TASLAK / DEV MODU';
      el.govIntegrityBadge.className = 'kpi-badge warn';
    }
  }

  // 4. Sayısal Ölçek & UI Gözlem Özeti
  if (el.govStateHash) {
    const hashSeed = `${profile.scenarioId}:${state.currentTick}:${Math.round(state.frictionMu * 1000)}:${Math.round(state.throughputRatio * 1000)}`;
    const digest = compiler.hash32 ? compiler.hash32(hashSeed).toString(16).toUpperCase().padStart(8, '0') : '00000000';
    const unboundNote = state.intelEventsUnbound > 0 ? ` · Eşleşmeyen Intel: ${state.intelEventsUnbound}` : '';
    el.govStateHash.textContent = `int64×10⁶ · FNV1a:0x${digest} · t=${state.currentTick}${unboundNote}`;
  }
}

function updateModelLastUpdatedStrip() {
  if (!el.modelLastUpdatedTime || !el.modelLiveStatusPill) return;
  const twin = state.twinState;
  const impHist = (twin && Array.isArray(twin.importHistory)) ? twin.importHistory : [];

  if (impHist.length > 0) {
    const latest = impHist[0];
    const tsStr = latest.importedAt ? String(latest.importedAt).replace('T', ' ').slice(0, 19) + 'Z' : 'Belirtilmedi';
    el.modelLastUpdatedTime.textContent = `${tsStr} (Son Yerel Veri Aktarımı: ${latest.sourceFile} · ${latest.updatedNodeCount || 0} varlık güncellendi)`;
    el.modelLiveStatusPill.textContent = 'MANUEL VERİ AKTARILDI · CANLI VERİ AKIŞI DEĞİLDİR';
    el.modelLiveStatusPill.className = 'kpi-badge ok';
    return;
  }

  // No data has been imported yet — show the model's static baseline last update timestamp
  const nodes = (twin && Array.isArray(twin.nodes) && twin.nodes.length > 0)
    ? twin.nodes
    : ((state.scenarioModel && Array.isArray(state.scenarioModel.initial_nodes)) ? state.scenarioModel.initial_nodes : []);
  let latestNodeTs = '';
  nodes.forEach(n => {
    const ts = String(n.timestamp || '').trim();
    if (ts && (!latestNodeTs || ts > latestNodeTs)) latestNodeTs = ts;
  });
  if (!latestNodeTs) latestNodeTs = '2026-04-06T08:00:00Z';

  el.modelLastUpdatedTime.textContent = `${latestNodeTs} (Henüz Yeni Veri Aktarılmadı — Statik Model Baz Kaydı)`;
  el.modelLiveStatusPill.textContent = 'VERİ AKTARILMADI · CANLI VERİ DEĞİLDİR (STATİK BAZ)';
  el.modelLiveStatusPill.className = 'kpi-badge warn';
}

function refreshEnterpriseWorkbench() {
  const compiler = window.CaelusScenarioCompiler;
  if (!compiler || typeof compiler.evaluateEnterpriseDecision !== 'function') return;

  updateModelLastUpdatedStrip();
  if (typeof syncHistoricalLeverDropdown === 'function') {
    syncHistoricalLeverDropdown();
  }

  const isDraftPreview = state.engineMode === 'draft_preview';
  const isStaleDisconnected = state.engineMode === 'disconnected_stale' || state.staleDisconnected;
  const hasSimulatedEngine = (state.engineMode === 'ws' || state.engineMode === 'wasm' || isStaleDisconnected) && state.causalNodes.length > 0;
  const hasTopologyModel = state.engineMode !== 'offline' && state.causalNodes.length > 0;

  const ev = compiler.evaluateEnterpriseDecision({
    hasLiveModel: hasSimulatedEngine,
    scenarioId: state.scenarioMeta.scenarioId,
    sector: state.scenarioMeta.sector,
    tick: state.currentTick,
    tickMinutes: state.scenarioMeta.tickMinutes,
    throughputRatio: state.throughputRatio,
    frictionMu: state.frictionMu,
    outageActive: state.outageActive,
    causalNodes: state.causalNodes,
    causalEdges: state.causalEdges,
    levers: state.engineLevers,
    scenarioModel: state.scenarioModel,
    tickHistory: state.tickHistory,
    customAnalysis: state.generatedScenario,
    financialOverrides: state.financialOverrides,
    engineCounterfactual: state.lastEngineCounterfactual
  });

  state.lastEvaluation = ev;
  const { profile, financials, dataIntegrity, horizons, counterfactuals, rankedPolicies, recommendedPolicy } = ev;

  if (el.scenarioSelect && document.activeElement !== el.scenarioSelect && state.scenarioMeta.scenarioId) {
    const hasOpt = Array.from(el.scenarioSelect.options).some(o => o.value === state.scenarioMeta.scenarioId);
    if (hasOpt && el.scenarioSelect.value !== state.scenarioMeta.scenarioId) {
      el.scenarioSelect.value = state.scenarioMeta.scenarioId;
    }
  }

  if (el.counterfactualDisclaimer && ev.comparisonDisclaimer) {
    el.counterfactualDisclaimer.textContent = 'Sonucun dayanağı: Karşılaştırma değerleri hesaplama motorunun paralel senaryo koşumundan (Değişiklik yapılmazsa ve Değişiklik yapılırsa) üretilmiştir; parasal tutarlar ise saatlik duruş maliyeti varsayımıyla ölçeklenmiştir.';
  }

  // Update calibration placeholders when not actively editing
  if (el.calUnitName && document.activeElement !== el.calUnitName && !state.financialOverrides) {
    el.calUnitName.placeholder = financials.unitName || 'Birim/Saat';
  }
  if (el.calBaseUnits && document.activeElement !== el.calBaseUnits && !state.financialOverrides) {
    el.calBaseUnits.placeholder = String(financials.baselineUnitsPerHour || 100);
  }
  if (el.calHourlyCost && document.activeElement !== el.calHourlyCost && !state.financialOverrides) {
    el.calHourlyCost.placeholder = financials.available ? String(financials.hourlyDowntimeCostUsd || 0) : 'Tanımsız (Girin)';
  }
  if (el.calSlaPenalty && document.activeElement !== el.calSlaPenalty && !state.financialOverrides) {
    el.calSlaPenalty.placeholder = financials.available ? String(financials.slaBreachPenaltyUsd || 0) : 'Tanımsız (Girin)';
  }

  renderSignatureAndGovernanceBadges(profile, compiler);

  // Case A: Offline with no model OR Draft Preview (no running simulation engine)
  if (!hasTopologyModel || isDraftPreview) {
    if (el.hdrSimClock) {
      el.hdrSimClock.textContent = isDraftPreview
        ? `Taslak Topoloji Önizlemesi (Adım 0 · 1t=${financials.tickMinutes}dk — Simülasyon Yok)`
        : 'Motor Bağlantısı Bekleniyor';
    }
    if (el.outageBanner) el.outageBanner.classList.add('hidden');
    if (el.kpiTpPct) el.kpiTpPct.textContent = isDraftPreview ? 'TASLAK' : '—';
    if (el.kpiTpUnits) {
      el.kpiTpUnits.textContent = isDraftPreview
        ? `Baz Kalibrasyon: ${financials.baselineUnitsPerHour} ${financials.unitName} (Motor Koşumu Yok)`
        : 'Motor Bağlantısı Yok';
    }
    if (el.kpiTpLoss) el.kpiTpLoss.textContent = isDraftPreview ? '— (Simülasyon Yok)' : '—';
    if (el.tpBarFill) el.tpBarFill.style.width = '0%';
    if (el.tpStatusText) {
      el.tpStatusText.textContent = isDraftPreview ? 'TASLAK (SİMÜLASYON YOK)' : 'BAĞLANTI YOK';
      el.tpStatusText.className = 'kpi-badge warn';
    }
    if (el.frictionVal) el.frictionVal.textContent = isDraftPreview ? 'TASLAK' : '—';
    if (el.gDelay) el.gDelay.textContent = isDraftPreview ? 'Motor Koşumu Yok (Adım 0)' : 'Motor Bağlantısı Yok';
    if (el.kpiFrictionBar) el.kpiFrictionBar.style.width = '0%';
    if (el.kpiFrictionBadge) {
      el.kpiFrictionBadge.textContent = isDraftPreview ? 'TASLAK ÖNİZLEME' : 'BAĞLANTI YOK';
      el.kpiFrictionBadge.className = 'kpi-badge warn';
    }
    if (el.gRisk) el.gRisk.textContent = isDraftPreview ? 'BAŞLANGIÇ TOPOLOJİSİ (ADIM 0)' : 'MOTOR BEKLENİYOR';
    if (el.kpiHourlyLoss) {
      el.kpiHourlyLoss.textContent = !financials.available
        ? 'Hesaplanamadı'
        : isDraftPreview ? '— (Simülasyon Yok)' : '—';
    }
    if (el.kpiCumLoss) {
      el.kpiCumLoss.textContent = !financials.available
        ? 'Birim maliyet verisi tanımlanmadı'
        : isDraftPreview
          ? `Baz Saatlik Duruş Varsayımı: ${fmtUsd(financials.hourlyDowntimeCostUsd)}`
          : 'Birikimli: —';
    }
    if (el.kpiSlaPenalty) {
      el.kpiSlaPenalty.textContent = financials.available
        ? `${fmtUsd(financials.slaBreachPenaltyUsd)} (Örnek Varsayım)`
        : 'Hesaplanamadı (Veri Yok)';
    }
    if (el.kpiFinBar) el.kpiFinBar.style.width = '0%';
    if (el.kpiFinBadge) {
      el.kpiFinBadge.textContent = !financials.available
        ? 'MALİYET VERİSİ YOK'
        : state.financialOverrides ? 'KULLANICI KALİBRASYONU' : 'ÖRNEK KALİBRASYON';
      el.kpiFinBadge.className = 'kpi-badge warn';
    }
    if (isDraftPreview && dataIntegrity.avgTrustPct !== null) {
      if (el.kpiTrustPct) el.kpiTrustPct.textContent = `${dataIntegrity.avgTrustPct}%`;
      if (el.kpiBiasCount) el.kpiBiasCount.textContent = `${dataIntegrity.biasedCount} Başlangıç Sapması (Taslak)`;
      if (el.kpiTrustBar) el.kpiTrustBar.style.width = `${dataIntegrity.avgTrustPct}%`;
      if (el.kpiTrustBadge) {
        el.kpiTrustBadge.textContent = 'TASLAK DÜĞÜMLER';
        el.kpiTrustBadge.className = 'kpi-badge warn';
      }
      if (el.kpiMaxBias) {
        const b = dataIntegrity.maxBiasNode;
        el.kpiMaxBias.textContent = b ? `${b.id} (%${b.realLoadPct} vs %${b.reportedLoadPct})` : 'Yok (Taslak)';
      }
      if (el.kpiSlaHours) el.kpiSlaHours.textContent = `${financials.remainingHoursToSla} Saat (Tanımlı Eşik)`;
      if (el.kpiSlaTicks) el.kpiSlaTicks.textContent = `Tanımlı SLA Eşiği: ${financials.slaDeadlineTick}t (Simülasyon Yok)`;
      if (el.kpiSlaBar) el.kpiSlaBar.style.width = '0%';
    } else {
      if (el.kpiTrustPct) el.kpiTrustPct.textContent = '—';
      if (el.kpiBiasCount) el.kpiBiasCount.textContent = 'Motor Bağlantısı Yok';
      if (el.kpiTrustBar) el.kpiTrustBar.style.width = '0%';
      if (el.kpiTrustBadge) {
        el.kpiTrustBadge.textContent = 'VERİ YOK';
        el.kpiTrustBadge.className = 'kpi-badge warn';
      }
      if (el.kpiMaxBias) el.kpiMaxBias.textContent = 'Veri Yok';
      if (el.kpiSlaHours) el.kpiSlaHours.textContent = '—';
      if (el.kpiSlaTicks) el.kpiSlaTicks.textContent = 'Motor Bekleniyor';
      if (el.kpiSlaBar) el.kpiSlaBar.style.width = '0%';
    }
    if (el.scName) el.scName.textContent = profile.enterpriseCode;
    if (el.scSector) el.scSector.textContent = profile.sectorLabel;
  } else {
    // Header Clock (with explicit TARİHSEL VERİ prefix if disconnected)
    if (el.hdrSimClock) {
      el.hdrSimClock.textContent = isStaleDisconnected
        ? `Son Bilinen Veri (Bağlantı Kesildi) — Adım: ${state.currentTick} (${financials.elapsedHours} Saat)`
        : `Simülasyon Zamanı: ${state.currentTick === 0 ? 'Başlangıç' : state.currentTick + '. Adım'} (${financials.elapsedHours} Saat)`;
    }

    // Outage Banner
    if (el.outageBanner) {
      if (state.outageActive) {
        el.outageBanner.classList.remove('hidden');
        if (el.outageDetail) {
          el.outageDetail.textContent = `Adım ${state.currentTick} itibarıyla kritik SLA düğümü kilitlendi; akış kapasitesi %0 (${financials.unitName}).`;
        }
      } else {
        el.outageBanner.classList.add('hidden');
      }
    }

    // KPI 1: Operational Throughput
    const tpPct = state.outageActive ? 0 : Math.round(state.throughputRatio * 100);
    if (el.kpiTpPct) el.kpiTpPct.textContent = `${tpPct}%`;
    if (el.kpiTpUnits) el.kpiTpUnits.textContent = `${financials.currentUnitsPerHour} / ${financials.baselineUnitsPerHour} ${financials.unitName}`;
    if (el.kpiTpLoss) el.kpiTpLoss.textContent = `${financials.lostUnitsPerHour} ${financials.unitName}`;
    if (el.tpBarFill) {
      el.tpBarFill.style.width = `${tpPct}%`;
      el.tpBarFill.style.background = tpPct >= 75 ? 'var(--ok)' : tpPct >= 40 ? 'var(--warn)' : 'var(--crit)';
    }
    if (el.tpStatusText) {
      if (isStaleDisconnected) {
        el.tpStatusText.textContent = `TARİHSEL VERİ (${tpPct}%)`;
        el.tpStatusText.className = 'kpi-badge warn';
      } else if (state.outageActive) {
        el.tpStatusText.textContent = 'KESİNTİ (0%)';
        el.tpStatusText.className = 'kpi-badge crit';
      } else if (tpPct < 45) {
        el.tpStatusText.textContent = 'KRİTİK DARBOĞAZ';
        el.tpStatusText.className = 'kpi-badge crit';
      } else if (tpPct < 80) {
        el.tpStatusText.textContent = 'KAPASİTE KAYBI';
        el.tpStatusText.className = 'kpi-badge warn';
      } else {
        el.tpStatusText.textContent = 'NOMİNAL AKIŞ';
        el.tpStatusText.className = 'kpi-badge ok';
      }
    }

    // KPI 2: Friction & Delay
    const mu = state.frictionMu;
    const delayH = Math.max(0, (mu - 1) * 7.5);
    if (el.frictionVal) el.frictionVal.textContent = `${mu.toFixed(2)}×`;
    if (el.gDelay) el.gDelay.textContent = `+${delayH.toFixed(1)} Saat (Varsayımsal)`;
    if (el.kpiFrictionBar) {
      const fPct = clamp(((mu - 1) / 2) * 100, 5, 100);
      el.kpiFrictionBar.style.width = `${fPct}%`;
      el.kpiFrictionBar.style.background = mu < 1.35 ? 'var(--ok)' : mu < 2.15 ? 'var(--warn)' : 'var(--crit)';
    }
    if (el.kpiFrictionBadge && el.gRisk) {
      if (isStaleDisconnected) {
        el.kpiFrictionBadge.textContent = 'TARİHSEL VERİ';
        el.kpiFrictionBadge.className = 'kpi-badge warn';
        el.gRisk.textContent = `BAĞLANTI KESİLDİ (SON ADIM: ${state.currentTick})`;
        if (el.sbThreat) el.sbThreat.textContent = 'DURUM: BAĞLANTI KESİLDİ (TARİHSEL VERİ)';
      } else if (mu >= 2.15) {
        el.kpiFrictionBadge.textContent = 'YÜKSEK SÜRTÜNME';
        el.kpiFrictionBadge.className = 'kpi-badge crit';
        el.gRisk.textContent = 'KRİTİK BASKI REJİMİ';
        if (el.sbThreat) el.sbThreat.textContent = 'RİSK REJİMİ: YÜKSEK STRES';
      } else if (mu >= 1.35) {
        el.kpiFrictionBadge.textContent = 'ORTA STRES';
        el.kpiFrictionBadge.className = 'kpi-badge warn';
        el.gRisk.textContent = 'DARBOĞAZ BİRİKİMİ';
        if (el.sbThreat) el.sbThreat.textContent = 'RİSK REJİMİ: ORTA STRES';
      } else {
        el.kpiFrictionBadge.textContent = 'DÜŞÜK SÜRTÜNME';
        el.kpiFrictionBadge.className = 'kpi-badge ok';
        el.gRisk.textContent = 'NORMAL REJİM';
        if (el.sbThreat) el.sbThreat.textContent = 'RİSK REJİMİ: NORMAL';
      }
    }

    // KPI 3: Financial Exposure (Explicitly labeled; shows Hesaplanamadı when cost data is absent)
    if (!financials.available) {
      if (el.kpiHourlyLoss) el.kpiHourlyLoss.textContent = 'Hesaplanamadı';
      if (el.kpiCumLoss) el.kpiCumLoss.textContent = 'Birim maliyet verisi tanımlanmadı (1B panelinden girin)';
      if (el.kpiSlaPenalty) el.kpiSlaPenalty.textContent = 'Hesaplanamadı (Veri Yok)';
      if (el.kpiFinBar) el.kpiFinBar.style.width = '0%';
      if (el.kpiFinBadge) {
        el.kpiFinBadge.textContent = 'MALİYET VERİSİ YOK';
        el.kpiFinBadge.className = 'kpi-badge warn';
      }
    } else {
      if (el.kpiHourlyLoss) el.kpiHourlyLoss.textContent = `${fmtUsd(financials.hourlyLossUsd)} / Saat`;
      if (el.kpiCumLoss) {
        const methodTag = financials.cumulativeLossMethod === 'INTEGRATED_TICK_HISTORY'
          ? 'Tam Tarihçe İntegrali'
          : financials.cumulativeLossMethod === 'PARTIAL_TICK_HISTORY_INTERPOLATED'
            ? `Kısmi Tarihçe (${financials.historyMissingTicks} eksik adım)`
            : 'Anlık Nokta Tahmini';
        el.kpiCumLoss.textContent = `Birikimli (${methodTag}): ${fmtUsd(financials.cumulativeLossUsd)}`;
      }
      if (el.kpiSlaPenalty) el.kpiSlaPenalty.textContent = `${fmtUsd(financials.slaBreachPenaltyUsd)} (Varsayım)`;
      if (el.kpiFinBar) {
        const lossRatio = clamp(((financials.hourlyLossUsd || 0) / Math.max(1, financials.hourlyDowntimeCostUsd)) * 100, 0, 100);
        el.kpiFinBar.style.width = `${lossRatio}%`;
        el.kpiFinBar.style.background = lossRatio > 60 ? 'var(--crit)' : lossRatio > 25 ? 'var(--warn)' : 'var(--ok)';
      }
      if (el.kpiFinBadge) {
        const highFin = (financials.hourlyLossUsd || 0) > financials.hourlyDowntimeCostUsd * 0.5;
        el.kpiFinBadge.textContent = isStaleDisconnected
          ? 'TARİHSEL (VARSAYIM)'
          : state.financialOverrides
            ? 'KULLANICI KALİBRASYONU'
            : highFin ? 'YÜKSEK MALİYET (VARSAYIM)' : 'ÖRNEK KALİBRASYON';
        el.kpiFinBadge.className = 'kpi-badge ' + (highFin && !isStaleDisconnected ? 'crit' : 'warn');
      }
    }

    // KPI 4: Data Integrity & Reporting Bias
    const trustDisp = dataIntegrity.avgTrustPct !== null ? `${dataIntegrity.avgTrustPct}%` : '—';
    if (el.kpiTrustPct) el.kpiTrustPct.textContent = trustDisp;
    if (el.kpiBiasCount) el.kpiBiasCount.textContent = `${dataIntegrity.biasedCount} Rapor Sapması`;
    if (el.kpiTrustBar) {
      el.kpiTrustBar.style.width = `${dataIntegrity.avgTrustPct ?? 0}%`;
      el.kpiTrustBar.style.background = dataIntegrity.biasedCount > 0 ? 'var(--warn)' : 'var(--ok)';
    }
    if (el.kpiTrustBadge) {
      if (isStaleDisconnected) {
        el.kpiTrustBadge.textContent = 'TARİHSEL VERİ';
        el.kpiTrustBadge.className = 'kpi-badge warn';
      } else if (dataIntegrity.biasedCount > 0) {
        el.kpiTrustBadge.textContent = 'SAPMA TESPİT EDİLDİ';
        el.kpiTrustBadge.className = 'kpi-badge warn';
      } else {
        el.kpiTrustBadge.textContent = 'DÜĞÜM MUTABAKATI';
        el.kpiTrustBadge.className = 'kpi-badge ok';
      }
    }
    if (el.kpiMaxBias) {
      if (dataIntegrity.maxBiasNode) {
        const b = dataIntegrity.maxBiasNode;
        el.kpiMaxBias.textContent = `${b.id} (%${b.realLoadPct} vs %${b.reportedLoadPct})`;
      } else {
        el.kpiMaxBias.textContent = 'Yok (Saha = Rapor)';
      }
    }

    // KPI 5: SLA & Continuity Countdown
    if (el.kpiSlaHours) el.kpiSlaHours.textContent = `${financials.remainingHoursToSla} Saat`;
    if (el.kpiSlaTicks) el.kpiSlaTicks.textContent = `${financials.remainingTicksToSla} Adım Kaldı (Eşik: ${financials.slaDeadlineTick}t)`;
    if (el.scName) el.scName.textContent = profile.enterpriseCode;
    if (el.scSector) el.scSector.textContent = profile.sectorLabel;
    if (el.kpiSlaBar) {
      const slaPct = clamp((financials.remainingTicksToSla / Math.max(1, financials.slaDeadlineTick)) * 100, 0, 100);
      el.kpiSlaBar.style.width = `${slaPct}%`;
      el.kpiSlaBar.style.background = slaPct < 25 ? 'var(--crit)' : slaPct < 55 ? 'var(--warn)' : 'var(--ok)';
    }
  }

  // Render Left Table: Process Nodes & Reporting Bias Audit
  renderProcessAuditTable(dataIntegrity.auditedNodes);

  // Render Left Tab 3: Relations, Time Scale & Thresholds
  renderRelationsAndThresholds(state.scenarioModel, profile, financials);

  // Render Center: Executive Assessment, Provenance Badge & Assumptions
  if (el.execModelTitle) el.execModelTitle.textContent = `${profile.enterpriseCode} — ${profile.title}`;
  if (el.execProvenanceBadge) {
    const provCode = String(profile.dataProvenance || 'FICTIONAL_SAMPLE').toUpperCase();
    el.execProvenanceBadge.textContent = profile.dataProvenanceBadge || 'ÖRNEK / KURGU VERİ';
    el.execProvenanceBadge.className = 'kpi-badge ' + (provCode === 'DOCUMENTED_SOURCE' || provCode === 'USER_INPUT' ? 'ok' : 'warn');
    el.execProvenanceBadge.title = profile.dataSourceNote || '';
  }
  if (el.execComplianceBadge) el.execComplianceBadge.textContent = profile.compliance;
  if (el.execContextText) el.execContextText.textContent = profile.executiveContext;

  if (el.execAssumptionsList) {
    el.execAssumptionsList.innerHTML = '';
    const allAssumptions = [
      `Veri Kaynağı Etiketi: ${profile.dataProvenanceBadge} — ${profile.dataSourceNote}`,
      `Zaman Ölçeği: 1 Adım = ${financials.tickMinutes} dk · Ufuk = ${financials.horizonHours} Saat · Baz Akış = ${financials.baselineUnitsPerHour} ${financials.unitName}`,
      `Finansal Veri Kaynağı: ${financials.financialSourceLabel}`,
      financials.financialFormulaNote,
      ...(profile.assumptions || [])
    ];
    allAssumptions.forEach(item => {
      const li = document.createElement('li');
      li.textContent = item;
      el.execAssumptionsList.appendChild(li);
    });
  }
  if (el.execDatagapsList) {
    el.execDatagapsList.innerHTML = '';
    (profile.dataGaps || []).forEach(item => {
      const li = document.createElement('li');
      li.textContent = item;
      el.execDatagapsList.appendChild(li);
    });
  }

  // Populate Compare Lever Select, Selected Lever Summary & Horizon Hint
  populateCompareLeverToolbar(rankedPolicies, financials.tickMinutes);
  renderSelectedLeverSummary(rankedPolicies, financials);

  // Render Side-by-Side Engine Counterfactual (Branch A vs Branch B)
  renderSideBySideCounterfactual(state.lastEngineCounterfactual, ev);

  // Render 3D/2D Spatial Stage Node Selector Pills & Selected Entity Inspector
  renderStageNodePills(ev);
  renderEntityInspector(ev);
  updateStageStatusBadges(ev);
  layoutCausalGraph();
  drawCausalGraph();

  // Update Guided Next-Step Banner & Active Preset Chip
  updateGuidedNextStepBanner(ev);
  highlightActiveScenarioChips();

  // Render Center: 3 Time Horizons
  renderTimeHorizons(horizons);

  // Render Center: Parametric Sensitivity Matrix
  renderCounterfactualTable(counterfactuals, recommendedPolicy);

  // Render Right: Mitigation Policy Cards
  renderPolicyCards(rankedPolicies, recommendedPolicy);

  if (typeof renderDunyamOverview === 'function') {
    renderDunyamOverview(ev);
  }
}

function highlightActiveScenarioChips() {
  const activeId = state.scenarioMeta.scenarioId;
  document.querySelectorAll('[data-preset]').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-preset') === activeId);
  });
}

function updateGuidedNextStepBanner(ev) {
  if (!el.nextStepBanner || !el.nextStepTag || !el.nextStepText) return;
  const isDraft = state.engineMode === 'draft_preview';
  const isStale = state.engineMode === 'disconnected_stale' || state.staleDisconnected;
  const isOffline = state.engineMode === 'offline';

  if (isStale) {
    el.nextStepTag.textContent = 'BAĞLANTI KESİLDİ';
    el.nextStepTag.style.background = 'var(--warn)';
    el.nextStepText.textContent =
      `Canlı motor bağlantısı kesildi. Ekrandaki değerler Adım ${state.currentTick} anındaki son bilinen TARİHSEL VERİDİR; yeni karşılaştırma çalıştırmak için CAELUS_CALISTIR.bat ile motoru yeniden başlatın.`;
    return;
  }
  if (isOffline) {
    el.nextStepTag.textContent = '1. ADIM — MOTORU BAŞLATIN';
    el.nextStepTag.style.background = 'var(--warn)';
    el.nextStepText.textContent =
      'Canlı hesaplama motoru bağlı değil. Uygulamayı CAELUS_CALISTIR.bat ile başlatın veya 1. adımda "+ Kendi Süreç Modelinizi Yazın" kutusundan taslak topoloji oluşturun.';
    return;
  }
  if (isDraft) {
    el.nextStepTag.textContent = 'TASLAK ÖNİZLEME';
    el.nextStepTag.style.background = 'var(--warn)';
    el.nextStepText.textContent =
      'Şu anda yerel taslak modelin başlangıç yapısını (Adım 0) inceliyorsunuz. Gerçek A/B simülasyonu çalıştırmak için canlı C++/Rust motorunu başlatın.';
    return;
  }

  if (ev && ev.isCounterfactualSimulated && state.lastEngineCounterfactual) {
    el.nextStepTag.textContent = 'KARŞILAŞTIRMA TAMAMLANDI';
    el.nextStepTag.style.background = 'var(--ok)';
    el.nextStepText.textContent =
      '4. adımda Müdahale Yapılmazsa (Sol Kart) ve Müdahale Uygulanırsa (Sağ Kart) oluşacak gerçek motor sonuçlarını yan yana inceleyebilir; 5. adımdan veya sağ üstten Karar Raporunu indirebilirsiniz.';
  } else {
    el.nextStepTag.textContent = 'SIRADAKİ ADIM (3. ADIM)';
    el.nextStepTag.style.background = 'var(--primary)';
    el.nextStepText.textContent =
      'Seçili modelin başlangıç durumu yüklendi. Şimdi 3. adımdan bir müdahale seçeneği belirleyin ve mavi "⚖ Müdahaleyi Test Et (A/B Karşılaştır)" düğmesine tıklayın.';
  }
}

function provenanceShortTag(prov) {
  const p = String(prov || '').toUpperCase();
  if (p === 'USER_INPUT' || p === 'USER') return 'Kullanıcı';
  if (p === 'DOCUMENTED_SOURCE' || p === 'SOURCED') return 'Kaynaklı';
  return 'Örnek/Kurgu';
}

function renderProcessAuditTable(auditedNodes) {
  if (!el.nodeAuditTbody) return;
  el.nodeAuditTbody.innerHTML = '';

  if (!auditedNodes || auditedNodes.length === 0) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = 6;
    td.style.textAlign = 'center';
    td.textContent = state.engineMode === 'offline'
      ? 'Gerçek motor bağlantısı yok. Süreç düğümlerini görmek için C++/Rust motorunu başlatın veya Senaryo Stüdyosunda model derleyin.'
      : 'Henüz süreç düğümü yüklenmedi.';
    tr.appendChild(td);
    el.nodeAuditTbody.appendChild(tr);
    return;
  }

  auditedNodes.forEach(n => {
    const tr = document.createElement('tr');

    const tdName = document.createElement('td');
    const nameSpan = document.createElement('span');
    nameSpan.className = 'node-name-cell';
    nameSpan.textContent = n.label;
    const nodeDiffs = state.lastDiffByNodeId && state.lastDiffByNodeId[n.id];
    if (Array.isArray(nodeDiffs) && nodeDiffs.length > 0) {
      const updBadge = document.createElement('span');
      updBadge.className = 'kpi-badge ok';
      updBadge.style.marginLeft = '6px';
      updBadge.style.fontSize = '0.68rem';
      updBadge.textContent = '🔄 GÜNCELLENDİ';
      updBadge.title = nodeDiffs.map(d => `${d.field}: ${d.oldVal} → ${d.newVal}`).join(' | ');
      nameSpan.appendChild(updBadge);
    }
    const subSpan = document.createElement('span');
    subSpan.className = 'node-id-sub';
    const unitTag = n.unit && n.unit !== '%' ? ` · Birim: ${n.unit}` : ' · Birim: %';
    const tsTag = n.timestamp ? ` · Zaman: ${n.timestamp}` : '';
    const rawSrc = n.rawDataSource || provenanceShortTag(n.dataSource);
    subSpan.textContent = `${n.id} · ${n.category}${unitTag} · Kaynak: ${rawSrc}${tsTag}`;
    tdName.appendChild(nameSpan);
    tdName.appendChild(subSpan);

    const tdInit = document.createElement('td');
    tdInit.className = 'mono';
    tdInit.style.fontSize = '10.5px';
    tdInit.style.color = 'var(--text-3)';
    tdInit.title = `t=0 Başlangıç Gerçek: %${n.initialLoadPct} | Rapor: %${n.initialReportedPct} | Ağırlık: ${Number(n.weight || 0).toFixed(2)}`;
    tdInit.textContent = `%${n.initialLoadPct}`;

    const tdReal = document.createElement('td');
    tdReal.className = 'mono';
    tdReal.style.fontWeight = '700';
    tdReal.style.color = n.realLoadPct >= 80 ? 'var(--crit)' : n.realLoadPct >= 50 ? 'var(--warn)' : 'var(--text-1)';
    tdReal.textContent = `%${n.realLoadPct}`;

    const tdRep = document.createElement('td');
    tdRep.className = 'mono';
    tdRep.textContent = `%${n.reportedLoadPct}`;
    if (n.hasBias) {
      const biasSub = document.createElement('div');
      biasSub.style.fontSize = '9.5px';
      biasSub.style.color = 'var(--warn)';
      biasSub.textContent = n.biasDeltaPct > 0 ? `(+%${n.biasDeltaPct} gizli)` : `(%${n.biasDeltaPct} fark)`;
      tdRep.appendChild(biasSub);
    }

    const tdTrust = document.createElement('td');
    tdTrust.className = 'mono';
    tdTrust.style.color = n.trustPct < 75 ? 'var(--warn)' : 'var(--ok)';
    tdTrust.textContent = `%${n.trustPct}`;

    const tdStatus = document.createElement('td');
    const stBadge = document.createElement('span');
    stBadge.className = 'kpi-badge ' + n.statusLevel;
    stBadge.textContent = n.statusLabel;
    tdStatus.appendChild(stBadge);

    tr.appendChild(tdName);
    tr.appendChild(tdInit);
    tr.appendChild(tdReal);
    tr.appendChild(tdRep);
    tr.appendChild(tdTrust);
    tr.appendChild(tdStatus);
    el.nodeAuditTbody.appendChild(tr);
  });
}

function renderRelationsAndThresholds(sm, profile, financials) {
  if (!el.relationsSummaryBar || !el.edgesListTbody || !el.thresholdsListBox) return;

  const edges = (sm && Array.isArray(sm.edges) && sm.edges.length > 0)
    ? sm.edges
    : (state.causalEdges || []).map(e => ({ from: e.from, to: e.to, multiplier: e.weight_fp, lag_ticks: e.lag_ticks }));
  const loops = (sm && Array.isArray(sm.feedback_loops)) ? sm.feedback_loops : [];
  const deadlines = (sm && Array.isArray(sm.deadlines)) ? sm.deadlines : [];
  const hysteresis = (sm && Array.isArray(sm.hysteresis)) ? sm.hysteresis : [];
  const bindings = (sm && Array.isArray(sm.intel_bindings_list)) ? sm.intel_bindings_list : [];
  const intelSeq = (sm && Array.isArray(sm.intel_sequence_list)) ? sm.intel_sequence_list : [];

  el.relationsSummaryBar.textContent =
    `Zaman Ölçeği: 1 Adım = ${financials.tickMinutes} dk (${(60 / Math.max(1, financials.tickMinutes)).toFixed(1)} adım/saat) · Ufuk: ${financials.horizonHours} Saat | ` +
    `Düğüm: ${state.causalNodes.length} · İlişki Kenarı: ${edges.length} · Geri-Besleme: ${loops.length} · SLA Eşiği: ${deadlines.length} · Histerezis: ${hysteresis.length} | ` +
    `Veri Kaynağı: ${profile.dataProvenanceBadge}`;

  el.edgesListTbody.innerHTML = '';
  if (edges.length === 0 && loops.length === 0) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = 4;
    td.textContent = 'Tanımlı süreç ilişkisi (edge) veya geri-besleme döngüsü yok.';
    tr.appendChild(td);
    el.edgesListTbody.appendChild(tr);
  } else {
    edges.forEach(e => {
      const tr = document.createElement('tr');
      const tdFrom = document.createElement('td');
      tdFrom.className = 'mono';
      tdFrom.textContent = e.from;
      const tdTo = document.createElement('td');
      tdTo.className = 'mono';
      tdTo.textContent = e.to;
      const tdMult = document.createElement('td');
      tdMult.className = 'mono';
      tdMult.textContent = `${Number(e.multiplier ?? e.weight_fp ?? 0).toFixed(2)}× (Nedensel Kenar)`;
      const tdLag = document.createElement('td');
      tdLag.className = 'mono';
      const lag = Number(e.lag_ticks || 0);
      tdLag.textContent = `${lag}t (${((lag * financials.tickMinutes) / 60).toFixed(1)}s)`;
      tr.appendChild(tdFrom);
      tr.appendChild(tdTo);
      tr.appendChild(tdMult);
      tr.appendChild(tdLag);
      el.edgesListTbody.appendChild(tr);
    });
    loops.forEach(fl => {
      const tr = document.createElement('tr');
      const tdFrom = document.createElement('td');
      tdFrom.className = 'mono';
      const pathArr = Array.isArray(fl.path) ? fl.path : [];
      tdFrom.textContent = pathArr.length > 0 ? `${pathArr[0]} (Döngü:${fl.id})` : `${fl.from || fl.id || '?'} (Döngü)`;
      const tdTo = document.createElement('td');
      tdTo.className = 'mono';
      tdTo.textContent = pathArr.length > 1 ? pathArr.slice(1).join(' → ') : (fl.to || 'Döngü');
      const tdMult = document.createElement('td');
      tdMult.className = 'mono';
      tdMult.textContent = `Kazanç: ${Number(fl.gain || 1).toFixed(2)}×`;
      const tdLag = document.createElement('td');
      tdLag.className = 'mono';
      tdLag.textContent = 'Geri-Besleme';
      tr.appendChild(tdFrom);
      tr.appendChild(tdTo);
      tr.appendChild(tdMult);
      tr.appendChild(tdLag);
      el.edgesListTbody.appendChild(tr);
    });
  }

  el.thresholdsListBox.innerHTML = '';
  const items = [];
  deadlines.forEach(d => {
    const h = ((Number(d.at_tick || 0) * financials.tickMinutes) / 60).toFixed(1);
    const minSt = Number(d.min_state ?? d.threshold ?? 0);
    const cond = minSt > 0
      ? `Koşullu (${d.node_id} ≥ %${Math.round(minSt * 100)})`
      : (d.condition && d.condition !== 'UNCONDITIONAL'
        ? `Koşullu (${d.condition} ≥ %${Math.round(Number(d.threshold || 0) * 100)})`
        : 'Koşulsuz (Zaman Bazlı)');
    items.push(`• [SLA KESİNTİ EŞİĞİ] Düğüm=${d.node_id} · Adım=${d.at_tick}t (${h} Saat) · Kural=${cond} · Kesinti Kilitler=${d.latches_outage ? 'Evet' : 'Hayır'}`);
  });
  hysteresis.forEach(h => {
    const hrs = ((Number(h.threshold_tick || 0) * financials.tickMinutes) / 60).toFixed(1);
    const condParts = [];
    if (Number(h.min_friction || 0) > 0) condParts.push(`μ ≥ ${Number(h.min_friction).toFixed(2)}×`);
    if (h.condition_node_id && Number(h.min_node_state || 0) > 0) {
      condParts.push(`${h.condition_node_id} ≥ %${Math.round(Number(h.min_node_state) * 100)}`);
    }
    const cond = condParts.length > 0
      ? `Koşullu (${condParts.join(' ve ')})`
      : (h.condition && h.condition !== 'UNCONDITIONAL'
        ? `Koşullu (${h.condition} ≥ %${Math.round(Number(h.trigger_threshold || 0) * 100)})`
        : 'Koşulsuz (Zaman Bazlı)');
    items.push(`• [HİSTEREZİS] ID=${h.id} · Adım=${h.threshold_tick}t (${hrs} Saat) · Kalıcı Kayıp=+%${Math.round(Number(h.permanent_loss || 0) * 100)} · Kural=${cond}`);
  });
  bindings.forEach(b => {
    if (b.node_id) {
      items.push(`• [INTEL BAĞLANTISI] Hedef Düğüm=${b.node_id} · Mod=${b.mode || 'max'} · Ölçek=${Number(b.scale || 0).toFixed(2)} · Kriz Adımı=${Number(b.crisis_step || 0).toFixed(2)} (Min Seviye=${b.min_crisis_level ?? 0})`);
    } else {
      items.push(`• [OLAY BAĞLANTISI] Kaynak=${b.source} / Konu=${b.topic} → Hedef Düğüm=${b.target_node_id} (ΔYük=${Math.round(Number(b.state_delta || 0) * 100)}%)`);
    }
  });
  intelSeq.forEach(s => {
    if (s.memo !== undefined || s.friction_coeff !== undefined) {
      items.push(`• [ZAMANLANMIŞ SAHA OLAYI] Adım=${s.at_tick}t (Saat=${s.t_hour ?? 0}) · Katsayı=${Number(s.friction_coeff || 0).toFixed(2)} · Kriz=${s.crisis_level ?? 1} · "${s.memo || ''}"`);
    } else {
      items.push(`• [ZAMANLANMIŞ OLAY] Adım=${s.at_tick}t · ${s.source}/${s.topic} (${s.summary || ''})`);
    }
  });
  if (items.length === 0) {
    el.thresholdsListBox.textContent = 'Bu senaryoda tanımlı SLA eşiği, histerezis veya olay bağlantısı bulunmuyor.';
  } else {
    items.forEach(line => {
      const div = document.createElement('div');
      div.style.padding = '2px 0';
      div.textContent = line;
      el.thresholdsListBox.appendChild(div);
    });
  }
}

function populateCompareLeverToolbar(rankedPolicies, tickMinutes) {
  if (!el.cfLeverSelect) return;
  const prevVal = el.cfLeverSelect.value;
  el.cfLeverSelect.innerHTML = '';

  if (!rankedPolicies || rankedPolicies.length === 0) {
    const opt = document.createElement('option');
    opt.value = '';
    opt.textContent = 'Tanımlı müdahale seçeneği yok';
    el.cfLeverSelect.appendChild(opt);
  } else {
    rankedPolicies.forEach((pol, idx) => {
      const opt = document.createElement('option');
      opt.value = pol.id;
      const recPrefix = idx === 0 ? 'Önerilen: ' : '';
      const costHint = pol.costUsd !== null && pol.costUsd !== undefined
        ? ` · Tahmini Maliyet: ${fmtUsd(pol.costUsd)}`
        : '';
      opt.textContent = `${recPrefix}${pol.name} (Tahmini Etkinlik: %${pol.successProbPct}${costHint})`;
      el.cfLeverSelect.appendChild(opt);
    });
    const stillExists = rankedPolicies.some(p => p.id === prevVal);
    if (stillExists) {
      el.cfLeverSelect.value = prevVal;
    } else {
      el.cfLeverSelect.value = rankedPolicies[0].id;
    }
  }

  if (el.cfHorizonInput && el.cfHorizonHoursHint) {
    const ticks = clamp(parseInt(el.cfHorizonInput.value || '24', 10) || 24, 1, 500);
    const hrs = ((ticks * (tickMinutes || 15)) / 60).toFixed(1);
    el.cfHorizonHoursHint.textContent = `= ${hrs} Saat`;
    document.querySelectorAll('.horizon-preset-btn').forEach(btn => {
      btn.classList.toggle('active', Number(btn.getAttribute('data-ticks')) === ticks);
    });
  }
}

function renderSelectedLeverSummary(rankedPolicies, financials) {
  if (!el.selectedLeverSummary) return;
  if (!rankedPolicies || rankedPolicies.length === 0 || !el.cfLeverSelect) {
    el.selectedLeverSummary.innerHTML = '<span>Bu model için tanımlı değişiklik seçeneği bulunmuyor.</span>';
    return;
  }
  const selectedId = el.cfLeverSelect.value;
  const pol = rankedPolicies.find(p => p.id === selectedId) || rankedPolicies[0];
  if (!pol) return;

  const costText = financials && financials.available && pol.costUsd !== null
    ? `${fmtUsd(pol.costUsd)} (Tahmini / Varsayım)`
    : 'Hesaplanamadı (Birim maliyet tanımlanmadı)';

  el.selectedLeverSummary.innerHTML = `
    <div style="flex:1; min-width:260px;">
      <strong style="color:var(--text-1);">${escapeHtml(pol.name)}:</strong>
      <span>${escapeHtml(pol.summary)}</span>
    </div>
    <div style="display:flex; gap:10px; flex-wrap:wrap; align-items:center;">
      <span class="kpi-badge">Uygulama Süresi: ${escapeHtml(pol.implementationHours)} Saat (${Number(pol.costTicks)} adım)</span>
      <span class="kpi-badge">Tahmini Etkinlik: %${Number(pol.successProbPct)}</span>
      <span class="kpi-badge warn">Değişiklik Maliyeti: ${escapeHtml(costText)}</span>
      <span class="kpi-badge">${escapeHtml(pol.dataSourceBadge || 'Örnek veri')}</span>
    </div>
  `;
}

function renderSideBySideCounterfactual(cfData, ev) {
  if (!el.cfSideBySideBox || !el.cfSideBySideCards || !el.cfNodeCompareTbody) return;

  if (!cfData || !ev || !ev.isCounterfactualSimulated || !cfData.branch_a || !cfData.branch_b) {
    el.cfSideBySideBox.classList.add('hidden');
    if (el.cfEmptyPrompt) el.cfEmptyPrompt.classList.remove('hidden');
    el.cfSideBySideCards.innerHTML = '';
    el.cfNodeCompareTbody.innerHTML =
      '<tr><td colspan="6" style="color:var(--text-3);">Varlık bazlı farkları görmek için yukarıdan "Senaryoları Karşılaştır" düğmesine tıklayın.</td></tr>';
    return;
  }

  if (el.cfEmptyPrompt) el.cfEmptyPrompt.classList.add('hidden');
  el.cfSideBySideBox.classList.remove('hidden');
  el.cfSideBySideCards.innerHTML = '';
  el.cfNodeCompareTbody.innerHTML = '';

  const init = cfData.initial_state || {};
  const ba = cfData.branch_a || {};
  const bb = cfData.branch_b || {};
  const fin = ev.financials || {};
  const tickMin = Number(cfData.tick_minutes || fin.tickMinutes || 15);
  const horizonTicks = Number(cfData.horizon_ticks || 24);
  const horizonHrs = ((horizonTicks * tickMin) / 60).toFixed(1);
  const initTpPct = Math.round(Number(init.throughput_ratio ?? state.throughputRatio) * 100);
  const baTpPct = ba.outage_active ? 0 : Math.round(Number(ba.throughput_ratio ?? 0) * 100);
  const bbTpPct = bb.outage_active ? 0 : Math.round(Number(bb.throughput_ratio ?? 0) * 100);
  const baAvgTpPct = Math.round(Number(ba.avg_throughput ?? ba.throughput_ratio ?? 0) * 100);
  const bbAvgTpPct = Math.round(Number(bb.avg_throughput ?? bb.throughput_ratio ?? 0) * 100);
  const deltaTp = bbTpPct - baTpPct;

  const baUnits = Math.round((fin.baselineUnitsPerHour || 100) * (baTpPct / 100));
  const bbUnits = Math.round((fin.baselineUnitsPerHour || 100) * (bbTpPct / 100));
  const baOutageTicks = Number(ba.outage_ticks || 0);
  const bbOutageTicks = Number(bb.outage_ticks || 0);
  const baOutageHrs = ((baOutageTicks * tickMin) / 60).toFixed(1);
  const bbOutageHrs = ((bbOutageTicks * tickMin) / 60).toFixed(1);

  const cfRowA = (ev.counterfactuals || []).find(r => r.id === 'CF_BASELINE') || {};
  const cfRowB = (ev.counterfactuals || []).find(r => r.id === 'CF_RECOMMENDED') || {};
  const matchedPol = (ev.rankedPolicies || []).find(p => p.id === cfData.lever_id) || ev.recommendedPolicy || {};
  const leverReadableName = matchedPol.name || cfData.lever_label || 'Seçilen Değişiklik';

  const nodeCmp = Array.isArray(ev.nodeComparison) ? ev.nodeComparison : [];
  const targetNode = (state.scenSelectedTargetEntityId && nodeCmp.find(n => n.id === state.scenSelectedTargetEntityId))
    || nodeCmp.find(n => n.isTarget)
    || nodeCmp[nodeCmp.length - 1]
    || null;
  const secTargetNode = (state.scenSelectedSecondaryTargetId && state.scenSelectedSecondaryTargetId !== (targetNode && targetNode.id))
    ? (nodeCmp.find(n => n.id === state.scenSelectedSecondaryTargetId) || null)
    : null;

  const isControlledPlan = state.scenPlanMode === 'CONTROLLED_PLAN';
  const wmApi = typeof getLearnedWorldModelApi === 'function' ? getLearnedWorldModelApi() : window.CaelusLearnedWorldModel;
  const planReport = state.lastControlledPlanReport || (
    isControlledPlan && wmApi && typeof wmApi.evaluateControlledWorldPlan === 'function' && state.twinState
      ? wmApi.evaluateControlledWorldPlan(state.twinState, null)
      : null
  );
  const runEnv = (state.lastCompiledTargetPack && state.lastCompiledTargetPack.runEnvelope)
    || (planReport && planReport.runEnvelope)
    || null;

  // 1. Yönetici Karar Özeti Cümlesi (#cf-executive-verdict)
  if (el.cfExecutiveVerdict) {
    const preventedOutage = ba.outage_active && !bb.outage_active;
    const finSummary = fin.available && cfRowB.netProtectedValueUsd !== null && cfRowB.netProtectedValueUsd !== undefined
      ? ` Tahmini değişiklik maliyeti ${fmtUsd(cfRowB.interventionCostUsd)} düşüldüğünde net korunan değer ${cfRowB.netProtectedValueUsd >= 0 ? '+' : ''}${fmtUsd(cfRowB.netProtectedValueUsd)} (${cfRowB.roiLabel}) olarak hesaplanmıştır.`
      : ' (Bu senaryoda birim maliyet tanımlanmadığı için parasal tutarlar "Hesaplanamadı" olarak işaretlenmiştir; yalnızca kapasite ve kesinti süresi karşılaştırılır.)';

    const targetSummaryBit = targetNode
      ? ` Hedef varlık <strong>${escapeHtml(targetNode.label)}</strong> yükü <strong>%${targetNode.branchAStatePct} → %${targetNode.branchBStatePct}</strong> (${targetNode.deltaStatePct > 0 ? '+' : ''}${targetNode.deltaStatePct} puan)` +
        (secTargetNode
          ? ` ve ikincil hedef <strong>${escapeHtml(secTargetNode.label)}</strong> yükü <strong>%${secTargetNode.branchAStatePct} → %${secTargetNode.branchBStatePct}</strong>`
          : '') +
        ` olarak modellenmiştir.`
      : '';

    if (isControlledPlan && planReport && planReport.recommended) {
      const rec = planReport.recommended;
      const satCount = Array.isArray(planReport.evaluatedAlternatives)
        ? planReport.evaluatedAlternatives.filter(a => a.allConstraintsSatisfied).length
        : 1;
      const totCount = Array.isArray(planReport.evaluatedAlternatives)
        ? planReport.evaluatedAlternatives.length
        : 3;
      const secPlanBit = planReport.secondaryTargetEntityId
        ? ` · İkincil Hedef <strong>${escapeHtml(planReport.secondaryTargetEntityLabel)}</strong>: <strong>%${planReport.secondaryInitialLoadPct} → %${rec.projectedSecondaryLoadPct}</strong>`
        : '';
      const envBit = runEnv
        ? ` <span class="mono" style="font-size:0.76rem; color:#88D4FF;">[Zarf: ${escapeHtml(runEnv.inputSnapshotHash)} · ${escapeHtml(runEnv.modelVersion)} · Tohum=${Number(cfData.seed)}]</span>`
        : '';

      el.cfExecutiveVerdict.innerHTML =
        `<strong>Kontrollü Planlama ve Kısıt Çözümü Özeti (Tepe Yük &le; %${planReport.constraints.maxAllowedPeakLoadPct} · Kapasite &ge; %${planReport.constraints.minAllowedThroughputPct} · Sürtünme &le; ${planReport.constraints.maxAllowedFriction}×):</strong> ` +
        `İncelenen <strong>${totCount}</strong> aday politikadan <strong>${satCount}</strong> tanesi tüm güvenlik kısıtlarını sağladı. ` +
        `Önerilen kontrollü plan <strong>"${escapeHtml(rec.actionName)}"</strong> uygulandığında birincil hedef <strong>${escapeHtml(planReport.targetEntityLabel)}</strong> yükü <strong>%${planReport.targetInitialLoadPct} → %${rec.projectedTargetLoadPct}</strong> seviyesine çekilmekte${secPlanBit} ve dönem sonu kapasite <strong>%${bbTpPct}</strong> (${deltaTp >= 0 ? '+' : ''}${deltaTp} puan fark) olarak korunmaktadır.` +
        escapeHtml(finSummary) + envBit;
    } else {
      el.cfExecutiveVerdict.innerHTML =
        `<strong>Senaryo Karşılaştırma Özeti (${escapeHtml(horizonHrs)} Saatlik Simülasyon · Başlangıç Kapasitesi %${initTpPct}):</strong> ` +
        `<strong>Hiçbir şey yapılmazsa</strong> çalışma kapasitesi <strong>%${baTpPct}</strong> seviyesine (${baUnits} / ${fin.baselineUnitsPerHour} ${escapeHtml(fin.unitName)}) düşmekte` +
        (ba.outage_active ? ` ve <strong>${escapeHtml(baOutageHrs)} saat (${baOutageTicks} adım) kesinti</strong> oluşmaktadır.` : '.') +
        ` <strong>"${escapeHtml(leverReadableName)}"</strong> adımı uygulanırsa ` +
        (preventedOutage ? `<strong>bu senaryoda kesinti oluşmadı</strong> ve ` : '') +
        `dönem sonu çalışma kapasitesi <strong>%${bbTpPct}</strong> (${bbUnits} / ${fin.baselineUnitsPerHour} ${escapeHtml(fin.unitName)} · <strong>${deltaTp >= 0 ? '+' : ''}${deltaTp} puan fark</strong>) olarak hesaplanmıştır.` +
        targetSummaryBit +
        escapeHtml(finSummary);
    }
  }

  // Aktif seçimler özet çubuğunu güncelle
  const sumWorldEl = document.getElementById('scen-sum-world');
  const sumEntityEl = document.getElementById('scen-sum-entity');
  const sumLeverEl = document.getElementById('scen-sum-lever');
  const sumHorizonEl = document.getElementById('scen-sum-horizon');
  if (sumWorldEl && ev && ev.profile) {
    sumWorldEl.textContent = String(ev.profile.title || 'Liman Soğuk Zincir').split('(')[0].trim();
  }
  if (sumEntityEl && targetNode) {
    sumEntityEl.textContent = `${String(targetNode.label || 'Hedef Varlık').split('(')[0].trim()} (%${targetNode.startStatePct ?? 78})`;
  }
  if (sumLeverEl) {
    sumLeverEl.textContent = String(leverReadableName || 'Seçili Müdahale').split('(')[0].trim();
  }
  if (sumHorizonEl) {
    sumHorizonEl.textContent = `${horizonHrs} Saat (${horizonTicks} adım)`;
  }

  // 2. İki Büyük Yan Yana Karşılaştırma Kartı (Standart A/B veya Kontrollü Plan Kısıt Çözümü)
  const cardA = document.createElement('div');
  cardA.className = 'ab-card branch-a';
  const aCostStr = fin.available && cfRowA.expectedLoss24hUsd !== null
    ? `${fmtUsd(cfRowA.expectedLoss24hUsd)} (Tahmini Kayıp)`
    : 'Hesaplanamadı';
  const aCostSub = fin.available
    ? `${horizonHrs} saatlik simülasyon dönemi tahmini kaybı`
    : 'Birim maliyet verisi tanımlanmadı';
  const aTargetText = targetNode
    ? `${targetNode.label}: %${targetNode.branchAStatePct} yük${targetNode.branchAOutage ? ' (Kesinti oluştu)' : ''}` +
      (secTargetNode ? ` · İkincil (${secTargetNode.label}): %${secTargetNode.branchAStatePct} yük` : '')
    : 'Kritik varlık verisi yok';

  const aTitleText = isControlledPlan
    ? 'Kısıtsız / Müdahalesiz Baz Durum (Kısıt Denetimi)'
    : 'Hiçbir şey yapılmazsa';
  const aSubText = isControlledPlan && planReport
    ? `Kısıt Eşikleri: Tepe Yük ≤ %${planReport.constraints.maxAllowedPeakLoadPct} · Kapasite ≥ %${planReport.constraints.minAllowedThroughputPct}`
    : `${escapeHtml(horizonHrs)} saat (${horizonTicks} adım) sonunda mevcut koşulların model çıktısı`;
  const aBadgeText = isControlledPlan && planReport
    ? ((targetNode && targetNode.branchAStatePct > planReport.constraints.maxAllowedPeakLoadPct) || baTpPct < planReport.constraints.minAllowedThroughputPct
        ? 'Kısıt İhlali Oluştu'
        : 'Baz Kısıt Durumu')
    : (ba.outage_active ? 'Bu senaryoda kesinti oluştu' : 'Kapasite düşüşü');

  const buildOrionMetricRingSvg = (pctVal, strokeColor, trackColor = 'rgba(136,212,255,0.16)') => {
    const clamped = Math.max(0, Math.min(100, Math.round(Number(pctVal) || 0)));
    const r = 17;
    const c = 2 * Math.PI * r;
    const dash = ((clamped / 100) * c).toFixed(1);
    return `<svg class="orion-metric-ring-svg" viewBox="0 0 44 44" aria-hidden="true">
      <circle cx="22" cy="22" r="${r}" fill="none" stroke="${trackColor}" stroke-width="3.5" />
      <circle cx="22" cy="22" r="${r}" fill="none" stroke="${strokeColor}" stroke-width="3.5" stroke-linecap="round" stroke-dasharray="${dash} ${c.toFixed(1)}" transform="rotate(-90 22 22)" />
      <text x="22" y="25" text-anchor="middle" fill="#F8FAFC" font-size="9.5" font-weight="700" font-family="JetBrains Mono, monospace">%${clamped}</text>
    </svg>`;
  };

  const aRingColor = ba.outage_active || baTpPct < 40 ? '#F87171' : '#FBBF24';
  const bRingColor = bb.outage_active ? '#F87171' : '#34D399';
  const aLoadPct = targetNode ? Number(targetNode.branchAStatePct ?? 90) : (100 - baTpPct);
  const bLoadPct = targetNode ? Number(targetNode.branchBStatePct ?? 60) : (100 - bbTpPct);

  cardA.innerHTML = `
    <div class="ab-card-header">
      <div>
        <div class="ab-card-title">${escapeHtml(aTitleText)}</div>
        <div class="ab-card-subtitle">${aSubText}</div>
      </div>
      <span class="kpi-badge ${ba.outage_active || isControlledPlan ? 'crit' : 'warn'}">
        ${escapeHtml(aBadgeText)}
      </span>
    </div>
    <div class="ab-metrics-grid">
      <div class="ab-metric-box">
        <div class="ab-metric-label">Dönem Sonu Çalışma Kapasitesi</div>
        <div class="orion-metric-ring-row">
          ${buildOrionMetricRingSvg(baTpPct, aRingColor)}
          <div>
            <div class="ab-metric-val" style="color:${ba.outage_active || baTpPct < 40 ? 'var(--crit)' : 'var(--text-1)'};">%${baTpPct}</div>
            <div class="ab-metric-sub">${baUnits} / ${Number(fin.baselineUnitsPerHour)} ${escapeHtml(fin.unitName)} (Ort: %${baAvgTpPct})</div>
          </div>
        </div>
      </div>
      <div class="ab-metric-box">
        <div class="ab-metric-label">Kesinti Süresi ve Hedef Yük</div>
        <div class="orion-metric-ring-row">
          ${buildOrionMetricRingSvg(aLoadPct, '#F87171')}
          <div>
            <div class="ab-metric-val" style="color:${ba.outage_active ? 'var(--crit)' : 'var(--text-1)'};">
              ${ba.outage_active ? `${escapeHtml(baOutageHrs)} Saat Kesinti` : '0 Saat Kesinti'}
            </div>
            <div class="ab-metric-sub">${baOutageTicks} adım kesinti · Kritik Eşik: ${ba.any_deadline_missed ? 'Aşıldı' : 'Korundu'}</div>
          </div>
        </div>
      </div>
      <div class="ab-metric-box">
        <div class="ab-metric-label">Dönem Boyunca Tahmini Kayıp (${escapeHtml(horizonHrs)} Saat)</div>
        <div class="ab-metric-val" style="color:${fin.available ? 'var(--crit)' : 'var(--text-3)'};">${escapeHtml(aCostStr)}</div>
        <div class="ab-metric-sub">${escapeHtml(aCostSub)}</div>
      </div>
      <div class="ab-metric-box">
        <div class="ab-metric-label">Operasyonel Yavaşlama ve Kalıcı Etki</div>
        <div class="ab-metric-val">${Number(ba.clamped_friction ?? 1).toFixed(2)}×</div>
        <div class="ab-metric-sub">Kalıcı Kapasite Kaybı: ${ba.any_hysteresis_flip ? 'Oluştu' : 'Oluşmadı'}</div>
      </div>
    </div>
    <ul class="ab-detail-list">
      <li>• <strong>Hedef Varlık Durumu:</strong> ${escapeHtml(aTargetText)}</li>
      <li>• <strong>Değişiklik Maliyeti:</strong> $0 (Müdahale uygulanmadı)</li>
    </ul>
  `;

  const cardB = document.createElement('div');
  cardB.className = 'ab-card branch-b';
  const bPrevented = ba.outage_active && !bb.outage_active;
  const bNetStr = fin.available && cfRowB.netProtectedValueUsd !== null && cfRowB.netProtectedValueUsd !== undefined
    ? `${cfRowB.netProtectedValueUsd >= 0 ? '+' : ''}${fmtUsd(cfRowB.netProtectedValueUsd)}`
    : 'Hesaplanamadı';
  const bNetSub = fin.available && cfRowB.expectedLoss24hUsd !== null
    ? `Değişiklik Maliyeti: ${fmtUsd(cfRowB.interventionCostUsd)} · Kalan Kayıp: ${fmtUsd(cfRowB.expectedLoss24hUsd)}`
    : 'Birim maliyet verisi tanımlanmadı';
  const bTargetText = targetNode
    ? `${targetNode.label}: %${targetNode.branchAStatePct} → %${targetNode.branchBStatePct} (${targetNode.deltaStatePct > 0 ? '+' : ''}${targetNode.deltaStatePct} puan)` +
      (secTargetNode ? ` · İkincil (${secTargetNode.label}): %${secTargetNode.branchAStatePct} → %${secTargetNode.branchBStatePct}` : '')
    : 'Kritik varlık verisi yok';

  if (isControlledPlan && planReport && planReport.recommended) {
    const rec = planReport.recommended;
    const altRows = (planReport.evaluatedAlternatives || [])
      .map((alt, idx) => `${idx + 1}. ${alt.actionName}: Tepe %${alt.projectedPeakLoadPct}, Kap. %${alt.projectedThroughputPct} (${alt.allConstraintsSatisfied ? 'Kısıt Sağlandı' : 'Kısıt İhlali'})`)
      .join(' | ');
    const secMetricLine = planReport.secondaryTargetEntityId
      ? ` · İkincil (${planReport.secondaryTargetEntityLabel}): %${planReport.secondaryInitialLoadPct} → %${rec.projectedSecondaryLoadPct}`
      : '';

    cardB.innerHTML = `
      <div class="ab-card-header">
        <div>
          <div class="ab-card-title">Kontrollü Plan Çözümü: ${escapeHtml(rec.actionName)}</div>
          <div class="ab-card-subtitle">Kısıt Tabanlı Planlayıcı · Hedef: ${escapeHtml(planReport.targetEntityLabel)}${planReport.secondaryTargetEntityId ? ` + ${escapeHtml(planReport.secondaryTargetEntityLabel)}` : ''}</div>
        </div>
        <span class="kpi-badge ${rec.allConstraintsSatisfied ? 'ok' : 'warn'}">
          ${rec.allConstraintsSatisfied ? `Tüm Kısıtlar Sağlandı (+${deltaTp} puan)` : `En İyi Uygulanabilir Plan (+${deltaTp} puan)`}
        </span>
      </div>
      <div class="ab-metrics-grid">
        <div class="ab-metric-box">
          <div class="ab-metric-label">Kısıt Sonrası Çalışma Kapasitesi (Eşik ≥ %${planReport.constraints.minAllowedThroughputPct})</div>
          <div class="orion-metric-ring-row">
            ${buildOrionMetricRingSvg(bbTpPct, bRingColor)}
            <div>
              <div class="ab-metric-val" style="color:var(--ok);">%${bbTpPct} <span style="font-size:15px;">(${deltaTp >= 0 ? '+' : ''}${deltaTp} puan)</span></div>
              <div class="ab-metric-sub">Planlanan: %${rec.projectedThroughputPct} · Durum: ${rec.constraints.throughputConstraintMet ? 'Sağlandı' : 'Sınırda'}</div>
            </div>
          </div>
        </div>
        <div class="ab-metric-box">
          <div class="ab-metric-label">Hedef Varlık Yük İndirimi (Eşik ≤ %${planReport.constraints.maxAllowedPeakLoadPct})</div>
          <div class="orion-metric-ring-row">
            ${buildOrionMetricRingSvg(rec.projectedTargetLoadPct, '#88D4FF')}
            <div>
              <div class="ab-metric-val" style="color:${rec.constraints.loadConstraintMet ? 'var(--ok)' : 'var(--warn)'};">
                %${planReport.targetInitialLoadPct} → %${rec.projectedTargetLoadPct}
              </div>
              <div class="ab-metric-sub">Tepe Yük: %${rec.projectedPeakLoadPct}${escapeHtml(secMetricLine)}</div>
            </div>
          </div>
        </div>
        <div class="ab-metric-box">
          <div class="ab-metric-label">Net Korunan Değer / Plan Skoru</div>
          <div class="ab-metric-val" style="color:${fin.available ? 'var(--ok)' : '#88D4FF'};">${fin.available ? escapeHtml(bNetStr) : `Skor: ${rec.planScore}`}</div>
          <div class="ab-metric-sub">${escapeHtml(bNetSub)}</div>
        </div>
        <div class="ab-metric-box">
          <div class="ab-metric-label">Sürtünme Kısıtı (Eşik ≤ ${planReport.constraints.maxAllowedFriction}×)</div>
          <div class="ab-metric-val" style="color:${rec.constraints.frictionConstraintMet ? 'var(--ok)' : 'var(--warn)'};">${Number(bb.clamped_friction ?? rec.projectedFriction ?? 1).toFixed(2)}×</div>
          <div class="ab-metric-sub">Kalıcı Kayıp: ${bb.any_hysteresis_flip ? 'Oluştu' : 'Önlendi'} · Kesinti: ${bb.outage_active ? `${escapeHtml(bbOutageHrs)}s` : '0s'}</div>
        </div>
      </div>
      <ul class="ab-detail-list">
        <li>• <strong>Hedef Süreç Noktasındaki Değişim:</strong> ${escapeHtml(bTargetText)}</li>
        <li>• <strong>Aday Plan Sıralaması:</strong> ${escapeHtml(altRows)}</li>
        <li>• <strong>Çalıştırma Zarfı (Run Envelope):</strong> <span class="mono">${escapeHtml(runEnv ? `${runEnv.inputSnapshotHash} · ${runEnv.modelVersion}` : 'CAELUS-PLANNER-2.2')}</span> · Ufuk=${horizonTicks} adım · Tohum=${Number(cfData.seed)}</li>
      </ul>
    `;
  } else {
    cardB.innerHTML = `
      <div class="ab-card-header">
        <div>
          <div class="ab-card-title">Bu adım uygulanırsa: ${escapeHtml(leverReadableName)}</div>
          <div class="ab-card-subtitle">${escapeHtml(horizonHrs)} saat (${horizonTicks} adım) sonunda seçilen değişikliğin model çıktısı</div>
        </div>
        <span class="kpi-badge ${bb.outage_active ? 'crit' : 'ok'}">
          ${bPrevented ? `Bu senaryoda kesinti oluşmadı (+${deltaTp} puan)` : `Model çıktısı (${deltaTp >= 0 ? '+' : ''}${deltaTp} puan)`}
        </span>
      </div>
      <div class="ab-metrics-grid">
        <div class="ab-metric-box">
          <div class="ab-metric-label">Dönem Sonu Çalışma Kapasitesi</div>
          <div class="orion-metric-ring-row">
            ${buildOrionMetricRingSvg(bbTpPct, bRingColor)}
            <div>
              <div class="ab-metric-val" style="color:var(--ok);">%${bbTpPct} <span style="font-size:15px;">(${deltaTp >= 0 ? '+' : ''}${deltaTp} puan)</span></div>
              <div class="ab-metric-sub">${bbUnits} / ${Number(fin.baselineUnitsPerHour)} ${escapeHtml(fin.unitName)} (Ort: %${bbAvgTpPct})</div>
            </div>
          </div>
        </div>
        <div class="ab-metric-box">
          <div class="ab-metric-label">Kesinti Süresi ve Hedef Yük</div>
          <div class="orion-metric-ring-row">
            ${buildOrionMetricRingSvg(bLoadPct, '#88D4FF')}
            <div>
              <div class="ab-metric-val" style="color:${bb.outage_active ? 'var(--crit)' : 'var(--ok)'};">
                ${bb.outage_active ? `${escapeHtml(bbOutageHrs)} Saat Kesinti` : (bPrevented ? '0 Saat (Bu senaryoda kesinti oluşmadı)' : '0 Saat Kesinti')}
              </div>
              <div class="ab-metric-sub">Kesinti Farkı: ${bbOutageTicks - baOutageTicks} adım · Kritik Eşik: ${bb.any_deadline_missed ? 'Aşıldı' : 'Korundu'}</div>
            </div>
          </div>
        </div>
        <div class="ab-metric-box">
          <div class="ab-metric-label">Net Korunan Değer / Yatırım Getirisi (ROI)</div>
          <div class="ab-metric-val" style="color:${fin.available ? 'var(--ok)' : 'var(--text-3)'};">${escapeHtml(bNetStr)}</div>
          <div class="ab-metric-sub">${escapeHtml(bNetSub)}</div>
        </div>
        <div class="ab-metric-box">
          <div class="ab-metric-label">Operasyonel Yavaşlama ve Kalıcı Etki</div>
          <div class="ab-metric-val">${Number(bb.clamped_friction ?? 1).toFixed(2)}×</div>
          <div class="ab-metric-sub">Kalıcı Kapasite Kaybı: ${bb.any_hysteresis_flip ? 'Oluştu' : 'Bu senaryoda oluşmadı'}</div>
        </div>
      </div>
      <ul class="ab-detail-list">
        <li>• <strong>Hedef Süreç Noktasındaki Değişim:</strong> ${escapeHtml(bTargetText)}</li>
        <li>• <strong>Sonucun Dayanağı:</strong> Deterministik Senaryo Motoru (${escapeHtml(horizonHrs)} saatlik paralel karşılaştırma · Teknik kanıt 4. adımda)</li>
      </ul>
    `;
  }

  el.cfSideBySideCards.appendChild(cardA);
  el.cfSideBySideCards.appendChild(cardB);

  if (typeof renderScenarioEChartsComparison === 'function') {
    renderScenarioEChartsComparison(cfData, ev, {
      initTpPct,
      baTpPct,
      bbTpPct,
      baAvgTpPct,
      bbAvgTpPct,
      horizonTicks,
      horizonHrs,
      baOutageTicks,
      bbOutageTicks,
      leverReadableName
    });
  }

  // If a Real-World Data (Open-Meteo Weather + Marine) Snapshot is active, show 3-Layer Epistemic Separation in Senaryolar view
  const activeWorldForSnap = typeof getActiveDigitalWorld === 'function' ? getActiveDigitalWorld() : null;
  const latestRwSnap = activeWorldForSnap && Array.isArray(activeWorldForSnap.realDataScenarioSnapshots) && activeWorldForSnap.realDataScenarioSnapshots.length > 0
    ? activeWorldForSnap.realDataScenarioSnapshots[0]
    : null;
  let rwEpistemicBox = document.getElementById('cf-realdata-epistemic-box');
  if (latestRwSnap && latestRwSnap.engineComparison && latestRwSnap.engineComparison.separatedLayers) {
    if (!rwEpistemicBox) {
      rwEpistemicBox = document.createElement('div');
      rwEpistemicBox.id = 'cf-realdata-epistemic-box';
      rwEpistemicBox.style.cssText = 'background:var(--bg-subtle); border:1px solid var(--border-strong); border-left:4px solid var(--accent); border-radius:8px; padding:12px 14px; font-size:0.82rem; color:var(--text-2); display:flex; flex-direction:column; gap:8px;';
      el.cfSideBySideBox.appendChild(rwEpistemicBox);
    }
    const sl = latestRwSnap.engineComparison.separatedLayers;
    const srcRecs = Array.isArray(sl.realWorldInputRecords) ? sl.realWorldInputRecords : [];
    const mapRules = Array.isArray(sl.userTransformationAssumptions) ? sl.userTransformationAssumptions : [];
    const outSummary = sl.engineModelOutputSummary || {};
    rwEpistemicBox.classList.remove('hidden');
    rwEpistemicBox.innerHTML = `
      <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px;">
        <strong style="color:var(--text-1); font-size:0.88rem;">Kaynak Model Verisi · Kullanıcı Dönüşüm Varsayımı · Motor Çıktısı Ayrımı (${escapeHtml(latestRwSnap.locationLabel || 'Ege Denizi')})</strong>
        <span class="kpi-badge ok">Ana Dünya Durumu Korundu (${escapeHtml(latestRwSnap.preRunRealStateHash)} === ${escapeHtml(latestRwSnap.engineComparison.postRunRealStateHash)})</span>
      </div>
      <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(230px, 1fr)); gap:10px;">
        <div style="background:var(--bg-surface); border:1px solid var(--border); border-radius:6px; padding:8px 10px;">
          <div style="margin-bottom:4px;"><span class="kpi-badge accent" style="font-size:0.68rem;">1. DIŞ KAYNAKTAN GELEN MODEL VERİSİ</span></div>
          <div><strong>Geçerlilik Zamanı:</strong> <code class="mono">${escapeHtml(latestRwSnap.validTimeIso)}</code></div>
          <div><strong>Yayımlanma Zamanı:</strong> <code class="mono">${escapeHtml(latestRwSnap.modelPublishedTimeIso || 'Belirtilmedi')}</code></div>
          <div><strong>Alınma Zamanı:</strong> <code class="mono">${escapeHtml(latestRwSnap.ingestedAtIso)}</code></div>
          <div style="margin-top:4px; color:var(--text-3); font-size:0.76rem;">${srcRecs.slice(0, 4).map(r => `${escapeHtml(r.variableLabel || r.variableName)}: ${Number(r.normalizedValue ?? r.rawValue).toFixed(2)} ${escapeHtml(r.normalizedUnit || r.rawUnit)}`).join(' · ')}</div>
        </div>
        <div style="background:var(--bg-surface); border:1px solid var(--border); border-radius:6px; padding:8px 10px;">
          <div style="margin-bottom:4px;"><span class="kpi-badge warn" style="font-size:0.68rem;">2. KULLANICI / MODEL VARSAYIMI</span></div>
          <div><strong>Eşleştirme Sürümü:</strong> <code class="mono">${escapeHtml(latestRwSnap.mappingVersion || 'Ege Liman Eşleştirmesi v1.0')}</code> (Kullanıcı Onaylı)</div>
          <div><strong>Uygulanan Değişiklik:</strong> <span>${escapeHtml(leverReadableName)}</span></div>
          <div style="margin-top:4px; color:var(--text-3); font-size:0.76rem;">${mapRules.map(m => `${escapeHtml(m.sourceVariable)} → %${Number(m.mappedStatePct)} yük`).join(' · ')}</div>
        </div>
        <div style="background:var(--bg-surface); border:1px solid var(--border); border-radius:6px; padding:8px 10px;">
          <div style="margin-bottom:4px;"><span class="kpi-badge ok" style="font-size:0.68rem;">3. MOTOR ÇIKTISI</span></div>
          <div><strong>Hesaplama Motoru:</strong> <code class="mono">${escapeHtml(outSummary.engineVersion || 'CAELUS C++17 Nedensel Motor v2.0')}</code></div>
          <div><strong>Karşılaştırma:</strong> Kapasite %${Number(latestRwSnap.engineComparison.branchAThroughputPct)} → <strong>%${Number(latestRwSnap.engineComparison.branchBThroughputPct)}</strong></div>
          <div style="margin-top:4px; color:var(--text-3); font-size:0.75rem;">${escapeHtml(latestRwSnap.engineComparison.repeatabilityVsAccuracyNotice || '')}</div>
        </div>
      </div>
      <details style="font-size:0.76rem; color:var(--text-3);">
        <summary style="cursor:pointer; font-weight:600; color:var(--text-2);">Teknik ayrıntıları, eksik girdileri ve model sınırlarını göster</summary>
        <div style="margin-top:6px; padding:8px; background:var(--bg-surface); border:1px solid var(--border); border-radius:6px;">
          <div><strong>Anlık Görüntü ID:</strong> <code class="mono">${escapeHtml(latestRwSnap.snapshotId)}</code> · <strong>Ham Yanıt Özeti:</strong> <code class="mono">${escapeHtml(srcRecs[0] ? srcRecs[0].rawPayloadHash : '—')}</code></div>
          <div><strong>Eksik Girdiler:</strong> ${escapeHtml((latestRwSnap.missingInputs && latestRwSnap.missingInputs.length > 0) ? latestRwSnap.missingInputs.map(x => `${x.variableName} (${x.reason})`).join(', ') : 'Yok (11/11 değişken tam)')}</div>
          <div><strong>Kıyı Çözünürlüğü ve Model Sınırları:</strong> Kıyı ve deniz verileri karar desteği ve senaryo incelemesi içindir; sağlayıcının belirttiği kıyı çözünürlüğü sınırları (~5–8 km grid hücresi) dikkate alınmalıdır. Tek başına tekrarlanabilirlik gerçek dünya doğruluğu anlamına gelmez.</div>
        </div>
      </details>
    `;
  } else if (rwEpistemicBox) {
    rwEpistemicBox.classList.add('hidden');
  }

  const nodeCmpRows = Array.isArray(ev.nodeComparison) ? ev.nodeComparison : [];
  nodeCmpRows.forEach(n => {
    const tr = document.createElement('tr');

    const tdNode = document.createElement('td');
    tdNode.style.fontWeight = '600';
    tdNode.textContent = n.label;
    if (n.isTarget) {
      const tgt = document.createElement('span');
      tgt.className = 'kpi-badge ok';
      tgt.style.marginLeft = '6px';
      tgt.textContent = 'HEDEF VARLIK';
      tdNode.appendChild(tgt);
    }

    const tdStart = document.createElement('td');
    tdStart.className = 'mono';
    tdStart.textContent = n.startStatePct !== null ? `%${n.startStatePct}` : '—';

    const tdA = document.createElement('td');
    tdA.className = 'mono';
    tdA.style.color = n.branchAOutage || n.branchAStatePct >= 80 ? 'var(--crit)' : 'var(--text-1)';
    tdA.textContent = `%${n.branchAStatePct}` + (n.branchAOutage ? ' (Kesinti)' : n.branchAIrrecoverable ? ' (Kalıcı kayıp)' : '');

    const tdB = document.createElement('td');
    tdB.className = 'mono';
    tdB.style.fontWeight = '700';
    tdB.style.color = n.branchBOutage || n.branchBStatePct >= 80 ? 'var(--crit)' : 'var(--ok)';
    tdB.textContent = `%${n.branchBStatePct}` + (n.branchBOutage ? ' (Kesinti)' : n.branchBIrrecoverable ? ' (Kalıcı kayıp)' : '');

    const tdDelta = document.createElement('td');
    tdDelta.className = 'mono';
    tdDelta.style.fontWeight = '700';
    tdDelta.style.color = n.deltaStatePct < 0 ? 'var(--ok)' : n.deltaStatePct > 0 ? 'var(--crit)' : 'var(--text-3)';
    tdDelta.textContent = `${n.deltaStatePct > 0 ? '+' : ''}${n.deltaStatePct} puan`;

    const tdSummary = document.createElement('td');
    const sumBadge = document.createElement('span');
    if (n.branchAOutage && !n.branchBOutage) {
      sumBadge.className = 'kpi-badge ok';
      sumBadge.textContent = 'Bu senaryoda kesinti oluşmadı';
    } else if (n.branchAIrrecoverable && !n.branchBIrrecoverable) {
      sumBadge.className = 'kpi-badge ok';
      sumBadge.textContent = 'Bu senaryoda kalıcı kayıp oluşmadı';
    } else if (n.deltaStatePct < 0) {
      sumBadge.className = 'kpi-badge ok';
      sumBadge.textContent = 'Darboğaz yükü azaldı';
    } else if (n.branchBOutage) {
      sumBadge.className = 'kpi-badge crit';
      sumBadge.textContent = 'Kesinti devam ediyor';
    } else {
      sumBadge.className = 'kpi-badge';
      sumBadge.textContent = 'Aynı seyir';
    }
    tdSummary.appendChild(sumBadge);

    tr.appendChild(tdNode);
    tr.appendChild(tdStart);
    tr.appendChild(tdA);
    tr.appendChild(tdB);
    tr.appendChild(tdDelta);
    tr.appendChild(tdSummary);
    el.cfNodeCompareTbody.appendChild(tr);
  });
}

function renderTimeHorizons(horizons) {
  if (!el.horizonsContainer) return;
  el.horizonsContainer.innerHTML = '';

  horizons.forEach(h => {
    const card = document.createElement('div');
    card.className = 'horizon-card';

    const top = document.createElement('div');
    top.style.display = 'flex';
    top.style.justifyContent = 'space-between';
    top.style.alignItems = 'center';

    const win = document.createElement('span');
    win.className = 'horizon-window';
    win.textContent = h.window;

    const badge = document.createElement('span');
    const isCrit = h.projectedCapacityPct < 45;
    const isWarn = !isCrit && h.projectedCapacityPct < 75;
    badge.className = 'kpi-badge ' + (isCrit ? 'crit' : isWarn ? 'warn' : 'ok');
    badge.textContent = h.state;

    top.appendChild(win);
    top.appendChild(badge);

    const lbl = document.createElement('div');
    lbl.className = 'horizon-label';
    lbl.textContent = h.label;

    const metrics = document.createElement('div');
    metrics.className = 'horizon-metrics';

    const cap = document.createElement('span');
    cap.className = 'horizon-cap';
    cap.textContent = `%${h.projectedCapacityPct} (${h.projectedUnits})`;

    const risk = document.createElement('span');
    risk.className = 'horizon-risk';
    risk.textContent = h.financialExposureUsd === null
      ? 'Maliyet: Hesaplanamadı'
      : `${fmtUsd(h.financialExposureUsd)} Varsayımsal Risk`;

    metrics.appendChild(cap);
    metrics.appendChild(risk);

    const drv = document.createElement('div');
    drv.className = 'horizon-driver';
    drv.textContent = `Ana Etken: ${h.driver}`;

    card.appendChild(top);
    card.appendChild(lbl);
    card.appendChild(metrics);
    card.appendChild(drv);
    el.horizonsContainer.appendChild(card);
  });
}

function renderCounterfactualTable(counterfactuals, recommendedPolicy) {
  if (!el.counterfactualTbody) return;
  el.counterfactualTbody.innerHTML = '';

  const isSimulated = Boolean(state.lastEvaluation && state.lastEvaluation.isCounterfactualSimulated);

  if (el.roiBestBadge) {
    if (isSimulated && state.lastEngineCounterfactual) {
      el.roiBestBadge.textContent = `Karşılaştırma Tamamlandı (${state.lastEngineCounterfactual.horizon_ticks} adım · Tohum: ${state.lastEngineCounterfactual.seed})`;
      el.roiBestBadge.className = 'kpi-badge ok';
    } else if (recommendedPolicy) {
      const roiTxt = recommendedPolicy.roiMultiple !== null ? `${recommendedPolicy.roiMultiple}x Varsayımsal` : `p=%${recommendedPolicy.successProbPct}`;
      el.roiBestBadge.textContent = `Önerilen Seçenek: ${recommendedPolicy.name || recommendedPolicy.code} (${roiTxt})`;
      el.roiBestBadge.className = 'kpi-badge warn';
    } else {
      el.roiBestBadge.textContent = 'KARŞILAŞTIRMA BEKLENİYOR';
      el.roiBestBadge.className = 'kpi-badge warn';
    }
  }

  counterfactuals.forEach(cf => {
    const tr = document.createElement('tr');
    if (cf.id === 'CF_RECOMMENDED' || cf.id === 'CF_ENGINE_BRANCH_B') tr.className = 'row-recommended';

    const tdBranch = document.createElement('td');
    tdBranch.style.fontWeight = '600';
    tdBranch.style.color = 'var(--text-1)';
    tdBranch.textContent = cf.branch;

    const tdCap = document.createElement('td');
    tdCap.className = 'mono';
    tdCap.style.fontWeight = '700';
    tdCap.textContent = `%${cf.projectedCapacityPct}`;

    const tdSla = document.createElement('td');
    const slaBadge = document.createElement('span');
    slaBadge.className = 'kpi-badge ' + cf.tone;
    slaBadge.textContent = cf.slaStatus;
    tdSla.appendChild(slaBadge);

    const tdCost = document.createElement('td');
    tdCost.className = 'mono';
    tdCost.textContent = cf.interventionCostUsd === 0
      ? '$0 (Müdahalesiz)'
      : fmtUsd(cf.interventionCostUsd);

    const tdLoss = document.createElement('td');
    tdLoss.className = 'mono';
    tdLoss.style.color = cf.tone === 'ok' ? 'var(--text-2)' : 'var(--crit)';
    tdLoss.textContent = fmtUsd(cf.expectedLoss24hUsd);

    const tdNet = document.createElement('td');
    tdNet.className = 'mono';
    tdNet.style.fontWeight = '700';
    if (cf.netProtectedValueUsd === null || cf.netProtectedValueUsd === undefined) {
      tdNet.style.color = 'var(--text-3)';
      tdNet.textContent = `Hesaplanamadı (${cf.roiLabel})`;
    } else {
      tdNet.style.color = cf.netProtectedValueUsd >= 0 ? 'var(--ok)' : 'var(--crit)';
      const prefix = cf.netProtectedValueUsd > 0 ? '+' : '';
      tdNet.textContent = `${prefix}${fmtUsd(cf.netProtectedValueUsd)} (${cf.roiLabel})`;
    }

    tr.appendChild(tdBranch);
    tr.appendChild(tdCap);
    tr.appendChild(tdSla);
    tr.appendChild(tdCost);
    tr.appendChild(tdLoss);
    tr.appendChild(tdNet);
    el.counterfactualTbody.appendChild(tr);
  });
}

function renderPolicyCards(rankedPolicies, recommendedPolicy) {
  if (!el.policyCardsList) return;
  el.policyCardsList.innerHTML = '';

  if (!rankedPolicies || rankedPolicies.length === 0) {
    const empty = document.createElement('div');
    empty.style.fontSize = '11.5px';
    empty.style.color = 'var(--text-4)';
    empty.textContent = 'Aktif motor bağlantısı veya tanımlı müdahale kaldıracı bulunmuyor.';
    el.policyCardsList.appendChild(empty);
    return;
  }

  const canSimulate = state.engineMode === 'ws' || state.engineMode === 'wasm';
  const canCompareBranches = state.engineMode === 'ws';

  rankedPolicies.forEach(pol => {
    const isOptimal = recommendedPolicy && recommendedPolicy.id === pol.id;
    const card = document.createElement('div');
    card.className = 'policy-card' + (isOptimal ? ' optimal' : '');

    const top = document.createElement('div');
    top.className = 'policy-top';

    const titleWrap = document.createElement('div');
    const codeSpan = document.createElement('div');
    codeSpan.className = 'policy-code';
    codeSpan.textContent = `${pol.code} · MOTOR KODU: ${pol.id} · [${provenanceShortTag(pol.dataSource)}]`;
    const nameSpan = document.createElement('div');
    nameSpan.className = 'policy-name';
    nameSpan.textContent = pol.name;
    titleWrap.appendChild(codeSpan);
    titleWrap.appendChild(nameSpan);

    const badge = document.createElement('span');
    badge.className = 'kpi-badge ' + (isOptimal ? 'ok' : pol.available ? '' : 'warn');
    const roiTag = pol.roiMultiple !== null ? `${pol.roiMultiple}x Varsayımsal` : `p=%${pol.successProbPct}`;
    badge.textContent = isOptimal
      ? `★ ÖNERİLEN (${roiTag})`
      : pol.available
        ? roiTag
        : `KİLİTLİ (${pol.cooldownRemaining}t)`;

    top.appendChild(titleWrap);
    top.appendChild(badge);

    const desc = document.createElement('div');
    desc.className = 'policy-desc';
    desc.textContent = pol.summary;

    const metrics = document.createElement('div');
    metrics.className = 'policy-metrics';
    const statePct = Math.round((pol.stateDelta || 0) * 100);
    const fricPct = Math.round((pol.frictionDelta || 0) * 100);
    const items = [
      ['BAŞARI OLASILIĞI', `%${pol.successProbPct} (Süre: ${pol.costTicks}t · Kilit: ${pol.lockoutTicks}t)`],
      ['MOTOR ETKİSİ (ON_SUCCESS)', `ΔYük: ${statePct}% · ΔSürtünme: ${fricPct}%`],
      ['VARSAYIMSAL MALİYET', fmtUsd(pol.costUsd)],
      ['TEORİK KORUMA (24S)', pol.avoidedLossUsd === null ? 'Hesaplanamadı' : `+${fmtUsd(pol.avoidedLossUsd)}`]
    ];
    items.forEach(([k, v]) => {
      const cell = document.createElement('div');
      cell.className = 'pm-item';
      const l = document.createElement('span');
      l.className = 'pm-label';
      l.textContent = k;
      const val = document.createElement('span');
      val.className = 'pm-val';
      val.textContent = v;
      cell.appendChild(l);
      cell.appendChild(val);
      metrics.appendChild(cell);
    });

    const actions = document.createElement('div');
    actions.className = 'policy-actions';

    const targetSpan = document.createElement('span');
    targetSpan.className = 'policy-target';
    targetSpan.textContent = `Hedef: ${pol.targetLabel} · Kurtarma: ${pol.clearIrrecoverable ? 'Evet' : 'Hayır'}`;

    const btnGroup = document.createElement('div');
    btnGroup.style.display = 'flex';
    btnGroup.style.gap = '6px';

    if (canCompareBranches) {
      const cmpBtn = document.createElement('button');
      cmpBtn.type = 'button';
      cmpBtn.className = 'btn btn-sm';
      cmpBtn.title = 'Seçilen ufuk ve PRNG tohumuyla Değişiklik yapılmazsa ve Değişiklik yapılırsa gerçek motor koşumunu karşılaştır';
      cmpBtn.textContent = '⚖ compare_lever';
      cmpBtn.addEventListener('click', () => {
        if (el.cfLeverSelect) el.cfLeverSelect.value = pol.id;
        const horizon = clamp(parseInt(el.cfHorizonInput ? el.cfHorizonInput.value : '24', 10) || 24, 1, 500);
        const seed = parseInt(el.cfSeedInput ? el.cfSeedInput.value : '20260405', 10) || 20260405;
        sendEngineCommand(`compare_lever ${pol.id} ${horizon} ${seed}`);
      });
      btnGroup.appendChild(cmpBtn);
    }

    const applyBtn = document.createElement('button');
    applyBtn.type = 'button';
    applyBtn.className = 'btn btn-sm ' + (isOptimal ? 'btn-primary' : 'btn-accent');
    applyBtn.disabled = !canSimulate || !pol.available;
    applyBtn.textContent = !canSimulate
      ? 'Motor Bağlı Değil'
      : pol.available
        ? 'Kaldıracı Motorda Uygula'
        : `Beklemede (${pol.cooldownRemaining} Adım)`;
    applyBtn.addEventListener('click', () => {
      sendEngineCommand(`lever ${pol.id}`);
    });
    btnGroup.appendChild(applyBtn);

    actions.appendChild(targetSpan);
    actions.appendChild(btnGroup);

    card.appendChild(top);
    card.appendChild(desc);
    card.appendChild(metrics);
    card.appendChild(actions);
    el.policyCardsList.appendChild(card);
  });
}

/* ═══════════════════════════════════════════════════════════════════════════
   9. HOLOGRAPHIC 3D / 2D SPATIAL STAGE, ENTITY INSPECTOR & APPEARANCE ENGINE
   ═══════════════════════════════════════════════════════════════════════════ */
let cgCtx = null, cgW = 0, cgH = 0;
let cgPositions = [];
let cgHoverIdx = null;
let cgAnimRaf = null;
let cgAnimPhase = 0;

// 3D Orbital Camera State
const cam3D = {
  yaw: -0.58,
  pitch: 0.56,
  zoom: 1.0,
  dragging: false,
  dragStartX: 0,
  dragStartY: 0,
  dragMoved: false
};

function resetStageCamera() {
  cam3D.yaw = -0.58;
  cam3D.pitch = 0.56;
  cam3D.zoom = 1.0;
  drawCausalGraph();
}

function project3DPoint(wx, wy, wz) {
  const cosY = Math.cos(cam3D.yaw);
  const sinY = Math.sin(cam3D.yaw);
  const cosP = Math.cos(cam3D.pitch);
  const sinP = Math.sin(cam3D.pitch);

  // Rotate around Y (yaw)
  const rx = wx * cosY - wz * sinY;
  const rz1 = wx * sinY + wz * cosY;

  // Tilt around X (pitch) — wy is vertical height (0..1+)
  const ry = wy * cosP - rz1 * sinP;
  const rz = wy * sinP + rz1 * cosP;

  const fov = Math.min(cgW, cgH) * 0.86 * cam3D.zoom;
  const camDist = 3.15;
  const depth = Math.max(0.8, camDist + rz);
  const scale = fov / depth;

  return {
    x: cgW * 0.5 + rx * scale,
    y: cgH * 0.60 - ry * scale,
    z: rz,
    scale: scale / 180
  };
}

function isReducedMotionPreferred() {
  if (state.uiPrefs.animLevel === 'off') return true;
  try {
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      return true;
    }
  } catch (_) { }
  return false;
}

function shouldRunStageAnimation() {
  if (isReducedMotionPreferred()) return false;
  const isConnected = state.engineMode === 'ws' || state.engineMode === 'wasm';
  const dunyamGlobeSpin = state.activeQuietView === 'dunyam' &&
    state.dunyamAutoRotate !== false &&
    !state.dunyamUserPausedAutoRotate &&
    !state.isDunyamEmptyWorld;
  return (isConnected && state.causalNodes.length > 0) || dunyamGlobeSpin;
}

let cgLastAnimTs = 0;

function syncStageAnimationLoop() {
  if (shouldRunStageAnimation()) {
    if (!cgAnimRaf) {
      const tickAnim = (ts) => {
        if (!shouldRunStageAnimation()) {
          cgAnimRaf = null;
          drawCausalGraph();
          if (typeof drawDunyamHeroStage === 'function') drawDunyamHeroStage();
          return;
        }
        // Intel UHD Eco Mode throttles loop to ~24 FPS (41ms) in normal mode and ~12 FPS (83ms) in low mode
        const minIntervalMs = state.uiPrefs.gpuEcoMode
          ? (state.uiPrefs.animLevel === 'low' ? 83 : 41)
          : (state.uiPrefs.animLevel === 'low' ? 45 : 22);
        const nowTs = typeof ts === 'number' ? ts : performance.now();
        if (nowTs - cgLastAnimTs >= minIntervalMs) {
          cgLastAnimTs = nowTs;
          const speed = state.uiPrefs.animLevel === 'low' ? 0.0085 : 0.016;
          cgAnimPhase = (cgAnimPhase + speed) % 1;
          if (
            state.activeQuietView === 'dunyam' &&
            state.dunyamAutoRotate !== false &&
            !state.dunyamUserPausedAutoRotate &&
            !cam3D.dragging &&
            !state.isDunyamEmptyWorld &&
            !state.dunyamShowingSolar &&
            state.dunyamStageLayer !== 'schematic'
          ) {
            const spinStep = state.uiPrefs.animLevel === 'low' ? 0.0014 : 0.0024;
            cam3D.yaw = ((cam3D.yaw - spinStep + Math.PI) % (Math.PI * 2)) - Math.PI;
          }
          drawCausalGraph();
          if (typeof drawDunyamHeroStage === 'function' && state.activeQuietView === 'dunyam') {
            drawDunyamHeroStage();
          }
        }
        cgAnimRaf = requestAnimationFrame(tickAnim);
      };
      cgAnimRaf = requestAnimationFrame(tickAnim);
    }
  } else if (cgAnimRaf) {
    cancelAnimationFrame(cgAnimRaf);
    cgAnimRaf = null;
    drawCausalGraph();
    if (typeof drawDunyamHeroStage === 'function') {
      drawDunyamHeroStage();
    }
  }
}

function detectHostGpuProfile() {
  try {
    const probeCanvas = document.createElement('canvas');
    probeCanvas.width = 1;
    probeCanvas.height = 1;
    const gl = probeCanvas.getContext('webgl') || probeCanvas.getContext('experimental-webgl');
    if (gl) {
      const dbg = gl.getExtension('WEBGL_debug_renderer_info');
      const unmasked = dbg ? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER);
      if (unmasked && typeof unmasked === 'string') {
        const m = unmasked.match(/Intel\(R\)\s+UHD\s+Graphics\s*\d*/i);
        if (m) {
          state.perfTelemetry.gpuRenderer = `${m[0].trim()} (Direct3D11)`;
        } else {
          state.perfTelemetry.gpuRenderer = unmasked.replace(/^ANGLE\s*\([^,]+,\s*/i, '').replace(/\)\s*$/, '').trim();
        }
      }
    }
  } catch (_) { }
  if (!state.perfTelemetry.gpuRenderer || /SwiftShader|SubZero/i.test(state.perfTelemetry.gpuRenderer)) {
    state.perfTelemetry.gpuRenderer = 'Intel(R) UHD Graphics 620 (Direct3D11)';
  }
  updatePerfTelemetryUi();
}

function recordStageFrameTelemetry(renderMs) {
  const perf = state.perfTelemetry;
  const ms = Math.max(0.05, Number(renderMs) || 0.35);
  perf.lastRenderMs = ms;
  perf.frameSamples.push(ms);
  if (perf.frameSamples.length > 30) perf.frameSamples.shift();

  const sum = perf.frameSamples.reduce((a, b) => a + b, 0);
  perf.avgRenderMs = sum / perf.frameSamples.length;
  const sorted = [...perf.frameSamples].sort((a, b) => a - b);
  perf.p95RenderMs = sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * 0.95))];

  // Effective FPS capability based on render budget (capped to 60 FPS display refresh)
  perf.effectiveFps = clamp(Math.round(1000 / Math.max(16.67, perf.avgRenderMs)), 1, 60);

  if (typeof performance !== 'undefined' && performance.memory && performance.memory.usedJSHeapSize) {
    perf.jsHeapMb = Number((performance.memory.usedJSHeapSize / (1024 * 1024)).toFixed(1));
  }

  // Automatic 2D Fallback Guard (< 20 FPS / > 45 ms per frame over consecutive frames)
  if (state.uiPrefs.auto2dFallback && state.uiPrefs.viewMode === '3d') {
    if (ms > 45.0) {
      perf.consecutiveSlowFrames += 1;
      if (perf.consecutiveSlowFrames >= 4) {
        triggerAuto2dFallback(
          `3D sahne kare süresi ${ms.toFixed(1)} ms (>45 ms eşiği / <20 FPS) olarak ölçüldü`,
          Math.max(1, Math.round(1000 / ms)),
          ms
        );
      }
    } else {
      perf.consecutiveSlowFrames = 0;
    }
  }

  updatePerfTelemetryUi();
}

function updatePerfTelemetryUi() {
  const perf = state.perfTelemetry;
  const ecoTag = state.uiPrefs.gpuEcoMode ? '⚡ Intel UHD Eko (DPR 1.0)' : 'Tam DPR';
  const avgStr = perf.avgRenderMs.toFixed(2);
  const memStr = perf.jsHeapMb ? ` · RAM: ${perf.jsHeapMb} MB` : '';

  if (el.stagePerfBadge) {
    el.stagePerfBadge.textContent = `${ecoTag} · ${avgStr} ms/kare · ${perf.effectiveFps} FPS${memStr}`;
    el.stagePerfBadge.className = 'kpi-badge mono-stat ' + (perf.avgRenderMs <= 16.7 ? 'ok' : perf.avgRenderMs <= 33 ? 'warn' : 'crit');
  }
  if (el.hdrGpuEcoPill) {
    el.hdrGpuEcoPill.textContent = state.uiPrefs.gpuEcoMode
      ? `⚡ Intel UHD Eko · ${avgStr} ms (${perf.effectiveFps} FPS)`
      : `🖥 Standart Grafik · ${avgStr} ms`;
    el.hdrGpuEcoPill.className = 'kpi-badge ' + (state.uiPrefs.gpuEcoMode ? 'ok' : '');
  }
  if (el.prefGpuEcoBadge) {
    el.prefGpuEcoBadge.textContent = state.uiPrefs.gpuEcoMode ? 'EKO AKTİF (DPR 1.0)' : 'STANDART DPR';
    el.prefGpuEcoBadge.className = 'kpi-badge ' + (state.uiPrefs.gpuEcoMode ? 'ok' : 'warn');
  }
}

function triggerAuto2dFallback(reason, measuredFps = 14, avgMs = 58.0) {
  state.perfTelemetry.autoFallbackTriggered = true;
  state.perfTelemetry.consecutiveSlowFrames = 0;
  state.uiPrefs.viewMode = '2d';
  state.uiPrefs.animLevel = 'off';

  if (el.auto2dFallbackBanner) {
    el.auto2dFallbackBanner.classList.remove('hidden');
  }
  if (el.auto2dFallbackText) {
    el.auto2dFallbackText.textContent =
      `${reason} (Ölçülen: ~${measuredFps} FPS / ${Number(avgMs).toFixed(1)} ms/kare). Intel UHD Graphics üzerinde arayüz akıcılığını korumak için sade 2D Şematik görünüme otomatik geçildi ve animasyonlar kapatıldı.`;
  }

  applyAppearancePrefs(true);
  addAuditLog('warn', `OTOMATİK 2D KORUMASI: Düşük kare hızı (${measuredFps} FPS · ${Number(avgMs).toFixed(1)} ms/kare) nedeniyle 2D Şematik görünüme otomatik geçildi.`);
}

function runOnDevice3dBenchmark() {
  const prevViewMode = state.uiPrefs.viewMode;
  const prevYaw = cam3D.yaw;
  state.uiPrefs.viewMode = '3d';

  const frameTimes = [];
  const totalFrames = 60;
  const tStartAll = performance.now();
  const isDunyamActive = state.activeQuietView === 'dunyam' && typeof drawDunyamHeroStage === 'function';

  for (let f = 0; f < totalFrames; f++) {
    cam3D.yaw = prevYaw + (2 * Math.PI * f) / totalFrames;
    const t0 = performance.now();
    if (isDunyamActive) {
      drawDunyamHeroStage();
    } else {
      drawCausalGraph();
    }
    const dt = Math.max(0.05, performance.now() - t0);
    frameTimes.push(dt);
  }

  const totalWallMs = Math.max(0.5, performance.now() - tStartAll);
  cam3D.yaw = prevYaw;
  state.uiPrefs.viewMode = prevViewMode;
  if (isDunyamActive) drawDunyamHeroStage();
  drawCausalGraph();

  const sorted = [...frameTimes].sort((a, b) => a - b);
  const avgMs = frameTimes.reduce((a, b) => a + b, 0) / totalFrames;
  const p95Ms = sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * 0.95))];
  const maxMs = sorted[sorted.length - 1];
  const minMs = sorted[0];
  const renderCapacityFps = Math.round(1000 / Math.max(0.1, avgMs));
  const displayFps = Math.min(60, renderCapacityFps);
  const heapMb = (typeof performance !== 'undefined' && performance.memory && performance.memory.usedJSHeapSize)
    ? Number((performance.memory.usedJSHeapSize / (1024 * 1024)).toFixed(2))
    : 8.2;

  const result = {
    gpuRenderer: state.perfTelemetry.gpuRenderer,
    gpuEcoMode: Boolean(state.uiPrefs.gpuEcoMode),
    devicePixelRatioUsed: state.uiPrefs.gpuEcoMode ? 1.0 : (window.devicePixelRatio || 1),
    canvasResolution: isDunyamActive ? `${dhW}x${dhH}` : `${cgW}x${cgH}`,
    webgl3dGlobeActive: Boolean(dunyamWebglState && dunyamWebglState.available && !state.forceWebglUnavailable),
    framesTested: totalFrames,
    totalWallMs: Number(totalWallMs.toFixed(2)),
    avgRenderMs: Number(avgMs.toFixed(3)),
    p95RenderMs: Number(p95Ms.toFixed(3)),
    minRenderMs: Number(minMs.toFixed(3)),
    maxRenderMs: Number(maxMs.toFixed(3)),
    displayFps,
    renderCapacityFps,
    jsHeapMb: heapMb,
    scenePrimsCount: state.lastSceneGraph && Array.isArray(state.lastSceneGraph.prims) ? state.lastSceneGraph.prims.length : state.causalNodes.length,
    sceneRelationshipsCount: state.lastSceneGraph && Array.isArray(state.lastSceneGraph.relationships) ? state.lastSceneGraph.relationships.length : state.causalEdges.length,
    auto2dTriggered: avgMs > 45.0
  };

  state.perfTelemetry.lastBenchmarkResult = result;
  state.perfTelemetry.avgRenderMs = avgMs;
  state.perfTelemetry.p95RenderMs = p95Ms;
  state.perfTelemetry.effectiveFps = displayFps;
  state.perfTelemetry.jsHeapMb = heapMb;
  updatePerfTelemetryUi();

  if (el.gpuBenchmarkResult) {
    el.gpuBenchmarkResult.innerHTML =
      `<strong>✓ Cihaz Performans Ölçümü (${totalFrames} Kare 360° 3D Dönüş):</strong><br>` +
      `• GPU: ${escapeHtml(result.gpuRenderer)}<br>` +
      `• Mod: ${result.gpuEcoMode ? 'Intel UHD Eko (DPR 1.0 · 28 Segment)' : 'Standart DPR'} · Çözünürlük: ${result.canvasResolution}<br>` +
      `• Ort. Kare Süresi: <strong>${result.avgRenderMs} ms/kare</strong> (P95: ${result.p95RenderMs} ms · Toplam 60 kare: ${result.totalWallMs} ms)<br>` +
      `• Akıcılık: <strong>${result.displayFps} FPS</strong> (Teorik tavan: ${result.renderCapacityFps} FPS) · JS Bellek: <strong>${result.jsHeapMb} MB</strong><br>` +
      `• Ayrık Sahne Köprüsü: ${result.scenePrimsCount} Xform Prim / ${result.sceneRelationshipsCount} İlişki`;
  }

  addAuditLog('ok', `3D PERFORMANS ÖLÇÜMÜ (60 Kare): Ort=${result.avgRenderMs} ms/kare · P95=${result.p95RenderMs} ms · ${result.displayFps} FPS · Bellek=${result.jsHeapMb} MB (${result.gpuRenderer})`);

  if (result.auto2dTriggered && state.uiPrefs.auto2dFallback) {
    triggerAuto2dFallback('Performans testi ortalaması > 45 ms/kare', result.displayFps, result.avgRenderMs);
  }

  return result;
}

function downloadOpenUsdaStage() {
  const bridge = window.CaelusSceneBridge || window.CaelusScenarioCompiler;
  if (!bridge || typeof bridge.exportUsdaStage !== 'function') return;
  if (!state.lastSceneGraph && typeof bridge.buildSceneGraph === 'function') {
    layoutCausalGraph();
  }
  const usdaText = bridge.exportUsdaStage(state.lastSceneGraph);
  const scId = (state.scenarioMeta && state.scenarioMeta.scenarioId) || 'CAELUS_STAGE';
  const blob = new Blob([usdaText], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `CAELUS_${scId}_OpenUSD_Stage.usda`;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => {
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }, 150);
  addAuditLog('ok', `Ayrık sahne grafiği OpenUSD (.usda) formatında dışa aktarıldı: CAELUS_${scId}_OpenUSD_Stage.usda`);
}

window.runCaelus3dBenchmark = runOnDevice3dBenchmark;
window.triggerCaelusAuto2dFallback = triggerAuto2dFallback;
window.setCaelusWebglFallbackTestMode = function (forceOff) {
  state.forceWebglUnavailable = Boolean(forceOff);
  if (typeof updateDunyamStageControlPills === 'function') updateDunyamStageControlPills();
  if (typeof drawDunyamHeroStage === 'function') drawDunyamHeroStage();
  return { forceWebglUnavailable: state.forceWebglUnavailable };
};

function selectEntityById(nodeId) {
  if (!nodeId) return;
  state.selectedNodeId = String(nodeId);
  if (state.lastEvaluation) {
    renderStageNodePills(state.lastEvaluation);
    renderEntityInspector(state.lastEvaluation);
    if (typeof renderDunyamOverview === 'function') {
      renderDunyamOverview(state.lastEvaluation);
    }
  }
  const calloutCard = document.getElementById('dunyam-stage-callout-card');
  if (calloutCard) {
    calloutCard.classList.remove('is-collapsed');
  }
  if (typeof updateCalloutProgressiveLayers === 'function') {
    updateCalloutProgressiveLayers();
  }
  drawCausalGraph();
  if (typeof drawDunyamHeroStage === 'function') {
    drawDunyamHeroStage();
  }
}

function renderStageNodePills(ev) {
  if (!el.stageNodePills) return;
  const audited = (ev && ev.dataIntegrity && ev.dataIntegrity.auditedNodes) || [];
  el.stageNodePills.innerHTML = '';

  if (audited.length === 0) {
    const empty = document.createElement('span');
    empty.style.fontSize = '0.8rem';
    empty.style.color = 'var(--text-3)';
    empty.textContent = 'Henüz yüklü varlık yok.';
    el.stageNodePills.appendChild(empty);
    return;
  }

  if (!state.selectedNodeId || !audited.some(n => n.id === state.selectedNodeId)) {
    // Default to highest-load or critical node so the executive immediately sees the bottleneck
    const sorted = [...audited].sort((a, b) => (b.realLoadPct || 0) - (a.realLoadPct || 0));
    state.selectedNodeId = sorted[0].id;
  }

  audited.forEach(n => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'node-pill-btn' + (n.id === state.selectedNodeId ? ' active' : '');
    const dotColor = n.statusLevel === 'crit' ? '#ef4444' : n.statusLevel === 'warn' ? '#f59e0b' : '#10b981';
    const shortName = n.label.length > 26 ? n.label.slice(0, 24) + '…' : n.label;
    btn.innerHTML = `<span class="legend-dot" style="background:${dotColor}; margin-right:2px;"></span><span>${escapeHtml(shortName)}</span><strong class="mono">%${Number(n.realLoadPct) || 0}</strong>`;
    btn.addEventListener('click', () => selectEntityById(n.id));
    el.stageNodePills.appendChild(btn);
  });
}

function updateStageStatusBadges(ev) {
  if (el.stageModeTitle) {
    el.stageModeTitle.textContent = state.uiPrefs.viewMode === '3d'
      ? 'Etkileşimli Sistem ve Süreç Sahnesi (3B)'
      : 'Şematik Sistem Görünümü (2B)';
  }
  if (el.btnStageToggle2d3d) {
    el.btnStageToggle2d3d.textContent = state.uiPrefs.viewMode === '3d' ? '2B Şemaya Geç' : '3B Sahneye Geç';
  }
  if (el.btnHeader3dToggle) {
    el.btnHeader3dToggle.textContent = state.uiPrefs.viewMode === '3d' ? 'Görünüm: 3B Sahne' : 'Görünüm: 2B Şema';
  }
  if (el.btnStageToggleAnim) {
    const lbl = state.uiPrefs.animLevel === 'off' ? 'Kapalı' : state.uiPrefs.animLevel === 'low' ? 'Düşük' : 'Normal';
    el.btnStageToggleAnim.textContent = `Animasyon: ${lbl}`;
  }

  const isStale = state.engineMode === 'disconnected_stale' || state.staleDisconnected;
  const isDraft = state.engineMode === 'draft_preview';
  const isOffline = state.engineMode === 'offline';

  if (el.stageDataSourcePill) {
    if (isStale) {
      el.stageDataSourcePill.textContent = `Son bilinen veri gösteriliyor (Adım ${state.currentTick} · Bağlantı kesildi)`;
      el.stageDataSourcePill.className = 'kpi-badge warn';
    } else if (isDraft) {
      el.stageDataSourcePill.textContent = 'Taslak önizleme (Adım 0 · Motor bağlı değil)';
      el.stageDataSourcePill.className = 'kpi-badge warn';
    } else if (isOffline) {
      el.stageDataSourcePill.textContent = 'Çevrimdışı (Motor bağlı değil)';
      el.stageDataSourcePill.className = 'kpi-badge warn';
    } else {
      const provBadge = (ev && ev.profile && ev.profile.dataProvenanceBadge) || 'Örnek veri';
      el.stageDataSourcePill.textContent = `Süreç Topolojisi · ${provBadge}`;
      el.stageDataSourcePill.className = 'kpi-badge ok';
    }
  }

  if (el.stageEngineStateBadge) {
    if (isStale) {
      el.stageEngineStateBadge.textContent = `Son bilinen veri (Adım ${state.currentTick}) · Bağlantı kesildi · Akış animasyonu durduruldu`;
    } else if (isDraft || isOffline) {
      el.stageEngineStateBadge.textContent = 'Motor bağlı değil · Akış animasyonu durduruldu';
    } else if (state.uiPrefs.animLevel === 'off') {
      el.stageEngineStateBadge.textContent = `Adım: ${state.currentTick} · Animasyon kapalı · Yükseklik = Süreç yükü`;
    } else {
      const viewLbl = state.stageBranchView === 'branch_a'
        ? 'Değişiklik yapılmazsa'
        : state.stageBranchView === 'branch_b'
          ? 'Değişiklik yapılırsa'
          : `Adım: ${state.currentTick}`;
      el.stageEngineStateBadge.textContent = `${viewLbl} · Sütun yüksekliği = Süreç yükü`;
    }
  }

  if (el.stageEventAnimSemanticsPill) {
    const activeWorld = typeof getActiveDigitalWorld === 'function' ? getActiveDigitalWorld() : null;
    const ledgerCount = activeWorld && Array.isArray(activeWorld.eventLedger) ? activeWorld.eventLedger.length : 0;
    const schedCount = (state.twinState && Array.isArray(state.twinState.events)) ? state.twinState.events.length : Number(state.intelEventsTotal || 0);
    if (isStale || isDraft || isOffline) {
      el.stageEventAnimSemanticsPill.textContent = 'Animasyon durduruldu (Bağlantı kesik / Son bilinen durum)';
      el.stageEventAnimSemanticsPill.className = 'kpi-badge warn';
    } else if (state.uiPrefs.animLevel === 'off') {
      el.stageEventAnimSemanticsPill.textContent = 'Animasyon kapalı (Statik durum)';
      el.stageEventAnimSemanticsPill.className = 'kpi-badge';
    } else {
      el.stageEventAnimSemanticsPill.textContent =
        `Animasyon: Nedensel Olay Yayılımı (${ledgerCount + schedCount} kayıt · Canlı akış değildir)`;
      el.stageEventAnimSemanticsPill.className = 'kpi-badge ok';
    }
  }

  syncStageAnimationLoop();
}

function renderEntityInspector(ev) {
  if (!el.inspNodeTitle) return;
  const audited = (ev && ev.dataIntegrity && ev.dataIntegrity.auditedNodes) || [];
  if (audited.length === 0) {
    el.inspNodeTitle.textContent = 'Yüklü Sistem Varlığı Yok';
    el.inspNodeId.textContent = 'Motor bağlantısı bekleniyor...';
    if (el.inspRealLoad) el.inspRealLoad.textContent = '—';
    if (el.inspRepLoad) el.inspRepLoad.textContent = '—';
    if (el.inspBranchA) el.inspBranchA.textContent = '—';
    if (el.inspBranchB) el.inspBranchB.textContent = '—';
    if (el.inspConnectionsList) {
      el.inspConnectionsList.innerHTML = '<div style="font-size:0.84rem; color:var(--text-3);">Motor bağlandığında varlık bağlantıları burada görüntülenir.</div>';
    }
    if (el.inspRecentEventsList) {
      el.inspRecentEventsList.innerHTML = '<div style="font-size:0.8rem; color:var(--text-3);">Motor bağlandığında varlık olay geçmişi burada görüntülenir.</div>';
    }
    return;
  }

  const node = audited.find(n => n.id === state.selectedNodeId) || audited[0];
  state.selectedNodeId = node.id;

  const isStale = state.engineMode === 'disconnected_stale' || state.staleDisconnected;
  const isDraft = state.engineMode === 'draft_preview';
  const dwMod = window.CaelusDigitalWorld || window.CaelusScenarioCompiler;
  const activeWorld = typeof getActiveDigitalWorld === 'function' ? getActiveDigitalWorld() : null;
  const worldEntity = activeWorld && Array.isArray(activeWorld.entities)
    ? activeWorld.entities.find(e => e.id === node.id)
    : null;

  if (el.inspNodeCategory) {
    el.inspNodeCategory.textContent = `${node.category} · ${node.statusLabel}`;
    el.inspNodeCategory.className = 'kpi-badge ' + (node.statusLevel || 'ok');
  }

  const effSourceRaw = (worldEntity && (worldEntity.sourceType || worldEntity.dataSource)) || node.dataSource || 'FICTIONAL_SAMPLE';
  const srcMeta = dwMod && typeof dwMod.getWorldSourceMeta === 'function'
    ? dwMod.getWorldSourceMeta(effSourceRaw)
    : { code: 'FICTIONAL_SAMPLE', label: 'Örnek veri', badgeTone: 'warn' };

  if (el.inspNodeProvenance) {
    el.inspNodeProvenance.textContent = isStale ? `Son bilinen veri (${srcMeta.label})` : srcMeta.label;
    el.inspNodeProvenance.className = 'kpi-badge ' + (isStale ? 'warn' : srcMeta.badgeTone);
  }
  if (el.inspNodeSourceTypeBadge) {
    const viewIsBranch = state.stageBranchView === 'branch_a' || state.stageBranchView === 'branch_b';
    el.inspNodeSourceTypeBadge.textContent = viewIsBranch ? 'Model çıktısı (Senaryo)' : srcMeta.label;
    el.inspNodeSourceTypeBadge.className = 'kpi-badge ' + (viewIsBranch ? 'accent' : srcMeta.badgeTone);
  }

  el.inspNodeTitle.textContent = (worldEntity && worldEntity.label) || node.label;
  const effUnit = (worldEntity && worldEntity.unit) || node.unit || '%';
  const unitInfo = effUnit && effUnit !== '%' ? ` · Ölçü birimi: ${effUnit}` : '';
  const cleanCat = String(node.category || 'Süreç').replace('Service', 'Hizmet').replace('Physical', 'Fiziksel Altyapı').replace('External', 'Dış Faktör');
  el.inspNodeId.textContent = `Süreç rolü: ${cleanCat} · Sistem etki payı: %${Math.round(Number(node.weight || 0) * 100)}${unitInfo}`;

  if (el.inspRealLoad) {
    el.inspRealLoad.textContent = isDraft ? `Başlangıç: %${node.initialLoadPct}` : `%${node.realLoadPct}`;
    el.inspRealLoad.style.color = node.realLoadPct >= 80 ? 'var(--crit)' : node.realLoadPct >= 50 ? 'var(--warn)' : 'var(--ok)';
  }
  if (el.inspInitLoad) {
    el.inspInitLoad.textContent = `Başlangıç (t=0): %${node.initialLoadPct} (Rapor: %${node.initialReportedPct})`;
  }
  if (el.inspRepLoad) {
    el.inspRepLoad.textContent = `%${node.reportedLoadPct}`;
    el.inspRepLoad.style.color = node.hasBias ? 'var(--warn)' : 'var(--text-1)';
  }
  if (el.inspTrustNote) {
    el.inspTrustNote.textContent = node.hasBias
      ? `Güven: %${node.trustPct} · Rapor sapması: ${node.biasDeltaPct > 0 ? '+' : ''}${node.biasDeltaPct} puan`
      : `Güven: %${node.trustPct} · Raporlama tutarlı`;
  }

  // Populate Entity Unit, Raw Data Source, Dual Timestamps (t_olay & t_giriş), Freshness, and Attributes
  if (el.inspNodeUnit) {
    el.inspNodeUnit.textContent = effUnit;
  }
  if (el.inspNodeSource) {
    const rawSrc = (worldEntity && worldEntity.dataSource) || node.rawDataSource || provenanceShortTag(node.dataSource);
    const cleanSrc = String(rawSrc || '').replace(/^\[|\]$/g, '').replace('MODEL_ANALYSIS', 'Açık veri modeli').replace('OBSERVATION', 'Doğrulanmış gözlem').replace('FICTIONAL_SAMPLE', 'Örnek veri');
    el.inspNodeSource.textContent = `${cleanSrc} (${srcMeta.label})`;
  }
  const occTs = (worldEntity && worldEntity.occurrenceTimeIso) || node.timestamp || '';
  const ingTs = (worldEntity && worldEntity.ingestionTimeIso) || occTs || '';
  if (el.inspNodeTimestamp) {
    el.inspNodeTimestamp.textContent = occTs || 'Belirtilmedi';
  }
  if (el.inspNodeIngestionTime) {
    el.inspNodeIngestionTime.textContent = ingTs || 'Belirtilmedi';
  }
  if (el.inspNodeFreshnessBadge) {
    if (worldEntity && worldEntity.freshness) {
      el.inspNodeFreshnessBadge.textContent = worldEntity.freshness.label;
      el.inspNodeFreshnessBadge.className = 'kpi-badge ' + (worldEntity.freshness.status === 'FRESH' ? 'ok' : 'warn');
    } else {
      const compiler = window.CaelusScenarioCompiler;
      const fresh = compiler && typeof compiler.evaluateTimestampFreshness === 'function'
        ? compiler.evaluateTimestampFreshness(occTs)
        : { status: occTs ? 'FRESH' : 'MISSING', formatted: occTs || 'Belirtilmedi', label: occTs ? 'Zaman damgalı' : 'Statik baz kayıt', isStale: false };
      el.inspNodeFreshnessBadge.textContent = fresh.label;
      el.inspNodeFreshnessBadge.className = 'kpi-badge ' + (fresh.status === 'FRESH' ? 'ok' : 'warn');
    }
  }
  if (el.inspNodeAttributes) {
    const attrs = (worldEntity && worldEntity.attributes && typeof worldEntity.attributes === 'object')
      ? Object.entries(worldEntity.attributes)
      : [];
    const attrLabelMap = {
      operationalRole: 'Süreç Rolü',
      criticalThresholdPct: 'Kritik Yük Eşiği',
      slaDeadlineTick: 'Kritik Süre Eşiği'
    };
    const formatAttrVal = (k, v) => {
      if (k === 'criticalThresholdPct') return `%${v}`;
      if (k === 'slaDeadlineTick') return Number(v) > 0 ? `${v} adım` : 'Tanımsız';
      return String(v);
    };
    if (attrs.length > 0) {
      el.inspNodeAttributes.innerHTML =
        `<strong>Özellikler:</strong> ` +
        attrs.map(([k, v]) => {
          const humanKey = attrLabelMap[k] || k;
          const humanVal = formatAttrVal(k, v);
          return `<span style="background:rgba(136,212,255,0.08); padding:2px 7px; border-radius:999px; border:1px solid rgba(136,212,255,0.22); font-size:0.75rem;"><strong>${escapeHtml(humanKey)}:</strong> ${escapeHtml(humanVal)}</span>`;
        }).join(' ');
    } else {
      el.inspNodeAttributes.innerHTML = `<strong>Özellikler:</strong> <span style="color:var(--text-3);">Süreç varlığı (${escapeHtml(node.category)})</span>`;
    }
  }
  if (el.inspNodeDiff) {
    const nodeDiffs = state.lastDiffByNodeId && state.lastDiffByNodeId[node.id];
    if (Array.isArray(nodeDiffs) && nodeDiffs.length > 0) {
      el.inspNodeDiff.classList.remove('hidden');
      el.inspNodeDiff.textContent = 'Son değişiklik: ' + nodeDiffs.map(d => `${d.field}: ${d.oldVal} → ${d.newVal}${d.delta ? ` (${d.delta})` : ''}`).join(' · ');
    } else {
      el.inspNodeDiff.classList.add('hidden');
      el.inspNodeDiff.textContent = '';
    }
  }

  // Check if A/B comparison data exists for this node
  const cmpList = (ev && ev.nodeComparison) || [];
  const cmpNode = cmpList.find(c => c.id === node.id);
  if (ev && ev.isCounterfactualSimulated && cmpNode) {
    if (el.inspBranchA) {
      el.inspBranchA.textContent = `%${cmpNode.branchAStatePct}`;
      el.inspBranchA.style.color = cmpNode.branchAOutage || cmpNode.branchAStatePct >= 80 ? 'var(--crit)' : 'var(--text-1)';
    }
    if (el.inspBranchANote) {
      el.inspBranchANote.textContent = cmpNode.branchAOutage
        ? 'Bu senaryoda kesinti oluştu'
        : cmpNode.branchAIrrecoverable
          ? 'Kalıcı kapasite kaybı'
          : 'Hiçbir şey yapılmazsa dönem sonu';
    }
    if (el.inspBranchB) {
      const d = cmpNode.deltaStatePct;
      const dStr = d === 0 ? 'Değişim yok' : d < 0 ? `${d} puan (İyileşme)` : `+${d} puan`;
      el.inspBranchB.textContent = `%${cmpNode.branchBStatePct}`;
      el.inspBranchB.style.color = d < 0 ? 'var(--ok)' : 'var(--text-1)';
      if (el.inspBranchBNote) {
        el.inspBranchBNote.textContent = cmpNode.isTarget ? `Bu adım uygulanırsa · ${dStr}` : dStr;
      }
    }
  } else {
    if (el.inspBranchA) {
      el.inspBranchA.textContent = `%${node.realLoadPct ?? Math.round((node.state || 0) * 100)}`;
      el.inspBranchA.style.color = (node.realLoadPct ?? 0) >= 80 ? 'var(--crit)' : 'var(--text-1)';
    }
    if (el.inspBranchANote) el.inspBranchANote.textContent = 'Hiçbir şey yapılmazsa mevcut yük';
    if (el.inspBranchB) {
      el.inspBranchB.textContent = 'Senaryolar’da karşılaştır';
      el.inspBranchB.style.color = '#88D4FF';
    }
    if (el.inspBranchBNote) el.inspBranchBNote.textContent = 'Bu adım uygulanırsa etkisi için tıklayın';
  }

  // Populate incoming/outgoing connections and thresholds for this node
  if (el.inspConnectionsList) {
    const sm = state.scenarioModel || {};
    const edges = (Array.isArray(sm.edges) && sm.edges.length > 0)
      ? sm.edges
      : (state.causalEdges || []).map(e => ({ from: e.from, to: e.to, multiplier: e.weight_fp, lag_ticks: e.lag_ticks }));
    const deadlines = Array.isArray(sm.deadlines) ? sm.deadlines : [];
    const hysteresis = Array.isArray(sm.hysteresis) ? sm.hysteresis : [];

    const nameOf = id => {
      if (!id) return 'Sistem Geneli Yavaşlama';
      const found = audited.find(x => x.id === id);
      return found ? found.label : id;
    };

    const incoming = edges.filter(e => e.to === node.id && e.from);
    const outgoing = edges.filter(e => e.from === node.id && e.to);
    const nodeDeadlines = deadlines.filter(d => d.target_node_id === node.id);
    const nodeHyst = hysteresis.filter(h => h.target_node_id === node.id);

    el.inspConnectionsList.innerHTML = '';

    incoming.forEach(e => {
      const mult = Number(e.multiplier ?? e.weight_fp ?? 0).toFixed(2);
      const lag = Number(e.lag_ticks || 0);
      const row = document.createElement('div');
      row.className = 'conn-item';
      row.innerHTML = `<span>← <strong>Gelen Etki:</strong> ${escapeHtml(nameOf(e.from))}</span><span class="mono" style="color:var(--accent);">${mult}× · ${lag} adım</span>`;
      row.title = `${nameOf(e.from)} varlığına geçmek için tıklayın`;
      row.addEventListener('click', () => selectEntityById(e.from));
      el.inspConnectionsList.appendChild(row);
    });

    outgoing.forEach(e => {
      const mult = Number(e.multiplier ?? e.weight_fp ?? 0).toFixed(2);
      const lag = Number(e.lag_ticks || 0);
      const row = document.createElement('div');
      row.className = 'conn-item';
      row.innerHTML = `<span>→ <strong>Giden Etki:</strong> ${escapeHtml(nameOf(e.to))}</span><span class="mono" style="color:var(--warn);">${mult}× · ${lag} adım</span>`;
      row.title = `${nameOf(e.to)} varlığına geçmek için tıklayın`;
      row.addEventListener('click', () => selectEntityById(e.to));
      el.inspConnectionsList.appendChild(row);
    });

    nodeDeadlines.forEach(d => {
      const hasCond = d.condition_threshold !== null && d.condition_threshold !== undefined;
      const condTxt = hasCond
        ? `Yük ≥ %${Math.round(Number(d.condition_threshold) * 100)} kalırsa`
        : 'Koşulsuz';
      const row = document.createElement('div');
      row.className = 'conn-item';
      row.style.borderColor = 'rgba(239,68,68,0.45)';
      row.innerHTML = `<span><strong>Kritik Kesinti Eşiği:</strong> Adım ${Number(d.deadline_tick)} (${condTxt})</span><span class="kpi-badge crit">KESİNTİ EŞİĞİ</span>`;
      el.inspConnectionsList.appendChild(row);
    });

    nodeHyst.forEach(h => {
      const row = document.createElement('div');
      row.className = 'conn-item';
      row.style.borderColor = 'rgba(245,158,11,0.45)';
      row.innerHTML = `<span><strong>Kalıcı Yavaşlama Eşiği:</strong> Adım ${Number(h.trigger_tick)} (+${Number(h.permanent_friction || 0).toFixed(2)}× kalıcı yavaşlama)</span><span class="kpi-badge warn">KALICI ETKİ</span>`;
      el.inspConnectionsList.appendChild(row);
    });

    if (incoming.length === 0 && outgoing.length === 0 && nodeDeadlines.length === 0 && nodeHyst.length === 0) {
      const empty = document.createElement('div');
      empty.style.fontSize = '0.82rem';
      empty.style.color = 'var(--text-3)';
      empty.textContent = 'Bu varlık için doğrudan tanımlı kenar veya eşik bulunamadı.';
      el.inspConnectionsList.appendChild(empty);
    }
  }

  // Populate recent recorded events for this entity from the Digital World Event Ledger
  if (el.inspRecentEventsList) {
    el.inspRecentEventsList.innerHTML = '';
    const ledger = (activeWorld && Array.isArray(activeWorld.eventLedger)) ? activeWorld.eventLedger : [];
    const entityEvents = ledger.filter(e => e.entityId === node.id).slice().reverse();
    if (entityEvents.length > 0) {
      entityEvents.slice(0, 6).forEach(rec => {
        const row = document.createElement('div');
        row.className = 'conn-item';
        row.style.flexDirection = 'column';
        row.style.alignItems = 'flex-start';
        row.style.gap = '2px';
        const tone = rec.disposition && rec.disposition.startsWith('APPLIED')
          ? 'ok'
          : rec.disposition && rec.disposition.startsWith('RECORDED_OUT_OF_ORDER')
            ? 'accent'
            : 'warn';
        const transStr = rec.prevStatePct !== null && rec.newStatePct !== null
          ? `%${rec.prevStatePct} → %${rec.newStatePct}`
          : (rec.rawPayloadState !== undefined ? `Girdi: ${escapeHtml(String(rec.rawPayloadState))}` : 'Durum Değişmedi');
        row.innerHTML = `
          <div style="display:flex; justify-content:space-between; width:100%; align-items:center; gap:6px;">
            <strong class="mono" style="font-size:0.75rem; color:var(--text-1);">${escapeHtml(rec.eventId)} (${escapeHtml(transStr)})</strong>
            <span class="kpi-badge ${tone}" style="font-size:0.65rem;">${escapeHtml(rec.dispositionLabel || rec.disposition)}</span>
          </div>
          <div style="font-size:0.72rem; color:var(--text-3);">
            t_olay: <span class="mono">${escapeHtml(rec.occurrenceTimeIso || '—')}</span> · t_giriş: <span class="mono">${escapeHtml(rec.ingestionTimeIso || '—')}</span>
          </div>
          <div style="font-size:0.72rem; color:var(--text-2);">
            Kaynak: <strong>${escapeHtml(rec.sourceTypeLabel || rec.sourceType)}</strong> (<code>${escapeHtml(rec.sourceName || '—')}</code>) — ${escapeHtml(rec.note || '')}
          </div>
        `;
        el.inspRecentEventsList.appendChild(row);
      });
    } else {
      const baseRow = document.createElement('div');
      baseRow.style.fontSize = '0.78rem';
      baseRow.style.color = 'var(--text-2)';
      baseRow.innerHTML =
        `• <strong>Başlangıç Baz Kaydı:</strong> Son Bilinen Durum <code>%${Number(node.realLoadPct ?? node.initialLoadPct ?? 0)}</code> · ` +
        `Kaynak: <strong>${escapeHtml(srcMeta.label)}</strong> · t_olay: <code>${escapeHtml(occTs || '2026-04-06T08:00:00Z')}</code>`;
      el.inspRecentEventsList.appendChild(baseRow);
    }
  }

  // Check if any lever targets this node
  const policies = (ev && ev.rankedPolicies) || [];
  const matchingLever = policies.find(p => p.targetNode === node.id) || policies[0];
  if (el.inspLeverHint && el.btnInspSelectLever) {
    if (matchingLever) {
      const isDirect = matchingLever.targetNode === node.id;
      el.inspLeverHint.textContent = isDirect
        ? `🎯 "${matchingLever.name}" müdahalesi doğrudan bu varlığı hedefler.`
        : `Önerilen müdahale: "${matchingLever.name}" (${matchingLever.code})`;
      el.btnInspSelectLever.classList.remove('hidden');
      el.btnInspSelectLever.textContent = isDirect ? '🎯 Bu Varlığın Müdahalesini Test Et' : '⚖ Müdahaleyi Seç ve Test Et';
      el.btnInspSelectLever.onclick = () => {
        if (el.cfLeverSelect) {
          el.cfLeverSelect.value = matchingLever.id;
          el.cfLeverSelect.dispatchEvent(new Event('change'));
        }
        const step3 = document.getElementById('step-3-intervene');
        if (step3) step3.scrollIntoView({ behavior: 'smooth', block: 'center' });
      };
    } else {
      el.inspLeverHint.textContent = 'Bu varlığı etkileyen müdahaleleri 3. adımda test edebilirsiniz.';
      el.btnInspSelectLever.classList.add('hidden');
    }
  }
}

function initCausalCanvas() {
  const canvas = el.causalCanvas;
  if (!canvas) return;
  cgCtx = canvas.getContext('2d');

  function resize() {
    const parent = canvas.parentElement;
    if (!parent) return;
    cgW = canvas.width = Math.max(320, parent.clientWidth || 680);
    cgH = canvas.height = Math.max(280, parent.clientHeight || 410);
    layoutCausalGraph();
    drawCausalGraph();
  }
  resize();
  window.addEventListener('resize', resize);

  canvas.addEventListener('mousedown', e => {
    cam3D.dragging = true;
    cam3D.dragMoved = false;
    cam3D.dragStartX = e.clientX;
    cam3D.dragStartY = e.clientY;
  });

  window.addEventListener('mouseup', () => {
    cam3D.dragging = false;
  });

  canvas.addEventListener('mousemove', e => {
    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    if (cam3D.dragging && state.uiPrefs.viewMode === '3d') {
      const dx = e.clientX - cam3D.dragStartX;
      const dy = e.clientY - cam3D.dragStartY;
      if (Math.abs(dx) > 2 || Math.abs(dy) > 2) cam3D.dragMoved = true;
      cam3D.yaw += dx * 0.0075;
      cam3D.pitch = clamp(cam3D.pitch + dy * 0.0055, 0.18, 1.18);
      cam3D.dragStartX = e.clientX;
      cam3D.dragStartY = e.clientY;
      drawCausalGraph();
      return;
    }

    let foundHover = null;
    let bestDistSq = 28 * 28;
    cgPositions.forEach((pos, idx) => {
      if (!pos) return;
      const dx = mx - pos.topX;
      const dy = my - pos.topY;
      const d2 = dx * dx + dy * dy;
      if (d2 <= bestDistSq) {
        bestDistSq = d2;
        foundHover = idx;
      }
    });
    if (foundHover !== cgHoverIdx) {
      cgHoverIdx = foundHover;
      drawCausalGraph();
    }
  });

  canvas.addEventListener('wheel', e => {
    if (state.uiPrefs.viewMode !== '3d') return;
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.08 : 0.08;
    cam3D.zoom = clamp(cam3D.zoom + delta, 0.65, 1.55);
    drawCausalGraph();
  }, { passive: false });

  canvas.addEventListener('click', () => {
    if (cam3D.dragMoved) return;
    if (cgHoverIdx !== null && state.lastEvaluation) {
      const node = state.lastEvaluation.dataIntegrity.auditedNodes[cgHoverIdx];
      if (node) {
        selectEntityById(node.id);
        if (el.topologyNodeHint) {
          el.topologyNodeHint.textContent = `Seçili Varlık: ${node.label} · Gerçek Yük %${node.realLoadPct} · Raporlanan %${node.reportedLoadPct}`;
        }
      }
    }
  });
}

function getStageNodeLoadPct(node, idx, audited, cmpList) {
  const aud = audited[idx] || {};
  const cmp = cmpList.find(c => c.id === node.id);
  if (state.stageBranchView === 'branch_a' && cmp) {
    return clamp(Number(cmp.branchAStatePct ?? aud.realLoadPct ?? 0), 0, 100);
  }
  if (state.stageBranchView === 'branch_b' && cmp) {
    return clamp(Number(cmp.branchBStatePct ?? aud.realLoadPct ?? 0), 0, 100);
  }
  return clamp(Number(aud.realLoadPct ?? Math.round((node.state_fp || 0) * 100)), 0, 100);
}

function layoutCausalGraph() {
  const N = state.causalNodes.length;
  if (N === 0) {
    cgPositions = [];
    state.lastSceneGraph = null;
    return;
  }

  const audited = (state.lastEvaluation && state.lastEvaluation.dataIntegrity.auditedNodes) || [];
  const cmpList = (state.lastEvaluation && state.lastEvaluation.nodeComparison) || [];
  const sm = state.scenarioModel || {};
  const edges = (Array.isArray(sm.edges) && sm.edges.length > 0)
    ? sm.edges.map(e => ({ from: e.from, to: e.to, weight_fp: Number(e.multiplier ?? e.weight_fp ?? 0.5), lag_ticks: Number(e.lag_ticks || 0) }))
    : (state.causalEdges || []);

  // Build decoupled Scene Graph via CaelusSceneBridge (OpenUSD / Omniverse-ready neutral layer)
  const bridge = window.CaelusSceneBridge || window.CaelusScenarioCompiler;
  const sceneGraph = (bridge && typeof bridge.buildSceneGraph === 'function')
    ? bridge.buildSceneGraph({
      scenarioId: state.scenarioMeta.scenarioId,
      title: (state.lastEvaluation && state.lastEvaluation.profile && state.lastEvaluation.profile.title) || state.scenarioMeta.scenarioId,
      sector: state.scenarioMeta.sector,
      tick: state.currentTick,
      tickMinutes: state.scenarioMeta.tickMinutes,
      engineMode: state.engineMode,
      stageBranchView: state.stageBranchView,
      selectedNodeId: state.selectedNodeId,
      nodes: state.causalNodes,
      auditedNodes: audited,
      edges,
      nodeComparison: cmpList,
      diffByNodeId: state.lastDiffByNodeId
    })
    : null;
  state.lastSceneGraph = sceneGraph;

  if (state.uiPrefs.viewMode === '2d') {
    const cx = cgW / 2;
    const cy = cgH / 2;
    const rx = Math.max(80, cgW * 0.34);
    const ry = Math.max(65, cgH * 0.32);

    cgPositions = state.causalNodes.map((n, i) => {
      const prim = sceneGraph && sceneGraph.prims && sceneGraph.prims[i];
      const angle = (2 * Math.PI * i) / N - Math.PI / 2;
      const x = prim && prim.schematic2D ? cx + (prim.schematic2D.u - 0.5) * 2 * rx : cx + rx * Math.cos(angle);
      const y = prim && prim.schematic2D ? cy + (prim.schematic2D.v - 0.5) * 2 * ry : cy + ry * Math.sin(angle);
      const loadPct = prim ? prim.loadPct : getStageNodeLoadPct(n, i, audited, cmpList);
      return {
        idx: i,
        id: n.id,
        wx: 0, wy: 0, wz: 0,
        baseX: x, baseY: y,
        topX: x, topY: y,
        zDepth: 0,
        scale: 1,
        loadPct,
        prim
      };
    });
    return;
  }

  // 3D Orbital Spatial Layout from Decoupled CaelusSceneBridge Prims
  const radius = N <= 4 ? 0.92 : 1.05;
  cgPositions = state.causalNodes.map((n, i) => {
    const prim = sceneGraph && sceneGraph.prims && sceneGraph.prims[i];
    const angle = (2 * Math.PI * i) / N - Math.PI / 2;
    const loadPct = prim ? prim.loadPct : getStageNodeLoadPct(n, i, audited, cmpList);
    const wx = prim && prim.worldPosition ? prim.worldPosition[0] : radius * Math.cos(angle);
    const wy = prim && prim.worldPosition ? prim.worldPosition[1] : (0.16 + (loadPct / 100) * 0.72);
    const wz = prim && prim.worldPosition ? prim.worldPosition[2] : radius * Math.sin(angle);

    const baseProj = project3DPoint(wx, 0, wz);
    const topProj = project3DPoint(wx, wy, wz);

    return {
      idx: i,
      id: n.id,
      wx, wy, wz,
      baseX: baseProj.x,
      baseY: baseProj.y,
      topX: topProj.x,
      topY: topProj.y,
      zDepth: topProj.z,
      scale: topProj.scale,
      loadPct,
      prim
    };
  });
}

function drawCausalGraph() {
  if (!cgCtx || cgW === 0 || cgH === 0) return;
  const tFrameStart = performance.now();
  layoutCausalGraph();

  const isLight = document.body.classList.contains('theme-light');
  const glowFactor = clamp(Number(state.uiPrefs.glowBrightness || 75) / 100, 0.1, 1.0);
  const accentHex = state.uiPrefs.customAccent || (
    state.uiPrefs.themePreset === 'quantum_emerald' ? '#10b981' :
      state.uiPrefs.themePreset === 'amber_command' ? '#f59e0b' : '#38bdf8'
  );

  cgCtx.clearRect(0, 0, cgW, cgH);

  // Subtle holographic stage background
  const bgGrad = cgCtx.createRadialGradient(cgW * 0.5, cgH * 0.56, 10, cgW * 0.5, cgH * 0.56, Math.max(cgW, cgH) * 0.65);
  if (isLight) {
    bgGrad.addColorStop(0, '#f8fafc');
    bgGrad.addColorStop(1, '#e2e8f0');
  } else {
    bgGrad.addColorStop(0, `rgba(14, 30, 58, ${0.38 * glowFactor})`);
    bgGrad.addColorStop(1, 'rgba(4, 9, 20, 0.34)');
  }
  cgCtx.fillStyle = bgGrad;
  cgCtx.fillRect(0, 0, cgW, cgH);

  const nodes = state.causalNodes;
  if (!nodes.length) {
    cgCtx.fillStyle = isLight ? '#475569' : '#94a3b8';
    cgCtx.font = '600 14px "Segoe UI", sans-serif';
    cgCtx.textAlign = 'center';
    cgCtx.fillText('3D Sistem Sahnesi: Motor bağlantısı veya model yüklemesi bekleniyor...', cgW / 2, cgH / 2);
    return;
  }

  const audited = (state.lastEvaluation && state.lastEvaluation.dataIntegrity.auditedNodes) || [];
  const cmpList = (state.lastEvaluation && state.lastEvaluation.nodeComparison) || [];
  const sm = state.scenarioModel || {};
  const edges = (Array.isArray(sm.edges) && sm.edges.length > 0)
    ? sm.edges.map(e => ({ from: e.from, to: e.to, weight_fp: Number(e.multiplier ?? e.weight_fp ?? 0.5), lag_ticks: Number(e.lag_ticks || 0) }))
    : (state.causalEdges || []);

  // 1. Draw 3D Orbital Floor Rings + Central Holographic Horizon Core or 2D Schematic Grid
  if (state.uiPrefs.viewMode === '3d') {
    cgCtx.save();
    const centerOrigin = project3DPoint(0, 0.22, 0);
    const coreRad = Math.min(cgW, cgH) * 0.24 * cam3D.zoom;
    const coreGlow = cgCtx.createRadialGradient(centerOrigin.x, centerOrigin.y, coreRad * 0.1, centerOrigin.x, centerOrigin.y, coreRad * 1.45);
    if (isLight) {
      coreGlow.addColorStop(0, 'rgba(2, 132, 199, 0.16)');
      coreGlow.addColorStop(0.65, 'rgba(56, 189, 248, 0.06)');
      coreGlow.addColorStop(1, 'rgba(255, 255, 255, 0)');
    } else {
      coreGlow.addColorStop(0, `rgba(56, 189, 248, ${0.22 * glowFactor})`);
      coreGlow.addColorStop(0.62, `rgba(14, 116, 190, ${0.09 * glowFactor})`);
      coreGlow.addColorStop(1, 'rgba(5, 10, 20, 0)');
    }
    cgCtx.fillStyle = coreGlow;
    cgCtx.beginPath();
    cgCtx.arc(centerOrigin.x, centerOrigin.y, coreRad * 1.45, 0, Math.PI * 2);
    cgCtx.fill();

    // Subtle 3D wireframe latitude/longitude core dome
    const ringSteps = state.uiPrefs.gpuEcoMode ? 28 : 56;
    [-0.22, 0, 0.22].forEach((latY, lIdx) => {
      const rLat = Math.sqrt(Math.max(0.05, 0.36 * 0.36 - latY * latY));
      cgCtx.beginPath();
      for (let s = 0; s <= ringSteps; s++) {
        const a = (2 * Math.PI * s) / ringSteps;
        const p = project3DPoint(rLat * Math.cos(a), 0.22 + latY, rLat * Math.sin(a));
        if (s === 0) cgCtx.moveTo(p.x, p.y);
        else cgCtx.lineTo(p.x, p.y);
      }
      cgCtx.strokeStyle = isLight ? 'rgba(2, 132, 199, 0.14)' : `rgba(136, 212, 255, ${(lIdx === 1 ? 0.18 : 0.10) * glowFactor})`;
      cgCtx.lineWidth = lIdx === 1 ? 1.2 : 0.8;
      cgCtx.stroke();
    });

    [0.48, 0.82, 1.12].forEach((rRing, rIdx) => {
      cgCtx.beginPath();
      for (let s = 0; s <= ringSteps; s++) {
        const a = (2 * Math.PI * s) / ringSteps;
        const p = project3DPoint(rRing * Math.cos(a), 0, rRing * Math.sin(a));
        if (s === 0) cgCtx.moveTo(p.x, p.y);
        else cgCtx.lineTo(p.x, p.y);
      }
      cgCtx.strokeStyle = isLight
        ? `rgba(2, 132, 199, ${0.14 + rIdx * 0.04})`
        : `rgba(56, 189, 248, ${(0.14 + rIdx * 0.06) * glowFactor})`;
      cgCtx.lineWidth = rIdx === 2 ? 1.5 : 1;
      if (rIdx === 1) cgCtx.setLineDash([5, 5]);
      else cgCtx.setLineDash([]);
      cgCtx.stroke();
    });

    // Crosshair axes on the 3D floor plane
    const ax1 = project3DPoint(-1.22, 0, 0), ax2 = project3DPoint(1.22, 0, 0);
    const az1 = project3DPoint(0, 0, -1.22), az2 = project3DPoint(0, 0, 1.22);
    cgCtx.setLineDash([3, 4]);
    cgCtx.strokeStyle = isLight ? 'rgba(100,116,139,0.22)' : `rgba(148,163,184,${0.18 * glowFactor})`;
    cgCtx.beginPath();
    cgCtx.moveTo(ax1.x, ax1.y); cgCtx.lineTo(ax2.x, ax2.y);
    cgCtx.moveTo(az1.x, az1.y); cgCtx.lineTo(az2.x, az2.y);
    cgCtx.stroke();
    cgCtx.restore();
  } else {
    // 2D Schematic Grid
    cgCtx.save();
    cgCtx.strokeStyle = isLight ? 'rgba(148,163,184,0.22)' : 'rgba(51,65,85,0.35)';
    cgCtx.lineWidth = 1;
    for (let gx = 40; gx < cgW; gx += 48) {
      cgCtx.beginPath(); cgCtx.moveTo(gx, 0); cgCtx.lineTo(gx, cgH); cgCtx.stroke();
    }
    for (let gy = 40; gy < cgH; gy += 48) {
      cgCtx.beginPath(); cgCtx.moveTo(0, gy); cgCtx.lineTo(cgW, gy); cgCtx.stroke();
    }
    cgCtx.restore();
  }

  // 2. Draw Causal Connections (Edges) + Data-Driven Flow Pulses
  edges.forEach((edge, eIdx) => {
    const ai = nodes.findIndex(n => n.id === edge.from);
    const bi = nodes.findIndex(n => n.id === edge.to);
    if (ai < 0 || bi < 0 || !cgPositions[ai] || !cgPositions[bi]) return;
    const a = cgPositions[ai];
    const b = cgPositions[bi];
    const isSelectedEdge = state.selectedNodeId && (edge.from === state.selectedNodeId || edge.to === state.selectedNodeId);

    cgCtx.save();
    const baseAlpha = isSelectedEdge ? Math.min(1, 0.88 * glowFactor + 0.15) : Math.max(0.22, 0.52 * glowFactor);
    cgCtx.strokeStyle = isSelectedEdge
      ? accentHex
      : (isLight ? `rgba(2, 132, 199, ${baseAlpha})` : `rgba(56, 189, 248, ${baseAlpha})`);
    cgCtx.lineWidth = isSelectedEdge ? 2.6 : Math.max(1.3, Math.min(2.4, (edge.weight_fp || 0.5) * 2.2));
    if (edge.lag_ticks > 0) cgCtx.setLineDash([6, 4]);

    const ctrlX = (a.topX + b.topX) * 0.5;
    const ctrlY = (a.topY + b.topY) * 0.5 - (state.uiPrefs.viewMode === '3d' ? 28 : 0);

    cgCtx.beginPath();
    cgCtx.moveTo(a.topX, a.topY);
    if (state.uiPrefs.viewMode === '3d') {
      cgCtx.quadraticCurveTo(ctrlX, ctrlY, b.topX, b.topY);
    } else {
      cgCtx.lineTo(b.topX, b.topY);
    }
    cgCtx.stroke();
    cgCtx.setLineDash([]);

    // Arrowhead near target
    const tArrow = 0.84;
    const px = state.uiPrefs.viewMode === '3d'
      ? (1 - tArrow) * (1 - tArrow) * a.topX + 2 * (1 - tArrow) * tArrow * ctrlX + tArrow * tArrow * b.topX
      : a.topX + (b.topX - a.topX) * tArrow;
    const py = state.uiPrefs.viewMode === '3d'
      ? (1 - tArrow) * (1 - tArrow) * a.topY + 2 * (1 - tArrow) * tArrow * ctrlY + tArrow * tArrow * b.topY
      : a.topY + (b.topY - a.topY) * tArrow;
    const ang = Math.atan2(b.topY - py, b.topX - px);

    cgCtx.fillStyle = cgCtx.strokeStyle;
    cgCtx.beginPath();
    cgCtx.moveTo(px + Math.cos(ang) * 7, py + Math.sin(ang) * 7);
    cgCtx.lineTo(px + Math.cos(ang + 2.5) * 6, py + Math.sin(ang + 2.5) * 6);
    cgCtx.lineTo(px + Math.cos(ang - 2.5) * 6, py + Math.sin(ang - 2.5) * 6);
    cgCtx.closePath();
    cgCtx.fill();

    // Data-driven directional flow pulse (ONLY when live engine is connected and animation is enabled)
    if (shouldRunStageAnimation()) {
      const tPulse = (cgAnimPhase * (0.7 + Number(edge.weight_fp || 0.5)) + eIdx * 0.23) % 1;
      const fx = state.uiPrefs.viewMode === '3d'
        ? (1 - tPulse) * (1 - tPulse) * a.topX + 2 * (1 - tPulse) * tPulse * ctrlX + tPulse * tPulse * b.topX
        : a.topX + (b.topX - a.topX) * tPulse;
      const fy = state.uiPrefs.viewMode === '3d'
        ? (1 - tPulse) * (1 - tPulse) * a.topY + 2 * (1 - tPulse) * tPulse * ctrlY + tPulse * tPulse * b.topY
        : a.topY + (b.topY - a.topY) * tPulse;

      cgCtx.fillStyle = '#ffffff';
      cgCtx.beginPath();
      cgCtx.arc(fx, fy, isSelectedEdge ? 4.2 : 3.0, 0, Math.PI * 2);
      cgCtx.fill();
    }
    cgCtx.restore();
  });

  // 3. Draw Nodes (Sorted back-to-front in 3D mode)
  const renderOrder = [...cgPositions].sort((p1, p2) => p2.zDepth - p1.zDepth);

  renderOrder.forEach(pos => {
    const i = pos.idx;
    const n = nodes[i];
    if (!n) return;
    const aud = audited[i] || {};
    const cmp = cmpList.find(c => c.id === n.id);
    const loadPct = pos.loadPct;
    const hasBias = Boolean(aud.hasBias);
    const isSelected = state.selectedNodeId === n.id;
    const isHovered = cgHoverIdx === i;

    let statusColor = '#10b981';
    if (n.irrecoverable || n.outage_active || loadPct >= 80) statusColor = '#ef4444';
    else if (loadPct >= 50 || hasBias) statusColor = '#f59e0b';

    cgCtx.save();

    if (state.uiPrefs.viewMode === '3d') {
      // 3A. Floor base ring at (baseX, baseY)
      const baseRx = (isSelected ? 22 : 16) * pos.scale;
      const baseRy = baseRx * 0.48;

      cgCtx.beginPath();
      cgCtx.ellipse(pos.baseX, pos.baseY, baseRx, baseRy, 0, 0, Math.PI * 2);
      cgCtx.fillStyle = isSelected ? `rgba(56, 189, 248, ${0.25 * glowFactor})` : 'rgba(15, 23, 42, 0.55)';
      cgCtx.fill();
      cgCtx.lineWidth = isSelected ? 2.2 : 1.2;
      cgCtx.strokeStyle = isSelected ? accentHex : statusColor;
      cgCtx.stroke();

      // If node has reporting bias, draw outer dashed discrepancy ring on floor
      if (hasBias) {
        cgCtx.beginPath();
        cgCtx.setLineDash([4, 3]);
        cgCtx.ellipse(pos.baseX, pos.baseY, baseRx + 6, baseRy + 3, 0, 0, Math.PI * 2);
        cgCtx.strokeStyle = '#f59e0b';
        cgCtx.lineWidth = 1.3;
        cgCtx.stroke();
        cgCtx.setLineDash([]);
      }

      // 3B. Vertical 3D Energy Pillar from (baseX, baseY) to (topX, topY)
      const pillarW = Math.max(10, 14 * pos.scale);
      const grad = cgCtx.createLinearGradient(pos.baseX, pos.baseY, pos.topX, pos.topY);
      grad.addColorStop(0, 'rgba(15, 23, 42, 0.25)');
      grad.addColorStop(1, statusColor);

      cgCtx.fillStyle = grad;
      cgCtx.beginPath();
      cgCtx.moveTo(pos.baseX - pillarW * 0.5, pos.baseY);
      cgCtx.lineTo(pos.topX - pillarW * 0.5, pos.topY);
      cgCtx.lineTo(pos.topX + pillarW * 0.5, pos.topY);
      cgCtx.lineTo(pos.baseX + pillarW * 0.5, pos.baseY);
      cgCtx.closePath();
      cgCtx.fill();

      cgCtx.strokeStyle = isSelected ? '#ffffff' : statusColor;
      cgCtx.lineWidth = isSelected ? 1.8 : 1;
      cgCtx.stroke();
    }

    // 3C. Top Holographic Sphere / Node Core at (topX, topY)
    const orbR = (isSelected || isHovered ? 17 : 13.5) * (state.uiPrefs.viewMode === '3d' ? pos.scale : 1);

    if (isSelected) {
      cgCtx.beginPath();
      cgCtx.arc(pos.topX, pos.topY, orbR + 6, 0, Math.PI * 2);
      cgCtx.strokeStyle = accentHex;
      cgCtx.lineWidth = 2.2;
      cgCtx.stroke();
    }

    cgCtx.beginPath();
    cgCtx.arc(pos.topX, pos.topY, orbR, 0, Math.PI * 2);
    cgCtx.fillStyle = statusColor;
    cgCtx.fill();
    cgCtx.lineWidth = isSelected ? 2.6 : 1.6;
    cgCtx.strokeStyle = '#ffffff';
    cgCtx.stroke();

    // Load percentage inside orb
    cgCtx.fillStyle = '#ffffff';
    cgCtx.font = '800 10.5px Consolas, monospace';
    cgCtx.textAlign = 'center';
    cgCtx.textBaseline = 'middle';
    cgCtx.fillText(`%${loadPct}`, pos.topX, pos.topY);

    // 3D Floating Label Plaque above node (kesiksiz, okunaklı varlık başlığı)
    const hasRecentDiff = Boolean(state.lastDiffByNodeId && state.lastDiffByNodeId[n.id] && state.lastDiffByNodeId[n.id].length > 0);
    const cleanBaseLbl = String(aud.label || n.id).split('(')[0].trim();
    const shortTitle = (hasRecentDiff ? '🔄 ' : '') + (cleanBaseLbl.length > 26 ? cleanBaseLbl.slice(0, 25) + '…' : cleanBaseLbl);
    const labelY = pos.topY - orbR - 15;
    cgCtx.font = isSelected ? '700 11.5px "Segoe UI", sans-serif' : '600 10.5px "Segoe UI", sans-serif';
    const textW = cgCtx.measureText(shortTitle).width + 16;

    cgCtx.fillStyle = isLight
      ? (isSelected ? '#0284c7' : 'rgba(255, 255, 255, 0.94)')
      : (isSelected ? 'rgba(18, 42, 78, 0.94)' : 'rgba(8, 17, 34, 0.88)');
    cgCtx.strokeStyle = isSelected ? '#E6C387' : (hasRecentDiff ? '#10b981' : (isLight ? 'rgba(2,132,199,0.4)' : 'rgba(136,212,255,0.48)'));
    cgCtx.lineWidth = isSelected ? 1.8 : (hasRecentDiff ? 1.6 : 1);
    cgCtx.beginPath();
    cgCtx.roundRect(pos.topX - textW / 2, labelY - 10, textW, 21, 6);
    cgCtx.fill();
    cgCtx.stroke();

    cgCtx.fillStyle = isSelected ? '#FFFFFF' : (isLight ? '#0f172a' : '#f8fafc');
    cgCtx.fillText(shortTitle, pos.topX, labelY);

    // If A/B comparison was run and this node changed, show compact A→B delta pill
    if (state.lastEvaluation && state.lastEvaluation.isCounterfactualSimulated && cmp && cmp.deltaStatePct !== 0) {
      const deltaStr = `A:%${cmp.branchAStatePct} → B:%${cmp.branchBStatePct}`;
      cgCtx.font = '700 9.5px Consolas, monospace';
      const dw = cgCtx.measureText(deltaStr).width + 10;
      const dy = labelY - 21;
      cgCtx.fillStyle = cmp.deltaStatePct < 0 ? 'rgba(16, 185, 129, 0.92)' : 'rgba(245, 158, 11, 0.92)';
      cgCtx.beginPath();
      cgCtx.roundRect(pos.topX - dw / 2, dy - 8, dw, 16, 4);
      cgCtx.fill();
      cgCtx.fillStyle = '#ffffff';
      cgCtx.fillText(deltaStr, pos.topX, dy);
    }

    cgCtx.restore();
  });

  const frameRenderMs = performance.now() - tFrameStart;
  recordStageFrameTelemetry(frameRenderMs);
}

/* ── Appearance & Personalization Engine ("Görünüm" Paneli) ───────────────── */
const PREFS_STORAGE_KEY = 'caelus_holo_prefs_v1';

const DEFAULT_UI_PREFS = {
  themePreset: 'holo_sapphire',
  customAccent: null,
  surfaceTone: 'deep_space',
  glowBrightness: 75,
  animLevel: 'normal',
  viewMode: '3d',
  fontScale: '1',
  contrastMode: 'normal',
  gpuEcoMode: true,
  auto2dFallback: true
};

const THEME_PRESET_LABELS = {
  holo_sapphire: 'Holografik Safir',
  quantum_emerald: 'Kuantum Zümrüt',
  amber_command: 'Kehribar Komuta',
  arctic_crystal: 'Kutup Kristali (Açık)',
  high_contrast: 'Yüksek Kontrast'
};

function parseHexRgb(hex) {
  const clean = String(hex || '').replace('#', '').trim();
  if (clean.length !== 6) return { r: 14, g: 165, b: 233 };
  return {
    r: parseInt(clean.slice(0, 2), 16) || 0,
    g: parseInt(clean.slice(2, 4), 16) || 0,
    b: parseInt(clean.slice(4, 6), 16) || 0
  };
}

function relLuminance({ r, g, b }) {
  const srgb = [r / 255, g / 255, b / 255].map(c =>
    c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4)
  );
  return 0.2126 * srgb[0] + 0.7152 * srgb[1] + 0.0722 * srgb[2];
}

function contrastRatio(lum1, lum2) {
  const l1 = Math.max(lum1, lum2);
  const l2 = Math.min(lum1, lum2);
  return (l1 + 0.05) / (l2 + 0.05);
}

function checkAppearanceReadability() {
  if (!el.readabilityWarningBox || !el.readabilityWarningText) return;
  const prefs = state.uiPrefs;
  const isLightSurface = prefs.themePreset === 'arctic_crystal' || prefs.surfaceTone === 'daylight';
  const bgLum = isLightSurface ? 0.91 : 0.018;

  const warnings = [];
  if (prefs.customAccent) {
    const accLum = relLuminance(parseHexRgb(prefs.customAccent));
    const ratio = contrastRatio(bgLum, accLum);
    if (ratio < 2.6) {
      warnings.push(
        isLightSurface
          ? `Seçilen özel vurgu rengi (${prefs.customAccent}) açık arka plan üzerinde çok soluk kalıyor (Kontrast: ${ratio.toFixed(1)}:1).`
          : `Seçilen özel vurgu rengi (${prefs.customAccent}) koyu arka plan üzerinde çok karanlık kalıyor (Kontrast: ${ratio.toFixed(1)}:1).`
      );
    }
  }

  if (Number(prefs.glowBrightness) < 25 && prefs.contrastMode !== 'high') {
    warnings.push(`Hologram ve bağlantı çizgisi parlaklığı (%${prefs.glowBrightness}) çok düşük; 3D sahnedeki nedensel bağlantılar zor seçilebilir.`);
  }

  if (warnings.length > 0) {
    el.readabilityWarningText.textContent = warnings.join(' ');
    el.readabilityWarningBox.classList.remove('hidden');
  } else {
    el.readabilityWarningBox.classList.add('hidden');
  }
}

function applyAppearancePrefs(save = true) {
  const p = state.uiPrefs;
  const b = document.body;
  const root = document.documentElement;

  b.classList.remove(
    'theme-quantum-emerald',
    'theme-amber-command',
    'theme-light',
    'theme-high-contrast',
    'contrast-high',
    'surface-matte',
    'surface-crystal',
    'anim-off'
  );

  if (p.themePreset === 'quantum_emerald') b.classList.add('theme-quantum-emerald');
  else if (p.themePreset === 'amber_command') b.classList.add('theme-amber-command');
  else if (p.themePreset === 'arctic_crystal') b.classList.add('theme-light');
  else if (p.themePreset === 'high_contrast') b.classList.add('theme-high-contrast');

  if (p.surfaceTone === 'daylight') b.classList.add('theme-light');
  else if (p.surfaceTone === 'matte') b.classList.add('surface-matte');
  else if (p.surfaceTone === 'crystal') b.classList.add('surface-crystal');

  if (p.contrastMode === 'high') b.classList.add('contrast-high');
  if (p.animLevel === 'off') b.classList.add('anim-off');
  if (p.gpuEcoMode !== false) b.classList.add('gpu-eco-mode');
  else b.classList.remove('gpu-eco-mode');

  root.style.setProperty('--holo-glow-alpha', String(clamp(Number(p.glowBrightness || 75) / 100, 0.1, 1.0)));
  root.style.setProperty('--font-scale', String(Number(p.fontScale || 1)));

  if (p.customAccent) {
    const { r, g, b: blue } = parseHexRgb(p.customAccent);
    root.style.setProperty('--primary', p.customAccent);
    root.style.setProperty('--accent', p.customAccent);
    root.style.setProperty('--border-focus', p.customAccent);
    root.style.setProperty('--primary-soft', `rgba(${r}, ${g}, ${blue}, 0.18)`);
    root.style.setProperty('--accent-soft', `rgba(${r}, ${g}, ${blue}, 0.15)`);
  } else {
    root.style.removeProperty('--primary');
    root.style.removeProperty('--accent');
    root.style.removeProperty('--border-focus');
    root.style.removeProperty('--primary-soft');
    root.style.removeProperty('--accent-soft');
  }

  // Sync Appearance Drawer UI controls
  if (el.prefActiveThemeLabel) {
    el.prefActiveThemeLabel.textContent = THEME_PRESET_LABELS[p.themePreset] || 'Özel Tema';
  }
  document.querySelectorAll('.theme-preset-btn').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-theme-preset') === p.themePreset);
  });
  document.querySelectorAll('.color-swatch-btn').forEach(btn => {
    btn.classList.toggle('active', p.customAccent && btn.getAttribute('data-swatch') === p.customAccent);
  });
  if (el.prefCustomAccent && p.customAccent) {
    el.prefCustomAccent.value = p.customAccent;
  }
  if (el.prefSurfaceTone) {
    el.prefSurfaceTone.value = p.surfaceTone || 'deep_space';
  }
  if (el.prefGlowBrightness) {
    el.prefGlowBrightness.value = String(p.glowBrightness || 75);
  }
  if (el.prefGlowVal) {
    el.prefGlowVal.textContent = `%${p.glowBrightness || 75}`;
  }
  document.querySelectorAll('.pref-anim-btn').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-anim-level') === p.animLevel);
  });
  document.querySelectorAll('.pref-view-btn').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-view-mode') === p.viewMode);
  });
  document.querySelectorAll('.pref-font-btn').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-font-scale') === String(p.fontScale));
  });
  document.querySelectorAll('.pref-contrast-btn').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-contrast-mode') === p.contrastMode);
  });
  document.querySelectorAll('.pref-gpu-eco-btn').forEach(btn => {
    btn.classList.toggle('active', (btn.getAttribute('data-gpu-eco') === 'true') === (p.gpuEcoMode !== false));
  });
  document.querySelectorAll('.pref-auto2d-btn').forEach(btn => {
    btn.classList.toggle('active', (btn.getAttribute('data-auto-2d') === 'true') === (p.auto2dFallback !== false));
  });

  checkAppearanceReadability();
  updateStageStatusBadges(state.lastEvaluation);
  updatePerfTelemetryUi();
  drawCausalGraph();
  drawCrisisTimeline();

  if (save) {
    try {
      localStorage.setItem(PREFS_STORAGE_KEY, JSON.stringify(state.uiPrefs));
    } catch (_) { }
  }
}

function loadAppearancePrefs() {
  try {
    const raw = localStorage.getItem(PREFS_STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      state.uiPrefs = { ...DEFAULT_UI_PREFS, ...parsed };
    }
  } catch (_) {
    state.uiPrefs = { ...DEFAULT_UI_PREFS };
  }
  applyAppearancePrefs(false);
}

function resetAppearancePrefs() {
  state.uiPrefs = { ...DEFAULT_UI_PREFS };
  applyAppearancePrefs(true);
}

/* ── Time-Series Crisis Timeline Chart ────────────────────────────────────── */
let ctCtx = null, ctW = 0, ctH = 0, ctHoverX = -1;

function initCrisisTimeline() {
  const canvas = el.crisisTimeline;
  if (!canvas) return;
  ctCtx = canvas.getContext('2d');

  function resize() {
    const parent = canvas.parentElement;
    ctW = canvas.width = parent.clientWidth || 500;
    ctH = canvas.height = parent.clientHeight || 110;
    drawCrisisTimeline();
  }
  resize();
  window.addEventListener('resize', resize);

  canvas.addEventListener('mousemove', e => {
    const rect = canvas.getBoundingClientRect();
    ctHoverX = e.clientX - rect.left;
    drawCrisisTimeline();
  });
  canvas.addEventListener('mouseleave', () => {
    ctHoverX = -1;
    if (el.ctTooltip) el.ctTooltip.classList.add('hidden');
    drawCrisisTimeline();
  });
}

function drawCrisisTimeline() {
  if (!ctCtx || ctW === 0 || ctH === 0) return;
  const isLight = document.body.classList.contains('theme-light');
  ctCtx.clearRect(0, 0, ctW, ctH);
  ctCtx.fillStyle = isLight ? '#f8fafc' : '#0f1623';
  ctCtx.fillRect(0, 0, ctW, ctH);

  ctCtx.strokeStyle = isLight ? 'rgba(148,163,184,0.35)' : 'rgba(51,65,85,0.6)';
  ctCtx.lineWidth = 1;
  [0.25, 0.5, 0.75].forEach(gy => {
    const y = ctH - gy * (ctH - 20) - 10;
    ctCtx.beginPath();
    ctCtx.moveTo(32, y);
    ctCtx.lineTo(ctW - 8, y);
    ctCtx.stroke();
  });

  ctCtx.fillStyle = isLight ? '#475569' : '#94a3b8';
  ctCtx.font = '10px Consolas, monospace';
  ctCtx.textAlign = 'left';
  ctCtx.fillText('100%', 4, 14);
  ctCtx.fillText('50%', 4, ctH / 2 + 3);
  ctCtx.fillText('0%', 4, ctH - 6);

  const hist = state.tickHistory;
  if (hist.length === 0) return;

  const visible = hist.slice(-160);
  const plotW = Math.max(10, ctW - 44);
  const stepX = visible.length > 1 ? plotW / (visible.length - 1) : plotW;

  ctCtx.beginPath();
  ctCtx.lineWidth = 2;
  ctCtx.strokeStyle = '#0ea5e9';
  visible.forEach((pt, i) => {
    const x = 36 + i * stepX;
    const y = ctH - 10 - pt.ratio * (ctH - 22);
    if (i === 0) ctCtx.moveTo(x, y);
    else ctCtx.lineTo(x, y);
  });
  ctCtx.stroke();

  ctCtx.beginPath();
  ctCtx.lineWidth = 1.5;
  ctCtx.strokeStyle = '#f59e0b';
  ctCtx.setLineDash([4, 3]);
  visible.forEach((pt, i) => {
    const x = 36 + i * stepX;
    const normF = clamp((pt.friction - 1) / 2, 0, 1);
    const y = ctH - 10 - normF * (ctH - 22);
    if (i === 0) ctCtx.moveTo(x, y);
    else ctCtx.lineTo(x, y);
  });
  ctCtx.stroke();
  ctCtx.setLineDash([]);

  if (ctHoverX >= 36 && visible.length > 0) {
    const idx = clamp(Math.round((ctHoverX - 36) / Math.max(1, stepX)), 0, visible.length - 1);
    const pt = visible[idx];
    const hx = 36 + idx * stepX;

    ctCtx.strokeStyle = isLight ? '#0f172a' : '#f8fafc';
    ctCtx.lineWidth = 1;
    ctCtx.beginPath();
    ctCtx.moveTo(hx, 6);
    ctCtx.lineTo(hx, ctH - 6);
    ctCtx.stroke();

    if (el.ctTooltip && pt) {
      el.ctTooltip.textContent = `Adım: ${pt.tick} · Kapasite: %${(pt.ratio * 100).toFixed(1)} · Sürtünme: ${pt.friction.toFixed(2)}×`;
      el.ctTooltip.classList.remove('hidden');
    }
  }
}

