      state.uiPrefs.themePreset = preset;
      state.uiPrefs.customAccent = null;
      if (preset === 'arctic_crystal') state.uiPrefs.surfaceTone = 'daylight';
      else if (state.uiPrefs.surfaceTone === 'daylight') state.uiPrefs.surfaceTone = 'deep_space';
      applyAppearancePrefs(true);
