      const diffReport = compiler.diffTwinStates(
        state.baselineTwinSnapshot,
        editedTwin,
        'USER_MODEL_EDITOR'
      );
      applyTwinStateToEngine(editedTwin, diffReport, 'Genel Model Düzenleyici Güncellemesi');
