      const activeId = (state.twinState && state.twinState.scenarioId) || state.scenarioMeta.scenarioId || '';
      const dsKey = String(activeId).toUpperCase().includes('TWIN-LIMAN') ? 'TWIN-LIMAN-01' : 'EX-01_LIMAN_SOGUK_ZINCIR';
      const sample = compiler.getSampleImportDataset(dsKey, 'CSV');
      if (el.dtImportRawText) el.dtImportRawText.value = sample.rawText;
      if (el.dtImportSourceName) el.dtImportSourceName.value = sample.sourceName;
      if (el.dtImportDefaultUnit) el.dtImportDefaultUnit.value = '% Yük';
