// BOŞ DÜNYA DURUMU, ÇOK DİLLİ (TR/EN/AR/HE) VE KİŞİSEL TEMA KONTROLÜ
// ═══════════════════════════════════════════════════════════════════════════

function getHumanFriendlySourceLabel(rawProvenance) {
  const code = String(rawProvenance || '').toUpperCase();
  if (code.includes('OBSERVED') || code.includes('WIN32') || code.includes('SENSOR')) {
    return 'Bilginin kaynağı: Gözlem';
  }
  if (code.includes('HISTORICAL') || code.includes('DOCUMENTED') || code.includes('LEDGER')) {
    return 'Bilginin kaynağı: Geçmiş kayıt';
  }
  if (code.includes('COMPUTED') || code.includes('KEPLER') || code.includes('EPHEMERIS')) {
    return 'Bilginin kaynağı: Hesaplanmış değer';
  }
  if (code.includes('MODEL_OUTPUT') || code.includes('COUNTERFACTUAL') || code.includes('BRANCH')) {
    return 'Bilginin kaynağı: Model çıktısı';
  }
  if (code.includes('USER') || code.includes('MANUAL') || code.includes('CALIBRATION')) {
    return 'Bilginin kaynağı: Kullanıcı varsayımı';
  }
  if (code.includes('RECOMMENDATION')) {
    return 'Bilginin kaynağı: Öneri';
  }
  return 'Bilginin kaynağı: Örnek veya kurgu';
}

function switchQuietView(viewId, options = {}) {
  const validViews = ['dunyam', 'kesfet', 'kozmos', 'senaryolar', 'hafiza', 'baglantilar', 'ayarlar'];
  const target = validViews.includes(viewId) ? viewId : 'dunyam';
  state.activeQuietView = target;

  if (state.allViewsSinglePageMode && !options.exitAllViews) {
    document.body.removeAttribute('data-quiet-view');
  } else {
    state.allViewsSinglePageMode = false;
    document.body.setAttribute('data-quiet-view', target);
  }

  document.querySelectorAll('.quiet-nav-tab').forEach(btn => {
    const isMatch = btn.getAttribute('data-quiet-nav') === target;
    btn.classList.toggle('active', isMatch);
    btn.setAttribute('aria-selected', isMatch ? 'true' : 'false');
    btn.setAttribute('tabindex', isMatch ? '0' : '-1');
  });

  document.querySelectorAll('.caelus-mobile-nav-btn').forEach(btn => {
    const isMatch = btn.getAttribute('data-quiet-nav') === target;
    btn.classList.toggle('active', isMatch);
    btn.setAttribute('aria-current', isMatch ? 'page' : 'false');
  });

  if (typeof syncSpatialCompassView === 'function') {
    syncSpatialCompassView(target);
  }
  if (window.CaelusSpatialExperience && typeof window.CaelusSpatialExperience.syncSpatialModeLayout === 'function') {
    window.CaelusSpatialExperience.syncSpatialModeLayout(target);
  }

  if (target === 'kozmos') {
    document.body.classList.remove('kesfet-solar-focus');
    if (typeof renderLivingUniversePanel === 'function') renderLivingUniversePanel();
  } else if (target === 'kesfet' && options.openDigitalWorld) {
    const detailsDw = document.getElementById('details-digital-world');
    if (detailsDw) detailsDw.open = true;
  } else if (target === 'senaryolar') {
    if (options.openHistorical) {
      const detailsHist = document.getElementById('details-historical-comparison');
      if (detailsHist) detailsHist.open = true;
    }
    const cfBox = document.getElementById('cf-side-by-side-box');
    if (cfBox && cfBox.classList.contains('hidden') && el.btnRunCompareLever) {
      setTimeout(() => {
        if (cfBox.classList.contains('hidden') && el.btnRunCompareLever) {
          el.btnRunCompareLever.click();
        }
      }, 60);
    }
  } else if (target === 'hafiza' && options.focusQa) {
    const qaInput = document.getElementById('hafiza-search-input') || document.getElementById('univ-qa-input');
    if (qaInput) setTimeout(() => qaInput.focus(), 60);
  } else if (target === 'baglantilar' && options.openDataImport) {
    const detailsImp = document.getElementById('details-data-import');
    if (detailsImp) detailsImp.open = true;
  }

  if (typeof renderUnifiedPageWorkspaces === 'function') {
    renderUnifiedPageWorkspaces(state.lastEvaluation);
  }

  if (typeof animateCaelusViewTransition === 'function') {
    animateCaelusViewTransition(target);
  }

  window.scrollTo(0, 0);

  requestAnimationFrame(() => {
    window.scrollTo(0, 0);
    if (typeof layoutCausalGraph === 'function') layoutCausalGraph();
    if (typeof drawCausalGraph === 'function') drawCausalGraph();
    if (typeof drawDunyamHeroStage === 'function') drawDunyamHeroStage();
    if (target === 'kozmos' && typeof renderLivingUniversePanel === 'function') renderLivingUniversePanel();
    if (typeof drawTimeline === 'function') drawTimeline();
    if (target === 'hafiza' && typeof renderHafizaStreamWorkspace === 'function') renderHafizaStreamWorkspace();
    if (target === 'senaryolar' && typeof resizeScenarioECharts === 'function') resizeScenarioECharts();
  });
}

