function dhCalloutIsOverlay() {
  return window.innerWidth > 760;
}

function dhCenterY() {
  return window.innerWidth <= 760 ? dhH * 0.50 : dhH * 0.47;
}

function dhGlobeRadius() {
  const overlayMode = dhCalloutIsOverlay();
  return Math.min(dhW * (overlayMode ? 0.255 : 0.36), dhH * (overlayMode ? 0.355 : 0.39)) * cam3D.zoom;
}

