function worldHasGeographicCoords(scenarioId, activeWorld) {
  const scId = String(scenarioId || (state.scenarioMeta && state.scenarioMeta.scenarioId) || '');
  if (
    !scId ||
    scId === 'EX-01_LIMAN_SOGUK_ZINCIR' ||
    scId === 'BS-01_SAHTE_UFUK' ||
    scId === 'TWIN-LIMAN-01' ||
    scId === 'WORLD-LIMAN-01' ||
    scId.includes('LIMAN')
  ) {
    return true;
  }
  if (activeWorld && (activeWorld.worldId === 'WORLD-LIMAN-01' || activeWorld.scenarioId === 'EX-01_LIMAN_SOGUK_ZINCIR')) {
    return true;
  }
  if (activeWorld && Array.isArray(activeWorld.realWorldRecords)) {
    const hasGeoRec = activeWorld.realWorldRecords.some(r =>
      r && r.location && r.location.hasCoordinates !== false && typeof r.location.lat === 'number' && typeof r.location.lon === 'number'
    );
    if (hasGeoRec) return true;
  }
  return false;
}

