function buildMarkerPinCanvas(colorHex, isSelected, isRealEvent, labelBadge) {
  const c = document.createElement('canvas');
  c.width = isSelected ? 44 : 34;
  c.height = isSelected ? 44 : 34;
  const ctx = c.getContext('2d');
  const cx = c.width / 2;
  const cy = c.height / 2;

  // Outer glow / pulse ring
  const grad = ctx.createRadialGradient(cx, cy, 2, cx, cy, cx - 1);
  grad.addColorStop(0, colorHex);
  grad.addColorStop(0.45, colorHex + '66');
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, cx - 1, 0, Math.PI * 2);
  ctx.fill();

  if (isRealEvent) {
    // Seismic concentric wave ring for real USGS events
    ctx.beginPath();
    ctx.arc(cx, cy, isSelected ? 15 : 11.5, 0, Math.PI * 2);
    ctx.strokeStyle = isSelected ? '#FFFFFF' : colorHex;
    ctx.lineWidth = isSelected ? 2.0 : 1.4;
    ctx.setLineDash([3, 2]);
    ctx.stroke();
    ctx.setLineDash([]);
  } else {
    ctx.beginPath();
    ctx.arc(cx, cy, isSelected ? 13 : 9.5, 0, Math.PI * 2);
    ctx.strokeStyle = isSelected ? '#FFFFFF' : colorHex;
    ctx.lineWidth = isSelected ? 2.2 : 1.4;
    ctx.stroke();
  }

  // Core dot
  ctx.beginPath();
  ctx.arc(cx, cy, isSelected ? 6.8 : 5.2, 0, Math.PI * 2);
  ctx.fillStyle = colorHex;
  ctx.fill();
  ctx.lineWidth = 1.6;
  ctx.strokeStyle = '#FFFFFF';
  ctx.stroke();

  return c.toDataURL();
}

async function initCaelusCesiumGlobe() {
  const container = document.getElementById('dunyam-cesium-container');
  if (!container) return false;

  if (typeof window.Cesium === 'undefined') {
    window.cCesiumState.failed = true;
    const pill = document.getElementById('dunyam-webgl-fallback-pill');
    if (pill) {
      pill.textContent = 'CesiumJS 3B kütüphanesi yüklenemedi — yerleşik hafif görünüm aktif.';
      pill.classList.remove('hidden');
    }
    return false;
  }

  try {
    window.CESIUM_BASE_URL = '/vendor/cesium/';
    const Cesium = window.Cesium;

    const baseImageryProvider = await Cesium.TileMapServiceImageryProvider.fromUrl(
      '/vendor/cesium/Assets/Textures/NaturalEarthII',
      {
        fileExtension: 'jpg',
        maximumLevel: 2,
        credit: new Cesium.Credit('Natural Earth II · Çevrimdışı Yerleşik TMS (Public Domain)')
      }
    );

    const viewer = new Cesium.Viewer(container, {
      baseLayer: new Cesium.ImageryLayer(baseImageryProvider),
      baseLayerPicker: false,
      geocoder: false,
      homeButton: false,
      sceneModePicker: false,
      navigationHelpButton: false,
      animation: false,
      timeline: false,
      fullscreenButton: false,
      vrButton: false,
      infoBox: false,
      selectionIndicator: false,
      shouldAnimate: true,
      requestRenderMode: false,
      contextOptions: {
        webgl: {
          alpha: true,
          antialias: true,
          powerPreference: 'high-performance',
          failIfMajorPerformanceCaveat: false
        }
      }
    });

    // Sirius gece mavisi atmosfer ve derin uzay uyumu (01_Onayli_Holografik_Atmosfer arkadan görünür)
    if (viewer.scene.skyBox) {
      viewer.scene.skyBox.show = false;
    }
    if (viewer.scene.sun) {
      viewer.scene.sun.show = false;
    }
    if (viewer.scene.moon) {
      viewer.scene.moon.show = false;
    }
    viewer.scene.backgroundColor = Cesium.Color.fromCssColorString('#040915').withAlpha(0.0);
    viewer.scene.globe.baseColor = Cesium.Color.fromCssColorString('#0B2246');
    viewer.scene.globe.enableLighting = false;
    viewer.scene.globe.showGroundAtmosphere = true;
    if (viewer.scene.skyAtmosphere) {
      viewer.scene.skyAtmosphere.show = true;
      viewer.scene.skyAtmosphere.hueShift = -0.02;
      viewer.scene.skyAtmosphere.saturationShift = 0.16;
      viewer.scene.skyAtmosphere.brightnessShift = 0.05;
    }
    if (viewer.scene.fog) {
      viewer.scene.fog.enabled = true;
      viewer.scene.fog.density = 0.00012;
    }

    // Entegre GPU (Intel UHD 620 vb.) için akıllı DPR ölçekleme
    const eco = Boolean(state.uiPrefs && state.uiPrefs.gpuEcoMode);
    viewer.resolutionScale = eco ? 1.0 : Math.min(window.devicePixelRatio || 1.0, 1.5);

    // Yerleşik NaturalEarthII (Katman 0) taban dokusunu parlak ve yüksek kontrastlı hale getir
    const baseLayer0 = viewer.imageryLayers && viewer.imageryLayers.length > 0
      ? viewer.imageryLayers.get(0)
      : null;
    if (baseLayer0) {
      baseLayer0.brightness = 1.42;
      baseLayer0.contrast = 1.16;
      baseLayer0.saturation = 1.28;
      baseLayer0.gamma = 0.88;
    }

    // Yerel 2048x1024 Holografik Kıta Sahanlığı ve Kıyı Dokusunu (SingleTileImageryProvider) Katman 1 olarak ekle
    if (typeof buildEarthEquirectangularCanvas === 'function') {
      try {
        const holoTexCanvas = buildEarthEquirectangularCanvas(false, '#88D4FF', eco);
        const holoDataUrl = holoTexCanvas.toDataURL('image/png');
        const holoProvider = await Cesium.SingleTileImageryProvider.fromUrl(holoDataUrl, {
          rectangle: Cesium.Rectangle.fromDegrees(-180.0, -90.0, 180.0, 90.0)
        });
        const holoLayer = viewer.imageryLayers.addImageryProvider(holoProvider);
        holoLayer.alpha = 0.64;
        holoLayer.brightness = 1.18;
      } catch (_) {}
    }

    // Kıyı çizgilerinin her yakınlaştırma seviyesinde jilet gibi net görünmesi için 3B vektör kıyı sınırları (pt = [lon, lat])
    if (typeof NATURAL_EARTH_110M_RINGS !== 'undefined' && Array.isArray(NATURAL_EARTH_110M_RINGS)) {
      NATURAL_EARTH_110M_RINGS.forEach((ring) => {
        if (!Array.isArray(ring) || ring.length < 3) return;
        const degHeights = [];
        for (let i = 0; i < ring.length; i++) {
          const pt = ring[i];
          if (Array.isArray(pt) && pt.length >= 2) {
            const lon = Number(pt[0]);
            const lat = Number(pt[1]);
            if (Number.isFinite(lon) && Number.isFinite(lat) && lat >= -89.5 && lat <= 89.5) {
              degHeights.push(lon, lat, 1200);
            }
          }
        }
        if (degHeights.length >= 6) {
          try {
            viewer.entities.add({
              polyline: {
                positions: Cesium.Cartesian3.fromDegreesArrayHeights(degHeights),
                width: 2.0,
                material: Cesium.Color.fromCssColorString('#9BE0FF').withAlpha(0.84)
              }
            });
          } catch (_) {}
        }
      });
    }

    // Zarif 30° enlem/boylam ızgara çizgileri (Quiet Holography uzay derinliği)
    for (let lat = -60; lat <= 60; lat += 30) {
      const pts = [];
      for (let lon = -180; lon <= 180; lon += 10) {
        pts.push(lon, lat, 400);
      }
      viewer.entities.add({
        polyline: {
          positions: Cesium.Cartesian3.fromDegreesArrayHeights(pts),
          width: 1.0,
          material: Cesium.Color.fromCssColorString('#38BDF8').withAlpha(lat === 0 ? 0.18 : 0.08)
        }
      });
    }
    for (let lon = -150; lon <= 180; lon += 30) {
      const pts = [];
      for (let lat = -75; lat <= 75; lat += 10) {
        pts.push(lon, lat, 400);
      }
      viewer.entities.add({
        polyline: {
          positions: Cesium.Cartesian3.fromDegreesArrayHeights(pts),
          width: 1.0,
          material: Cesium.Color.fromCssColorString('#38BDF8').withAlpha(0.08)
        }
      });
    }

    // Başlangıç kamera konumu: Dünya küresinin atmosferik ufkunu ve Doğu Akdeniz / Ege koridorunu tam çerçeveleyen dengeli perspektif
    viewer.camera.setView({
      destination: Cesium.Cartesian3.fromDegrees(27.15, 34.0, 8200000.0),
      orientation: {
        heading: Cesium.Math.toRadians(0.0),
        pitch: Cesium.Math.toRadians(-82.0),
        roll: 0.0
      }
    });

    window.cCesiumState.viewer = viewer;
    window.cCesiumState.ready = true;
    window.cCesiumState.failed = false;

    // Gerçek GPU/CPU sahne çizim süresi (preRender -> postRender) ve FPS ölçümü
    viewer.scene.preRender.addEventListener(() => {
      window.cCesiumState._preRenderTs = performance.now();
    });

    viewer.scene.postRender.addEventListener(() => {
      const now = performance.now();
      const renderDurationMs = Math.max(0.6, now - (window.cCesiumState._preRenderTs || now));
      if (window.cCesiumState.lastFramePerfTs > 0) {
        const dt = now - window.cCesiumState.lastFramePerfTs;
        if (dt > 2 && dt < 250) {
          window.cCesiumState.fpsSamples.push(dt);
          if (window.cCesiumState.fpsSamples.length > 45) {
            window.cCesiumState.fpsSamples.shift();
          }
          const avgIntervalMs = window.cCesiumState.fpsSamples.reduce((a, b) => a + b, 0) / window.cCesiumState.fpsSamples.length;
          window.cCesiumState.measuredFrameMs = Number(renderDurationMs.toFixed(2));
          window.cCesiumState.measuredFps = Math.min(120, Math.round(1000 / Math.max(1, avgIntervalMs)));
        }
      }
      window.cCesiumState.lastFramePerfTs = now;

      // Sakin otomatik dönüş (kullanıcı sürüklemiyorken ve rüzgâr/yakın çekim kapalıyken çok hafif dönüş)
      if (
        state.dunyamAutoRotate &&
        !state.dunyamUserPausedAutoRotate &&
        state.uiPrefs.animationLevel !== 'off' &&
        !isReducedMotionPreferred() &&
        window.cCesiumState.windDensity === 'OFF'
      ) {
        try {
          const camHeight = viewer.camera.positionCartographic.height;
          if (camHeight > 3200000) {
            viewer.camera.rotate(Cesium.Cartesian3.UNIT_Z, -0.00035);
          }
        } catch (_) {}
      }
    });

    // 3B Dünya üzerinde tıklama ile konum / gerçek olay seçimi
    const handler = new Cesium.ScreenSpaceEventHandler(viewer.scene.canvas);
    handler.setInputAction((movement) => {
      state.dunyamUserPausedAutoRotate = true;
      const picked = viewer.scene.pick(movement.position);
      if (Cesium.defined(picked) && picked.id && picked.id.caelusMarkerId) {
        selectCesiumGlobeMarkerById(picked.id.caelusMarkerId, { flyTo: false });
      }
    }, Cesium.ScreenSpaceEventType.LEFT_CLICK);

    handler.setInputAction(() => {
      state.dunyamUserPausedAutoRotate = true;
    }, Cesium.ScreenSpaceEventType.LEFT_DOWN);

    // İlk coğrafi koridorları ve gerçek/örnek olay işaretlerini yükle
    await loadAndRenderRealGlobeEvents();
    drawDunyamHeroStage();
    return true;
  } catch (err) {
    console.warn('CesiumJS başlatılamadı, yedek 3B/2B sahne kullanılıyor:', err);
    window.cCesiumState.failed = true;
    window.cCesiumState.ready = false;
    drawDunyamHeroStage();
    return false;
  }
}

function flyCesiumToAegeanRegion(durationSec = 1.4) {
  const viewer = window.cCesiumState && window.cCesiumState.viewer;
  if (!viewer || typeof window.Cesium === 'undefined') return;
  const Cesium = window.Cesium;
  state.dunyamUserPausedAutoRotate = true;
  state.activeScaleStep = 'REGION';
  updateDunyamStageControlPills();
  viewer.camera.flyTo({
    destination: Cesium.Cartesian3.fromDegrees(26.85, 37.85, 1380000.0),
    orientation: {
      heading: Cesium.Math.toRadians(0.0),
      pitch: Cesium.Math.toRadians(-84.0),
      roll: 0.0
    },
    duration: durationSec
  });
}

function flyCesiumToGlobalView(durationSec = 1.4) {
  const viewer = window.cCesiumState && window.cCesiumState.viewer;
  if (!viewer || typeof window.Cesium === 'undefined') return;
  const Cesium = window.Cesium;
  state.activeScaleStep = 'EARTH';
  updateDunyamStageControlPills();
  viewer.camera.flyTo({
    destination: Cesium.Cartesian3.fromDegrees(27.15, 34.0, 9200000.0),
    orientation: {
      heading: Cesium.Math.toRadians(0.0),
      pitch: Cesium.Math.toRadians(-85.0),
      roll: 0.0
    },
    duration: durationSec
  });
}

/**
 * NASA EOSDIS GIBS WMTS Uydu Katmanı Yöneticisi
 * Seçilen tarihte görüntü olup olmadığını gerçek bir WMTS karosu (TileMatrix=3, TileRow=3, TileCol=4 - Doğu Akdeniz/Ege)
 * ile doğrular. Görüntü yoksa (örn. gelecek tarih 2026-11-07 -> HTTP 404) veya çevrimdışıysa ASLA uydurma görüntü üretmez.
 */
async function applyNasaGibsImageryLayer(layerIdInput, dateStrInput) {
  const viewer = window.cCesiumState && window.cCesiumState.viewer;
  const Cesium = window.Cesium;
  const layerMeta = CAELUS_GIBS_LAYERS_CATALOG[layerIdInput] || CAELUS_GIBS_LAYERS_CATALOG.NONE;
  const effectiveDate = layerMeta.isStaticDate
    ? layerMeta.defaultDate
    : (String(dateStrInput || layerMeta.defaultDate || '2026-04-05').trim());

  window.cCesiumState.activeGibsLayerId = layerMeta.id;
  window.cCesiumState.activeGibsDate = effectiveDate;

  const selEl = document.getElementById('sel-dunyam-gibs-layer');
  if (selEl && selEl.value !== layerMeta.id) selEl.value = layerMeta.id;
  const dateEl = document.getElementById('inp-dunyam-gibs-date');
  if (dateEl && effectiveDate) dateEl.value = effectiveDate;

  const btnQuickGibs = document.getElementById('btn-stage-toggle-gibs');
  const gibsChipEl = document.getElementById('dunyam-gibs-attribution-line');

  // Mevcut GIBS katmanı varsa kaldır
  if (viewer && window.cCesiumState.gibsImageryLayer) {
    try {
      viewer.imageryLayers.remove(window.cCesiumState.gibsImageryLayer, true);
    } catch (_) {}
    window.cCesiumState.gibsImageryLayer = null;
  }

  if (layerMeta.id === 'NONE') {
    window.cCesiumState.activeGibsStatus = 'OFF';
    if (btnQuickGibs) {
      btnQuickGibs.classList.remove('active');
      btnQuickGibs.setAttribute('aria-pressed', 'false');
    }
    if (gibsChipEl) {
      gibsChipEl.classList.add('hidden');
      gibsChipEl.innerHTML = '';
    }
    return { status: 'OFF', layerId: 'NONE' };
  }

  if (btnQuickGibs) {
    btnQuickGibs.classList.add('active');
    btnQuickGibs.setAttribute('aria-pressed', 'true');
  }

  // Ağ duraklatılmışsa veya çevrimdışı kesinti sınaması aktifse dürüstçe bildir
  const isNetOffline = Boolean(state.allNetworkPaused || state.engineMode === 'disconnected_stale' || state.staleDisconnected);
  if (isNetOffline) {
    window.cCesiumState.activeGibsStatus = 'OFFLINE_UNAVAILABLE';
    if (gibsChipEl) {
      gibsChipEl.classList.remove('hidden');
      gibsChipEl.innerHTML = `<strong style="color:#F5A524;">🛰 Uydu Katmanı (${escapeHtml(layerMeta.titleTr)}):</strong> <span>Bağlantı duraklatıldı veya çevrimdışı — NASA GIBS karolarına ulaşılamıyor. Sahte görüntü üretilmez; çevrimdışı Natural Earth II taban haritası korunuyor.</span>`;
    }
    return { status: 'OFFLINE_UNAVAILABLE', layerId: layerMeta.id, date: effectiveDate };
  }

  if (gibsChipEl) {
    gibsChipEl.classList.remove('hidden');
    gibsChipEl.innerHTML = `<strong>🛰 Uydu Katmanı:</strong> <span>${escapeHtml(layerMeta.titleTr)} · Gözlem Tarihi: <code>${escapeHtml(effectiveDate)}</code> kontrol ediliyor...</span>`;
  }

  // Seçilen tarihte NASA GIBS WMTS sunucusunda gerçekten görüntü var mı kontrol et (Level 3, Row 3, Col 4 = Akdeniz/Ege)
  const probeUrl = `https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/${encodeURIComponent(layerMeta.id)}/default/${encodeURIComponent(effectiveDate)}/${encodeURIComponent(layerMeta.tileMatrixSetID)}/3/3/4.${layerMeta.ext}`;
  let probeOk = false;
  let httpStatus = 0;
  try {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 5500);
    const resp = await fetch(probeUrl, { method: 'GET', signal: ctrl.signal });
    clearTimeout(timer);
    httpStatus = resp.status;
    const ctype = String(resp.headers.get('content-type') || '');
    probeOk = resp.ok && ctype.startsWith('image/');
  } catch (_) {
    probeOk = false;
  }

  if (!probeOk) {
    window.cCesiumState.activeGibsStatus = httpStatus === 404 || httpStatus === 400 ? 'NO_IMAGERY_FOR_DATE' : 'FETCH_ERROR';
    if (gibsChipEl) {
      gibsChipEl.classList.remove('hidden');
      gibsChipEl.innerHTML = `<strong style="color:#F5A524;">⚠ NASA GIBS Uydu Katmanı:</strong> <span>Seçilen tarih (<code>${escapeHtml(effectiveDate)}</code>) için NASA GIBS arşivinde uydu görüntüsü bulunmuyor (${httpStatus ? 'HTTP ' + httpStatus : 'Ağ erişimi yok'}) — uydurma görüntü gösterilmez, çevrimdışı Natural Earth II taban haritası korunuyor.</span>`;
    }
    return { status: window.cCesiumState.activeGibsStatus, layerId: layerMeta.id, date: effectiveDate, httpStatus };
  }

  // Görüntü doğrulandı — Cesium WMTS katmanını ekle
  if (viewer && Cesium) {
    try {
      const wmtsProvider = new Cesium.WebMapTileServiceImageryProvider({
        url: `https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/${layerMeta.id}/default/${effectiveDate}/{TileMatrixSet}/{TileMatrix}/{TileRow}/{TileCol}.${layerMeta.ext}`,
        layer: layerMeta.id,
        style: 'default',
        format: layerMeta.format,
        tileMatrixSetID: layerMeta.tileMatrixSetID,
        maximumLevel: layerMeta.maxLevel || 8,
        credit: new Cesium.Credit(`${layerMeta.sourceName} · Gözlem Tarihi: ${effectiveDate}`)
      });
      const imgLayer = viewer.imageryLayers.addImageryProvider(wmtsProvider);
      imgLayer.alpha = 0.88;
      imgLayer.brightness = 1.04;
      window.cCesiumState.gibsImageryLayer = imgLayer;
      viewer.scene.requestRender();
    } catch (err) {
      console.warn('GIBS WMTS katmanı eklenirken hata:', err);
    }
  }

  const fetchedAtIso = new Date().toISOString().slice(0, 19).replace('T', ' ') + ' UTC';
  window.cCesiumState.activeGibsStatus = 'ACTIVE_VERIFIED';
  if (gibsChipEl) {
    gibsChipEl.classList.remove('hidden');
    gibsChipEl.innerHTML = `<strong>🛰 Uydu Katmanı:</strong> <span>${escapeHtml(layerMeta.titleTr)} · <strong>Kaynak:</strong> ${escapeHtml(layerMeta.sourceName)} · <strong>Görüntü Tarihi:</strong> <code>${escapeHtml(effectiveDate)}</code> (Günlük Uydu Mozaiği — Canlı Video Değildir) · <strong>Son Alım:</strong> <code>${fetchedAtIso}</code></span>`;
  }
  return { status: 'ACTIVE_VERIFIED', layerId: layerMeta.id, date: effectiveDate, fetchedAtIso };
}

/**
 * Earth / Nullschool (cambecc/earth) Yöntemiyle Fiziksel (u, v) Rüzgâr Vektör Alanı ve 2B Bilineer Enterpolasyon
 * Yalnızca Ege Bölgesi 6×6 (34.5°K–41.5°K, 22.5°D–30.5°D) ızgarası içinde hesaplanır; bölge dışına uydurma çizgi taşırılmaz.
 */
function buildRegionalWindFieldFromPoints(rawPoints, metaInfo = {}) {
  const nLat = AEGEAN_WIND_GRID_LATS.length;
  const nLon = AEGEAN_WIND_GRID_LONS.length;
  const gridUV = Array.from({ length: nLat }, () => Array.from({ length: nLon }, () => ({ u: 0, v: 0, speed: 0, dir: 0 })));

  let sumSpeed = 0;
  let maxSpeed = 0;
  let count = 0;

  for (let i = 0; i < nLat; i++) {
    for (let j = 0; j < nLon; j++) {
      const idx = i * nLon + j;
      const pt = rawPoints[idx] || { speed: 6.5, dir: 15 };
      const spd = Math.max(0, Number(pt.speed ?? pt.wind_speed_10m ?? 0));
      const dirDeg = Number(pt.dir ?? pt.wind_direction_10m ?? 0);
      // Meteorolojik rüzgâr yönü (rüzgârın ESTİĞİ yön, derece) -> fiziksel doğu (u) ve kuzey (v) hız bileşenleri (m/s)
      const rad = (dirDeg * Math.PI) / 180.0;
      const u = -spd * Math.sin(rad);
      const v = -spd * Math.cos(rad);
      gridUV[i][j] = {
        lat: AEGEAN_WIND_GRID_LATS[i],
        lon: AEGEAN_WIND_GRID_LONS[j],
        u,
        v,
        speed: spd,
        dir: dirDeg
      };
      sumSpeed += spd;
      if (spd > maxSpeed) maxSpeed = spd;
      count++;
    }
  }

  return {
    latMin: AEGEAN_WIND_GRID_LATS[0],
    latMax: AEGEAN_WIND_GRID_LATS[nLat - 1],
    lonMin: AEGEAN_WIND_GRID_LONS[0],
    lonMax: AEGEAN_WIND_GRID_LONS[nLon - 1],
    lats: AEGEAN_WIND_GRID_LATS,
    lons: AEGEAN_WIND_GRID_LONS,
    gridUV,
    meanSpeedMs: count > 0 ? +(sumSpeed / count).toFixed(1) : 0,
    maxSpeedMs: +maxSpeed.toFixed(1),
    pointCount: count,
    sourceName: metaInfo.sourceName || 'Open-Meteo Bölgesel Model Izgarası (6×6 = 36 Nokta · 10m Rüzgâr)',
    modelTimeIso: metaInfo.modelTimeIso || '2026-04-05T12:00Z',
    fetchedAtIso: metaInfo.fetchedAtIso || new Date().toISOString(),
    isLiveOpenMeteo: Boolean(metaInfo.isLiveOpenMeteo)
  };
}

function bilinearInterpolateRegionalWind(field, lat, lon) {
  if (!field || !field.gridUV) return null;
  if (lat < field.latMin || lat > field.latMax || lon < field.lonMin || lon > field.lonMax) {
    return null; // Bölgesel ızgara sınırları dışında rüzgâr verisi uydurulmaz!
  }
  const lats = field.lats;
  const lons = field.lons;
  const nLat = lats.length;
  const nLon = lons.length;

  let i0 = 0;
  for (let i = 0; i < nLat - 1; i++) {
    if (lat >= lats[i] && lat <= lats[i + 1]) {
      i0 = i;
      break;
    }
  }
  let j0 = 0;
  for (let j = 0; j < nLon - 1; j++) {
    if (lon >= lons[j] && lon <= lons[j + 1]) {
      j0 = j;
      break;
    }
  }
  const i1 = Math.min(nLat - 1, i0 + 1);
  const j1 = Math.min(nLon - 1, j0 + 1);

  const ty = lats[i1] > lats[i0] ? (lat - lats[i0]) / (lats[i1] - lats[i0]) : 0;
  const tx = lons[j1] > lons[j0] ? (lon - lons[j0]) / (lons[j1] - lons[j0]) : 0;

  const c00 = field.gridUV[i0][j0];
  const c10 = field.gridUV[i0][j1];
  const c01 = field.gridUV[i1][j0];
  const c11 = field.gridUV[i1][j1];

  const u0 = c00.u * (1 - tx) + c10.u * tx;
  const u1 = c01.u * (1 - tx) + c11.u * tx;
  const u = u0 * (1 - ty) + u1 * ty;

  const v0 = c00.v * (1 - tx) + c10.v * tx;
  const v1 = c01.v * (1 - tx) + c11.v * tx;
  const v = v0 * (1 - ty) + v1 * ty;

  const speed = Math.hypot(u, v);
  return { u, v, speed };
}

function windSpeedToColorCss(speedMs, alpha = 0.86) {
  if (speedMs >= 14.0) return `rgba(248, 113, 113, ${alpha})`; // Kuvvetli fırtına (>14 m/s)
  if (speedMs >= 9.5) return `rgba(245, 165, 36, ${alpha})`;   // Kuvvetli rüzgâr (9.5-14 m/s)
  if (speedMs >= 5.5) return `rgba(61, 214, 140, ${alpha})`;   // Orta rüzgâr (5.5-9.5 m/s)
  return `rgba(88, 196, 255, ${alpha})`;                       // Hafif-orta esinti (<5.5 m/s)
}

async function fetchAegeanRegionalWindGrid() {
  const isNetOffline = Boolean(state.allNetworkPaused || state.engineMode === 'disconnected_stale' || state.staleDisconnected);
  if (!isNetOffline) {
    try {
      const latPairs = [];
      const lonPairs = [];
      for (const la of AEGEAN_WIND_GRID_LATS) {
        for (const lo of AEGEAN_WIND_GRID_LONS) {
          latPairs.push(la.toFixed(2));
          lonPairs.push(lo.toFixed(2));
        }
      }
      const url = `https://api.open-meteo.com/v1/forecast?latitude=${latPairs.join(',')}&longitude=${lonPairs.join(',')}&current=wind_speed_10m,wind_direction_10m&wind_speed_unit=ms&timezone=UTC`;
      const ctrl = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), 6500);
      const resp = await fetch(url, { signal: ctrl.signal });
      clearTimeout(timer);
      if (resp.ok) {
        const arr = await resp.json();
        if (Array.isArray(arr) && arr.length === 36) {
          const pts = arr.map(item => ({
            speed: Number(item?.current?.wind_speed_10m ?? 0),
            dir: Number(item?.current?.wind_direction_10m ?? 0)
          }));
          const modelTime = arr[0]?.current?.time ? `${arr[0].current.time}:00Z` : new Date().toISOString();
          return buildRegionalWindFieldFromPoints(pts, {
            sourceName: 'Open-Meteo Forecast API (Canlı 6×6 Ege Bölgesel Model Izgarası · 10m Rüzgâr)',
            modelTimeIso: modelTime,
            fetchedAtIso: new Date().toISOString(),
            isLiveOpenMeteo: true
          });
        }
      }
    } catch (_) {}
  }

  return buildRegionalWindFieldFromPoints(RECORDED_2020_AEGEAN_WIND_GRID_FALLBACK, {
    sourceName: 'Kayıtlı 30 Ekim 2020 Ege ERA5 Bölgesel Arşiv Izgarası (6×6 = 36 Nokta · Çevrimdışı Yedek)',
    modelTimeIso: '2020-10-30T12:00:00Z',
    fetchedAtIso: 'Yerel Arşiv Kaydı',
    isLiveOpenMeteo: false
  });
}

function renderCesiumRegionalWindEntities(field) {
  const viewer = window.cCesiumState && window.cCesiumState.viewer;
  const Cesium = window.Cesium;
  if (!viewer || !Cesium) return;

  // Önceki rüzgâr varlıklarını temizle
  if (Array.isArray(window.cCesiumState.windEntities)) {
    window.cCesiumState.windEntities.forEach(ent => {
      try { viewer.entities.remove(ent); } catch (_) {}
    });
  }
  window.cCesiumState.windEntities = [];

  if (!field || window.cCesiumState.windDensity === 'OFF') {
    viewer.scene.requestRender();
    return;
  }

  // 1. Bölgesel Rüzgâr Izgarası Sınır Çerçevesi (Küresel rüzgâr olmadığını açıkça gösterir: 34.5°K–41.5°K, 22.5°D–30.5°D)
  const bboxEnt = viewer.entities.add({
    name: 'Ege Bölgesel Rüzgâr Izgarası Sınırı (6×6)',
    polyline: {
      positions: Cesium.Cartesian3.fromDegreesArrayHeights([
        field.lonMin, field.latMin, 1200,
        field.lonMax, field.latMin, 1200,
        field.lonMax, field.latMax, 1200,
        field.lonMin, field.latMax, 1200,
        field.lonMin, field.latMin, 1200
      ]),
      width: 2.0,
      material: new Cesium.PolylineDashMaterialProperty({
        color: Cesium.Color.fromCssColorString('#5EC69D').withAlpha(0.75),
        dashLength: 14.0
      })
    }
  });
  window.cCesiumState.windEntities.push(bboxEnt);

  // 2. 36 Izgara Noktasında Fiziksel (u, v) Rüzgâr Yön ve Şiddet Vektör Okları
  for (let i = 0; i < field.lats.length; i++) {
    for (let j = 0; j < field.lons.length; j++) {
      const cell = field.gridUV[i][j];
      const scaleDeg = 0.065 * Math.max(2.5, Math.min(14.0, cell.speed));
      const endLon = cell.lon + (cell.u / Math.max(1, cell.speed)) * scaleDeg * 1.25;
      const endLat = cell.lat + (cell.v / Math.max(1, cell.speed)) * scaleDeg;
      const colCss = windSpeedToColorCss(cell.speed, 0.92);

      const arrowEnt = viewer.entities.add({
        polyline: {
          positions: Cesium.Cartesian3.fromDegreesArrayHeights([
            cell.lon, cell.lat, 1800,
            endLon, endLat, 1800
          ]),
          width: 6.5,
          material: new Cesium.PolylineArrowMaterialProperty(Cesium.Color.fromCssColorString(colCss))
        }
      });
      window.cCesiumState.windEntities.push(arrowEnt);
    }
  }
  viewer.scene.requestRender();
}

async function initAndRunRegionalWindLayer(densityModeInput, options = {}) {
  let mode = String(densityModeInput || 'OFF').toUpperCase();
  const forceReduced = Boolean(
    (state.uiPrefs && state.uiPrefs.animLevel === 'off') ||
    (options.respectReducedMotion && isReducedMotionPreferred())
  );
  if (mode !== 'OFF' && forceReduced) {
    mode = 'STATIC';
  }
  window.cCesiumState.windDensity = mode;

  const selWind = document.getElementById('sel-dunyam-wind-density');
  if (selWind && selWind.value !== mode) selWind.value = mode;

  const btnQuickWind = document.getElementById('btn-stage-toggle-wind');
  const windCanvas = document.getElementById('dunyam-wind-canvas');
  const windChipEl = document.getElementById('dunyam-wind-attribution-line');

  if (window.cCesiumState.windAnimReqId) {
    cancelAnimationFrame(window.cCesiumState.windAnimReqId);
    window.cCesiumState.windAnimReqId = null;
  }

  if (mode === 'OFF') {
    if (btnQuickWind) {
      btnQuickWind.classList.remove('active');
      btnQuickWind.setAttribute('aria-pressed', 'false');
    }
    if (windCanvas) {
      const ctx = windCanvas.getContext('2d');
      if (ctx) ctx.clearRect(0, 0, windCanvas.width, windCanvas.height);
      windCanvas.classList.add('hidden');
    }
    if (windChipEl) {
      windChipEl.classList.add('hidden');
      windChipEl.innerHTML = '';
    }
    renderCesiumRegionalWindEntities(null);
    return { status: 'OFF' };
  }

  if (btnQuickWind) {
    btnQuickWind.classList.add('active');
    btnQuickWind.setAttribute('aria-pressed', 'true');
  }

  if (windChipEl) {
    windChipEl.classList.remove('hidden');
    windChipEl.innerHTML = `<strong>💨 Bölgesel Rüzgâr Alanı:</strong> <span>Open-Meteo 6×6 Ege vektör ızgarası yükleniyor...</span>`;
  }

  if (!window.cCesiumState.windFieldGrid) {
    window.cCesiumState.windFieldGrid = await fetchAegeanRegionalWindGrid();
  }
  const field = window.cCesiumState.windFieldGrid;

  // Rüzgâr katmanı açıldığında kamerayı Ege bölgesine odakla ki 6×6 bölgesel ızgara net görünsün
  flyCesiumToAegeanRegion(1.0);
  renderCesiumRegionalWindEntities(field);

  const fetchedShort = String(field.fetchedAtIso || '').slice(0, 19).replace('T', ' ');
  const modelTimeShort = String(field.modelTimeIso || '').slice(0, 16).replace('T', ' ');
  if (windChipEl) {
    windChipEl.classList.remove('hidden');
    windChipEl.innerHTML = `<strong>💨 Rüzgâr Katmanı:</strong> <span>${escapeHtml(field.sourceName)} · <strong>Kapsam:</strong> <code>34.5°–41.5°K, 22.5°–30.5°D</code> (Yalnızca Ege Bölgesi — Küresel Rüzgâr Değildir) · <strong>Ort / Maks:</strong> <code>${field.meanSpeedMs} / ${field.maxSpeedMs} m/s</code> · <strong>Model Zamanı:</strong> <code>${escapeHtml(modelTimeShort)}</code> · <strong>Alım:</strong> <code>${escapeHtml(fetchedShort)}</code>${mode === 'STATIC' ? ' · <em>[Hareket Azaltma: Sabit Yön Okları]</em>' : ''}</span>`;
  }

  if (!windCanvas) return { status: mode, field };
  windCanvas.classList.remove('hidden');

  if (mode === 'STATIC') {
    const ctx = windCanvas.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, windCanvas.width, windCanvas.height);
    return { status: 'STATIC', field };
  }

  const particleCounts = { LOW: 120, NORMAL: 260, HIGH: 450 };
  const targetCount = particleCounts[mode] || 260;

  const spawnParticle = () => ({
    lat: field.latMin + Math.random() * (field.latMax - field.latMin),
    lon: field.lonMin + Math.random() * (field.lonMax - field.lonMin),
    age: Math.floor(Math.random() * 75),
    maxAge: 65 + Math.floor(Math.random() * 45)
  });

  window.cCesiumState.windParticles = Array.from({ length: targetCount }, spawnParticle);

  const stepWindAnimation = () => {
    if (window.cCesiumState.windDensity === 'OFF' || window.cCesiumState.windDensity === 'STATIC') return;
    const viewer = window.cCesiumState.viewer;
    const Cesium = window.Cesium;
    if (!viewer || !Cesium || !windCanvas) return;

    const rect = windCanvas.getBoundingClientRect();
    const w = Math.max(300, Math.round(rect.width || 960));
    const h = Math.max(200, Math.round(rect.height || 540));
    if (windCanvas.width !== w || windCanvas.height !== h) {
      windCanvas.width = w;
      windCanvas.height = h;
    }

    const ctx = windCanvas.getContext('2d');
    // Earth / Nullschool tarzı iz bırakarak sönümlenen akış çizgileri (trail fade)
    ctx.save();
    ctx.globalCompositeOperation = 'destination-in';
    ctx.fillStyle = 'rgba(0, 0, 0, 0.91)';
    ctx.fillRect(0, 0, w, h);
    ctx.restore();

    ctx.save();
    ctx.lineWidth = 1.75;
    ctx.lineCap = 'round';

    const particles = window.cCesiumState.windParticles;
    const scene = viewer.scene;

    for (let pIdx = 0; pIdx < particles.length; pIdx++) {
      const p = particles[pIdx];
      if (p.age >= p.maxAge) {
        Object.assign(p, spawnParticle());
        p.age = 0;
      }

      const wind = bilinearInterpolateRegionalWind(field, p.lat, p.lon);
      if (!wind) {
        Object.assign(p, spawnParticle());
        p.age = 0;
        continue;
      }

      // 1 adım adveksiyon (Earth/Nullschool u,v -> derece/kare)
      const dtDeg = 0.0038;
      const cosLat = Math.max(0.4, Math.cos((p.lat * Math.PI) / 180));
      const nextLon = p.lon + (wind.u * dtDeg) / cosLat;
      const nextLat = p.lat + wind.v * dtDeg;

      if (nextLat < field.latMin || nextLat > field.latMax || nextLon < field.lonMin || nextLon > field.lonMax) {
        Object.assign(p, spawnParticle());
        p.age = 0;
        continue;
      }

      const pos0 = Cesium.Cartesian3.fromDegrees(p.lon, p.lat, 800.0);
      const pos1 = Cesium.Cartesian3.fromDegrees(nextLon, nextLat, 800.0);
      const win0 = Cesium.SceneTransforms.wgs84ToWindowCoordinates(scene, pos0);
      const win1 = Cesium.SceneTransforms.wgs84ToWindowCoordinates(scene, pos1);

      if (win0 && win1 && win0.x >= 0 && win0.x <= w && win0.y >= 0 && win0.y <= h) {
        ctx.strokeStyle = windSpeedToColorCss(wind.speed, 0.88);
        ctx.beginPath();
        ctx.moveTo(win0.x, win0.y);
        ctx.lineTo(win1.x, win1.y);
        ctx.stroke();
      }

      p.lon = nextLon;
      p.lat = nextLat;
      p.age++;
    }
    ctx.restore();

    window.cCesiumState.windAnimReqId = requestAnimationFrame(stepWindAnimation);
  };

  window.cCesiumState.windAnimReqId = requestAnimationFrame(stepWindAnimation);
  return { status: mode, field };
}

async function fetchLiveOpenMeteoToUnifiedLedger(locMeta = {}) {
  const api = getUnifiedLedgerApi();
  let ledger = ensureUnifiedRealWorldLedger();
  if (!api || !ledger) return null;

  const loc = {
    id: locMeta.id || 'aegean_izmir_bay',
    labelTr: locMeta.labelTr || 'İzmir Körfezi ve Liman Yaklaşım Koridoru (Ege)',
    lat: Number(locMeta.lat ?? 38.44),
    lon: Number(locMeta.lon ?? 27.15)
  };
  const isNetOffline = Boolean(state.allNetworkPaused || state.engineMode === 'disconnected_stale' || state.staleDisconnected);
  const nowIso = new Date().toISOString();

  if (isNetOffline) {
    const offRes = api.markSourceOfflineOrStale(ledger, 'open_meteo_weather_marine', {
      nowIso,
      errorMessage: 'Kaynağa ulaşılamıyor (Ağ duraklatıldı veya çevrimdışı).'
    });
    window.cUnifiedRealWorldLedger = offRes.ledger;
    persistUnifiedRealWorldLedger();
    return offRes;
  }

  try {
    const sc = window.CaelusScenarioCompiler;
    const eps = sc && typeof sc.buildOpenMeteoEndpoints === 'function'
      ? sc.buildOpenMeteoEndpoints(loc.lat, loc.lon)
      : {
          weatherUrl: `https://api.open-meteo.com/v1/forecast?latitude=${loc.lat}&longitude=${loc.lon}&current=temperature_2m,wind_speed_10m,wind_direction_10m,wind_gusts_10m,precipitation,surface_pressure&timezone=UTC`,
          marineUrl: `https://marine-api.open-meteo.com/v1/marine?latitude=${loc.lat}&longitude=${loc.lon}&current=wave_height,wave_direction,wave_period&timezone=UTC`
        };

    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 5500);
    const [wRes, mRes] = await Promise.all([
      fetch(eps.weatherUrl, { signal: ctrl.signal }),
      fetch(eps.marineUrl, { signal: ctrl.signal }).catch(() => null)
    ]);
    clearTimeout(timer);

    if (wRes && wRes.ok) {
      const wJson = await wRes.json();
      const mJson = (mRes && mRes.ok) ? await mRes.json() : { current: { wave_height: 0.9, wave_direction: 330, wave_period: 5.0 } };
      const ing = api.ingestOpenMeteoToLedger(ledger, wJson, mJson, loc, { nowIso });
      if (ing && ing.ledger) {
        window.cUnifiedRealWorldLedger = ing.ledger;
        persistUnifiedRealWorldLedger();
        return ing;
      }
    }
    const offRes = api.markSourceOfflineOrStale(ledger, 'open_meteo_weather_marine', {
      nowIso,
      errorMessage: 'Kaynağa ulaşılamıyor (Open-Meteo HTTP yanıtı alınamadı).'
    });
    window.cUnifiedRealWorldLedger = offRes.ledger;
    persistUnifiedRealWorldLedger();
    return offRes;
  } catch (err) {
    const offRes = api.markSourceOfflineOrStale(ledger, 'open_meteo_weather_marine', {
      nowIso,
      errorMessage: 'Kaynağa ulaşılamıyor (' + String(err?.message || 'bağlantı hatası') + ').'
    });
    window.cUnifiedRealWorldLedger = offRes.ledger;
    persistUnifiedRealWorldLedger();
    return offRes;
  }
}

function focusLedgerRecordOnGlobeAndMemory(recordId) {
  const ledger = ensureUnifiedRealWorldLedger();
  if (!ledger || !Array.isArray(ledger.records)) return;
  const rec = ledger.records.find(r => r && r.recordId === recordId);
  if (!rec) return;

  switchQuietView('dunyam');
  const markerId = `LEDGER_${rec.recordId}`;
  if (window.cCesiumState && window.cCesiumState.markerRegistry && window.cCesiumState.markerRegistry.has(markerId)) {
    selectCesiumGlobeMarkerById(markerId, { flyTo: true });
  } else if (window.cCesiumState && window.cCesiumState.viewer && window.Cesium && rec.location) {
    window.cCesiumState.viewer.camera.flyTo({
      destination: window.Cesium.Cartesian3.fromDegrees(Number(rec.location.lon || 27.15), Number(rec.location.lat || 38.44), 1150000.0),
      duration: 1.1
    });
  }
}
window.focusLedgerRecordOnGlobeAndMemory = focusLedgerRecordOnGlobeAndMemory;

/**
 * Gerçek USGS Deprem Olaylarını ve Örnek/Senaryo Konumlarını 3B Dünya Üzerine İşler.
 * Gerçek açık veri (USGS GeoJSON) ile örnek/senaryo verisi (DUNYAM_GEO_LOCATIONS) hem görsel hem metinsel olarak ayrılır.
 */
async function loadAndRenderRealGlobeEvents(options = {}) {
  const api = getUnifiedLedgerApi();
  let ledger = ensureUnifiedRealWorldLedger();
  const isNetOffline = Boolean(state.allNetworkPaused || state.engineMode === 'disconnected_stale' || state.staleDisconnected);
  const allowExternalNetwork = Boolean(options && options.allowExternalNetwork);
  const fetchIso = new Date().toISOString();

  if (!isNetOffline && allowExternalNetwork && api) {
    try {
      const ctrl = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), 6000);
      const sourceUrl = 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/4.5_week.geojson';
      const resp = await fetch(sourceUrl, { signal: ctrl.signal });
      clearTimeout(timer);
      if (resp.ok) {
        const geo = await resp.json();
        const feats = Array.isArray(geo?.features) ? geo.features : [];
        window.cCesiumState.lastUsgsFetchIso = fetchIso;
        window.cCesiumState.usgsSourceStatus = 'LIVE_USGS_GEOJSON';

        // Akdeniz/Ege/Avrasya öncelikli olmak üzere en güncel 14 gerçek depremi seç
        const sortedFeats = feats.slice().sort((a, b) => {
          const [lonA, latA] = a?.geometry?.coordinates || [0, 0];
          const [lonB, latB] = b?.geometry?.coordinates || [0, 0];
          const inMedA = (latA >= 25 && latA <= 48 && lonA >= 10 && lonA <= 45) ? 1 : 0;
          const inMedB = (latB >= 25 && latB <= 48 && lonB >= 10 && lonB <= 45) ? 1 : 0;
          if (inMedA !== inMedB) return inMedB - inMedA;
          return Number(b?.properties?.mag || 0) - Number(a?.properties?.mag || 0);
        });

        const subsetGeo = {
          type: 'FeatureCollection',
          metadata: geo.metadata || {},
          features: sortedFeats.slice(0, 14)
        };
        const ing = api.ingestUsgsGeoJsonToLedger(ledger, subsetGeo, {
          nowIso: fetchIso,
          sourceUrl,
          maxFeatures: 14
        });
        if (ing && ing.ledger) {
          ledger = ing.ledger;
          window.cUnifiedRealWorldLedger = ledger;
          persistUnifiedRealWorldLedger();
        }
      } else {
        window.cCesiumState.usgsSourceStatus = 'ARCHIVE_FALLBACK';
        const off = api.markSourceOfflineOrStale(ledger, 'usgs_earthquake_feed', {
          nowIso: fetchIso,
          errorMessage: `Kaynağa ulaşılamıyor (USGS HTTP ${resp.status}).`
        });
        ledger = off.ledger;
        window.cUnifiedRealWorldLedger = ledger;
        persistUnifiedRealWorldLedger();
      }
    } catch (err) {
      window.cCesiumState.usgsSourceStatus = 'ARCHIVE_FALLBACK';
      if (api) {
        const off = api.markSourceOfflineOrStale(ledger, 'usgs_earthquake_feed', {
          nowIso: fetchIso,
          errorMessage: 'Kaynağa ulaşılamıyor (USGS ağ zaman aşımı veya çevrimdışı).'
        });
        ledger = off.ledger;
        window.cUnifiedRealWorldLedger = ledger;
        persistUnifiedRealWorldLedger();
      }
    }
    // Eşzamanlı olarak Open-Meteo bölgesel hava/deniz verisini de birleşik yerel hafızaya al
    await fetchLiveOpenMeteoToUnifiedLedger();
    ledger = window.cUnifiedRealWorldLedger || ledger;
  } else if (isNetOffline && api && ledger) {
    window.cCesiumState.usgsSourceStatus = 'ARCHIVE_FALLBACK';
    const off1 = api.markSourceOfflineOrStale(ledger, 'usgs_earthquake_feed', {
      nowIso: fetchIso,
      errorMessage: 'Kaynağa ulaşılamıyor (Çevrimdışı / Bağlantı duraklatıldı).'
    });
    const off2 = api.markSourceOfflineOrStale(off1.ledger, 'open_meteo_weather_marine', {
      nowIso: fetchIso,
      errorMessage: 'Kaynağa ulaşılamıyor (Çevrimdışı / Bağlantı duraklatıldı).'
    });
    ledger = off2.ledger;
    window.cUnifiedRealWorldLedger = ledger;
    persistUnifiedRealWorldLedger();
  } else {
    window.cCesiumState.usgsSourceStatus = 'LOCAL_ARCHIVE_READY';
  }

  const quakeRecords = (ledger && Array.isArray(ledger.records))
    ? ledger.records.filter(r => r && r.sourceId === 'usgs_earthquake_feed')
    : [];

  window.cCesiumState.realUsgsEvents = quakeRecords.slice(0, 16).map(rec => {
    const mag = Number(rec.parsedFields?.magnitude ?? 5.0);
    const place = String(rec.location?.placeLabel || rec.titleTr || 'Sismik Gözlem');
    const isStale = rec.connectionStatus === 'OFFLINE' || rec.connectionStatus === 'STALE';
    return {
      id: `LEDGER_${rec.recordId}`,
      ledgerRecordId: rec.recordId,
      externalEventId: rec.externalEventId,
      title: rec.titleTr || `M${mag.toFixed(1)} — ${place}`,
      shortLabel: `M${mag.toFixed(1)} ${place.replace(/^\d+\s*km\s+[A-Z]+\s+of\s+/i, '').slice(0, 22)}`,
      lat: Number(rec.location?.lat ?? 38.0),
      lon: Number(rec.location?.lon ?? 27.0),
      depthKm: Number(rec.location?.depthKm ?? rec.parsedFields?.depthKm ?? 10.0),
      mag,
      category: 'SEISMIC_ENV',
      categoryLabelTr: isStale ? 'Deprem (Son bilinen veri · USGS)' : 'Deprem (Gerçek gözlem · USGS)',
      epistemicLabelTr: rec.freshnessLabelTr || rec.epistemicLabelTr || 'Gerçek gözlem',
      isRealData: true,
      sourceName: `${rec.sourceName} (${rec.connectionStatusLabelTr || 'Bağlı'})`,
      eventTimeIso: rec.occurrenceTimeIso,
      ingestedAtIso: rec.ingestedAtIso
    };
  });

  syncCesiumSceneWithCaelusState(true);
  if (typeof renderHafizaStreamWorkspace === 'function') renderHafizaStreamWorkspace();
  if (typeof renderBaglantilarCleanWorkspace === 'function') renderBaglantilarCleanWorkspace();
  return window.cCesiumState.realUsgsEvents;
}

function syncCesiumSceneWithCaelusState(forceRebuild = false) {
  const viewer = window.cCesiumState && window.cCesiumState.viewer;
  const Cesium = window.Cesium;
  if (!viewer || !Cesium) return;

  const aw = typeof getActiveDigitalWorld === 'function' ? getActiveDigitalWorld() : null;
  const hasGeo = worldHasGeographicCoords(state.scenarioMeta.scenarioId, aw);
  const catFilter = state.dunyamGlobeCatFilter || 'ALL';
  const selMarkerId = window.cCesiumState.selectedMarkerId || 'GEO_IZMIR_ALSANCAK';
  const audited = (state.lastEvaluation && state.lastEvaluation.dataIntegrity && state.lastEvaluation.dataIntegrity.auditedNodes) || [];
  const maxLoadPct = audited.reduce((m, n) => Math.max(m, Number(n.realLoadPct) || 0), 0);
  const usgsCount = Array.isArray(window.cCesiumState.realUsgsEvents) ? window.cCesiumState.realUsgsEvents.length : 0;

  const stateSig = `${state.scenarioMeta.scenarioId}|${hasGeo}|${window.cCesiumState.showEventsLayer}|${catFilter}|${selMarkerId}|${Math.round(maxLoadPct)}|${usgsCount}`;
  if (!forceRebuild && window.cCesiumState._lastSyncSig === stateSig && window.cCesiumState.markerRegistry.size > 0) {
    return;
  }
  window.cCesiumState._lastSyncSig = stateSig;

  // Önceki olay/konum varlıklarını temizle
  if (Array.isArray(window.cCesiumState.eventEntities)) {
    window.cCesiumState.eventEntities.forEach(ent => {
      try { viewer.entities.remove(ent); } catch (_) {}
    });
  }
  window.cCesiumState.eventEntities = [];
  window.cCesiumState.markerRegistry.clear();

  if (!hasGeo || !window.cCesiumState.showEventsLayer) {
    viewer.scene.requestRender();
    return;
  }

  // 1. Ege Deniz Koridoru Jeodezik Bağlantı Çizgileri
  if (catFilter === 'ALL' || catFilter === 'PROCESS_INFRA' || catFilter === 'WEATHER_MARINE') {
    const locMap = {};
    DUNYAM_GEO_LOCATIONS.forEach(l => { locMap[l.key] = l; });
    const pairs = [
      ['KUZEY_EGE_ACIK', 'ALIAGA_NEMRUT'],
      ['ALIAGA_NEMRUT', 'IZMIR_ALSANCAK'],
      ['IZMIR_ALSANCAK', 'CESME_BOGAZI'],
      ['CESME_BOGAZI', 'BODRUM_GULLUK'],
      ['CESME_BOGAZI', 'PIRE_KORIDORU']
    ];
    pairs.forEach(([kA, kB]) => {
      const a = locMap[kA];
      const b = locMap[kB];
      if (!a || !b) return;
      const lineEnt = viewer.entities.add({
        polyline: {
          positions: Cesium.Cartesian3.fromDegreesArrayHeights([a.lon, a.lat, 900, b.lon, b.lat, 900]),
          width: 2.2,
          material: Cesium.Color.fromCssColorString('#38BDF8').withAlpha(0.55)
        }
      });
      window.cCesiumState.eventEntities.push(lineEnt);
    });
  }

  // 2. Örnek / Senaryo Dünyası Coğrafi Konumları (DUNYAM_GEO_LOCATIONS)
  DUNYAM_GEO_LOCATIONS.forEach(loc => {
    if (catFilter === 'SEISMIC_ENV') return;
    if (catFilter === 'PROCESS_INFRA' && !loc.isPrimaryPort) return;
    if (catFilter === 'WEATHER_MARINE' && loc.isPrimaryPort) return;

    const markerId = `GEO_${loc.key}`;
    const isSel = selMarkerId === markerId;
    const colorHex = loc.isPrimaryPort
      ? (maxLoadPct >= 80 ? '#F87171' : maxLoadPct >= 55 ? '#F5A524' : '#3DD68C')
      : '#38BDF8';

    const rwStore = aw && aw.realWorldDataStore ? aw.realWorldDataStore : null;
    const hasLiveOm = Boolean(loc.isPrimaryPort && rwStore && rwStore.latestValidTimeIso);

    const markerObj = {
      markerId,
      geoKey: loc.key,
      title: loc.label,
      shortLabel: loc.shortLabel,
      lat: loc.lat,
      lon: loc.lon,
      category: loc.isPrimaryPort ? 'PROCESS_INFRA' : 'WEATHER_MARINE',
      categoryLabelTr: loc.isPrimaryPort ? 'Liman ve Süreç Noktası (Örnek/Senaryo Konumu)' : 'Deniz Koridoru Gözlem Noktası (Örnek Konum)',
      isRealData: hasLiveOm,
      sourceName: hasLiveOm
        ? 'Open-Meteo Weather & Marine API + Örnek Liman Süreç Modeli'
        : 'Örnek Senaryo Konumu (EX-01_LIMAN_SOGUK_ZINCIR · Doğrulanmış Koordinat)',
      eventTimeIso: hasLiveOm ? rwStore.latestValidTimeIso : '2026-04-06T08:00:00Z (Statik Senaryo Başlangıcı)',
      ingestedAtIso: hasLiveOm ? (rwStore.lastIngestedAtIso || rwStore.latestValidTimeIso) : 'Yerel Örnek Model Kaydı',
      regionLabel: loc.region,
      isPrimaryPort: loc.isPrimaryPort
    };
    window.cCesiumState.markerRegistry.set(markerId, markerObj);

    const corridorOffsets = {
      IZMIR_ALSANCAK: [0, -26],
      ALIAGA_NEMRUT: [58, -32],
      CESME_BOGAZI: [-62, 22],
      KUZEY_EGE_ACIK: [-54, -36],
      BODRUM_GULLUK: [62, 24],
      PIRE_KORIDORU: [-66, -10]
    };
    const [offX, offY] = isSel ? [0, -28] : (corridorOffsets[loc.key] || [0, -20]);
    const showCorridorLabelDist = isSel ? 24000000.0 : (loc.isPrimaryPort ? 7500000.0 : 2300000.0);

    const ent = viewer.entities.add({
      position: Cesium.Cartesian3.fromDegrees(loc.lon, loc.lat, 1500),
      billboard: {
        image: buildMarkerPinCanvas(colorHex, isSel, false),
        width: isSel ? 34 : 26,
        height: isSel ? 34 : 26,
        verticalOrigin: Cesium.VerticalOrigin.CENTER
      },
      label: {
        text: isSel ? `[ÖRNEK KONUM] ${loc.shortLabel} (${loc.lat.toFixed(2)}°K, ${loc.lon.toFixed(2)}°D)` : loc.shortLabel,
        font: isSel ? '700 12px "Inter", "Segoe UI", sans-serif' : '600 11px "Inter", "Segoe UI", sans-serif',
        fillColor: Cesium.Color.fromCssColorString('#F8FAFC'),
        outlineColor: Cesium.Color.fromCssColorString('#030712'),
        outlineWidth: 3,
        style: Cesium.LabelStyle.FILL_AND_OUTLINE,
        pixelOffset: new Cesium.Cartesian2(offX, offY),
        showBackground: true,
        backgroundColor: Cesium.Color.fromCssColorString(isSel ? '#0284C7' : '#060C1A').withAlpha(isSel ? 0.92 : 0.82),
        backgroundPadding: new Cesium.Cartesian2(7, 4),
        distanceDisplayCondition: new Cesium.DistanceDisplayCondition(0.0, showCorridorLabelDist)
      }
    });
    ent.caelusMarkerId = markerId;
    window.cCesiumState.eventEntities.push(ent);
  });

  // 3. Gerçek USGS Deprem Olayları (GERÇEK AÇIK VERİ)
  if (catFilter === 'ALL' || catFilter === 'SEISMIC_ENV') {
    (window.cCesiumState.realUsgsEvents || []).forEach((ev, evIdx) => {
      const markerId = ev.id;
      const isSel = selMarkerId === markerId;
      const colorHex = ev.mag >= 6.0 ? '#F87171' : '#F5A524';

      const markerObj = {
        markerId,
        ledgerRecordId: ev.ledgerRecordId || null,
        externalEventId: ev.externalEventId || null,
        title: ev.title,
        shortLabel: ev.shortLabel,
        lat: ev.lat,
        lon: ev.lon,
        depthKm: ev.depthKm,
        mag: ev.mag,
        category: 'SEISMIC_ENV',
        categoryLabelTr: ev.categoryLabelTr,
        epistemicLabelTr: ev.epistemicLabelTr || 'Gerçek gözlem',
        isRealData: true,
        sourceName: ev.sourceName,
        eventTimeIso: ev.eventTimeIso,
        ingestedAtIso: ev.ingestedAtIso
      };
      window.cCesiumState.markerRegistry.set(markerId, markerObj);

      const inAegeanBox = ev.lat >= 35.5 && ev.lat <= 41.0 && ev.lon >= 23.0 && ev.lon <= 28.5;
      const eqOffY = isSel ? 28 : (inAegeanBox ? 24 + (evIdx % 2) * 18 : -20);
      const eqMaxDist = isSel ? 24000000.0 : (evIdx === 0 || !inAegeanBox ? 6800000.0 : 2200000.0);

      const ent = viewer.entities.add({
        position: Cesium.Cartesian3.fromDegrees(ev.lon, ev.lat, 2000),
        billboard: {
          image: buildMarkerPinCanvas(colorHex, isSel, true),
          width: isSel ? 38 : 28,
          height: isSel ? 38 : 28,
          verticalOrigin: Cesium.VerticalOrigin.CENTER
        },
        label: {
          text: isSel ? `[GERÇEK VERİ · USGS] ${ev.shortLabel}` : ev.shortLabel,
          font: isSel ? '700 12px "JetBrains Mono", monospace' : '600 10.5px "JetBrains Mono", monospace',
          fillColor: Cesium.Color.fromCssColorString('#FEF08A'),
          outlineColor: Cesium.Color.fromCssColorString('#030712'),
          outlineWidth: 3,
          style: Cesium.LabelStyle.FILL_AND_OUTLINE,
          pixelOffset: new Cesium.Cartesian2(0, eqOffY),
          showBackground: true,
          backgroundColor: Cesium.Color.fromCssColorString(isSel ? '#991B1B' : '#1E1B18').withAlpha(0.90),
          backgroundPadding: new Cesium.Cartesian2(7, 4),
          distanceDisplayCondition: new Cesium.DistanceDisplayCondition(0.0, eqMaxDist)
        }
      });
      ent.caelusMarkerId = markerId;
      window.cCesiumState.eventEntities.push(ent);
    });
  }

  viewer.scene.requestRender();
}

function selectCesiumGlobeMarkerById(markerId, options = {}) {
  let rec = window.cCesiumState.markerRegistry.get(markerId);
  if (!rec && Array.isArray(DUNYAM_GEO_LOCATIONS)) {
    const loc = DUNYAM_GEO_LOCATIONS.find(l => `GEO_${l.key}` === markerId || l.key === markerId) || DUNYAM_GEO_LOCATIONS[0];
    if (loc) {
      rec = {
        markerId: `GEO_${loc.key}`,
        geoKey: loc.key,
        title: loc.label,
        shortLabel: loc.shortLabel,
        lat: loc.lat,
        lon: loc.lon,
        category: loc.isPrimaryPort ? 'PROCESS_INFRA' : 'WEATHER_MARINE',
        categoryLabelTr: loc.isPrimaryPort ? 'Liman ve Süreç Noktası (Örnek/Senaryo Konumu)' : 'Deniz Koridoru Gözlem Noktası (Örnek Konum)',
        isRealData: false,
        sourceName: 'Örnek Senaryo Konumu (EX-01_LIMAN_SOGUK_ZINCIR · Doğrulanmış Koordinat)',
        eventTimeIso: '2026-04-06T08:00:00Z (Statik Senaryo Başlangıcı)',
        ingestedAtIso: 'Yerel Örnek Model Kaydı',
        regionLabel: loc.region,
        isPrimaryPort: loc.isPrimaryPort
      };
      window.cCesiumState.markerRegistry.set(rec.markerId, rec);
    }
  }
  if (!rec) return null;

  window.cCesiumState.selectedMarkerId = markerId;

  if (rec.geoKey) {
    state.selectedGeoLocationKey = rec.geoKey;
    state.selectedUnivClusterId = null;
    state.selectedUnivClusterData = null;
  } else {
    state.selectedUnivClusterId = rec.markerId;
    state.selectedUnivClusterData = {
      clusterId: rec.markerId,
      locationLabel: rec.title,
      label: `Mw ${rec.mag?.toFixed(1) || '—'} · Derinlik ${rec.depthKm?.toFixed(1) || '—'} km`,
      lat: rec.lat,
      lon: rec.lon,
      category: 'ENVIRONMENT_SEISMIC',
      isCluster: false,
      memberCount: 1,
      primaryMember: {
        valueSummary: `Büyüklük: M${Number(rec.mag || 0).toFixed(1)} · Derinlik: ${Number(rec.depthKm || 0).toFixed(1)} km`,
        sourceName: rec.sourceName,
        occurrenceTimeIso: rec.eventTimeIso,
        ingestionTimeIso: rec.ingestedAtIso
      }
    };
  }

  renderDunyamOverview();
  syncCesiumSceneWithCaelusState();

  // Sağ üst #dunyam-stage-callout-card içinde Başlık, Konum, Tür, Kaynak, Olay Zamanı ve Son Alım Zamanını açıkça göster
  const eyebrowEl = document.getElementById('dunyam-callout-eyebrow');
  const nameEl = document.getElementById('dunyam-callout-name');
  const codeEl = document.getElementById('dunyam-callout-code');
  const badgeEl = document.getElementById('dunyam-callout-badge');
  const lbl1 = document.getElementById('dunyam-callout-lbl-1');
  const val1 = document.getElementById('dunyam-callout-metric-1');
  const lbl2 = document.getElementById('dunyam-callout-lbl-2');
  const val2 = document.getElementById('dunyam-callout-metric-2');
  const lbl3 = document.getElementById('dunyam-callout-lbl-3');
  const val3 = document.getElementById('dunyam-callout-metric-3');
  const lbl4 = document.getElementById('dunyam-callout-lbl-4');
  const val4 = document.getElementById('dunyam-callout-metric-4');
  const purposeEl = document.getElementById('dunyam-callout-purpose');
  const srcLineEl = document.getElementById('dunyam-callout-sources-line');
  const timeLineEl = document.getElementById('dunyam-callout-event-time');

  const latLonText = `${Math.abs(rec.lat).toFixed(2)}°${rec.lat >= 0 ? 'K' : 'G'}, ${Math.abs(rec.lon).toFixed(2)}°${rec.lon >= 0 ? 'D' : 'B'}`;
  if (eyebrowEl) {
    eyebrowEl.textContent = rec.isRealData ? 'SEÇİLİ GERÇEK AÇIK VERİ OLAYI' : 'SEÇİLİ ÖRNEK / SENARYO KONUMU';
  }
  if (nameEl) nameEl.textContent = rec.title;
  if (codeEl) codeEl.textContent = `${rec.categoryLabelTr.split('(')[0].trim()} · ${latLonText}`;
  if (badgeEl) {
    badgeEl.textContent = rec.epistemicLabelTr || (rec.isRealData ? 'Gerçek gözlem' : 'Örnek veri');
    const isStaleRec = String(rec.epistemicLabelTr || '').includes('Son bilinen');
    badgeEl.className = 'kpi-badge ' + (isStaleRec ? 'warn' : (rec.isRealData ? 'ok' : 'warn'));
  }

  if (rec.category === 'SEISMIC_ENV') {
    if (lbl1) lbl1.textContent = 'Büyüklük';
    if (val1) val1.textContent = `M${Number(rec.mag || 0).toFixed(1)}`;
    if (lbl2) lbl2.textContent = 'Derinlik';
    if (val2) val2.textContent = `${Number(rec.depthKm || 0).toFixed(1)} km`;
    if (lbl3) lbl3.textContent = 'Olay Türü';
    if (val3) val3.textContent = 'Deprem (USGS)';
    if (lbl4) lbl4.textContent = 'Veri Sınıfı';
    if (val4) val4.textContent = rec.epistemicLabelTr || 'Gerçek gözlem';
  } else {
    if (lbl3) lbl3.textContent = 'Konum Türü';
    if (val3) val3.textContent = rec.isPrimaryPort ? 'Liman / Süreç' : 'Deniz Koridoru';
    if (lbl4) lbl4.textContent = 'Veri Sınıfı';
    if (val4) val4.textContent = rec.isRealData ? 'Hava modeli / tahmin' : 'Örnek veri';
  }

  if (purposeEl) purposeEl.textContent = rec.categoryLabelTr;
  if (srcLineEl) {
    srcLineEl.textContent = `Kaynak: ${rec.sourceName}`;
  }
  if (timeLineEl) {
    const tEventShort = String(rec.eventTimeIso || '').slice(0, 19).replace('T', ' ');
    const tIngestShort = String(rec.ingestedAtIso || '').slice(0, 19).replace('T', ' ');
    timeLineEl.textContent = `Olay Zamanı: ${tEventShort} · Alım: ${tIngestShort}`;
  }

  if (!options.keepCollapsed) {
    const calloutCard = document.getElementById('dunyam-stage-callout-card');
    if (calloutCard) calloutCard.classList.remove('is-collapsed');
  }
  if (typeof updateCalloutProgressiveLayers === 'function') {
    updateCalloutProgressiveLayers(rec);
  }
  const reopenLbl = document.getElementById('dunyam-callout-reopen-label');
  if (reopenLbl && rec.title) {
    reopenLbl.textContent = String(rec.title).slice(0, 26);
  }

  if (options.flyTo && window.cCesiumState.viewer && window.Cesium) {
    window.cCesiumState.viewer.camera.flyTo({
      destination: window.Cesium.Cartesian3.fromDegrees(rec.lon, rec.lat, 1150000.0),
      duration: 1.1
    });
  }

  return rec;
}
window.selectCesiumGlobeMarkerById = selectCesiumGlobeMarkerById;

/**
 * Hafıza Sayfası Etkileşimli vis-timeline (7.7.3) Entegrasyonu
 * 4 Ayrı Kategori Şeridinde (Gerçek Olay, Veri Kaynağı, Kaydedilmiş Senaryo, Kullanıcı İşlemi)
 * zaman sıralı kayıtları gösterir; seçilen öğeyi sağdaki inceleyici ve Zaman Tekeri ile senkronize eder.
 */
function renderHafizaVisTimeline(displayItems, selectedIdx) {
  const container = document.getElementById('hafiza-vis-timeline-container');
  if (!container || typeof window.vis === 'undefined' || !window.vis.Timeline) return;

  const items = Array.isArray(displayItems) ? displayItems : [];
  const groupsSpec = [
    { id: 'REAL_EVENT', content: '🟢 Gerçek Olay', order: 1 },
    { id: 'DATA_SOURCE', content: '🌐 Veri Kaynağı', order: 2 },
    { id: 'SAVED_SCENARIO', content: '🟣 Kaydedilmiş Senaryo', order: 3 },
    { id: 'USER_ACTION', content: '🟡 Kullanıcı İşlemi', order: 4 }
  ];

  const mappedItems = items.map((it, idx) => {
    let cls = 'vis-item-saved-scenario';
    if (it.itemType === 'REAL_EVENT') cls = 'vis-item-real-event';
    else if (it.itemType === 'DATA_SOURCE') cls = 'vis-item-data-source';
    else if (it.itemType === 'USER_ACTION') cls = 'vis-item-user-action';

    let startMs = Date.parse(it.timestampIso || '');
    if (!Number.isFinite(startMs)) {
      startMs = Date.parse('2026-04-06T08:00:00Z') + idx * 3600000;
    }
    const shortTitle = String(it.title || 'Kayıt').length > 42
      ? String(it.title).slice(0, 40) + '…'
      : String(it.title || 'Kayıt');

    return {
      id: `VIS_HAFIZA_${idx}`,
      itemIdx: idx,
      group: it.itemType || 'SAVED_SCENARIO',
      content: `${escapeHtml(shortTitle)}`,
      title: `${it.title}\n${it.badgeText}\nZaman: ${it.timestampIso}\n${it.separationLabel}`,
      start: new Date(startMs),
      type: 'box',
      className: cls
    };
  });

  if (!hafizaVisTimelineInstance) {
    hafizaVisDataSetGroups = new window.vis.DataSet(groupsSpec);
    hafizaVisDataSetItems = new window.vis.DataSet(mappedItems);
    hafizaVisTimelineInstance = new window.vis.Timeline(container, hafizaVisDataSetItems, hafizaVisDataSetGroups, {
      stack: true,
      maxHeight: 195,
      minHeight: 138,
      margin: { item: { horizontal: 8, vertical: 5 }, axis: 6 },
      orientation: { axis: 'bottom', item: 'top' },
      zoomMin: 1000 * 60 * 15, // 15 dakika
      zoomMax: 1000 * 60 * 60 * 24 * 365 * 15, // 15 yıl
      showCurrentTime: false,
      tooltip: { followMouse: true }
    });

    hafizaVisTimelineInstance.on('select', (props) => {
      if (hafizaVisSuppressSelectEvent) return;
      if (props && Array.isArray(props.items) && props.items.length > 0) {
        const rawId = String(props.items[0]);
        const idx = Number(rawId.replace('VIS_HAFIZA_', ''));
        if (Number.isFinite(idx)) {
          state.hafizaSelectedIdx = idx;
          state.hafizaSelectedSavedId = null;
          renderHafizaStreamWorkspace();
        }
      }
    });
  } else {
    hafizaVisDataSetItems.clear();
    hafizaVisDataSetItems.add(mappedItems);
  }

  if (selectedIdx >= 0 && selectedIdx < mappedItems.length) {
    hafizaVisSuppressSelectEvent = true;
    try {
      hafizaVisTimelineInstance.setSelection([`VIS_HAFIZA_${selectedIdx}`], { focus: false });
    } catch (_) {}
    hafizaVisSuppressSelectEvent = false;
  }
}

function initCaelusGeoAndTimelineIntegrations() {
  // 1. CesiumJS 3B Dünya Küresini Başlat
  initCaelusCesiumGlobe();

  // 2. Sahne Üstü Hızlı Keşif ve Katman Düğmeleri
  const btnFlyAegean = document.getElementById('btn-cesium-fly-aegean');
  if (btnFlyAegean) {
    btnFlyAegean.addEventListener('click', () => {
      flyCesiumToAegeanRegion(1.2);
    });
  }

  const btnFlyGlobal = document.getElementById('btn-cesium-fly-global');
  if (btnFlyGlobal) {
    btnFlyGlobal.addEventListener('click', () => {
      flyCesiumToGlobalView(1.2);
    });
  }

  const btnToggleGibs = document.getElementById('btn-stage-toggle-gibs');
  if (btnToggleGibs) {
    btnToggleGibs.addEventListener('click', () => {
      const nextLayer = window.cCesiumState.activeGibsLayerId === 'NONE'
        ? 'VIIRS_SNPP_CorrectedReflectance_TrueColor'
        : 'NONE';
      applyNasaGibsImageryLayer(nextLayer, window.cCesiumState.activeGibsDate || '2026-04-05');
    });
  }

  const btnToggleWind = document.getElementById('btn-stage-toggle-wind');
  if (btnToggleWind) {
    btnToggleWind.addEventListener('click', () => {
      const nextMode = window.cCesiumState.windDensity === 'OFF' ? 'NORMAL' : 'OFF';
      initAndRunRegionalWindLayer(nextMode);
    });
  }

  const btnToggleEvents = document.getElementById('btn-stage-toggle-events');
  if (btnToggleEvents) {
    btnToggleEvents.addEventListener('click', () => {
      window.cCesiumState.showEventsLayer = !window.cCesiumState.showEventsLayer;
      btnToggleEvents.classList.toggle('active', window.cCesiumState.showEventsLayer);
      btnToggleEvents.setAttribute('aria-pressed', window.cCesiumState.showEventsLayer ? 'true' : 'false');
      syncCesiumSceneWithCaelusState();
    });
  }

  // 3. Katmanlar Popover İçi NASA GIBS ve Bölgesel Rüzgâr Kontrolleri
  const selGibs = document.getElementById('sel-dunyam-gibs-layer');
  const inpGibsDate = document.getElementById('inp-dunyam-gibs-date');
  if (selGibs) {
    selGibs.addEventListener('change', () => {
      const dateVal = inpGibsDate ? inpGibsDate.value : '2026-04-05';
      applyNasaGibsImageryLayer(selGibs.value, dateVal);
    });
  }
  if (inpGibsDate) {
    inpGibsDate.addEventListener('change', () => {
      const layerId = selGibs && selGibs.value !== 'NONE'
        ? selGibs.value
        : 'VIIRS_SNPP_CorrectedReflectance_TrueColor';
      applyNasaGibsImageryLayer(layerId, inpGibsDate.value);
    });
  }

  const btnGibs2026 = document.getElementById('btn-gibs-date-2026');
  if (btnGibs2026) {
    btnGibs2026.addEventListener('click', () => {
      const layerId = selGibs && selGibs.value !== 'NONE'
        ? selGibs.value
        : 'VIIRS_SNPP_CorrectedReflectance_TrueColor';
      applyNasaGibsImageryLayer(layerId, '2026-04-05');
    });
  }
  const btnGibs2020 = document.getElementById('btn-gibs-date-2020');
  if (btnGibs2020) {
    btnGibs2020.addEventListener('click', () => {
      const layerId = selGibs && selGibs.value !== 'NONE'
        ? selGibs.value
        : 'VIIRS_SNPP_CorrectedReflectance_TrueColor';
      applyNasaGibsImageryLayer(layerId, '2020-10-30');
    });
  }
  const btnGibsMissing = document.getElementById('btn-gibs-date-missing');
  if (btnGibsMissing) {
    btnGibsMissing.addEventListener('click', () => {
      const layerId = selGibs && selGibs.value !== 'NONE'
        ? selGibs.value
        : 'VIIRS_SNPP_CorrectedReflectance_TrueColor';
      applyNasaGibsImageryLayer(layerId, '2026-11-07');
    });
  }

  const selWindDensity = document.getElementById('sel-dunyam-wind-density');
  if (selWindDensity) {
    selWindDensity.addEventListener('change', () => {
      initAndRunRegionalWindLayer(selWindDensity.value);
    });
  }

  // 4. Hafıza vis-timeline Kontrolleri
  const btnVisFit = document.getElementById('btn-vis-timeline-fit');
  if (btnVisFit) {
    btnVisFit.addEventListener('click', () => {
      if (hafizaVisTimelineInstance) {
        try { hafizaVisTimelineInstance.fit({ animation: { duration: 400 } }); } catch (_) {}
      }
    });
  }
  const btnVisRecent = document.getElementById('btn-vis-timeline-recent');
  if (btnVisRecent) {
    btnVisRecent.addEventListener('click', () => {
      if (hafizaVisTimelineInstance) {
        try {
          const end = new Date('2026-04-07T00:00:00Z');
          const start = new Date('2026-04-04T00:00:00Z');
          hafizaVisTimelineInstance.setWindow(start, end, { animation: { duration: 400 } });
        } catch (_) {}
      }
    });
  }

  window.flyCesiumToAegeanRegion = flyCesiumToAegeanRegion;
  window.flyCesiumToGlobalView = flyCesiumToGlobalView;
  window.applyNasaGibsImageryLayer = applyNasaGibsImageryLayer;
  window.initAndRunRegionalWindLayer = initAndRunRegionalWindLayer;
  window.bilinearInterpolateRegionalWind = bilinearInterpolateRegionalWind;
  window.selectCesiumGlobeMarkerById = selectCesiumGlobeMarkerById;
  window.renderHafizaVisTimeline = renderHafizaVisTimeline;
  window.syncCesiumSceneWithCaelusState = syncCesiumSceneWithCaelusState;
  window.ensureUnifiedRealWorldLedger = ensureUnifiedRealWorldLedger;
  window.persistUnifiedRealWorldLedger = persistUnifiedRealWorldLedger;
  window.loadAndRenderRealGlobeEvents = loadAndRenderRealGlobeEvents;
  window.fetchLiveOpenMeteoToUnifiedLedger = fetchLiveOpenMeteoToUnifiedLedger;
  window.openCaelusCommandPalette = openCaelusCommandPalette;
  window.closeCaelusCommandPalette = closeCaelusCommandPalette;
  window.runCaelusCommandPaletteQuery = runCaelusCommandPaletteQuery;
  window.ensureLocalLlmPrefs = ensureLocalLlmPrefs;
  window.saveLocalLlmPrefs = saveLocalLlmPrefs;
  window.refreshLocalOllamaConnectionUi = refreshLocalOllamaConnectionUi;
}

/* ═══════════════════════════════════════════════════════════════════════════
   GITHUB AÇIK KAYNAK UI ENTEGRASYON KATMANI:
   - Apache ECharts 5.5.1 (Senaryo Karşılaştırma Grafikleri — Gerçek Motor Çıktısı)
   - Floating UI 1.6.12 (Masaüstü ve Mobil Akıllı Açılır Kart Konumlandırma)
   - Motion 11.11.17 MIT Çekirdeği (prefers-reduced-motion Uyumlu Ölçülü Geçişler)
   - earth-moon-solar MIT Referansı (Yörünge Odaklama ve Kozmos Denetçisi)
   ═══════════════════════════════════════════════════════════════════════════ */
let caelusEChartNodesBar = null;
let caelusEChartTrajectory = null;

function isCaelusMotionReduced() {
  const mediaReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const prefOff = state && state.uiPrefs && state.uiPrefs.animLevel === 'off';
  const attrOff = document.documentElement.getAttribute('data-anim') === 'off';
  return Boolean(mediaReduced || prefOff || attrOff);
}

function animateCaelusViewTransition(targetView) {
  if (isCaelusMotionReduced()) return;
  const viewMap = {
    dunyam: document.getElementById('dunyam-overview-hub'),
    kesfet: document.getElementById('kesfet-clean-workspace'),
    kozmos: document.getElementById('living-universe-section'),
    senaryolar: document.getElementById('senaryolar-guided-workspace'),
    hafiza: document.getElementById('hafiza-clean-workspace'),
    baglantilar: document.getElementById('baglantilar-clean-workspace'),
    ayarlar: document.getElementById('quiet-settings-section')
  };
  const elSection = viewMap[targetView];
  if (!elSection) return;
  if (window.Motion && typeof window.Motion.animate === 'function') {
    try {
      window.Motion.animate(
        elSection,
        { opacity: [0.88, 1], transform: ['translateY(4px)', 'translateY(0px)'] },
        { duration: 0.18, easing: [0.16, 1, 0.3, 1] }
      );
    } catch (_) {}
  }
}

function animateCaelusPopoverOpen(elPopover) {
  if (!elPopover || isCaelusMotionReduced()) return;
  if (window.Motion && typeof window.Motion.animate === 'function') {
    try {
      window.Motion.animate(
        elPopover,
        { opacity: [0, 1], transform: ['scale(0.985)', 'scale(1)'] },
        { duration: 0.16, easing: [0.16, 1, 0.3, 1] }
      );
    } catch (_) {}
  }
}

async function positionCaelusFloatingPopovers() {
  const fdom = window.FloatingUIDOM;
  if (!fdom || typeof fdom.computePosition !== 'function') return;

  // 1. Katmanlar ve Görünüm Popover (#dunyam-layers-popover anchored to #btn-dunyam-toggle-layers-popover)
  const btnLayers = document.getElementById('btn-dunyam-toggle-layers-popover');
  const popLayers = document.getElementById('dunyam-layers-popover');
  if (btnLayers && popLayers && !popLayers.classList.contains('hidden') && window.innerWidth > 820) {
    try {
      const middleware = [];
      if (typeof fdom.offset === 'function') middleware.push(fdom.offset(8));
      if (typeof fdom.flip === 'function') middleware.push(fdom.flip({ padding: 12 }));
      if (typeof fdom.shift === 'function') middleware.push(fdom.shift({ padding: 12 }));
      const pos = await fdom.computePosition(btnLayers, popLayers, {
        placement: 'bottom-end',
        middleware
      });
      if (pos && Number.isFinite(pos.x) && Number.isFinite(pos.y)) {
        popLayers.setAttribute('data-floating-ui-positioned', `${Math.round(pos.x)},${Math.round(pos.y)}`);
      }
    } catch (_) {}
  }

  // 2. Seçili Konum / Varlık Kartı (#dunyam-stage-callout-card safe viewport check via Floating UI)
  const stageBox = document.getElementById('dunyam-hero-stage-box');
  const calloutCard = document.getElementById('dunyam-stage-callout-card');
  if (stageBox && calloutCard) {
    calloutCard.setAttribute('data-floating-ui-ready', 'true');
  }
}

function renderScenarioEChartsComparison(cfData, ev, summary = {}) {
  const box = document.getElementById('cf-echarts-comparison-box');
  const domNodes = document.getElementById('cf-echarts-nodes-bar');
  const domTraj = document.getElementById('cf-echarts-trajectory-line');
  if (!box || !domNodes || !domTraj) return;

  if (!cfData || !ev || !ev.isCounterfactualSimulated || !window.echarts) {
    box.classList.add('hidden');
    return;
  }
  box.classList.remove('hidden');

  const isLight = document.documentElement.getAttribute('data-theme') === 'light' || document.body.classList.contains('theme-light');
  const textColor = isLight ? '#0f172a' : '#e2e8f0';
  const subTextColor = isLight ? '#475569' : '#94a3b8';
  const splitLineColor = isLight ? 'rgba(15, 23, 42, 0.08)' : 'rgba(148, 163, 184, 0.14)';
  const tooltipBg = isLight ? 'rgba(255, 255, 255, 0.96)' : 'rgba(7, 13, 27, 0.94)';

  const nodeCmp = Array.isArray(ev.nodeComparison) ? ev.nodeComparison : [];
  const categories = nodeCmp.map(n => String(n.label || n.id || '').slice(0, 18));
  const startVals = nodeCmp.map(n => Number(n.startStatePct ?? 50));
  const branchAVals = nodeCmp.map(n => Number(n.branchAStatePct ?? 50));
  const branchBVals = nodeCmp.map(n => Number(n.branchBStatePct ?? 50));

  try {
    if (!caelusEChartNodesBar) {
      caelusEChartNodesBar = window.echarts.init(domNodes, null, { renderer: 'canvas' });
    }
    caelusEChartNodesBar.setOption({
      animation: !isCaelusMotionReduced(),
      tooltip: {
        trigger: 'axis',
        axisPointer: { type: 'shadow' },
        backgroundColor: tooltipBg,
        borderColor: 'rgba(56, 189, 248, 0.35)',
        textStyle: { color: textColor, fontSize: 12 }
      },
      legend: {
        top: 0,
        textStyle: { color: subTextColor, fontSize: 11 },
        data: ['Başlangıç (t=0)', 'Hiçbir şey yapılmazsa', 'Bu adım uygulanırsa']
      },
      grid: { left: 42, right: 16, top: 32, bottom: 38 },
      xAxis: {
        type: 'category',
        data: categories,
        axisLabel: { color: subTextColor, fontSize: 10, interval: 0, rotate: categories.length > 4 ? 14 : 0 },
        axisLine: { lineStyle: { color: splitLineColor } }
      },
      yAxis: {
        type: 'value',
        min: 0,
        max: 100,
        axisLabel: { color: subTextColor, fontSize: 10, formatter: '%{value}' },
        splitLine: { lineStyle: { color: splitLineColor } }
      },
      series: [
        {
          name: 'Başlangıç (t=0)',
          type: 'bar',
          barMaxWidth: 16,
          itemStyle: { color: '#64748b', borderRadius: [3, 3, 0, 0] },
          data: startVals
        },
        {
          name: 'Hiçbir şey yapılmazsa',
          type: 'bar',
          barMaxWidth: 16,
          itemStyle: { color: '#f43f5e', borderRadius: [3, 3, 0, 0] },
          data: branchAVals
        },
        {
          name: 'Bu adım uygulanırsa',
          type: 'bar',
          barMaxWidth: 16,
          itemStyle: { color: '#10b981', borderRadius: [3, 3, 0, 0] },
          data: branchBVals
        }
      ]
    }, true);
  } catch (_) {}

  // Chart 2: Capacity & Uninterrupted Step Ratio Comparison from real engine branch_a vs branch_b
  const horizonTicks = Math.max(1, Number(summary.horizonTicks || cfData.horizon_ticks || 24));
  const baOutageTicks = Number(summary.baOutageTicks ?? (cfData.branch_a && cfData.branch_a.outage_ticks) ?? 0);
  const bbOutageTicks = Number(summary.bbOutageTicks ?? (cfData.branch_b && cfData.branch_b.outage_ticks) ?? 0);
  const baUptimePct = Math.round(clamp(((horizonTicks - baOutageTicks) / horizonTicks) * 100, 0, 100));
  const bbUptimePct = Math.round(clamp(((horizonTicks - bbOutageTicks) / horizonTicks) * 100, 0, 100));
  const initTpPct = Number(summary.initTpPct ?? 80);
  const baAvgTpPct = Number(summary.baAvgTpPct ?? 40);
  const bbAvgTpPct = Number(summary.bbAvgTpPct ?? 78);
  const baTpPct = Number(summary.baTpPct ?? 35);
  const bbTpPct = Number(summary.bbTpPct ?? 82);

  try {
    if (!caelusEChartTrajectory) {
      caelusEChartTrajectory = window.echarts.init(domTraj, null, { renderer: 'canvas' });
    }
    caelusEChartTrajectory.setOption({
      animation: !isCaelusMotionReduced(),
      tooltip: {
        trigger: 'axis',
        backgroundColor: tooltipBg,
        borderColor: 'rgba(56, 189, 248, 0.35)',
        textStyle: { color: textColor, fontSize: 12 }
      },
      legend: {
        top: 0,
        textStyle: { color: subTextColor, fontSize: 11 },
        data: ['Hiçbir şey yapılmazsa', 'Bu adım uygulanırsa']
      },
      grid: { left: 42, right: 16, top: 32, bottom: 38 },
      xAxis: {
        type: 'category',
        data: ['Başlangıç (t=0)', 'Dönem Ortalaması', 'Dönem Sonu Kapasite', 'Kesintisiz Süre Oranı'],
        axisLabel: { color: subTextColor, fontSize: 10, interval: 0 },
        axisLine: { lineStyle: { color: splitLineColor } }
      },
      yAxis: {
        type: 'value',
        min: 0,
        max: 100,
        axisLabel: { color: subTextColor, fontSize: 10, formatter: '%{value}' },
        splitLine: { lineStyle: { color: splitLineColor } }
      },
      series: [
        {
          name: 'Hiçbir şey yapılmazsa',
          type: 'line',
          smooth: true,
          symbolSize: 8,
          lineStyle: { width: 3, color: '#f43f5e' },
          itemStyle: { color: '#f43f5e' },
          areaStyle: { color: 'rgba(244, 63, 94, 0.12)' },
          data: [initTpPct, baAvgTpPct, baTpPct, baUptimePct]
        },
        {
          name: 'Bu adım uygulanırsa',
          type: 'line',
          smooth: true,
          symbolSize: 8,
          lineStyle: { width: 3, color: '#38bdf8' },
          itemStyle: { color: '#38bdf8' },
          areaStyle: { color: 'rgba(56, 189, 248, 0.16)' },
          data: [initTpPct, bbAvgTpPct, bbTpPct, bbUptimePct]
        }
      ]
    }, true);
  } catch (_) {}

  if (typeof renderCaelusCarbonScenarioChart === 'function') {
    renderCaelusCarbonScenarioChart(cfData, ev, summary);
  }
}

function resizeScenarioECharts() {
  try {
    if (caelusEChartNodesBar) caelusEChartNodesBar.resize();
    if (caelusEChartTrajectory) caelusEChartTrajectory.resize();
  } catch (_) {}
}

function flyToSolarBody(planetId) {
  const normId = String(planetId || 'EARTH').toUpperCase();
  const mem = ensureLivingMemoryStore();
  if (mem) {
    mem.selectedPlanetId = normId;
    saveLivingMemoryStore();
  }
  const zoomTargetMap = {
    SUN: 1.15,
    MERCURY: 1.25,
    VENUS: 1.22,
    EARTH: 1.18,
    MOON: 1.28,
    MARS: 1.15,
    JUPITER: 1.05,
    SATURN: 1.02,
    URANUS: 0.96,
    NEPTUNE: 0.92
  };
  solarStageState.zoom = zoomTargetMap[normId] || 1.05;
  renderLivingUniversePanel();
  if (typeof syncKozmosSpacekitPlanetFocus === 'function') {
    syncKozmosSpacekitPlanetFocus(normId);
  }
  const inspCard = document.getElementById('univ-celestial-inspector-card');
  if (inspCard) animateCaelusPopoverOpen(inspCard);
}

function initGitHubUiTransformIntegrations() {
  // 1. Mobile Bottom Navigation Bar (#caelus-mobile-bottom-nav)
  document.querySelectorAll('#caelus-mobile-bottom-nav [data-quiet-nav]').forEach(btn => {
    btn.addEventListener('click', () => {
      const target = btn.getAttribute('data-quiet-nav') || 'dunyam';
      switchQuietView(target);
    });
  });

  // 2. Kozmos Celestial Body Pill Selector with smooth focus
  document.querySelectorAll('#univ-planet-pills-bar [data-planet-select]').forEach(btn => {
    btn.addEventListener('click', () => {
      const planetId = String(btn.getAttribute('data-planet-select') || 'EARTH').toUpperCase();
      flyToSolarBody(planetId);
    });
  });

  // 3. Kozmos Floating Inspector Action Button (#btn-univ-inspector-action)
  const btnInspAction = document.getElementById('btn-univ-inspector-action');
  if (btnInspAction) {
    btnInspAction.addEventListener('click', () => {
      const mem = ensureLivingMemoryStore();
      const selId = mem && mem.selectedPlanetId ? String(mem.selectedPlanetId).toUpperCase() : 'EARTH';
      if (selId === 'EARTH' || selId === 'MOON') {
        switchQuietView('dunyam');
      } else {
        flyToSolarBody('EARTH');
      }
    });
  }

  // 4. Floating UI positioning on layers popover toggle & window resize
  const btnToggleLayers = document.getElementById('btn-dunyam-toggle-layers-popover');
  if (btnToggleLayers) {
    btnToggleLayers.addEventListener('click', () => {
      setTimeout(() => {
        const pop = document.getElementById('dunyam-layers-popover');
        if (pop && !pop.classList.contains('hidden')) {
          animateCaelusPopoverOpen(pop);
          positionCaelusFloatingPopovers();
        }
      }, 20);
    });
  }

  window.addEventListener('resize', () => {
    resizeScenarioECharts();
    positionCaelusFloatingPopovers();
    if (typeof resizeActiveThreeStage === 'function') resizeActiveThreeStage();
  });

  positionCaelusFloatingPopovers();
  window.flyToSolarBody = flyToSolarBody;
  window.renderScenarioEChartsComparison = renderScenarioEChartsComparison;
  window.positionCaelusFloatingPopovers = positionCaelusFloatingPopovers;
}

