function setCaelusSpatialPerfMode(mode) {
  const norm = ['FULL', 'BALANCED', 'LITE_2D'].includes(mode) ? mode : 'FULL';
  document.body.setAttribute('data-caelus-perf-mode', norm);
  document.querySelectorAll('#caelus-perf-mode-switcher [data-perf-mode]').forEach(btn => {
    const active = btn.getAttribute('data-perf-mode') === norm;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-pressed', active ? 'true' : 'false');
  });

  if (norm === 'LITE_2D') {
    const btn2d = document.querySelector('.pref-view-btn[data-view-mode="2d"]');
    if (btn2d) btn2d.click();
    const pill = document.getElementById('dunyam-stage-mode-pill');
    if (pill) pill.textContent = '◈ HAFİF / 2B ŞEMATİK SAHNE · EKO';
  } else if (norm === 'BALANCED') {
    const btn3d = document.querySelector('.pref-view-btn[data-view-mode="3d"]');
    const btnEco = document.querySelector('.pref-gpu-eco-btn[data-gpu-eco="true"]');
    if (btn3d) btn3d.click();
    if (btnEco) btnEco.click();
    const pill = document.getElementById('dunyam-stage-mode-pill');
    if (pill) pill.textContent = '◉ DENGELİ 3B SAHNE · DPR 1.0';
  } else {
    const btn3d = document.querySelector('.pref-view-btn[data-view-mode="3d"]');
    if (btn3d) btn3d.click();
    const pill = document.getElementById('dunyam-stage-mode-pill');
    if (pill) pill.textContent = '◉ TAM SAHNE 3B DÜNYA · WEBGL';
  }
}

function applyCytoscapeHopDepth(hopDepth) {
  const hop = Math.max(1, Math.min(3, Number(hopDepth) || 1));
  window.cActiveCytoscapeHop = hop;
  document.querySelectorAll('#kesfet-cy-hop-bar [data-cy-hop]').forEach(btn => {
    btn.classList.toggle('active', Number(btn.getAttribute('data-cy-hop')) === hop);
  });
  const statusLbl = document.getElementById('kesfet-cy-hop-status-label');
  if (statusLbl) {
    statusLbl.textContent = hop === 1
      ? 'Odak: 1. derece doğrudan komşular aktif; 2–3. derece yollar geri çekildi.'
      : hop === 2
        ? 'Odak: 1. ve 2. derece dolaylı yayılım yolları aydınlatıldı.'
        : 'Odak: 3. derece tam etki ağı gösteriliyor.';
  }

  const cy = window.cRealWorld13State && window.cRealWorld13State.cytoscapeInstance;
  if (!cy) return;
  const focusNode = cy.nodes('.active-focus').first();
  if (!focusNode || !focusNode.length) return;

  cy.elements().removeClass('active-neighbor active-edge dimmed');
  if (hop >= 3) {
    cy.nodes().not(focusNode).addClass('active-neighbor');
    cy.edges().addClass('active-edge');
    return;
  }
  let neighborhood = focusNode.closedNeighborhood();
  if (hop === 2) {
    neighborhood = neighborhood.union(neighborhood.nodes().closedNeighborhood());
  }
  cy.elements().not(neighborhood).addClass('dimmed');
  neighborhood.edges().addClass('active-edge');
  neighborhood.nodes().not(focusNode).addClass('active-neighbor');
}

function renderKesfetStepPathList() {
  const box = document.getElementById('kesfet-step-path-cards');
  if (!box) return;
  const aw = typeof getActiveDigitalWorld === 'function' ? getActiveDigitalWorld() : null;
  const nodes = (aw && Array.isArray(aw.nodes)) ? aw.nodes : [];
  const n0 = nodes[0] ? String(nodes[0].label || nodes[0].id).split('(')[0].trim() : 'Rıhtım Trafo ve Enerji';
  const n1 = nodes[1] ? String(nodes[1].label || nodes[1].id).split('(')[0].trim() : 'Reefer Soğuk Zincir';
  const n2 = nodes[2] ? String(nodes[2].label || nodes[2].id).split('(')[0].trim() : 'Terminal Kapı ve Kuyruk';

  const steps = [
    {
      step: '1. Olay (Başlangıç Şoku)',
      title: 'Sismik / Enerji Kesintisi Gözlemi',
      badge: '● Gerçek Gözlem',
      badgeCls: 'ok',
      desc: 'USGS sismik kaydı veya şebeke gerilim düşümü birincil altyapı düğümüne ulaşır.'
    },
    {
      step: '2. İlgili Varlık (1. Derece)',
      title: n0,
      badge: '● Doğrudan Bağ',
      badgeCls: 'accent',
      desc: `Doğrudan kapasite yükü ve enerji beslemesi etkilenir; 1. derece komşulukta öncelikli darboğaz oluşur.`
    },
    {
      step: '3. Olası Etki (2. Derece Yayılım)',
      title: `${n1} → ${n2}`,
      badge: '◆ Model / Hipotez',
      badgeCls: 'warn',
      desc: 'Gecikmeli geri besleme ve tampon tükenmesiyle soğuk zincir ve SLA koridoruna yayılır.'
    },
    {
      step: '4. Seçili Bağlam & Karar',
      title: 'Yedek Güç Koridoru + Mikroşebeke',
      badge: '◈ Müdahale Adayı',
      badgeCls: 'ok',
      desc: 'Seçili noktadan Gelecekler ve Senaryolar katmanına geçilerek müdahale etkisi sınanır.'
    }
  ];

  box.innerHTML = steps.map(s => `
    <div class="caelus-clean-card" style="padding:9px 11px; display:flex; flex-direction:column; gap:4px;">
      <div style="display:flex; align-items:center; justify-content:space-between; gap:6px;">
        <span style="font-size:0.68rem; font-weight:700; color:#E6C387;">${escapeHtml(s.step)}</span>
        <span class="kpi-badge ${s.badgeCls}" style="font-size:0.64rem;">${escapeHtml(s.badge)}</span>
      </div>
      <strong style="font-size:0.82rem; color:var(--text-1);">${escapeHtml(s.title)}</strong>
      <div style="font-size:0.73rem; color:var(--text-2); line-height:1.38;">${escapeHtml(s.desc)}</div>
    </div>
  `).join('');
}

function renderScenariosSixQuestionsAndThreeFutures(activeTabFilter = 'ALL') {
  const qGrid = document.getElementById('senaryolar-six-questions-grid');
  const fDeck = document.getElementById('senaryolar-three-futures-deck');
  if (!qGrid || !fDeck) return;

  const aw = typeof getActiveDigitalWorld === 'function' ? getActiveDigitalWorld() : null;
  const worldTitle = (aw && aw.title) ? aw.title : 'Liman Soğuk Zincir ve Terminal Dünyası';
  const leverSel = document.getElementById('lever-select');
  const leverText = (leverSel && leverSel.selectedOptions && leverSel.selectedOptions[0])
    ? leverSel.selectedOptions[0].textContent
    : 'Yedek Güç Koridoru ve Reefer Önceliklendirme';

  const sixQuestions = [
    { q: '1. Şu an hangi durumdayız?', a: `${worldTitle} üzerinde kritik süreç düğümleri ve kapasite eşikleri deterministik çekirdekte izleniyor.` },
    { q: '2. Hangi değişiklik veya olay inceleniyor?', a: `Seçili müdahale: ${leverText} (24 adım / 6.0 saat ufuk, sabit PRNG tohumu).` },
    { q: '3. Hiçbir şey yapılmazsa ne olabilir?', a: 'Baz durumda darboğaz 2. derece düğümlere yayılarak kapasite kaybı ve eşik aşımı üretir.' },
    { q: '4. Müdahale edilirse ne değişebilir?', a: 'Yedek koridor ve tampon devreye girerek kesintisiz çalışma oranını ve korunan kapasiteyi artırır.' },
    { q: '5. Hangi varsayımlar sonucu etkiliyor?', a: 'Tampon süresi, gecikme adımı (lag) ve birim duruş maliyeti varsayımı (varsayım ≠ gerçek fatura).' },
    { q: '6. Hangi veri eksik?', a: 'Tesis içi alt-sayaç telemetrisi ve temiz oda/soğuk zincir parti bazlı yeniden kalifikasyon süresi.' }
  ];

  qGrid.innerHTML = sixQuestions.map(item => `
    <div style="background:rgba(11,22,42,0.74); border:1px solid rgba(136,212,255,0.16); border-radius:10px; padding:8px 10px;">
      <div style="font-size:0.71rem; font-weight:700; color:#88D4FF;">${escapeHtml(item.q)}</div>
      <div style="font-size:0.74rem; color:var(--text-2); margin-top:3px; line-height:1.38;">${escapeHtml(item.a)}</div>
    </div>
  `).join('');

  const futures = [
    {
      key: 'BASELINE',
      title: '1. Baz Durum (Hiçbir Şey Yapılmazsa)',
      badge: 'MODEL ÇIKTISI · BAZ AKIŞ',
      badgeCls: 'crit',
      borderCol: 'rgba(248, 113, 113, 0.44)',
      capText: 'Kapasite: %42 · Kritik Darboğaz Riski Yüksek',
      desc: 'Müdahale uygulanmadığında şok 1. dereceden 2. ve 3. derece süreç düğümlerine yayılır; soğuk zincir ve temiz oda kalifikasyon kaybı büyür.'
    },
    {
      key: 'INTERVENTION',
      title: '2. Müdahale Senaryosu (Bu Adım Uygulanırsa)',
      badge: 'MODEL ÇIKTISI · MÜDAHALE',
      badgeCls: 'ok',
      borderCol: 'rgba(74, 222, 128, 0.44)',
      capText: 'Kapasite: %84 · Korunan Akış (+%42 Net Fark)',
      desc: 'Yedek enerji koridoru ve izole tampon devreye alınarak yayılım hızı kırılır; kritik düğümlerde eşik aşımı önlenir.'
    },
    {
      key: 'COMBINED_STRESS',
      title: '3. Birleşik Stres Senaryosu (Çoklu Şok)',
      badge: 'MODEL ÇIKTISI · BİRLEŞİK STRES',
      badgeCls: 'warn',
      borderCol: 'rgba(251, 191, 36, 0.44)',
      capText: 'Kapasite: %64 · Kısmi Koruma / Ek Önlem Gerekli',
      desc: 'Şebeke kesintisi ile eşzamanlı lojistik/su darboğazı birleştiğinde tekil müdahale kısmi koruma sağlar; çift kademeli mikroşebeke + UPW tamponu gerekir.'
    }
  ];

  const visibleFutures = activeTabFilter === 'ALL'
    ? futures
    : futures.filter(f => f.key === activeTabFilter);

  fDeck.innerHTML = visibleFutures.map(f => `
    <div style="background:rgba(10,19,36,0.88); border:1px solid ${f.borderCol}; border-radius:12px; padding:10px 12px; display:flex; flex-direction:column; gap:6px;">
      <div style="display:flex; align-items:center; justify-content:space-between; gap:6px; flex-wrap:wrap;">
        <strong style="font-size:0.84rem; color:var(--text-1);">${escapeHtml(f.title)}</strong>
        <span class="kpi-badge ${f.badgeCls}" style="font-size:0.65rem;">${escapeHtml(f.badge)}</span>
      </div>
      <div class="mono" style="font-size:0.78rem; font-weight:700; color:#E6C387;">${escapeHtml(f.capText)}</div>
      <div style="font-size:0.74rem; color:var(--text-2); line-height:1.4;">${escapeHtml(f.desc)}</div>
      <div style="font-size:0.68rem; color:var(--text-3);">Epistemik Sınır: Kalibre edilmemiş deterministik model skoru (gerçek olasılık değildir).</div>
    </div>
  `).join('');
}

function initCaelusSpatialInterfaceSystem() {
  // 1. Ensure #dunyam-stage-callout-card starts collapsed on initial load (before user selection)
  const calloutCard = document.getElementById('dunyam-stage-callout-card');
  if (calloutCard) {
    calloutCard.classList.add('is-collapsed');
  }
  updateCalloutProgressiveLayers();

  // 2. Wire Spatial Compass Trigger, Close button, Return to Stage button, and Alt+M / Escape keyboard shortcuts
  const compassTrig = document.getElementById('caelus-compass-trigger');
  const compassClose = document.getElementById('btn-close-compass-popover');
  const compassPop = document.getElementById('caelus-compass-popover');
  if (compassTrig) {
    compassTrig.addEventListener('click', (e) => {
      e.stopPropagation();
      toggleSpatialCompassPopover();
    });
  }
  if (compassClose) {
    compassClose.addEventListener('click', () => toggleSpatialCompassPopover(false));
  }

  // Dismiss first-run orientation hint
  const btnDismissHint = document.getElementById('btn-dismiss-spatial-onboarding');
  const hintBox = document.getElementById('caelus-spatial-onboarding-hint');
  if (btnDismissHint && hintBox) {
    btnDismissHint.addEventListener('click', () => {
      hintBox.classList.add('hidden');
    });
  }

  // Left world whisper collapse/expand button
  const btnWhisperToggle = document.getElementById('btn-dunyam-whisper-toggle');
  const whisperBox = document.getElementById('dunyam-hero-whisper-box');
  if (btnWhisperToggle && whisperBox) {
    btnWhisperToggle.addEventListener('click', () => {
      const collapsed = whisperBox.classList.toggle('is-whisper-collapsed');
      btnWhisperToggle.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
      btnWhisperToggle.textContent = collapsed ? '▸' : '▾';
    });
  }

  // Global keyboard shortcuts: Alt+M toggles spatial compass; Escape closes open spatial popovers/inspectors
  document.addEventListener('keydown', (e) => {
    if (e.altKey && (e.key === 'm' || e.key === 'M' || e.code === 'KeyM')) {
      e.preventDefault();
      toggleSpatialCompassPopover();
      return;
    }
    if (e.key === 'Escape') {
      if (compassPop && !compassPop.classList.contains('hidden')) {
        toggleSpatialCompassPopover(false);
      }
      const tlPop = document.getElementById('caelus-time-lens-popover');
      const btnTl = document.getElementById('btn-stage-time-lens');
      if (tlPop && !tlPop.classList.contains('hidden')) {
        tlPop.classList.add('hidden');
        if (btnTl) btnTl.setAttribute('aria-expanded', 'false');
      }
      const provPop = document.getElementById('caelus-provenance-drawer');
      const btnProv = document.getElementById('btn-stage-provenance-lens');
      if (provPop && !provPop.classList.contains('hidden')) {
        provPop.classList.add('hidden');
        if (btnProv) btnProv.setAttribute('aria-expanded', 'false');
      }
    }
  });

  // 3. Wire Bitemporal Time Lens Pod & Popover
  renderAndOpenTimeLensPopover('2021-03-17T23:59:59Z', false);
  const btnStageTl = document.getElementById('btn-stage-time-lens');
  const btnCloseTl = document.getElementById('btn-close-time-lens');
  const tlPop = document.getElementById('caelus-time-lens-popover');
  if (btnStageTl && tlPop) {
    btnStageTl.addEventListener('click', () => {
      const isHidden = tlPop.classList.contains('hidden');
      if (isHidden) {
        renderAndOpenTimeLensPopover(window.cActiveTimeLensCutoffIso || '2021-03-17T23:59:59Z', true);
      } else {
        tlPop.classList.add('hidden');
        btnStageTl.setAttribute('aria-expanded', 'false');
      }
    });
  }
  if (btnCloseTl && tlPop) {
    btnCloseTl.addEventListener('click', () => {
      tlPop.classList.add('hidden');
      if (btnStageTl) btnStageTl.setAttribute('aria-expanded', 'false');
    });
  }
  document.querySelectorAll('#time-lens-preset-bar [data-tl-cutoff]').forEach(btn => {
    btn.addEventListener('click', () => {
      renderAndOpenTimeLensPopover(btn.getAttribute('data-tl-cutoff'), true);
    });
  });
  const inpTlDate = document.getElementById('inp-time-lens-cutoff-date');
  if (inpTlDate) {
    inpTlDate.addEventListener('change', () => {
      if (inpTlDate.value) {
        renderAndOpenTimeLensPopover(`${inpTlDate.value}T23:59:59Z`, true);
      }
    });
  }
  const btnTlScenario = document.getElementById('btn-time-lens-launch-scenario');
  if (btnTlScenario) {
    btnTlScenario.addEventListener('click', () => {
      if (tlPop) tlPop.classList.add('hidden');
      if (btnStageTl) btnStageTl.setAttribute('aria-expanded', 'false');
      switchQuietView('senaryolar');
    });
  }
  const btnTlHafiza = document.getElementById('btn-time-lens-open-full-hafiza');
  if (btnTlHafiza) {
    btnTlHafiza.addEventListener('click', () => {
      if (tlPop) tlPop.classList.add('hidden');
      if (btnStageTl) btnStageTl.setAttribute('aria-expanded', 'false');
      switchQuietView('hafiza');
    });
  }

  // 4. Wire Contextual Provenance Drawer
  renderAndOpenProvenanceDrawer(false);
  const btnStageProv = document.getElementById('btn-stage-provenance-lens');
  const btnCloseProv = document.getElementById('btn-close-provenance-drawer');
  const provPop = document.getElementById('caelus-provenance-drawer');
  if (btnStageProv && provPop) {
    btnStageProv.addEventListener('click', () => {
      const isHidden = provPop.classList.contains('hidden');
      if (isHidden) {
        renderAndOpenProvenanceDrawer(true);
      } else {
        provPop.classList.add('hidden');
        btnStageProv.setAttribute('aria-expanded', 'false');
      }
    });
  }
  if (btnCloseProv && provPop) {
    btnCloseProv.addEventListener('click', () => {
      provPop.classList.add('hidden');
      if (btnStageProv) btnStageProv.setAttribute('aria-expanded', 'false');
    });
  }
  const btnProvOpenBag = document.getElementById('btn-provenance-open-baglantilar');
  if (btnProvOpenBag) {
    btnProvOpenBag.addEventListener('click', () => {
      if (provPop) provPop.classList.add('hidden');
      if (btnStageProv) btnStageProv.setAttribute('aria-expanded', 'false');
      switchQuietView('baglantilar');
    });
  }

  // Wire Callout progressive action buttons (#btn-callout-open-provenance, #btn-callout-open-timelens)
  const btnCalloutProv = document.getElementById('btn-callout-open-provenance');
  if (btnCalloutProv) {
    btnCalloutProv.addEventListener('click', () => renderAndOpenProvenanceDrawer(true));
  }
  const btnCalloutTl = document.getElementById('btn-callout-open-timelens');
  if (btnCalloutTl) {
    btnCalloutTl.addEventListener('click', () => renderAndOpenTimeLensPopover(window.cActiveTimeLensCutoffIso || '2021-03-17T23:59:59Z', true));
  }

  // 5. Wire 3-Tier Performance Mode Switcher (FULL / BALANCED / LITE_2D)
  document.querySelectorAll('#caelus-perf-mode-switcher [data-perf-mode]').forEach(btn => {
    btn.addEventListener('click', () => {
      setCaelusSpatialPerfMode(btn.getAttribute('data-perf-mode'));
    });
  });

  // 6. Wire Cytoscape Hop Depth Bar (1 / 2 / 3 hops) & Mobile Step-by-Step Path List
  document.querySelectorAll('#kesfet-cy-hop-bar [data-cy-hop]').forEach(btn => {
    btn.addEventListener('click', () => {
      applyCytoscapeHopDepth(Number(btn.getAttribute('data-cy-hop')) || 1);
    });
  });
  renderKesfetStepPathList();

  // 7. Wire Scenarios 6 Core Questions & 3 Competing Futures Deck + Mobile Tab Switcher
  renderScenariosSixQuestionsAndThreeFutures('ALL');
  document.querySelectorAll('#senaryolar-mobile-future-tabs [data-future-tab]').forEach(btn => {
    btn.addEventListener('click', () => {
      const tabKey = btn.getAttribute('data-future-tab') || 'ALL';
      document.querySelectorAll('#senaryolar-mobile-future-tabs [data-future-tab]').forEach(b => {
        const active = b === btn;
        b.classList.toggle('active', active);
        b.setAttribute('aria-selected', active ? 'true' : 'false');
      });
      renderScenariosSixQuestionsAndThreeFutures(tabKey);
    });
  });

  // Expose spatial interface helpers for automated tests
  window.toggleSpatialCompassPopover = toggleSpatialCompassPopover;
  window.renderAndOpenTimeLensPopover = renderAndOpenTimeLensPopover;
  window.renderAndOpenProvenanceDrawer = renderAndOpenProvenanceDrawer;
  window.setCaelusSpatialPerfMode = setCaelusSpatialPerfMode;
  window.applyCytoscapeHopDepth = applyCytoscapeHopDepth;
  window.renderScenariosSixQuestionsAndThreeFutures = renderScenariosSixQuestionsAndThreeFutures;

  // 8. Wire 4 Primary Quick Actions (1. Bir durumu incele, 2. Seçenekleri karşılaştır, 3. Kendi dosyanı kullan, 4. Önceki çalışmalarını aç)
  document.querySelectorAll('[data-quick-action]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const act = btn.getAttribute('data-quick-action');
      toggleSpatialCompassPopover(false);
      if (act === 'inspect-state') {
        switchQuietView('dunyam');
        const callout = document.getElementById('dunyam-stage-callout-card');
        if (callout) callout.classList.remove('is-collapsed');
        updateCalloutProgressiveLayers();
      } else if (act === 'compare-options') {
        switchQuietView('senaryolar');
      } else if (act === 'use-own-file') {
        switchQuietView('dunyam');
        if (typeof toggleFirstRealTaskDrawer === 'function') {
          toggleFirstRealTaskDrawer(true);
        }
      } else if (act === 'open-history') {
        switchQuietView('hafiza');
      }
    });
  });

  if (window.CaelusSpatialExperience && typeof window.CaelusSpatialExperience.initSpatialStageExperience === 'function') {
    window.CaelusSpatialExperience.initSpatialStageExperience();
  }
}

// ============================================================================
// CAELUS İLK GERÇEK GÖREV (9 ADIMLI KULLANICI VERİSİ, DÜNYA MODELİ VE RAPOR STÜDYOSU)
// ============================================================================

const cFirstRealTaskState = {
  activeCaseId: 'VAKA_A',
  customReadReport: null,
  customFileName: null,
  selectedSheetName: null,
  selectedDelimiter: '',
  columnOverrides: {},
  dedupDecisions: {},
  questionTr: '',
  workflowResult: null,
  transferredToStage: false
};

function renderFirstRealTaskDrawerUI() {
  const eng = window.CaelusFirstRealTaskEngine;
  const drawer = document.getElementById('caelus-first-real-task-drawer');
  if (!eng || !drawer) return null;

  const activeLocale = (typeof state !== 'undefined' && state.activeLocaleCode) ? state.activeLocaleCode : 'tr-TR';
  const wf = eng.runCompleteFirstRealTaskWorkflow({
    caseId: cFirstRealTaskState.activeCaseId,
    readReport: cFirstRealTaskState.customReadReport || null,
    fileName: cFirstRealTaskState.customFileName || undefined,
    sheetName: cFirstRealTaskState.selectedSheetName || undefined,
    delimiter: cFirstRealTaskState.selectedDelimiter || undefined,
    columnOverrides: cFirstRealTaskState.columnOverrides,
    dedupDecisions: cFirstRealTaskState.dedupDecisions,
    mergeConfirmedCandidates: false,
    questionTr: cFirstRealTaskState.questionTr || undefined,
    locale: activeLocale
  });
  cFirstRealTaskState.workflowResult = wf;

  if (!wf.ok) {
    const summaryEl = document.getElementById('frt-file-summary-strip');
    if (summaryEl) {
      summaryEl.innerHTML = `<span style="color:#F87171; font-weight:700;">[✖ DOSYA OKUMA HATASI — ${escapeHtml(wf.read_report?.error_code || 'HATA')}]:</span> ${escapeHtml(wf.read_report?.error_message || 'Dosya okunamadı.')}`;
    }
    return wf;
  }

  // Adım 1: Dosya, Sayfa ve Güvenlik Özeti
  const fileBadge = document.getElementById('frt-active-file-badge');
  if (fileBadge) {
    fileBadge.textContent = `Dosya: ${wf.read_report.source_file} (${wf.selected_sheet_name})`;
  }
  const sheetSelect = document.getElementById('frt-sheet-select');
  if (sheetSelect) {
    sheetSelect.innerHTML = (wf.read_report.sheet_names || [])
      .map(
        (sn) =>
          `<option value="${escapeHtml(sn)}" ${sn === wf.selected_sheet_name ? 'selected' : ''}>Sayfa: ${escapeHtml(sn)}</option>`
      )
      .join('');
  }
  const summaryEl = document.getElementById('frt-file-summary-strip');
  if (summaryEl) {
    const warnHtml = (wf.read_report.warnings || [])
      .map((w) => `<div style="color:#FBBF24; margin-top:3px;">[◆ UYARI] ${escapeHtml(w)}</div>`)
      .join('');
    summaryEl.innerHTML = `
      <div>
        <strong>[● KAYNAK DOSYA]:</strong> <code>${escapeHtml(wf.read_report.source_file)}</code> ·
        <strong>SHA-256 (FIPS 180-4):</strong> <code>${escapeHtml(wf.read_report.source_hash_sha256.slice(0, 20))}…</code> ·
        <strong>Geçerli Satır:</strong> <strong>${wf.data_package.valid_record_count}</strong> / ${wf.data_package.total_data_rows} ·
        <strong>Makro Politikası:</strong> <code>${escapeHtml(wf.read_report.macro_policy)}</code>
      </div>
      ${warnHtml}
    `;
  }

  // Adım 2: Sütun Eşleme Tablosu
  const mapStatusBadge = document.getElementById('frt-mapping-status-badge');
  if (mapStatusBadge) {
    mapStatusBadge.textContent = wf.mapping_result.requiredRolesSatisfied
      ? '✓ Zorunlu Alanlar Eşlendi'
      : '⚠ Kaynak Varlık Alanı Seçilmeli';
    mapStatusBadge.className = 'kpi-badge ' + (wf.mapping_result.requiredRolesSatisfied ? 'ok' : 'warn');
  }
  const mapTbody = document.getElementById('frt-mapping-tbody');
  if (mapTbody) {
    const roleOptions = wf.mapping_result.availableRoles || [];
    mapTbody.innerHTML = (wf.mapping_result.proposals || [])
      .map((p) => {
        const optsHtml = roleOptions
          .map(
            (r) =>
              `<option value="${escapeHtml(r.roleId)}" ${r.roleId === p.effectiveRole ? 'selected' : ''}>${escapeHtml(r.labelTr)}</option>`
          )
          .join('');
        return `
          <tr>
            <td><code>${escapeHtml(p.columnLetter)}</code></td>
            <td><strong>${escapeHtml(p.originalHeader)}</strong><br/><span style="color:#94A3B8; font-size:0.70rem;">norm: ${escapeHtml(p.normalizedHeader)}</span></td>
            <td><code>${escapeHtml(p.inferredType)}</code><br/><span style="color:#CBD5E1; font-size:0.70rem;">Örn: ${escapeHtml((p.sampleValues || []).slice(0, 2).join(', '))}</span></td>
            <td>
              <select class="select-enterprise frt-role-select" data-col-idx="${p.columnIndex}" aria-label="${escapeHtml(p.originalHeader)} için CAELUS alanı seçin" style="font-size:0.73rem; padding:3px 6px; width:100%;">
                ${optsHtml}
              </select>
            </td>
            <td>
              <span class="kpi-badge ${p.mappingMethod === 'USER_OVERRIDE_CONFIRMED' ? 'accent' : 'ok'}" style="font-size:0.66rem;">${escapeHtml(p.confidenceClass)}</span>
              <div style="margin-top:2px; color:#E2E8F0; font-size:0.71rem;">${escapeHtml(p.ruleExplanationTr)}</div>
            </td>
          </tr>
        `;
      })
      .join('');

    mapTbody.querySelectorAll('.frt-role-select').forEach((sel) => {
      sel.addEventListener('change', () => {
        const colIdx = Number(sel.getAttribute('data-col-idx'));
        cFirstRealTaskState.columnOverrides[colIdx] = sel.value;
        renderFirstRealTaskDrawerUI();
      });
    });
  }

  // Adım 3: Satır Bazlı Doğrulama Hataları ve Formül Denetimi
  const errBadge = document.getElementById('frt-error-count-badge');
  if (errBadge) {
    errBadge.textContent = `[✖ ${wf.data_package.import_errors.length} Doğrulama Hatası (${wf.data_package.error_row_count} Satır İzole)]`;
  }
  const errListEl = document.getElementById('frt-errors-list');
  if (errListEl) {
    const errItems = (wf.data_package.import_errors || []).map(
      (err) => `
        <div style="background:rgba(127,29,29,0.32); border:1px solid rgba(248,113,113,0.45); border-radius:8px; padding:6px 8px;">
          <div><strong>[✖ Satır ${err.source_row} · ${escapeHtml(err.column_name)}]</strong> <code>${escapeHtml(err.error_code)}</code></div>
          <div style="color:#FECACA;">${escapeHtml(err.reason_tr)}</div>
          <div style="color:#FDE68A; font-size:0.71rem;"><strong>Öneri:</strong> ${escapeHtml(err.remediation_tr)}</div>
        </div>
      `
    );
    const formulaItems = (wf.data_package.formula_audit_entries || [])
      .filter((f) => f.formula_status === 'FORMULA_UNCOMPUTED')
      .map(
        (f) => `
          <div style="background:rgba(120,53,15,0.32); border:1px solid rgba(251,191,36,0.45); border-radius:8px; padding:6px 8px;">
            <div><strong>[◆ Hücre ${escapeHtml(f.cell_ref)} · Hesaplanmamış Formül]</strong> <code>${escapeHtml(f.formula_expression)}</code></div>
            <div style="color:#FDE68A;">${escapeHtml(f.explanation_tr)}</div>
          </div>
        `
      );
    errListEl.innerHTML =
      errItems.concat(formulaItems).join('') ||
      '<div style="color:#4ADE80;">[● TAM DOĞRULANDI] Bu sayfada satır hatası bulunmadı.</div>';
  }

  // Adım 4: Varlık Tekilleştirme Adayları (Birleştir / Ayrı Tut)
  const dedupBadge = document.getElementById('frt-dedup-count-badge');
  if (dedupBadge) {
    dedupBadge.textContent = `${wf.dedup_report.candidate_count} Aday Küme`;
  }
  const dedupListEl = document.getElementById('frt-dedup-list');
  if (dedupListEl) {
    dedupListEl.innerHTML =
      (wf.dedup_report.candidates || [])
        .map((c) => {
          const isMerged = c.decision === 'MERGE';
          const isSeparate = c.decision === 'KEEP_SEPARATE';
          return `
            <div style="background:rgba(15,31,58,0.84); border:1px solid rgba(56,189,248,0.38); border-radius:8px; padding:8px 10px; display:flex; flex-direction:column; gap:5px;">
              <div style="display:flex; align-items:center; justify-content:space-between; gap:6px; flex-wrap:wrap;">
                <strong>Kanonik Öneri: ${escapeHtml(c.suggested_canonical_name)}</strong>
                <span class="kpi-badge ${isMerged ? 'ok' : isSeparate ? 'warn' : 'accent'}" style="font-size:0.68rem;">
                  Karar: ${isMerged ? 'BİRLEŞTİRİLDİ' : isSeparate ? 'AYRI TUTULDU' : 'KULLANICI ONAYI BEKLİYOR'}
                </span>
              </div>
              <div style="color:#CBD5E1; font-size:0.72rem;">${escapeHtml(c.conflicting_fields.join(' | '))}</div>
              <div style="color:#93C5FD; font-size:0.71rem;">${escapeHtml(c.rule_explanation_tr)}</div>
              <div style="display:flex; gap:6px; flex-wrap:wrap; margin-top:2px;">
                <button type="button" class="btn btn-sm ${isMerged ? 'btn-primary' : ''}" data-dedup-cluster="${escapeHtml(c.cluster_id)}" data-dedup-action="MERGE">✓ Birleştir (Tek Varlık Yap)</button>
                <button type="button" class="btn btn-sm ${isSeparate ? 'btn-accent' : ''}" data-dedup-cluster="${escapeHtml(c.cluster_id)}" data-dedup-action="KEEP_SEPARATE">⇄ Ayrı Tut (Farklı Kurumlar)</button>
              </div>
            </div>
          `;
        })
        .join('') || '<div style="color:#CBD5E1;">Tekilleştirme gerektiren mükerrer yazımlı varlık bulunmadı.</div>';

    dedupListEl.querySelectorAll('[data-dedup-action]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const cid = btn.getAttribute('data-dedup-cluster');
        const act = btn.getAttribute('data-dedup-action');
        cFirstRealTaskState.dedupDecisions[cid] = act;
        renderFirstRealTaskDrawerUI();
      });
    });
  }

  // Adım 5 & 6: Dünya Özeti ve Soru
  const qInput = document.getElementById('frt-question-input');
  if (qInput && !cFirstRealTaskState.questionTr) {
    qInput.value = wf.comparison_result.question_tr;
  }
  const incRep = wf.world_model.entity_inclusion_report || {
    total_entity_count: wf.world_model.entity_count,
    included_entity_count: wf.world_model.entity_count,
    excluded_entity_count: 0
  };
  const transferSummaryEl = document.getElementById('frt-world-transfer-summary');
  if (transferSummaryEl) {
    transferSummaryEl.innerHTML = `
      <strong>[● DÜNYA MODELİ HAZIR]:</strong> Dünya Kimliği: <code>${escapeHtml(wf.world_model.world_id)}</code> ·
      <strong>Dahil Edilen Varlık:</strong> <strong>${incRep.included_entity_count} / ${incRep.total_entity_count}</strong> (Hariç Tutulan: ${incRep.excluded_entity_count} · Sessiz Kırpma: Yok) ·
      <strong>${wf.world_model.relation_count}</strong> Doğrulanmış İlişki ·
      <strong>${wf.world_model.assumptions.length}</strong> Açık Varsayım.
    `;
  }

  // Adım 7: İki Seçeneği Karşılaştır
  const recBadge = document.getElementById('frt-recommended-option-badge');
  if (recBadge) {
    recBadge.textContent = `${wf.comparison_result.stance_label_tr || 'Önerilen'}: ${wf.comparison_result.recommended_option_id}`;
  }
  const cmpBox = document.getElementById('frt-comparison-box');
  if (cmpBox) {
    const cmp = wf.comparison_result;
    const nodeRowsHtml = (cmp.node_comparisons || [])
      .map(
        (nc) => `
          <tr>
            <td><strong>${escapeHtml(nc.node_label)}</strong><br/><code>${escapeHtml(nc.node_id)}</code></td>
            <td>${nc.baseline_stress}</td>
            <td><strong>${nc.option1_stress}</strong> (${nc.option1_net_relief})</td>
            <td><strong>${nc.option2_stress}</strong> (${nc.option2_net_relief})</td>
            <td><code>[▲ ${escapeHtml(nc.epistemic_class)}]</code></td>
            <td>${escapeHtml(nc.source_file)}#${escapeHtml(nc.source_sheet)}:Satır [${escapeHtml(nc.source_rows.join(', '))}]<br/><span style="color:#93C5FD;">${escapeHtml(nc.dedup_decision)}</span></td>
          </tr>
        `
      )
      .join('');

    cmpBox.innerHTML = `
      <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(220px, 1fr)); gap:8px;">
        <div style="background:rgba(15,23,42,0.85); border:1px solid rgba(148,163,184,0.35); border-radius:8px; padding:8px 10px;">
          <div style="font-size:0.70rem; color:#94A3B8; font-weight:700;">[▲ SİMÜLASYON] MÜDAHALESİZ TEMEL AKIŞ</div>
          <div style="font-size:1.05rem; font-weight:800; color:#F87171;">Sistem Baskısı: ${cmp.baseline.system_stress_score}</div>
          <div style="font-size:0.72rem; color:#CBD5E1;">Hiçbir müdahale uygulanmadığında 24 adım sonundaki yayılım</div>
        </div>
        <div style="background:rgba(15,38,32,0.85); border:1px solid rgba(74,222,128,0.45); border-radius:8px; padding:8px 10px;">
          <div style="font-size:0.70rem; color:#4ADE80; font-weight:700;">[▲ SİMÜLASYON] SEÇENEK 1 (VARSAYIMA BAĞLI ÖNERİ)</div>
          <div style="font-size:1.05rem; font-weight:800; color:#4ADE80;">Baskı: ${cmp.option_1.system_stress_score} (${cmp.option_1.delta_vs_baseline})</div>
          <div style="font-size:0.72rem; color:#E2E8F0;">${escapeHtml(cmp.option_1.intervention_label)}</div>
        </div>
        <div style="background:rgba(15,28,52,0.85); border:1px solid rgba(56,189,248,0.40); border-radius:8px; padding:8px 10px;">
          <div style="font-size:0.70rem; color:#38BDF8; font-weight:700;">[▲ SİMÜLASYON] SEÇENEK 2 (ALTERNATİF)</div>
          <div style="font-size:1.05rem; font-weight:800; color:#38BDF8;">Baskı: ${cmp.option_2.system_stress_score} (${cmp.option_2.delta_vs_baseline})</div>
          <div style="font-size:0.72rem; color:#E2E8F0;">${escapeHtml(cmp.option_2.intervention_label)}</div>
        </div>
      </div>
      <div style="padding:8px 10px; background:rgba(12,24,44,0.85); border-left:3px solid #E6C387; border-radius:6px; color:#F1F5F9;">
        <div><strong>Karar Dayanağı (${escapeHtml(cmp.stance_label_tr || 'Varsayıma Bağlı Karşılaştırma')}):</strong> ${escapeHtml(cmp.recommendation_explanation_tr)}</div>
        <div style="margin-top:4px; font-size:0.71rem; color:#93C5FD;">
          <strong>Hesaplama Motoru:</strong> ${escapeHtml(cmp.calculation_engine_label_tr || cmp.calculation_engine || '')} ·
          <strong>Kullanılan Alanlar:</strong> ${escapeHtml((cmp.used_fields_in_calculation || []).join(', '))} ·
          <strong>Hesaba Katılmayan Alanlar:</strong> ${escapeHtml((cmp.unused_fields_in_calculation || []).join(', '))}
        </div>
      </div>
      <div class="caelus-frt-table-wrap">
        <table class="caelus-frt-table">
          <thead>
            <tr>
              <th>Varlık / Düğüm</th>
              <th>Müdahalesiz</th>
              <th>Seçenek 1 Sonrası</th>
              <th>Seçenek 2 Sonrası</th>
              <th>Bilgi Sınıfı</th>
              <th>Kaynak Dosya # Sayfa : Satır ve Tekilleştirme</th>
            </tr>
          </thead>
          <tbody>${nodeRowsHtml}</tbody>
        </table>
      </div>
    `;
  }

  // Adım 8: Satır Bazlı Kaynak İzi Tablosu
  const provTbody = document.getElementById('frt-provenance-tbody');
  if (provTbody) {
    provTbody.innerHTML = (wf.data_package.records || [])
      .map(
        (r) => `
          <tr>
            <td><code>[● ${escapeHtml(r.epistemic_status)}]</code></td>
            <td><strong>${escapeHtml(r.entity_name)}</strong><br/><code>${escapeHtml(r.record_id)}</code></td>
            <td>${escapeHtml(r.relation_type)} → <strong>${escapeHtml(r.target_entity_name || '-')}</strong><br/>Değer: ${r.value} ${escapeHtml(r.unit)} (Kritiklik: ${r.criticality_weight})</td>
            <td><code>${escapeHtml(r.source_file)}#${escapeHtml(r.source_sheet)}:Satır ${r.source_row}</code><br/><span style="color:#94A3B8; font-size:0.69rem;">SHA: ${escapeHtml(r.source_hash.slice(0, 14))}…</span></td>
            <td>Olay: <code>${escapeHtml(r.occurred_at.slice(0, 10))}</code><br/>Öğrenilme: <code>${escapeHtml(r.learned_at.slice(0, 10))}</code></td>
            <td><code>${escapeHtml(r.mapping_method)}</code><br/>Onay: <strong>${escapeHtml(r.user_confirmation)}</strong></td>
          </tr>
        `
      )
      .join('');
  }

  return wf;
}

function transferFirstRealTaskWorldToStage() {
  const wf = cFirstRealTaskState.workflowResult || renderFirstRealTaskDrawerUI();
  if (!wf || !wf.ok) return false;

  cFirstRealTaskState.transferredToStage = true;
  const pack = wf.world_model.scenario_pack;
  if (pack && pack.extended_causal_model) {
    state.activeScenario = pack.id;
    state.scenarioPack = pack;
    state.causalNodes = pack.extended_causal_model.nodes.map((n, idx) => ({
      id: n.id,
      label: n.label,
      kind: n.kind,
      state: n.state_fp / 1000000,
      reportedState: n.reported_state_fp / 1000000,
      trust: n.trust_fp / 1000000,
      capacity: n.capacity_fp / 1000000,
      weight: n.weight_fp / 1000000,
      deadlineTick: n.deadline_tick,
      irrecoverable: Boolean(n.irrecoverable),
      notes: n.notes,
      provenance: n.provenance,
      x: 0.18 + (idx % 4) * 0.21,
      y: 0.28 + Math.floor(idx / 4) * 0.36
    }));
    state.causalEdges = pack.extended_causal_model.edges
      .filter((e) => e.to !== '')
      .map((e) => ({
        from: e.from,
        to: e.to,
        multiplier: e.multiplier_fp / 1000000,
        lag: e.lag_ticks,
        active: e.active
      }));
  }

  const worldTitleEl = document.getElementById('dunyam-world-title');
  if (worldTitleEl) {
    worldTitleEl.textContent = `Kullanıcı Dünya Modeli — ${wf.data_package.source_file}`;
  }
  const statusSentEl = document.getElementById('dunyam-status-sentence');
  if (statusSentEl) {
    statusSentEl.textContent = `${wf.data_package.source_file} (${wf.selected_sheet_name}) içinden ${wf.world_model.entity_count} varlık ve ${wf.world_model.relation_count} doğrulanmış ilişki sahneye aktarıldı. Önerilen müdahale: ${wf.comparison_result.recommended_option_label}.`;
  }
  const srcBadgeEl = document.getElementById('dunyam-source-badge');
  if (srcBadgeEl) {
    srcBadgeEl.textContent = `Bilginin kaynağı: Kullanıcı Verisi (${wf.data_package.source_file})`;
  }

  if (typeof drawCausalGraph === 'function') drawCausalGraph();
  if (typeof drawDunyamHeroStage === 'function') drawDunyamHeroStage();
  if (typeof updateCalloutProgressiveLayers === 'function') updateCalloutProgressiveLayers();
  if (typeof renderAndOpenProvenanceDrawer === 'function') renderAndOpenProvenanceDrawer(false);
  if (typeof renderAndOpenTimeLensPopover === 'function') {
    renderAndOpenTimeLensPopover(window.cActiveTimeLensCutoffIso || '2021-03-17T23:59:59Z', false);
  }

  const transferSummaryEl = document.getElementById('frt-world-transfer-summary');
  if (transferSummaryEl) {
    transferSummaryEl.innerHTML = `<span style="color:#4ADE80; font-weight:700;">✓ SAHNEYE AKTARILDI:</span> <code>${escapeHtml(wf.world_model.world_id)}</code> (${wf.world_model.entity_count} varlık, ${wf.world_model.relation_count} ilişki) 3B/2B sahneye, Kaynak İzi çekmecesine, Zaman Merceğine ve deterministik senaryo motoruna bağlandı.`;
  }
  return true;
}

function toggleFirstRealTaskDrawer(forceOpen) {
  const drawer = document.getElementById('caelus-first-real-task-drawer');
  const btn = document.getElementById('btn-stage-first-real-task');
  if (!drawer) return;
  const willOpen = typeof forceOpen === 'boolean' ? forceOpen : drawer.classList.contains('hidden');
  if (willOpen) {
    drawer.classList.remove('hidden');
    if (btn) btn.setAttribute('aria-expanded', 'true');
    renderFirstRealTaskDrawerUI();
  } else {
    drawer.classList.add('hidden');
    if (btn) btn.setAttribute('aria-expanded', 'false');
  }
}

function initCaelusFirstRealTaskSystem() {
  const eng = window.CaelusFirstRealTaskEngine;
  if (!eng) return;

  // Varsayılan Vaka A ile ilk durumu hazırla
  cFirstRealTaskState.dedupDecisions['DEDUP_ALFA_TEKNOLOJI'] = 'MERGE';
  renderFirstRealTaskDrawerUI();

  const btnOpen = document.getElementById('btn-stage-first-real-task');
  const btnClose = document.getElementById('btn-close-first-real-task-drawer');
  if (btnOpen) {
    btnOpen.addEventListener('click', () => toggleFirstRealTaskDrawer());
  }
  if (btnClose) {
    btnClose.addEventListener('click', () => toggleFirstRealTaskDrawer(false));
  }

  // Klavye kısayolu: Alt+V
  document.addEventListener('keydown', (e) => {
    if (e.altKey && (e.key === 'v' || e.key === 'V' || e.code === 'KeyV')) {
      e.preventDefault();
      toggleFirstRealTaskDrawer();
    }
  });

  // 9 Adım Sekme Gezinmesi
  document.querySelectorAll('#frt-step-nav-bar [data-frt-step]').forEach((btn) => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('#frt-step-nav-bar [data-frt-step]').forEach((b) => {
        const active = b === btn;
        b.classList.toggle('active', active);
        b.setAttribute('aria-selected', active ? 'true' : 'false');
      });
      const stepNum = Number(btn.getAttribute('data-frt-step'));
      const targetMap = {
        1: 'frt-step-1-ingest',
        2: 'frt-step-2-mapping',
        3: 'frt-step-3-errors',
        4: 'frt-step-4-dedup',
        5: 'frt-step-5-6-world-scenario',
        6: 'frt-step-5-6-world-scenario',
        7: 'frt-step-7-compare',
        8: 'frt-step-8-provenance',
        9: 'frt-step-9-export'
      };
      const targetEl = document.getElementById(targetMap[stepNum]);
      if (targetEl && typeof targetEl.scrollIntoView === 'function') {
        targetEl.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    });
  });

  // Vaka A ve Vaka B Yükleme Butonları
  const btnVakaA = document.getElementById('btn-frt-load-vaka-a');
  if (btnVakaA) {
    btnVakaA.addEventListener('click', () => {
      cFirstRealTaskState.activeCaseId = 'VAKA_A';
      cFirstRealTaskState.customReadReport = null;
      cFirstRealTaskState.customFileName = null;
      cFirstRealTaskState.selectedSheetName = null;
      cFirstRealTaskState.columnOverrides = {};
      cFirstRealTaskState.dedupDecisions = { DEDUP_ALFA_TEKNOLOJI: 'MERGE' };
      cFirstRealTaskState.questionTr = '';
      cFirstRealTaskState.transferredToStage = false;
      renderFirstRealTaskDrawerUI();
    });
  }

  const btnVakaB = document.getElementById('btn-frt-load-vaka-b');
  if (btnVakaB) {
    btnVakaB.addEventListener('click', () => {
      cFirstRealTaskState.activeCaseId = 'VAKA_B';
      cFirstRealTaskState.customReadReport = null;
      cFirstRealTaskState.customFileName = null;
      cFirstRealTaskState.selectedSheetName = null;
      cFirstRealTaskState.columnOverrides = {};
      cFirstRealTaskState.dedupDecisions = { DEDUP_ULUSAL_VERI_MERKEZI: 'MERGE' };
      cFirstRealTaskState.questionTr = '';
      cFirstRealTaskState.transferredToStage = false;
      renderFirstRealTaskDrawerUI();
    });
  }

  // Bilgisayardan / Telefondan Gerçek Dosya Seçimi (.xlsx / .csv)
  const fileInput = document.getElementById('frt-file-input');
  if (fileInput) {
    fileInput.addEventListener('change', async () => {
      const file = fileInput.files && fileInput.files[0];
      if (!file) return;
      cFirstRealTaskState.customFileName = file.name;
      cFirstRealTaskState.columnOverrides = {};
      cFirstRealTaskState.dedupDecisions = {};
      cFirstRealTaskState.transferredToStage = false;
      const lower = file.name.toLowerCase();
      if (lower.endsWith('.xlsx') || lower.endsWith('.xlsm') || lower.endsWith('.ods')) {
        const ab = await file.arrayBuffer();
        cFirstRealTaskState.customReadReport = eng.parseOpenXmlXlsxBytes(new Uint8Array(ab), file.name);
      } else {
        const txt = await file.text();
        cFirstRealTaskState.customReadReport = eng.readCsvContent(txt, {
          fileName: file.name,
          delimiter: cFirstRealTaskState.selectedDelimiter || undefined
        });
      }
      cFirstRealTaskState.selectedSheetName =
        cFirstRealTaskState.customReadReport?.sheet_names?.[0] || null;
      renderFirstRealTaskDrawerUI();
    });
  }

  // Sayfa Seçici ve Ayırıcı Seçici
  const sheetSelect = document.getElementById('frt-sheet-select');
  if (sheetSelect) {
    sheetSelect.addEventListener('change', () => {
      cFirstRealTaskState.selectedSheetName = sheetSelect.value;
      renderFirstRealTaskDrawerUI();
    });
  }
  const delimSelect = document.getElementById('frt-delimiter-select');
  if (delimSelect) {
    delimSelect.addEventListener('change', () => {
      cFirstRealTaskState.selectedDelimiter = delimSelect.value;
      renderFirstRealTaskDrawerUI();
    });
  }

  // Adım 5 & 6: Dünyaya Aktar ve Senaryo Karşılaştır
  const btnTransfer = document.getElementById('btn-frt-transfer-to-world');
  if (btnTransfer) {
    btnTransfer.addEventListener('click', () => {
      transferFirstRealTaskWorldToStage();
    });
  }
  const btnRunCmp = document.getElementById('btn-frt-run-comparison');
  if (btnRunCmp) {
    btnRunCmp.addEventListener('click', () => {
      const qInput = document.getElementById('frt-question-input');
      if (qInput) cFirstRealTaskState.questionTr = qInput.value.trim();
      renderFirstRealTaskDrawerUI();
      transferFirstRealTaskWorldToStage();
    });
  }

  // Adım 9: Rapor Dışa Aktarma (.xlsx, HTML/PDF, Güvenli .csv)
  const statusBanner = document.getElementById('frt-export-status-banner');
  const btnExportXlsx = document.getElementById('btn-frt-export-xlsx');
  if (btnExportXlsx) {
    btnExportXlsx.addEventListener('click', () => {
      const wf = cFirstRealTaskState.workflowResult || renderFirstRealTaskDrawerUI();
      if (!wf || !wf.ok) return;
      const xlsxBytes = wf.export_builders.buildXlsxBytes();
      const sha = eng.computeSha256Hex(xlsxBytes);
      try {
        const blob = new Blob([xlsxBytes], {
          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `CAELUS_Aciklanabilir_Rapor_${wf.data_package.dataset_id}.xlsx`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1500);
      } catch (_) {}
      if (statusBanner) {
        statusBanner.innerHTML = `<strong>✓ 7 SAYFALI .XLSX RAPOR ÜRETİLDİ:</strong> <code>CAELUS_Aciklanabilir_Rapor_${escapeHtml(wf.data_package.dataset_id)}.xlsx</code> (${xlsxBytes.length} bayt · SHA-256: <code>${sha.slice(0, 16)}…</code> · Sayfalar: ${escapeHtml(wf.workbook_spec.sheet_titles.join(', '))}).`;
      }
    });
  }

  const btnExportHtmlPdf = document.getElementById('btn-frt-export-html-pdf');
  if (btnExportHtmlPdf) {
    btnExportHtmlPdf.addEventListener('click', () => {
      const wf = cFirstRealTaskState.workflowResult || renderFirstRealTaskDrawerUI();
      if (!wf || !wf.ok) return;
      const activeLocale = (typeof state !== 'undefined' && state.activeLocaleCode) ? state.activeLocaleCode : 'tr-TR';
      const htmlReport = wf.export_builders.buildPrintHtml({ locale: activeLocale });
      const dossierModal = document.getElementById('dossier-modal');
      const dossierContent = document.getElementById('dossier-content');
      if (dossierModal && dossierContent) {
        dossierContent.innerHTML = htmlReport;
        dossierModal.classList.remove('hidden');
      }
      if (statusBanner) {
        statusBanner.innerHTML = `<strong>✓ ÇOK SAYFALI HTML / PDF BASKI RAPORU AÇILDI (${escapeHtml(activeLocale)}):</strong> 7 bölüm ve kaynak izi tabloları (@media print uyumlu, ${htmlReport.length} bayt) görüntülenmeye ve PDF olarak kaydedilmeye hazır.`;
      }
    });
  }

  const btnExportCsv = document.getElementById('btn-frt-export-csv');
  if (btnExportCsv) {
    btnExportCsv.addEventListener('click', () => {
      const wf = cFirstRealTaskState.workflowResult || renderFirstRealTaskDrawerUI();
      if (!wf || !wf.ok) return;
      const safeCsv = wf.export_builders.buildSafeCsv();
      try {
        const blob = new Blob([safeCsv], { type: 'text/csv;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `CAELUS_Guvenli_Kaynak_Izli_Rapor_${wf.data_package.dataset_id}.csv`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1500);
      } catch (_) {}
      if (statusBanner) {
        statusBanner.innerHTML = `<strong>✓ GÜVENLİ .CSV RAPOR ÜRETİLDİ:</strong> Formül enjeksiyonuna (=, +, -, @, \\t, \\r) karşı korumalı <code>CAELUS_Guvenli_Kaynak_Izli_Rapor_${escapeHtml(wf.data_package.dataset_id)}.csv</code> (${safeCsv.length} bayt) kaydedildi.`;
      }
    });
  }

  window.toggleFirstRealTaskDrawer = toggleFirstRealTaskDrawer;
  window.renderFirstRealTaskDrawerUI = renderFirstRealTaskDrawerUI;
  window.transferFirstRealTaskWorldToStage = transferFirstRealTaskWorldToStage;
  window.cFirstRealTaskState = cFirstRealTaskState;
}

// ============================================================================
// YAŞAYAN DÜNYA KATMANI V2, LLM DIŞI KONUŞAN DANIŞMAN VE KİŞİSEL AJAN STÜDYOSU
// ============================================================================
function initCaelusLivingAdvisorAndAgentStudio() {
  const lwm = window.CaelusLivingWorldModel;
  const advMod = window.CaelusConversationalAdvisor;
  const stuMod = window.CaelusPersonalAgentStudio;
  const gateMod = window.CaelusWorldDataGate;

  const drawer = document.getElementById('caelus-living-advisor-agent-drawer');
  const openBtn = document.getElementById('btn-stage-living-advisor-studio');
  const closeBtn = document.getElementById('btn-close-living-advisor-studio');
  if (!drawer) return;

  // Üretim modunda ilk açılışta 0 sahte olgu, boş kullanıcı tercihi ve varsayılan çevrim dışı veri kapısı ile başlar
  const worldDataGate = gateMod && typeof gateMod.createWorldDataGate === 'function'
    ? gateMod.createWorldDataGate({ initialMode: 'OFFLINE' })
    : null;

  const advisorSession = advMod && typeof advMod.createConversationalAdvisorSession === 'function'
    ? advMod.createConversationalAdvisorSession({
        language: (typeof state !== 'undefined' && state.activeLocaleCode) || 'tr-TR',
        enableTrainingSampleMode: false
      })
    : null;

  const agentStudio = stuMod && typeof stuMod.createPersonalAgentStudio === 'function'
    ? stuMod.createPersonalAgentStudio({
        enableTrainingSampleMode: false
      })
    : null;

  const livingScheduler = lwm && typeof lwm.createLivingWorldScheduler === 'function'
    ? lwm.createLivingWorldScheduler({
        executionMode: 'YALNIZ_UYGULAMA_ACIKKEN',
        defaultEnabled: false
      })
    : null;

  function loadStarterAgentTemplatesOnDemand() {
    if (!agentStudio) return;
    if (!agentStudio.listAgents().some((a) => a.agent_id === 'agent-real-source-tracker-01')) {
      agentStudio.createAgent({
        agent_id: 'agent-real-source-tracker-01',
        name: '1. Gerçek Kaynak Takip Ajanı (Örnek Şablon)',
        purpose: 'İzin verilen açık kaynaklarda (Wikidata, World Bank, SEC EDGAR, OpenAlex) seçtiğiniz varlıklarla ilgili yeni kayıtları ve sendikasyon tekrarlarını izlemek.',
        capabilityType: 'TRACK_REAL_SOURCE',
        executionMode: 'APP_OPEN',
        allowed_sources: ['wikidata', 'world_bank', 'sec_edgar', 'openalex'],
        entities: ['TSMC', 'Turkiye'],
        network_access: true,
        local_file_read: false
      });
    }
    if (!agentStudio.listAgents().some((a) => a.agent_id === 'agent-user-file-inspector-02')) {
      agentStudio.createAgent({
        agent_id: 'agent-user-file-inspector-02',
        name: '2. Kullanıcı Dosyası İnceleme Ajanı (Örnek Şablon)',
        purpose: 'Yalnızca sizin yüklediğiniz ve izin verdiğiniz yerel CSV/TSV dosyasını okuyarak sütunları eşlemek, bozuk satırları yakalamak ve satır izi kurmak.',
        capabilityType: 'INSPECT_USER_FILE',
        executionMode: 'MANUAL',
        allowed_sources: ['user_local_file'],
        user_files: ['tedarik_secenekleri_2026.csv'],
        network_access: false,
        local_file_read: true
      });
    }
    if (!agentStudio.listAgents().some((a) => a.agent_id === 'agent-option-comparator-03')) {
      agentStudio.createAgent({
        agent_id: 'agent-option-comparator-03',
        name: '3. Seçenek Karşılaştırma ve Özet Ajanı (Örnek Şablon)',
        purpose: 'Seçenekleri maliyet, süre ve risk kriterlerine göre deterministik formülle karşılaştırmak ve birim uyumsuzluklarını yakalamak.',
        capabilityType: 'COMPARE_OPTIONS',
        executionMode: 'MANUAL',
        allowed_sources: ['user_local_file'],
        network_access: false,
        local_file_read: false,
        parameters: {
          options: [
            { name: 'Seçenek A (Yerel Hat)', cost: 142, currency: 'USD', durationDays: 18, riskScore: 15 },
            { name: 'Seçenek B (Uzun Mesafe Hat)', cost: 118, currency: 'USD', durationDays: 34, riskScore: 42 }
          ]
        }
      });
    }
  }

  let activeLaaTab = 'living-world';
  let activeLwSubview = 'DUNYA_SIMDI';

  function showSovereignFeedback(msgHtml, isWarn) {
    const el = document.getElementById('laa-sovereign-action-feedback');
    if (!el) return;
    el.classList.remove('hidden');
    el.style.background = isWarn ? 'rgba(120,53,15,0.55)' : 'rgba(16,82,56,0.45)';
    el.style.borderColor = isWarn ? '#F59E0B' : '#3DD68C';
    el.innerHTML = msgHtml;
  }

  function updateSovereignStatusBarAndPreview() {
    const summaryBadge = document.getElementById('laa-permitted-sources-summary');
    const modeSelect = document.getElementById('sel-laa-gate-mode');
    const sampleBadge = document.getElementById('laa-training-sample-badge');
    const sampleSepBadge = document.getElementById('laa-sample-separation-badge');
    const previewBox = document.getElementById('laa-outbound-query-preview');
    const sourceSelect = document.getElementById('sel-laa-source-id');
    const queryInput = document.getElementById('inp-laa-source-query-entity');

    if (worldDataGate) {
      const perms = worldDataGate.getSourcePermissionsAndStatus();
      const enabledCount = perms.filter((p) => p.enabled && !p.paused).length;
      const modeInfo = worldDataGate.getMode();
      if (summaryBadge) {
        summaryBadge.textContent = `Kip: ${modeInfo.labelTr} · İzinli Kaynak: ${enabledCount} / ${perms.length}`;
      }
      if (modeSelect && modeSelect.value !== modeInfo.code) {
        modeSelect.value = modeInfo.code;
      }
    }

    if (advisorSession) {
      const mem = advisorSession.inspectSeparatedMemory();
      const isSample = Boolean(mem.trainingSampleModeActive);
      if (sampleBadge) sampleBadge.classList.toggle('hidden', !isSample);
      if (sampleSepBadge) {
        sampleSepBadge.textContent = isSample
          ? '⚠️ Örnek veri (Eğitim Alanı Açık — Gerçek Hafızadan İzole)'
          : `Üretim Modu: ${mem.C_SOURCED_WORLD_MEMORY_COUNT} Gerçek Kayıt · 0 Sahte Olgu`;
      }
    }

    if (previewBox && gateMod && typeof gateMod.previewOutboundSourceQuery === 'function') {
      const sid = sourceSelect ? sourceSelect.value : 'wikidata';
      const qVal = queryInput ? queryInput.value.trim() : 'TSMC';
      const qParams = sid === 'wikidata'
        ? (/^Q\d+/i.test(qVal) ? { entityId: qVal } : { searchQuery: qVal || 'TSMC' })
        : sid === 'world_bank_indicators'
          ? { countries: qVal || 'TUR', indicator: 'NY.GDP.MKTP.KD.ZG' }
          : sid === 'sec_edgar_submissions'
            ? { cik: qVal || '0000320193' }
            : sid === 'openalex_scholarly'
              ? { search: qVal || 'supply chain' }
              : { query: qVal || 'semiconductor' };
      const prev = gateMod.previewOutboundSourceQuery(sid, qParams, {});
      previewBox.textContent = `🔒 Paylaşım Önizlemesi: ${prev.userPreviewTr || ''}`;
    }
  }

  function getActiveRecordsForDisplay() {
    if (!advisorSession) return [];
    const mem = advisorSession.inspectSeparatedMemory();
    if (mem.C_SOURCED_WORLD_MEMORY && mem.C_SOURCED_WORLD_MEMORY.length > 0) {
      return mem.C_SOURCED_WORLD_MEMORY;
    }
    if (mem.trainingSampleModeActive && advMod && typeof advMod.buildDefaultAdvisorWorldRecords === 'function') {
      return advMod.buildDefaultAdvisorWorldRecords();
    }
    return [];
  }

  function renderLivingWorldSubview() {
    const host = document.getElementById('laa-living-world-content');
    const emptyMsgEl = document.getElementById('laa-empty-world-message');
    if (!host || !lwm) return;

    updateSovereignStatusBarAndPreview();
    const memRecords = getActiveRecordsForDisplay();
    const isSampleActive = advisorSession ? Boolean(advisorSession.inspectSeparatedMemory().trainingSampleModeActive) : false;

    if (emptyMsgEl) {
      if (memRecords.length === 0) {
        emptyMsgEl.textContent = (advMod && advMod.EMPTY_WORLD_DATA_MESSAGE_TR)
          || 'Henüz gerçek dünya verisi alınmadı. Bir kaynak seçebilir veya dosya ekleyebilirsin.';
      } else if (isSampleActive && (!advisorSession || advisorSession.inspectSeparatedMemory().C_SOURCED_WORLD_MEMORY_COUNT === 0)) {
        emptyMsgEl.textContent = '⚠️ Örnek veri (Eğitim Alanı açık): Gösterilen kayıtlar eğitim amaçlıdır; gerçek dünya hafızasına aktarılmaz ve canlı kaynak doğrulaması sayılmaz.';
      } else {
        emptyMsgEl.textContent = `Gerçek kaynaklardan doğrulanmış şema ile alınan ${memRecords.length} kayıt yerel dünya hafızasında incelenmeye hazır.`;
      }
    }

    if (activeLwSubview === 'DUNYA_SIMDI') {
      const connectors = Array.isArray(lwm.REAL_WORLD_SOURCE_CONNECTORS_CATALOG)
        ? lwm.REAL_WORLD_SOURCE_CONNECTORS_CATALOG
        : Object.values(lwm.REAL_WORLD_SOURCE_CONNECTORS_CATALOG || {});
      const gatePerms = worldDataGate ? worldDataGate.getSourcePermissionsAndStatus() : [];
      const permById = {};
      gatePerms.forEach((p) => { permById[p.sourceId] = p; });

      const clock = typeof lwm.getSystemClockAndTimezoneState === 'function'
        ? lwm.getSystemClockAndTimezoneState()
        : { utcNowIso: new Date().toISOString(), timeZone: 'UTC' };

      const rowsHtml = connectors.map((c) => {
        const sid = c.source_id || c.sourceId || c.id || '';
        const name = c.name || c.displayName || sid;
        const lic = c.data_license || c.license || 'Açık Lisans';
        const comm = c.commercial_usage_status || c.commercialStatus || 'İNCELEMEDE';
        const domain = (c.domain_coverage || c.domains || []).join(', ');
        const gp = permById[sid] || { enabled: false, paused: false, lastSuccessAt: null, lastError: null, recordsCount: 0 };
        const statusBadge = gp.enabled && !gp.paused
          ? '<span class="kpi-badge ok">İZİNLİ</span>'
          : gp.paused
            ? '<span class="kpi-badge warn">DURAKLATILDI</span>'
            : '<span class="kpi-badge">KAPALI (Varsayılan)</span>';
        const syncInfo = gp.lastError
          ? `<span style="color:#F87171; font-size:0.68rem;">Hata: ${escapeHtml(gp.lastError.messageTr || gp.lastError.code || '')}</span>`
          : gp.lastSuccessAt
            ? `<span style="color:#4ADE80; font-size:0.68rem;">Son Başarılı: ${escapeHtml(String(gp.lastSuccessAt).slice(0, 19))} (${gp.recordsCount} kayıt)</span>`
            : '<span style="color:var(--text-2); font-size:0.68rem;">Henüz sorgulanmadı</span>';

        return `
          <tr>
            <td><strong>${escapeHtml(name)}</strong><br><code class="mono" style="font-size:0.68rem;">${escapeHtml(sid)}</code></td>
            <td>${escapeHtml(domain)}</td>
            <td><span class="kpi-badge ok">${escapeHtml(lic)}</span><br><span style="font-size:0.67rem; color:var(--text-2);">${escapeHtml(comm)}</span></td>
            <td>${statusBadge}<br>${syncInfo}</td>
            <td>
              <div style="display:flex; gap:4px; flex-wrap:wrap;">
                <button type="button" class="btn btn-sm" data-gate-toggle-source="${escapeHtml(sid)}">${gp.enabled ? 'İzni Kapat' : 'İzin Ver'}</button>
                <button type="button" class="btn btn-sm btn-primary" data-gate-poll-source="${escapeHtml(sid)}">Şimdi Sorgula</button>
                <button type="button" class="btn btn-sm" data-gate-remove-source="${escapeHtml(sid)}">Kaldır</button>
              </div>
            </td>
          </tr>
        `;
      }).join('');

      host.innerHTML = `
        <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:6px;">
          <span><strong>Sistem Saati (UTC):</strong> <code class="mono">${escapeHtml(clock.utcNowIso || '')}</code> · Saat Dilimi: <code>${escapeHtml(clock.timeZone || 'UTC')}</code></span>
          <span class="kpi-badge ok">5 Açık Veri Kaynağı · Kaynak Bazlı İzin ve SHA-256 Denetimi</span>
        </div>
        <div class="caelus-frt-table-wrap">
          <table class="caelus-frt-table">
            <thead>
              <tr>
                <th>Gerçek Veri Kaynağı</th>
                <th>Kapsanan Alanlar</th>
                <th>Lisans &amp; Ticari Durum</th>
                <th>İzin &amp; Son Güncelleme</th>
                <th>Kullanıcı Kontrolü</th>
              </tr>
            </thead>
            <tbody>${rowsHtml}</tbody>
          </table>
        </div>
      `;

      host.querySelectorAll('[data-gate-toggle-source]').forEach((btn) => {
        btn.addEventListener('click', () => {
          const sid = btn.getAttribute('data-gate-toggle-source');
          if (!worldDataGate) return;
          const cur = worldDataGate.getSourcePermissionsAndStatus().find((x) => x.sourceId === sid);
          const nextEnabled = !(cur && cur.enabled);
          worldDataGate.setSourcePermission(sid, nextEnabled);
          if (nextEnabled && worldDataGate.getMode().code === 'OFFLINE') {
            worldDataGate.setMode('PERMITTED_CONNECTION');
          }
          renderLivingWorldSubview();
        });
      });

      host.querySelectorAll('[data-gate-poll-source]').forEach((btn) => {
        btn.addEventListener('click', async () => {
          const sid = btn.getAttribute('data-gate-poll-source');
          const selEl = document.getElementById('sel-laa-source-id');
          if (selEl) selEl.value = sid;
          await executeGateSourceQuery(sid);
        });
      });

      host.querySelectorAll('[data-gate-remove-source]').forEach((btn) => {
        btn.addEventListener('click', () => {
          const sid = btn.getAttribute('data-gate-remove-source');
          if (!worldDataGate) return;
          const rem = worldDataGate.removeSourceRecords(sid);
          showSovereignFeedback(`✓ <code>${escapeHtml(sid)}</code> kaynağı devre dışı bırakıldı ve ${rem.removedCount} yerel kayıt temizlendi.`, false);
          renderLivingWorldSubview();
        });
      });
    } else if (activeLwSubview === 'ILGILENDIGIM_KONU') {
      if (memRecords.length === 0) {
        host.innerHTML = `
          <div style="padding:12px 14px; border-radius:10px; background:rgba(12,24,46,0.85); border:1px solid rgba(136,212,255,0.25); color:#F8FAFC;">
            <strong>Henüz gerçek dünya verisi alınmadı. Bir kaynak seçebilir veya dosya ekleyebilirsin.</strong>
            <div style="margin-top:4px; font-size:0.74rem; color:var(--text-2);">Yukarıdaki <em>"Kaynak Seç"</em> kutusundan Wikidata veya World Bank seçip <strong>"Kaynağa İzin Ver &amp; Şimdi Sorgula"</strong> düğmesine basabilir ya da yerel <code>.csv</code> dosyanızı yükleyebilirsiniz.</div>
          </div>
        `;
        return;
      }

      const recRows = memRecords.map((r) => {
        const badgeClass = r.isSampleFixture ? 'warn' : 'ok';
        const epLabel = r.isSampleFixture
          ? 'Örnek veri (Eğitim)'
          : (r.epistemic_label_tr || r.epistemic_status || 'Kaynaktan alınmış iddia');
        return `
          <tr>
            <td>
              <strong>${escapeHtml(r.title || r.record_id)}</strong>
              <br><span style="color:var(--text-2); font-size:0.71rem;">${escapeHtml(r.summary || '')}</span>
              <br><code style="font-size:0.65rem; color:#93C5FD;">SHA-256: ${escapeHtml(String(r.content_hash || '').slice(0, 16))}… · Biçim: ${escapeHtml(r.data_format || 'JSON')}</code>
            </td>
            <td>
              ${escapeHtml(r.source_name || r.source_id)}
              <br><code style="font-size:0.67rem;">${escapeHtml(r.source_license || '')}</code>
              ${r.source_url ? `<br><a href="${escapeHtml(r.source_url)}" target="_blank" rel="noopener noreferrer" style="font-size:0.67rem; color:#38BDF8;">Kaynak Bağlantısı ↗</a>` : ''}
            </td>
            <td>
              <div>A. Olay: <code>${escapeHtml(String(r.event_time || 'not_provided').slice(0, 19))}</code></div>
              <div>B. Yayın: <code>${escapeHtml(String(r.source_published_at || 'not_provided').slice(0, 19))}</code></div>
              <div>C. Alım: <code>${escapeHtml(String(r.ingested_at || '').slice(0, 19))}</code></div>
              <div>D. Kontrol: <code>${escapeHtml(String(r.last_checked_at || '').slice(0, 19))}</code></div>
            </td>
            <td>
              <span class="kpi-badge ${badgeClass}">${escapeHtml(epLabel)}</span>
              <div style="font-size:0.67rem; color:var(--text-2); margin-top:3px;">${escapeHtml(r.freshness_status || 'FRESH')}</div>
            </td>
          </tr>
        `;
      }).join('');

      host.innerHTML = `
        <div style="font-size:0.76rem; color:#88D4FF; font-weight:600;">Kayıtlı Dünya ve Varlık Kayıtları (Olay Tarihi ≠ Alım Tarihi · Kaynaktan Alınmış İddia ≠ Bağımsız Doğrulanmış Olgu):</div>
        <div class="caelus-frt-table-wrap">
          <table class="caelus-frt-table">
            <thead>
              <tr>
                <th>Başlık, Özet &amp; İçerik Özeti (Hash)</th>
                <th>Kaynak Sağlayıcı, Lisans &amp; Bağlantı</th>
                <th>Zaman Damgaları (A/B/C/D)</th>
                <th>Bilgi Statüsü &amp; Tazelik</th>
              </tr>
            </thead>
            <tbody>${recRows}</tbody>
          </table>
        </div>
      `;
    } else {
      if (memRecords.length === 0) {
        host.innerHTML = `
          <div style="padding:12px 14px; border-radius:10px; background:rgba(12,24,46,0.85); border:1px solid rgba(136,212,255,0.25); color:#F8FAFC;">
            <strong>Henüz gerçek dünya verisi alınmadı. Bir kaynak seçebilir veya dosya ekleyebilirsin.</strong>
            <div style="margin-top:4px; font-size:0.74rem; color:var(--text-2);">Alanlar arası bağlantı ve varlık tekilleştirme analizi için önce gerçek bir kaynak sorgulayın veya Eğitim Alanını açın.</div>
          </div>
        `;
        return;
      }

      const v2Records = (advMod && typeof advMod.convertAdvisorRecordToLivingWorldV2 === 'function')
        ? memRecords.map(advMod.convertAdvisorRecordToLivingWorldV2).filter(Boolean)
        : [];
      const entRes = typeof lwm.resolveLivingWorldEntities === 'function'
        ? lwm.resolveLivingWorldEntities(v2Records)
        : { candidateMatches: [] };
      const matches = entRes.candidateMatches || entRes.candidates || [];
      const candidateBanner = matches.length > 0
        ? matches.map((c) => `<div style="padding:6px 10px; background:rgba(245,158,11,0.14); border:1px solid rgba(245,158,11,0.45); border-radius:8px;"><strong>Yanlış Birleştirme Koruması:</strong> ${escapeHtml(c.status_message_tr || c.promptTr || 'Bu iki kayıt aynı kuruma ait olabilir.')} (Otomatik birleştirilmedi.)</div>`).join('')
        : '<div style="padding:6px 10px; background:rgba(245,158,11,0.14); border:1px solid rgba(245,158,11,0.45); border-radius:8px;"><strong>Yanlış Birleştirme Koruması:</strong> Kesin dış kimlik eşleşmesi olmayan benzer isimler otomatik birleştirilmez; tüm kayıtların kaynak izi ayrı korunur.</div>';

      const crossConn = typeof lwm.discoverCrossDomainLivingConnections === 'function'
        ? lwm.discoverCrossDomainLivingConnections(v2Records)
        : { directRelations: [], candidateHypothesisPaths: [] };

      const directItems = (crossConn.directRelations || []).slice(0, 6).map((rel) =>
        `<li><strong>[${escapeHtml(rel.connection_category_label_tr || 'Doğrudan Kaynaklı İlişki')}]:</strong> ${escapeHtml(rel.from_entity)} → ${escapeHtml(rel.to_entity)} (${escapeHtml(rel.predicate)}) — <em>${escapeHtml(rel.why_shown_tr || '')}</em></li>`
      ).join('');

      host.innerHTML = `
        ${candidateBanner}
        <div style="padding:8px 10px; background:rgba(12,24,46,0.78); border:1px solid rgba(136,212,255,0.22); border-radius:10px;">
          <strong>Mevcut Kayıtlardan Çıkarılan Alanlar Arası İlişkiler (Birlikte Geçme ≠ Nedensellik):</strong>
          <ul style="margin:6px 0 0 16px; line-height:1.45;">
            ${directItems || '<li>Seçili kayıtlarda doğrudan ilişkili varlık bağlantısı listelendi.</li>'}
          </ul>
        </div>
      `;
    }
  }

  async function executeGateSourceQuery(overrideSourceId) {
    if (!worldDataGate) return;
    const sourceSelect = document.getElementById('sel-laa-source-id');
    const queryInput = document.getElementById('inp-laa-source-query-entity');
    const queryBtn = document.getElementById('btn-laa-query-selected-source');
    const sid = overrideSourceId || (sourceSelect ? sourceSelect.value : 'wikidata');
    const qVal = queryInput ? queryInput.value.trim() : 'TSMC';

    if (worldDataGate.getMode().code === 'OFFLINE') {
      worldDataGate.setMode('PERMITTED_CONNECTION');
    }
    worldDataGate.setSourcePermission(sid, true);
    updateSovereignStatusBarAndPreview();

    const qParams = sid === 'wikidata'
      ? (/^Q\d+/i.test(qVal) ? { entityId: qVal } : { searchQuery: qVal || 'TSMC' })
      : sid === 'world_bank_indicators'
        ? { countries: qVal || 'TUR', indicator: 'NY.GDP.MKTP.KD.ZG' }
        : sid === 'sec_edgar_submissions'
          ? { cik: qVal || '0000320193' }
          : sid === 'openalex_scholarly'
            ? { search: qVal || 'supply chain' }
            : { query: qVal || 'semiconductor' };

    if (queryBtn) {
      queryBtn.disabled = true;
      queryBtn.textContent = 'Sorgulanıyor...';
    }
    try {
      const res = await worldDataGate.queryExternalSource(sid, qParams);
      if (res.ok && Array.isArray(res.records) && res.records.length > 0) {
        if (advisorSession) advisorSession.addWorldRecordsToAdvisorMemory(res.records);
        if (agentStudio && typeof agentStudio.addWorldRecordsToPool === 'function') {
          agentStudio.addWorldRecordsToPool(res.records);
        }
        if (livingScheduler && advMod && typeof advMod.convertAdvisorRecordToLivingWorldV2 === 'function') {
          const v2Recs = res.records.map(advMod.convertAdvisorRecordToLivingWorldV2).filter(Boolean);
          livingScheduler.ingestNormalizedRecordsIntoScheduler(sid, v2Recs);
        }
        showSovereignFeedback(
          `✓ <strong>${escapeHtml(sid)}</strong> kaynağından <strong>${res.records.length}</strong> gerçek kayıt alındı (SHA-256 mühürlü). Şimdi <em>İlgilendiğim Konu</em> veya <em>Konuşan Danışman</em> sekmesinde sorgulayabilirsiniz.`,
          false
        );
      } else {
        showSovereignFeedback(
          `⚠️ <strong>${escapeHtml(sid)}</strong> sorgusu tamamlanamadı: ${escapeHtml(res.userMessageTr || res.errorCode || 'Kaynak yanıt vermedi')}. ${res.staleWarningTr ? escapeHtml(res.staleWarningTr) : 'Sahte veri üretilmedi.'}`,
          true
        );
      }
    } catch (err) {
      showSovereignFeedback(`⚠️ Kaynak sorgu hatası: ${escapeHtml(String(err && err.message ? err.message : err))}`, true);
    } finally {
      if (queryBtn) {
        queryBtn.disabled = false;
        queryBtn.textContent = '🔍 Kaynağa İzin Ver & Şimdi Sorgula';
      }
      renderLivingWorldSubview();
    }
  }

  function renderAdvisorTurnOutput(turnRec) {
    const out = document.getElementById('laa-advisor-turn-output');
    if (!out || !turnRec) return;
    const plan = turnRec.structuredAnswerPlan || {};
    const passport = turnRec.answerPassport || { segments: [] };
    const disc = passport.mandatoryDisclosure7 || {};
    const semiring = passport.provenanceSemiring || {};

    const segHtml = (passport.segments || []).map((seg) => `
      <div style="padding:5px 8px; border-radius:7px; background:rgba(15,28,52,0.85); border-left:3px solid #38bdf8; display:flex; align-items:flex-start; justify-content:space-between; gap:8px;">
        <span><strong>[${escapeHtml(seg.epistemicState || seg.classCode)} · ${escapeHtml(seg.labelTr)}]:</strong> ${escapeHtml(seg.text)}</span>
      </div>
    `).join('');

    const datesList = (disc.dataAndEventDates || []).map((d) =>
      `<code>${escapeHtml(d.recordId)}</code> (Olay: ${escapeHtml(String(d.eventTime || 'not_provided').slice(0, 10))}, Alım: ${escapeHtml(String(d.ingestedAt || '').slice(0, 10))})`
    ).join(' · ') || 'Yerel/doğrudan değerlendirme';

    out.innerHTML = `
      <div style="padding:10px 12px; border-radius:10px; background:rgba(12,26,48,0.92); border:1px solid rgba(136,212,255,0.32);">
        <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:6px; margin-bottom:6px;">
          <strong style="color:#E6C387;">Konuşma Turu #${turnRec.turnIndex} · Niyet: <code>${escapeHtml(plan.user_intent || '')}</code> · Politika: <code>${escapeHtml(plan.answer_type || '')}</code></strong>
          <span class="kpi-badge ok">Odak Varlık: ${escapeHtml((plan.referenced_entities || []).join(', ') || 'Belirtilmedi')}</span>
        </div>
        <div style="white-space:pre-line; color:#F8FAFC; line-height:1.5; margin-bottom:8px;">${escapeHtml(turnRec.answerText || '')}</div>
        <div style="padding:7px 9px; border-radius:8px; background:rgba(8,18,36,0.82); border:1px solid rgba(136,212,255,0.18); font-size:0.72rem; line-height:1.45;">
          <strong style="color:#88D4FF;">7 Zorunlu Cevap Bileşeni (Bölüm 5.2):</strong>
          <div>1. <strong>Dayandığı Kaynaklar / Dosya Satırları:</strong> ${escapeHtml((disc.sourcesOrFileRows || []).join(', ') || 'Henüz dış kaynak/dosya kaydı eşleşmedi')}</div>
          <div>2. <strong>Veri ve Olay Tarihleri:</strong> ${datesList}</div>
          <div>3. <strong>Uygulanan Hesap / Kural:</strong> <code>${escapeHtml(disc.appliedRuleOrCalculation || 'DIRECT_RECORD_LOOKUP')}</code></div>
          <div>4. <strong>Varsayımlar:</strong> ${escapeHtml((disc.assumptions || []).join(' | ') || 'Ek model varsayımı yok')}</div>
          <div>5. <strong>Bilinmeyenler / Eksik Veri:</strong> ${escapeHtml((disc.unknowns || []).join(' | ') || 'Belirtilmedi')}</div>
          <div>6. <strong>Önerilen Sonraki Adım:</strong> ${escapeHtml(disc.nextStepForUser || plan.suggested_next_action || '')}</div>
          <div>7. <strong>ProvSQL Soykütük Polinomu (ℕ[X]):</strong> <code>${escapeHtml(semiring.polynomialExpression || '0')}</code></div>
        </div>
      </div>
      <div style="display:flex; flex-direction:column; gap:5px;">
        <strong style="font-size:0.75rem; color:#4ADE80;">CEVAP PASAPORTU (${passport.segments.length} Kanıt/Epistemik Segment · LLM Kullanılmadı):</strong>
        ${segHtml}
      </div>
    `;
  }

  function renderAgentStudioList() {
    const listEl = document.getElementById('laa-agent-studio-list');
    if (!listEl || !agentStudio) return;
    const agents = agentStudio.listAgents();

    if (agents.length === 0) {
      listEl.innerHTML = `
        <div style="padding:10px 12px; border-radius:10px; background:rgba(12,24,46,0.86); border:1px dashed rgba(136,212,255,0.35); color:#F8FAFC;">
          <strong>Henüz tanımlı kişisel ajan yok (Varsayılan olarak sahte ajan yüklenmez).</strong>
          <div style="font-size:0.73rem; color:var(--text-2); margin-top:3px;">Yukarıdaki hedef kutusuna doğal dilde amacınızı yazıp izinleri seçerek yeni bir ajan oluşturabilir veya <strong>"📋 3 Örnek Ajan Şablonunu Yükle"</strong> düğmesini kullanabilirsiniz.</div>
        </div>
      `;
      return;
    }

    listEl.innerHTML = agents.map((ag) => `
      <div style="padding:9px 11px; border-radius:10px; background:rgba(12,24,46,0.86); border:1px solid rgba(136,212,255,0.24); display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px;">
        <div style="min-width:220px; flex:1;">
          <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap;">
            <strong style="color:#F8FAFC;">${escapeHtml(ag.name)}</strong>
            <span class="kpi-badge ok">${escapeHtml(ag.status)}</span>
            <span class="kpi-badge mono">v${ag.version} · ${escapeHtml(ag.capability_type)}</span>
          </div>
          <div style="font-size:0.73rem; color:var(--text-2); margin-top:2px;">${escapeHtml(ag.purpose)}</div>
          <div style="font-size:0.70rem; color:#88D4FF; margin-top:2px;">İzinli Kaynaklar: <code>${escapeHtml((ag.allowed_sources || []).join(', ') || 'yok')}</code> · Ağ: <code>${ag.permissions.network_access ? 'AÇIK' : 'KAPALI'}</code> · Dosya Okuma: <code>${ag.permissions.local_file_read ? 'AÇIK' : 'KAPALI'}</code> · Dosyalar: <code>${escapeHtml((ag.user_files || []).join(', ') || 'yok')}</code></div>
        </div>
        <div style="display:flex; gap:5px; flex-wrap:wrap;">
          <button type="button" class="btn btn-sm btn-primary" data-run-agent-id="${escapeHtml(ag.agent_id)}">▶ Çalıştır</button>
          <button type="button" class="btn btn-sm" data-pause-agent-id="${escapeHtml(ag.agent_id)}">⏸ Duraklat</button>
          <button type="button" class="btn btn-sm" data-stop-agent-id="${escapeHtml(ag.agent_id)}">⏹ Durdur</button>
          <button type="button" class="btn btn-sm" data-revoke-agent-id="${escapeHtml(ag.agent_id)}" title="Ağ ve dosya okuma izinlerini geri al">🔒 Yetkiyi Geri Al</button>
          <button type="button" class="btn btn-sm" data-export-agent-id="${escapeHtml(ag.agent_id)}">📤 Güvenli Şablon</button>
          <button type="button" class="btn btn-sm" data-delete-agent-id="${escapeHtml(ag.agent_id)}">🗑 Sil</button>
        </div>
      </div>
    `).join('');

    listEl.querySelectorAll('[data-run-agent-id]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const aid = btn.getAttribute('data-run-agent-id');
        agentStudio.resumeAgentRun(aid);
        const report = agentStudio.runAgent(aid);
        renderAgentStudioList();
        renderAgentRunReport(report);
      });
    });

    listEl.querySelectorAll('[data-pause-agent-id]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const aid = btn.getAttribute('data-pause-agent-id');
        agentStudio.pauseAgentRun(aid);
        renderAgentStudioList();
      });
    });

    listEl.querySelectorAll('[data-stop-agent-id]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const aid = btn.getAttribute('data-stop-agent-id');
        agentStudio.stopAgentRun(aid);
        renderAgentStudioList();
      });
    });

    listEl.querySelectorAll('[data-revoke-agent-id]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const aid = btn.getAttribute('data-revoke-agent-id');
        agentStudio.revokeAgentPermission(aid, 'network_access');
        agentStudio.revokeAgentPermission(aid, 'local_file_read');
        renderAgentStudioList();
        const outEl = document.getElementById('laa-agent-run-output');
        if (outEl) {
          outEl.innerHTML = `<div style="padding:8px 10px; border-radius:8px; background:rgba(120,53,15,0.55); border:1px solid #F59E0B;"><strong>🔒 Yetki Geri Alındı:</strong> <code>${escapeHtml(aid)}</code> ajanının dış ağ ve yerel dosya okuma izinleri kapatıldı (Cedar Politikası: DENY).</div>`;
        }
      });
    });

    listEl.querySelectorAll('[data-export-agent-id]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const aid = btn.getAttribute('data-export-agent-id');
        const ag = agentStudio.listAgents().find((x) => x.agent_id === aid);
        if (!ag) return;
        const safeTpl = agentStudio.exportAgentTemplateSafe(ag);
        const outEl = document.getElementById('laa-agent-run-output');
        if (outEl) {
          outEl.innerHTML = `<div style="padding:8px 10px; border-radius:8px; background:rgba(16,82,56,0.45); border:1px solid #3DD68C;"><strong>✓ Güvenli Ajan Şablonu Dışa Aktarıldı (Gizli Anahtarlar ve Özel Dosyalar Temizlendi):</strong><pre style="margin-top:6px; font-size:0.70rem; overflow-x:auto;">${escapeHtml(JSON.stringify(safeTpl, null, 2))}</pre></div>`;
        }
      });
    });

    listEl.querySelectorAll('[data-delete-agent-id]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const aid = btn.getAttribute('data-delete-agent-id');
        const delRes = agentStudio.deleteAgentWithImpactPreview(aid, true);
        renderAgentStudioList();
        const outEl = document.getElementById('laa-agent-run-output');
        if (outEl && delRes && delRes.impactPreview) {
          outEl.innerHTML = `<div style="padding:8px 10px; border-radius:8px; background:rgba(15,28,52,0.85); border:1px solid rgba(136,212,255,0.3);"><strong>🗑 Ajan Silindi:</strong> ${escapeHtml(delRes.impactPreview.impactMessageTr || '')}</div>`;
        }
      });
    });
  }

  function renderAgentRunReport(report) {
    const outEl = document.getElementById('laa-agent-run-output');
    if (!outEl || !report) return;
    outEl.innerHTML = `
      <div style="padding:10px 12px; border-radius:10px; background:rgba(8,22,42,0.92); border:1px solid rgba(74,222,128,0.45);">
        <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:6px;">
          <strong style="color:#4ADE80;">Ajan Çalışma ve Kanıt Kartı: ${escapeHtml(report.agentName || '')} (v${report.agentVersion || 1})</strong>
          <span class="kpi-badge ok">Durum: ${escapeHtml(report.status || '')} · ${report.durationMs || 1} ms</span>
        </div>
        <div style="margin-top:4px; color:#F8FAFC;">${escapeHtml(report.summaryTr || '')}</div>
        <div style="margin-top:4px; font-size:0.72rem; color:#88D4FF;">Kanıt Sayısı: ${(report.evidenceItems || []).length} · Denetim Adımı: ${(report.auditSteps || []).length} · Engellenen Yetkisiz Girişim: ${(report.blockedPermissionAttempts || []).length}</div>
        ${(report.unknowns && report.unknowns.length > 0) ? `<div style="margin-top:4px; font-size:0.72rem; color:#FBBF24;"><strong>Bilinmeyen / Hata Kayıtları:</strong> ${escapeHtml(report.unknowns.join(' | '))}</div>` : ''}
      </div>
    `;
  }

  function switchLaaTab(tabId) {
    activeLaaTab = tabId;
    drawer.querySelectorAll('[data-laa-tab]').forEach((btn) => {
      const isMatch = btn.getAttribute('data-laa-tab') === tabId;
      btn.classList.toggle('active', isMatch);
      btn.setAttribute('aria-selected', isMatch ? 'true' : 'false');
    });
    const p1 = document.getElementById('laa-panel-living-world');
    const p2 = document.getElementById('laa-panel-advisor');
    const p3 = document.getElementById('laa-panel-agent-studio');
    if (p1) p1.classList.toggle('hidden', tabId !== 'living-world');
    if (p2) p2.classList.toggle('hidden', tabId !== 'advisor');
    if (p3) p3.classList.toggle('hidden', tabId !== 'agent-studio');

    if (tabId === 'living-world') renderLivingWorldSubview();
    if (tabId === 'agent-studio') renderAgentStudioList();
  }

  if (openBtn) {
    openBtn.addEventListener('click', () => {
      const willOpen = drawer.classList.contains('hidden');
      drawer.classList.toggle('hidden', !willOpen);
      openBtn.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
      if (willOpen) {
        renderLivingWorldSubview();
        renderAgentStudioList();
      }
    });
  }
  if (closeBtn) {
    closeBtn.addEventListener('click', () => {
      drawer.classList.add('hidden');
      if (openBtn) openBtn.setAttribute('aria-expanded', 'false');
    });
  }

  drawer.querySelectorAll('[data-laa-tab]').forEach((btn) => {
    btn.addEventListener('click', () => {
      switchLaaTab(btn.getAttribute('data-laa-tab'));
    });
  });

  drawer.querySelectorAll('[data-lw-subview]').forEach((btn) => {
    btn.addEventListener('click', () => {
      activeLwSubview = btn.getAttribute('data-lw-subview');
      drawer.querySelectorAll('[data-lw-subview]').forEach((b) => {
        b.classList.toggle('active', b.getAttribute('data-lw-subview') === activeLwSubview);
      });
      renderLivingWorldSubview();
    });
  });

  // Egemen Dijital Alan Kontrolleri (Kip, Örnek Veri Anahtarı, Yerel Dosya, Paket İçe Aktar, Veri Dışa Aktar / Sil)
  const modeSelectEl = document.getElementById('sel-laa-gate-mode');
  if (modeSelectEl && worldDataGate) {
    modeSelectEl.addEventListener('change', () => {
      worldDataGate.setMode(modeSelectEl.value);
      updateSovereignStatusBarAndPreview();
      renderLivingWorldSubview();
    });
  }

  const sampleToggleEl = document.getElementById('chk-laa-training-sample-mode');
  if (sampleToggleEl) {
    sampleToggleEl.addEventListener('change', () => {
      const enabled = Boolean(sampleToggleEl.checked);
      if (advisorSession && typeof advisorSession.setTrainingSampleMode === 'function') {
        advisorSession.setTrainingSampleMode(enabled);
      }
      if (agentStudio && typeof agentStudio.setTrainingSampleMode === 'function') {
        agentStudio.setTrainingSampleMode(enabled);
      }
      updateSovereignStatusBarAndPreview();
      renderLivingWorldSubview();
      showSovereignFeedback(
        enabled
          ? '⚠️ <strong>Örnek veri (Eğitim Alanı)</strong> açıldı. Gösterilen örnek kayıtlar gerçek dünya hafızasına aktarılmaz.'
          : '✓ <strong>Örnek veri (Eğitim Alanı)</strong> kapatıldı. Yalnızca gerçek kaynaklardan alınan kayıtlar ve kendi dosyalarınız kullanılır.',
        enabled
      );
    });
  }

  const sourceSelectEl = document.getElementById('sel-laa-source-id');
  const queryEntityInputEl = document.getElementById('inp-laa-source-query-entity');
  const querySourceBtnEl = document.getElementById('btn-laa-query-selected-source');
  if (sourceSelectEl) sourceSelectEl.addEventListener('change', updateSovereignStatusBarAndPreview);
  if (queryEntityInputEl) queryEntityInputEl.addEventListener('input', updateSovereignStatusBarAndPreview);
  if (querySourceBtnEl) {
    querySourceBtnEl.addEventListener('click', () => {
      executeGateSourceQuery();
    });
  }

  const localFileInput = document.getElementById('inp-laa-local-user-file');
  if (localFileInput) {
    localFileInput.addEventListener('change', (ev) => {
      const file = ev.target && ev.target.files ? ev.target.files[0] : null;
      if (!file) return;
      const reader = new FileReader();
      reader.onload = () => {
        const content = String(reader.result || '');
        if (worldDataGate) worldDataGate.registerPrivateUserFile(file.name, content);
        const parsed = advisorSession ? advisorSession.loadUserFileIntoAdvisor(file.name, content) : null;
        if (agentStudio) agentStudio.registerUserFile(file.name, content);
        showSovereignFeedback(
          `✓ <strong>${escapeHtml(file.name)}</strong> yerel özel alanınıza (Alan A) yüklendi: <strong>${parsed ? parsed.validRows.length : 0}</strong> geçerli satır, sütunlar: <code>${escapeHtml(parsed && parsed.columns ? parsed.columns.join(', ') : '')}</code>. Dış kaynaklarla paylaşılmaz.`,
          false
        );
      };
      reader.readAsText(file, 'utf-8');
    });
  }

  const importPkgBtn = document.getElementById('btn-laa-import-package-trigger');
  const importPkgInput = document.getElementById('inp-laa-separate-device-pkg');
  if (importPkgBtn && importPkgInput) {
    importPkgBtn.addEventListener('click', () => importPkgInput.click());
    importPkgInput.addEventListener('change', (ev) => {
      const file = ev.target && ev.target.files ? ev.target.files[0] : null;
      if (!file || !worldDataGate) return;
      const reader = new FileReader();
      reader.onload = () => {
        try {
          const pkg = JSON.parse(String(reader.result || '{}'));
          worldDataGate.setMode('SEPARATE_DEVICE_IMPORT');
          const imp = worldDataGate.importSeparateDevicePackage(pkg);
          if (imp.ok) {
            const extRecs = worldDataGate.inspectZones().B_EXTERNAL_SOURCE_RECORDS || [];
            if (advisorSession) advisorSession.addWorldRecordsToAdvisorMemory(extRecs);
            if (agentStudio && typeof agentStudio.addWorldRecordsToPool === 'function') {
              agentStudio.addWorldRecordsToPool(extRecs);
            }
            showSovereignFeedback(`✓ Ayrı cihaz paketi doğrulandı ve ${imp.importedCount} kayıt içeri aktarıldı.`, false);
            renderLivingWorldSubview();
          } else {
            showSovereignFeedback(`⚠️ Paket doğrulaması başarısız: ${escapeHtml(imp.userMessageTr || imp.errorCode || '')}`, true);
          }
        } catch (err) {
          showSovereignFeedback(`⚠️ Geçersiz JSON paketi: ${escapeHtml(String(err.message || err))}`, true);
        }
      };
      reader.readAsText(file, 'utf-8');
    });
  }

  const exportUserDataBtn = document.getElementById('btn-laa-export-user-data');
  if (exportUserDataBtn) {
    exportUserDataBtn.addEventListener('click', () => {
      const payload = {
        exported_at: new Date().toISOString(),
        schema: 'CAELUS_SOVEREIGN_USER_EXPORT_V1',
        advisor_memory: advisorSession ? advisorSession.inspectSeparatedMemory() : null,
        decision_task: decisionWorkspace ? decisionWorkspace.load() : null,
        world_gate_zones: worldDataGate ? worldDataGate.inspectZones() : null,
        agents: agentStudio ? agentStudio.listAgents().map((a) => agentStudio.exportAgentTemplateSafe(a)) : []
      };
      try {
        const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `caelus_yerel_verilerim_${new Date().toISOString().slice(0, 10)}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      } catch (_) {}
      showSovereignFeedback('✓ Tüm yerel tercihleriniz, kayıtlarınız ve güvenli ajan şablonlarınız JSON olarak dışa aktarıldı.', false);
    });
  }

  const deleteUserDataBtn = document.getElementById('btn-laa-delete-user-data');
  if (deleteUserDataBtn) {
    deleteUserDataBtn.addEventListener('click', () => {
      if (advisorSession) {
        advisorSession.clearDialogueState();
        advisorSession.deleteUserPreferences();
      }
      if (agentStudio && typeof agentStudio.clearStudioStorage === 'function') {
        agentStudio.clearStudioStorage();
        agentStudio.listAgents().slice().forEach((ag) => {
          agentStudio.deleteAgentWithImpactPreview(ag.agent_id, true);
        });
      }
      renderLivingWorldSubview();
      renderAgentStudioList();
      showSovereignFeedback('🗑 Yerel konuşma geçmişi, kullanıcı tercihleri ve ajan kayıtları cihaz hafızasından silindi.', false);
    });
  }

  const btnExportCorePkg = document.getElementById('btn-laa-export-core-pkg');
  if (btnExportCorePkg && lwm && typeof lwm.buildVersionedCoreAnalysisPackage === 'function') {
    btnExportCorePkg.addEventListener('click', () => {
      const memRecs = advisorSession ? advisorSession.inspectSeparatedMemory().C_SOURCED_WORLD_MEMORY : [];
      const v2Recs = (advMod && typeof advMod.convertAdvisorRecordToLivingWorldV2 === 'function')
        ? memRecs.map(advMod.convertAdvisorRecordToLivingWorldV2).filter(Boolean)
        : memRecs;
      const pkg = lwm.buildVersionedCoreAnalysisPackage(v2Recs);
      const replay = lwm.runOfflineCorePackageReplay(pkg);
      const host = document.getElementById('laa-living-world-content');
      if (host) {
        host.insertAdjacentHTML(
          'afterbegin',
          `<div style="padding:8px 10px; border-radius:8px; background:rgba(16,82,56,0.45); border:1px solid #3DD68C;"><strong>✓ Çevrim Dışı Çekirdek Veri Paketi Üretildi ve Doğrulandı:</strong> Şema <code>${escapeHtml(pkg.schema_version)}</code> · SHA-256: <code>${escapeHtml((pkg.package_hash_sha256 || pkg.package_sha256 || '').slice(0, 16))}…</code> · Deterministik Tekrar Oynatma: <code>${replay.ok ? 'BİREBİR EŞLEŞTİ (0 Ağ İsteği)' : 'HATA'}</code></div>`
        );
      }
    });
  }

  const btnSyncReal = document.getElementById('btn-laa-sync-real-sources');
  if (btnSyncReal) {
    btnSyncReal.addEventListener('click', async () => {
      btnSyncReal.disabled = true;
      btnSyncReal.textContent = 'Kontrol Ediliyor...';
      try {
        await executeGateSourceQuery();
      } catch (_) {}
      btnSyncReal.disabled = false;
      btnSyncReal.textContent = '🔄 Bağlı Gerçek Kaynakları Şimdi Kontrol Et';
      renderLivingWorldSubview();
    });
  }

  // Konuşan Danışman Kontrolleri
  const interestsInput = document.getElementById('inp-laa-user-interests');
  const saveInterestsBtn = document.getElementById('btn-laa-save-user-interests');
  if (saveInterestsBtn && advisorSession) {
    saveInterestsBtn.addEventListener('click', () => {
      const raw = interestsInput ? interestsInput.value : '';
      const list = raw.split(',').map((s) => s.trim()).filter(Boolean);
      advisorSession.updateUserPreferences({ interestAreas: list });
      showSovereignFeedback(`✓ Kişisel ilgi alanlarınız yerel hafızaya kaydedildi: <strong>${escapeHtml(list.join(', ') || 'Temizlendi')}</strong>`, false);
    });
  }

  const decisionPanel = document.getElementById('laa-decision-workspace');
  let decisionWorkspace;
  if (decisionPanel && advMod?.createDecisionWorkspace) {
    const taskForm = decisionPanel.querySelector('#laa-decision-task');
    const evidenceForm = decisionPanel.querySelector('#laa-decision-evidence');
    const replayForm = decisionPanel.querySelector('#laa-decision-replay');
    const deleteBtn = decisionPanel.querySelector('#laa-decision-delete');
    const optionRows = decisionPanel.querySelector('#laa-decision-options');
    const optionTemplate = decisionPanel.querySelector('#laa-decision-option');
    const status = decisionPanel.querySelector('#laa-decision-status');
    const output = decisionPanel.querySelector('#laa-decision-output');
    const statuses = {
      AVAILABLE: 'Uygulanabilir', WAITING: 'Teyit bekliyor', DENIED: 'Teyit reddedildi',
      OUTSIDE_LIMITS: 'Hedef veya bütçe dışında', EXPIRED: 'Karar süresi doldu'
    };
    const planName = (plan) => plan.recommended?.name ||
      (plan.status === 'WAITING_FOR_EVIDENCE' ? 'Teyit bekleniyor' : 'Uygulanabilir seçenek yok');
    const displayTime = (time) => new Date(time).toLocaleString('tr-TR');
    function addOption() {
      if (optionRows.childElementCount >= 20) return;
      const row = optionTemplate.content.cloneNode(true);
      row.querySelector('[data-remove-option]').addEventListener('click', (event) => {
        if (optionRows.childElementCount > 1) event.currentTarget.closest('fieldset').remove();
      });
      optionRows.append(row);
    }
    function renderDecision(plan, previous) {
      const heading = document.createElement('p');
      heading.textContent = plan.goal + ' · ' + displayTime(plan.asOf) + ' · Sonuç: ' + planName(plan);
      const options = document.createElement('ul');
      for (const option of plan.options) {
        const item = document.createElement('li');
        item.textContent = option.name + ' · ' + option.units + ' birim · ' + option.cost +
          ' · Son karar: ' + displayTime(option.deadline) + ' · ' + statuses[option.status] +
          (option.condition ? ' · ' + option.condition : '') +
          (option.evidence ? ' · Kaynak: ' + option.evidence.reference : '');
        options.append(item);
      }
      output.replaceChildren(heading, options);
      if (previous) {
        const change = document.createElement('p');
        change.textContent = 'Önce: ' + planName(previous) + ' / Şimdi: ' + planName(plan);
        output.prepend(change);
      }
    }
    function refreshDecision() {
      const saved = decisionWorkspace.load();
      taskForm.hidden = Boolean(saved);
      replayForm.hidden = !saved;
      deleteBtn.hidden = !saved;
      const select = evidenceForm.elements.condition;
      select.replaceChildren();
      const conditions = new Set(saved?.task.options.map((option) => option.condition).filter(Boolean));
      for (const condition of conditions) select.add(new Option(condition, condition));
      evidenceForm.hidden = conditions.size === 0;
      if (saved) renderDecision(decisionWorkspace.replay());
      else output.replaceChildren();
    }
    function handleDecision(event, action) {
      event.preventDefault();
      status.textContent = '';
      try { action(); } catch (error) { status.textContent = error.message; }
    }
    try {
      decisionWorkspace = advMod.createDecisionWorkspace(window.localStorage);
      addOption();
      addOption();
      refreshDecision();
    } catch (error) {
      status.textContent = error.message;
    }
    if (decisionWorkspace) {
      decisionPanel.querySelector('#laa-decision-add-option').addEventListener('click', addOption);
      taskForm.addEventListener('submit', (event) => handleDecision(event, () => {
        const values = taskForm.elements;
        const options = Array.from(optionRows.children, (row) => ({
          name: row.querySelector('[name=optionName]').value,
          units: row.querySelector('[name=optionUnits]').valueAsNumber,
          cost: row.querySelector('[name=optionCost]').valueAsNumber,
          deadline: new Date(row.querySelector('[name=optionDeadline]').value).toISOString(),
          condition: row.querySelector('[name=optionCondition]').value.trim()
        }));
        decisionWorkspace.create({
          goal: values.goal.value, minUnits: values.minUnits.valueAsNumber,
          maxCost: values.maxCost.valueAsNumber, options
        });
        refreshDecision();
      }));
      evidenceForm.addEventListener('submit', (event) => handleDecision(event, () => {
        const values = evidenceForm.elements;
        const update = decisionWorkspace.recordEvidence({
          condition: values.condition.value, status: values.status.value, reference: values.reference.value
        });
        renderDecision(update.after, update.before);
        values.reference.value = '';
      }));
      replayForm.addEventListener('submit', (event) => handleDecision(event, () => {
        renderDecision(decisionWorkspace.replay(new Date(replayForm.elements.asOf.value).toISOString()));
      }));
      deleteBtn.addEventListener('click', (event) => handleDecision(event, () => {
        if (!window.confirm('Yerel görev ve teyit geçmişi silinsin mi?')) return;
        decisionWorkspace.clear();
        taskForm.reset();
        refreshDecision();
      }));
      deleteUserDataBtn?.addEventListener('click', (event) => handleDecision(event, () => {
        decisionWorkspace.clear();
        taskForm.reset();
        refreshDecision();
      }));
    }
  }

  const experimentPanel = document.getElementById('laa-experiment-workspace');
  let experimentWorkspace;
  if (experimentPanel && advMod?.createExperimentWorkspace) {
    const protocolForm = experimentPanel.querySelector('#laa-experiment-protocol');
    const observationForm = experimentPanel.querySelector('#laa-experiment-observation');
    const deleteBtn = experimentPanel.querySelector('#laa-experiment-delete');
    const status = experimentPanel.querySelector('#laa-experiment-status');
    const output = experimentPanel.querySelector('#laa-experiment-output');
    const bounds = (range) => range.low + ' – ' + range.high;

    function renderExperiment(result) {
      protocolForm.hidden = Boolean(result);
      observationForm.hidden = !result || Boolean(result.record.observation);
      deleteBtn.hidden = !result;
      output.replaceChildren();
      if (!result) return;
      const { record, baselineMatched, compatibleHypotheses, predictionsOverlap, outcome } = result;
      const { protocol, observation } = record;
      const heading = document.createElement('p');
      heading.textContent = protocol.question + ' · ' + protocol.measurement + ' · ' + protocol.intervention;
      const list = document.createElement('ul');
      const entries = [
        'Ön kayıt: ' + record.createdAt + ' · Dayanak: ' + protocol.source,
        'Temel tahmin: ' + bounds(protocol.baseline),
        ...protocol.hypotheses.map((hypothesis) => hypothesis.name + ': ' + bounds(hypothesis.expected)),
        predictionsOverlap ? 'Hipotez aralıkları kesişiyor. Bazı ölçümler ayrım sağlayamaz.' : 'Hipotez aralıkları ayrık.'
      ];
      if (observation) {
        entries.push(
          'Gözlem: ' + observation.value + ' · Kaynak: ' + observation.source + ' · ' + observation.receivedAt,
          baselineMatched ? 'Gözlem temel tahmin aralığında.' : 'Gözlem temel tahmin aralığı dışında.',
          outcome === 'ONE_COMPATIBLE' ? 'Bu gözlemle uyumlu tek hipotez: ' + compatibleHypotheses[0] :
            outcome === 'INCONCLUSIVE' ? 'Bu gözlem iki hipotezi ayıramıyor.' : 'Gözlem iki hipotezin de tahmini dışında.'
        );
      }
      for (const entry of entries) {
        const item = document.createElement('li');
        item.textContent = entry;
        list.append(item);
      }
      output.append(heading, list);
    }

    async function runExperiment(event, action) {
      event?.preventDefault();
      status.textContent = '';
      try { await action(); } catch (error) { status.textContent = error.message; }
    }

    runExperiment(null, async () => {
      experimentWorkspace = advMod.createExperimentWorkspace(window.localStorage, window.crypto);
      renderExperiment(await experimentWorkspace.load());
    });
    protocolForm.addEventListener('submit', (event) => runExperiment(event, async () => {
      if (!experimentWorkspace) throw new Error('Yerel deney kaydı kullanılamıyor.');
      const v = protocolForm.elements;
      const interval = (prefix) => ({ low: v[prefix + 'Low'].valueAsNumber, high: v[prefix + 'High'].valueAsNumber });
      renderExperiment(await experimentWorkspace.register({
        question: v.question.value, measurement: v.measurement.value,
        intervention: v.intervention.value, source: v.source.value,
        baseline: interval('baseline'),
        hypotheses: [
          { name: v.firstName.value, expected: interval('first') },
          { name: v.secondName.value, expected: interval('second') }
        ]
      }));
    }));
    observationForm.addEventListener('submit', (event) => runExperiment(event, async () => {
      const v = observationForm.elements;
      renderExperiment(await experimentWorkspace.observe({ value: v.value.valueAsNumber, source: v.source.value }));
    }));
    function clearExperiment() {
      experimentWorkspace?.clear();
      protocolForm.reset();
      observationForm.reset();
      renderExperiment(null);
    }
    deleteBtn.addEventListener('click', (event) => runExperiment(event, () => {
      if (window.confirm('Yerel deney kaydı ve ölçüm silinsin mi?')) clearExperiment();
    }));
    deleteUserDataBtn?.addEventListener('click', (event) => runExperiment(event, clearExperiment));
  }

  const askInput = document.getElementById('inp-laa-advisor-question');
  const askBtn = document.getElementById('btn-laa-advisor-ask');
  const replayBtn = document.getElementById('btn-laa-advisor-replay');
  const replayStatus = document.getElementById('laa-advisor-replay-status');
  const replayComparison = document.getElementById('laa-advisor-replay-comparison');
  if (replayBtn && replayStatus && replayComparison && advisorSession) {
    const clearReplayComparison = () => {
      replayComparison.hidden = true;
      replayComparison.replaceChildren();
      replayStatus.textContent = '';
    };
    replayBtn.addEventListener('click', () => {
      clearReplayComparison();
      const question = askInput?.value.trim();
      const asOf = document.getElementById('inp-laa-advisor-as-of')?.value;
      if (!question || !asOf) {
        replayStatus.textContent = 'Soruyu ve geçmiş bilgi kesitini girin.';
        return;
      }
      try {
        const compareAsOf = document.getElementById('inp-laa-advisor-compare-as-of')?.value;
        const comparison = compareAsOf ? advisorSession.compareAdvisorReplayCuts(question, asOf, compareAsOf) : null;
        const result = comparison ? comparison.after : advisorSession.replayAdvisorTurn(question, asOf);
        if (comparison) {
          const previousAnswer = document.createElement('p');
          previousAnswer.textContent = 'İlk kesitteki yanıt: ' + comparison.before.answerText;
          const changes = document.createElement('ul');
          for (const change of comparison.evidenceChanges) {
            const item = document.createElement('li');
            item.textContent = (change.kind === 'REVISED' ? 'Güncellendi: ' : 'Eklendi: ') +
              change.title + ' · ' + change.receivedAt + ' · ' + change.sourceUrl;
            changes.append(item);
          }
          if (!changes.childElementCount) {
            const item = document.createElement('li');
            item.textContent = 'İki kesit arasında kaynak değişikliği yok.';
            changes.append(item);
          }
          replayComparison.append(previousAnswer, changes);
          replayComparison.hidden = false;
        }
        const count = result.answerPassport.availableWorldRecordCount;
        renderAdvisorTurnOutput(result);
        replayStatus.textContent = 'Geçmiş bilgi kesiti: ' + (compareAsOf || asOf).replace('T', ' ') + ' · ' + count + ' kaynak kaydı';
      } catch (error) {
        replayStatus.textContent = error instanceof RangeError ? error.message : 'Geçmiş bilgi kesiti değerlendirilemedi.';
      }
    });
    askBtn?.addEventListener('click', clearReplayComparison);
    drawer.querySelectorAll('.laa-advisor-quick-q, #btn-laa-reset-dialogue-state').forEach((button) => {
      button.addEventListener('click', clearReplayComparison);
    });
  }

  if (askBtn && advisorSession) {
    askBtn.addEventListener('click', () => {
      const q = askInput ? askInput.value.trim() : '';
      if (!q) return;
      const turnRec = advisorSession.processAdvisorTurn(q);
      renderAdvisorTurnOutput(turnRec);
    });
  }

  drawer.querySelectorAll('.laa-advisor-quick-q').forEach((btn) => {
    btn.addEventListener('click', () => {
      const q = btn.getAttribute('data-advisor-q') || '';
      if (askInput) askInput.value = q;
      if (advisorSession) {
        const turnRec = advisorSession.processAdvisorTurn(q);
        renderAdvisorTurnOutput(turnRec);
      }
    });
  });

  const resetBtn = document.getElementById('btn-laa-reset-dialogue-state');
  if (resetBtn && advisorSession) {
    resetBtn.addEventListener('click', () => {
      advisorSession.clearDialogueState();
      const out = document.getElementById('laa-advisor-turn-output');
      if (out) {
        out.innerHTML = `<div style="padding:8px 10px; border-radius:8px; background:rgba(15,28,52,0.85);">✓ Konuşma içi geçici bağlam (A_EPHEMERAL_DIALOGUE_STATE) sıfırlandı.</div>`;
      }
    });
  }

  // Kişisel Ajan Doğal Dil Hedef Ayrıştırıcı ve Açık İzin Seçimi
  const goalInput = document.getElementById('inp-laa-agent-goal');
  const goalCreateBtn = document.getElementById('btn-laa-parse-goal-create-agent');
  const testUnsupportedBtn = document.getElementById('btn-laa-test-unsupported-goal');
  const loadStarterAgentsBtn = document.getElementById('btn-laa-load-starter-agents');
  const feedbackEl = document.getElementById('laa-agent-draft-feedback');

  if (loadStarterAgentsBtn) {
    loadStarterAgentsBtn.addEventListener('click', () => {
      loadStarterAgentTemplatesOnDemand();
      renderAgentStudioList();
    });
  }

  function handleGoalParse(rawGoal) {
    if (!agentStudio || !stuMod) return;
    const draft = stuMod.parseNaturalLanguageGoalToAgentDraft(rawGoal);
    if (!draft.supported) {
      if (feedbackEl) {
        feedbackEl.classList.remove('hidden');
        feedbackEl.innerHTML = `<strong>Desteklenmeyen Kaynak Reddedildi:</strong> ${escapeHtml(draft.honestUserMessageTr)} <em>(${escapeHtml(draft.rejectedReason || '')})</em>`;
      }
      return;
    }
    if (feedbackEl) feedbackEl.classList.add('hidden');
    const permNet = document.getElementById('chk-laa-agent-perm-network');
    const permFile = document.getElementById('chk-laa-agent-perm-file');
    const permNotify = document.getElementById('chk-laa-agent-perm-notify');

    agentStudio.createAgent({
      name: draft.proposedName,
      purpose: draft.proposedPurpose,
      capabilityType: draft.capabilityType,
      executionMode: draft.executionMode,
      allowed_sources: draft.selectedSources,
      entities: draft.focusEntities,
      network_access: permNet ? Boolean(permNet.checked) : Boolean(draft.permissions && draft.permissions.network_access),
      local_file_read: permFile ? Boolean(permFile.checked) : Boolean(draft.permissions && draft.permissions.local_file_read),
      notifications: permNotify ? Boolean(permNotify.checked) : false
    });
    renderAgentStudioList();
  }

  if (goalCreateBtn) {
    goalCreateBtn.addEventListener('click', () => {
      const g = goalInput ? goalInput.value.trim() : '';
      if (g) handleGoalParse(g);
    });
  }
  if (testUnsupportedBtn) {
    testUnsupportedBtn.addEventListener('click', () => {
      if (goalInput) goalInput.value = 'Bütün sosyal medyayı izle';
      handleGoalParse('Bütün sosyal medyayı izle');
    });
  }

  renderLivingWorldSubview();
  renderAgentStudioList();

  window.caelusWorldDataGateInstance = worldDataGate;
  window.caelusAdvisorSession = advisorSession;
  window.caelusPersonalAgentStudioInstance = agentStudio;
  window.caelusLivingWorldSchedulerInstance = livingScheduler;
}

document.addEventListener('DOMContentLoaded', async () => {
  updateClock();
  setInterval(updateClock, 1000);

  detectHostGpuProfile();
  loadAppearancePrefs();
  loadDigitalWorldStoreFromLocalStorage();
  refreshSavedModelsDropdown();
  initCausalCanvas();
  initCrisisTimeline();
  initEventBindings();
  renderLivingUniversePanel();
  initCaelusGeoAndTimelineIntegrations();
  initGitHubUiTransformIntegrations();
  initCaelusTenRepoIntegrations();
  initCaelusRealWorld13TechIntegrations();
  initCaelusWorldImpactEngineUI();
  initCaelusLivingWorldModelUI();
  initCaelusDiscoveryValueEngineUI();
  initCaelusSpatialInterfaceSystem();
  initCaelusFirstRealTaskSystem();
  initCaelusLivingAdvisorAndAgentStudio();

  addAuditLog('info', 'CAELUS Karar Analitiği Arayüzü başlatıldı. Gerçek motor bağlantısı kontrol ediliyor...');
  addReplLine('Motor konsolu hazır. Komutlar: status, list levers, lever <id>, compare_lever <id> <ufuk> <tohum>, tick <n>, scenario <id>, load_json <json>, reset', 'info');

  // 1. Check if embedded WASM binary is present
  const wasmOk = await WasmEngine.init();
  if (wasmOk && WasmEngine.hasScenario('BS-01_SAHTE_UFUK')) {
    updateConnectionStatusPill('wasm');
    WasmEngine.loadScenarioId('BS-01_SAHTE_UFUK');
  } else {
    // 2. Otherwise start in honest offline state (never run a fake JS engine)
    updateConnectionStatusPill('offline');
    if (state.digitalWorldStore && state.digitalWorldStore.userActivatedWorld && getActiveDigitalWorld()) {
      restoreActiveDigitalWorldToEngine(false);
    }
    refreshEnterpriseWorkbench();
  }

  // 3. Connect to live C++/Rust desktop engine on 127.0.0.1:47809 if running
  connectLiveBridge();
});
